window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_000"]={"n":"无名氏","dyn":"元","poems":[{"t":"一寸金","f":"曲","c":["堪叹群迷，梦空花几人悟。","更假饶锦帐铜山，朱履玉簪，毕竟于身何故。","未若红尘外，幽隐竹篱蓬户。","青松下，一曲高歌，笑傲年华换今古。","紫府。","春光清，都雅会时，妙有真趣。","看自然天乐，星楼月殿，鸾飞凤舞。","白云深处。","壶内神仙景，谁肯少年回顾。","逍遥界，独我归来，复入寥阳去。"]},{"t":"西江月","f":"曲","c":["富贵又争人我，贫穷更待如何。","有缘有分是非多。","无福无灾无祸。","教他一任奢侈，箪瓢也是存活。","劝君休要苦张罗。","大限临头怎躲。"]},{"t":"西江月","f":"曲","c":["一不轻师慢法，二诵清净仙经。","三存真气养神灵。","四把尘劳拂尽。","五断无明业火，六除俗里人情。","七擒猿马永安宁。","八味璚浆得饮。"]},{"t":"西江月","f":"曲","c":["顿悟修行道理，除情战睡敌魔。","不贪名利少风波。","懒散随缘且过。","饥后寻街乞饭，饱时信步蹉跎。","闲来古庙唱哩啰。","逍遥谁人似我。"]},{"t":"西江月","f":"曲","c":["食饱伤心损气，睡多梦里迷真。","眼观心动丧元神。","耳听灵台昧尽。","要见元初面目，慧刀割断红尘。","无情应物本来真。","此是修行捷径。"]},{"t":"一寸金 赏雪","f":"曲","c":["暮鸿嘹唳。","更晚来地籁，阴风齐起。","造作严凝，同云黯黯，四海玉龙呈端。","妆点万家清景，普绽琼花鲜丽。","最好是，命诗朋，纸帐围炉沉醉。","吟缀。","搜佳制，竹外清香，金蕾喷新蕊。","似糁银沙，或为粉蝶，高下乱飞空里。","庆知太平，先兆阴阳和矣。","这玄理，遇子猷，同赏江天真味。"]},{"t":"一剪梅","f":"曲","c":["粗布宽衣下领袍。","一襟潇洒，两袖飘飘。","水云活计伴渔樵。","过得今宵，莫问来朝。","九节苍龙杖一条。","仙经数卷，肩上横挑。","腰间悬个小丹瓢。","行也逍遥，坐也逍遥。"]},{"t":"二郎神","f":"曲","c":["小张歌，也好把、繁华勘破。","速认元初真面目，把意马心猿牢锁。","百岁光阴能有几，也不可虚过。","耳却听嘱咐，仙风道骨，莫向红尘埋堕。","省呵。","把师父亲言记着。","你原是蓬莱洞里仙，为思凡、人间沦落。","速整仙胎归上会，莫荏苒、俗情系缚。","自思忖，假饶积玉堆金，终久幻化如何。"]},{"t":"八声甘州","f":"曲","c":["一团春雪，抛在玉炉中煎。","炎炎进火不住添。","要晓得通红无焰烟。","须管莫亏折，斤两依然。","如此三千。","锻炼待不摇不动，方可为禅。","全真养命，只在恁么之间。","家园自有甘露泉。","要浇灌黄芽长瑞莲。","幽远待得来，与仙圣齐肩。"]},{"t":"八声甘州","f":"曲","c":["千门万户，尽七倾八倒，掘地寻天。","真个玄妙，返作笑胡言。","无为大道人行少，向捏怪途中，有万千伤感，蜣球却做灵丹。","无奈伤嗟最苦，又不知端的，枉弃了家缘。","时间清净，岂解汞收铅。","心思意想何曾遣，暂合眼、阴魔作睡缠。","展转越思深，返作雠冤。","谁信无中生有，有中生无，万派归源。"]},{"t":"上平西","f":"曲","c":["这无常，两个字，最难防。","要来时、无处潜藏。","不论老幼，不管贫富与贤良。","不管妻子与儿郎。","怎恋爷娘。","身居土血逐水气，随风魂魄游扬。","细看来、怎不情伤。","休贪火院，早早修取上天堂。","三千功满赴蓬岛，永在仙乡。"]},{"t":"上平西","f":"楚辞体","c":["引清风，邀明月，去来兮。","省多少、闲是闲非。","临山近水，近些松竹向些梅。","小院活计没多般，诗酒琴棋。","无萦无烦恼，无别离。","待改变一味愚痴。","蝇头蜗角得失，何所更何为。","不如闻早乐真机。","高卧云梯。"]},{"t":"山亭柳","f":"曲","c":["世事堪忧。","光景难留。","春去又逢秋。","四季催人老，百年似、蝶梦庄周。","勘破从前似假，着甚揽闲愁。","慷慨幸遇希夷教，尘情事、一笔都勾。","下志速勤修。","有等愚痴辈，马丹阳唤不回头。","打的无缘业鬼，有分做骷髅。"]},{"t":"太常引","f":"曲","c":["光阴迅速不停留。","春去又还秋。","展破皱眉头。","且唱和、仙歌散忧。","百年短景，争名竞利，图恁惹闲愁。","休恁苦贪求。","但得过、随缘便休。"]},{"t":"太常引","f":"曲","c":["百年勋业镜中看。","叹行路古来难。","风雨换朱颜。","更谁管、安仁鬓斑。","掀天声价，凌云气势，短梦破槐安。","回首问青山。","放一片、孤云自闲。"]},{"t":"忆江南","f":"曲","c":["长生药，本是五行仙。","子午二门开卯酉，四时运火合乾坤。","龙虎自相吞。"]},{"t":"忆江南","f":"曲","c":["十月满，开鼎一团红。","数片残云含五彩，解胎神水响玲珑。","气复异香秾。"]},{"t":"忆江南","f":"曲","c":["还丹术，切要经手传。","若信故方终自误，颠来倒去倒来颠。","不得怨神仙。"]},{"t":"忆江南","f":"曲","c":["才举意，玄象照离宫。","坎女离男金水火，几多铁骑漫英雄。","最苦是云中。","辽阳鹤，惊起老苍龙。","四海九州沾惠泽，狼烟影里弄清风。","堪作主人公。"]},{"t":"斗鹌鹑","f":"曲","c":["木马嘶风，我之不然。","石人点头，哑子会言。","碧眼胡僧，没手指天。","画一圈。","无所传。","任意咆哮，如瓶泻泉。","枉费工夫，去磨砌砖。","安用机关。","夺胜争先。","戈甲俱宁，太平四边。","不参禅。","不问仙。","一味醍醐，我知自然。","不移一步到西天。","木人把住，铁牛便牵。","火里生莲。","玄之又玄。","云雾敛，月正圆。","石女停机，金针线穿。","谢三郎许我钓鱼船。","带甲金鳞，红锦更鲜。","不出波澜。","浮沉自然。","自喜欢。","便忘筌。","这些消息，谁敢乱传。"]},{"t":"无俗念","f":"曲","c":["全真大道理无穷，妙得至人端的。","说破先天玄妙处，默悟其中消息。","体物全彰，应机独露，悟了生前毕。","虽明此理，工夫最要绵密。","低头泄漏天机，不因师指此事如何识。","万类三才谁主运，建立乾坤无一。","变化无穷，包含不尽，运用无踪迹。","虚空打破，光明遍周无极。"]},{"t":"无俗念","f":"曲","c":["浮生碌碌。","算由天由命，也由人福。","暑往寒来人渐老，多少兴衰翻覆。","点石为金，指山为宝，未满人欲。","千方万计，到头那个知足。","何似忙里偷闲，山间林下，净扫黄茅屋。","明月清风俱是伴，又有山青水绿。","斗酒诗篇，饥餐渴饮，且喜无荣辱。","醉来还醒，醒来还唱一曲。"]},{"t":"无俗念","f":"曲","c":["茅庵交坐，任清虚冷淡，心香频爇。","认得元初真面目，万法同归无别。","行若闲云，坐犹空谷，动静成休歇。","重玄之妙，信知擘口难说。","仰高弥远钻坚，瞻前忽后，一点元无缺。","语默仙凡俱契妙，禅道虚无寂灭。","遍量忘知，盈壤靡觉，表里圆通彻。","玄天独露，一轮无相心月。"]},{"t":"无俗念","f":"曲","c":["参玄龃龉，强钻研道法，坚如钢铁。","乌噪猿啼谈不二，切忌随他分别。","喝下明心，杖头见性，此理固难说。","疑团打破，本来头面轻泄。","无根树上花开，脉传今古，脱落轮回劫。","拂子龟毛敲兔角，漱石流泉长舌。","五派宗乘，六传祖意，空立齐腰雪。","为君举似，碧潭冷浸秋月。"]},{"t":"月上海棠","f":"曲","c":["昨夜因打北邙山过。","见个骷髅儿道边卧。","雨洒风吹，骷髅被牧童打破。","知他是，李四张三王大。","低头无语思量我。","大限来时怎亸。","家有千金，难免这场灾祸。","休争我，到底一家一个。"]},{"t":"月上海棠","f":"曲","c":["吾言劝了千千万。","无一个回头猛烈汉。","教上千般，犹道火院牵缠绊。","没计算。","一限又推一限。","忧儿忧女没衣饭。","指望百年永作伴。","阎王来追，鬼使上门唤。","拖将去也，不道家缘不办。"]},{"t":"木兰花慢","f":"曲","c":["本轻清体妙，湛然独与天游。","为透入凡胎，五行圈圚，四火拘囚。","穷年执迷不悟，认声色虚幻故延留。","元旧仙乡道域，咫尺天地迢遥。","欲求返本还元，诚只在自心头。","但默默精思，时时探索，必取功收。","虚空忽然粉碎，尽来生、业障一齐休。","振袂蓬莱阆苑，不愁弱水无舟。"]},{"t":"水仙子","f":"曲","c":["百年三万六千场，风雨忧愁一半妨。","眼里儿觑，心儿上想。","教我鬓边丝怎地当，把流年子细推详。","一日一个浅酌低唱，一夜一个花烛洞房，能有得多少时光？"]},{"t":"双调 水仙子 失题","f":"曲","c":["青山隐隐水茫茫，时节登高却异乡。","孤城孤客孤舟上，铁石人也断肠，泪涟涟断送了秋光。","黄花梦，一夜香，过了重阳。","夕阳西下水东流，一事无成两鬓秋。","伤心人比黄花瘦，怯重阳九月九。","强登临情思悠悠，望故国三千里，倚秋风十二楼。","没来由惹起闲愁。","常记的离筵饮泣饯行时，折尽青青杨柳枝。","欲拈斑管书心事，无那可乾坤天样般纸。","意悬悬诉不尽相思，谩写下鸳鸯字，空吟就花月词，凭何人付与娇姿。","一春鱼雁杳无闻，千里关山劳梦魂。","数归期屈指春纤困，结灯花犹未准。","叹芳年已过三旬，退莲脸消了红晕。","压春山长出皱纹，虚度了青春。"]},{"t":"水龙吟","f":"曲","c":["本自出家离尘世。","更不贪人间华丽。","蓬头垢面，终朝独坐，内修活计。","古庙窑龛里。","任他红轮西坠。","向无中认有，知白守黑，绵绵地，默调息。","心上别无萦系。","有腋袋拄杖相随。","草鞋短襦，精□赤腿，羊皮遮体。","饥后巡门乞。","饱来唱哩仑啰哩。","任傍人笑我，呆痴懒汉，有谁人识。"]},{"t":"水龙吟","f":"曲","c":["玉炉百和发虔心，信香一炷，氤氲缭绕。","来往盘旋，结成华盖。","报天地恩覆载。","报日月照临之德。","报国王水土，丰荣快乐，报父母恩怜爱。","上谢祖师圣教，丹阳师父传派。","红尘普度，全真大教，丘王长在。","太古居宁海。","共三人暗合法界。","愿皇王万岁，千秋臣宰。","请门人拜。"]},{"t":"水调歌头","f":"楚辞体","c":["五行不到处，一气未生前。","清光赫赫，无何乡里独超然。","日月岂能照鉴，天地不能包裹，晃朗妙无边。","赖有竹涧水，却向世人传。","杳兮冥，恍兮惚，湛兮然。","这些消息，浑身是口也难诠。","截断千差歧路，屏除万般机巧，缆住钓鱼船。","往事都休问，静坐一炉烟。"]},{"t":"水调歌头","f":"曲","c":["东风卷帘幕，时物又新奇。","桃花院落，小桥流水柳依依。","正是清明天气，茅草池塘鲜丽，何处不相宜。","紫燕添新垒，小雨洒芳菲。","老生涯，沽酒杖，钓鱼矶。","江湖一样，几声鸥鹭夕阳微。","百岁光阴石火，万叠云山烟锁，回首顿忘机。","蝶梦松窗下，高卧碧云溪。"]},{"t":"四块玉","f":"曲","c":["光景如梭，劝早早回头寻活计。","莫被利役名牵，酒色昏迷。","是非人我，空惹闲气。","铅枯汞竭，恁藏休悔，谩尔伤悲。","便做从今，下手理会，宁早莫稽迟。","呆痴。","自落便宜。","纵养家千口成何济。","枉使身心劳碌，昼夜无眠，老却朱颜，教君憔悴。","何须自苦，怎不回首，自家推算，无常有谁能替。"]},{"t":"失调名 自乐","f":"曲","c":["醉时节、就把青山靠。","醒来时、兴取瑶琴操。","操的是、鹤鸣九皋，水色清，山色近，迥然闲自乐。","俺也一如归阆苑，登蓬岛。","且恁底、寄迹人间，与造化、同游太虚，保养得、形神俱妙。"]},{"t":"归朝欢","f":"曲","c":["天地初分何处寄。","父母无生名甚字。","须将这个要分明，推穷此理宁论是。","细细传不二。","亦能整究从前事。","往来频，不知迷迷，甚日得言赐。","忽尔真灵前面至。","认得无形欢喜示。","惺惺觑着甚端严，辉辉返照通容易。","见时惟觅妙玄微，雅深中透出圆光，五般颜来，复本总祥瑞。"]},{"t":"永遇乐","f":"曲","c":["行也无忧，坐也无闷，长安长乐。","息息绵绵，朝朝暮暮，保养神珠一颗。","闲是闲非，莫偢莫采，大忌竞争人我。","灭无明、心似寒灰，便是道人功果。","猿儿不走，马儿捉住，龙虎定中交媾。","阳降阴升，日来月往，炉炼长生药。","抽添鼎内，不须炊爨，自有九阳真火。","霜心子、明把天机，与君说破。"]},{"t":"永遇乐","f":"曲","c":["养水养精，养神养血，先须养气。","日月阴阳，六爻八卦，细看参同契。","虚躯虚宝，千言万语，不过坎离两字。","向昆仑顶上，返本还元，要明终始。","一身虽小，如同天地。","八万四千余里。","玄牝之门，千生万化，都在冲和内此。","真真外，别无真谛。","方信道一而已。","异时见钟吕，如有未明，请师指示。"]},{"t":"永遇乐","f":"曲","c":["试问诸公，本来模样，如何形状。","纵使丹青，难描这个，旷劫端严相。","无形无影，观之不见，听之又无响。","露堂堂、不摇不动，目前甚是明朗。","人还省悟，回光返照，莫向外边劳攘。","放下诸缘，屏除万事，物物离心上。","迷云消散，性天独露，心月永无遮障。","与三界、一切诸仙，并无两样。"]},{"t":"永遇乐","f":"曲","c":["忙里偷闲，闹中取静，利名休竞。","有限光阴，无涯尘事，贪爱何时尽。","无情乌兔，催人早老，暗里换了绿鬓。","此形骸、假合幻化，算来有甚凭准。","随缘度日，和光同尘，惹甚闲愁闲闷。","富贵由天，荣华是命，休更劳方寸。","心中无事，眼前清净，俱是快活时景。","你若待、般般称意，耐心且等。"]},{"t":"永遇乐","f":"曲","c":["万法由心，应观法界，一切心造。","瞿昙同归，去揆不离，即心是道。","自从识得坎离，交际炼药，粗知昏晓。","看鸡飞蟾宫，兔走丹阙，更无烦恼。","气中真液，液中真气，和合不多不少。","种得黄芽，炼成赤水，龙虎交围绕。","九还七返，工夫到后，还我旧时年少。","待三千，功圆行满，恁时是了。"]},{"t":"玉交梭 梭疑枝之误","f":"曲","c":["我已叮咛劝。","展手心休倦。","后巷前街，茶坊酒肆且遍。","绕巡门，散喏好降心，与修行方便。","一志休回转。","趁了今生愿。","神气冲和，阴阳升降，虎龙争斗，迸金灿烂。","绕丹田，看真人出现。"]},{"t":"玉抱肚","f":"曲","c":["若论玄妙，听周风一诀。","把婴儿姹女，木金间隔。","从头分别。","先擒六贼三尸灭。","后捉玉兔饮乌血。","仗剑锋，麾魔障，荡袄邪。","全凭志猛烈。","那些个手段最奇绝。","龙奔虎走，来往放乖劣。","两兽擒来吾怎舍。","炉烹鼎炼无暂歇。","乾坤至宝，阴阳造化，斡运龟蛇。","东鸡叫出西江月。","会入黄庭赏白雪。","上丹温，中丹暖，下丹热。","三田宝结。","众仙举我赴金阙。","寥阳胜境，教我怎生说。"]},{"t":"玉胡蝶","f":"曲","c":["捉住玉山赤凤，神舟同泛，激浪漂浮。","便使乌龟开口，出头喜谟，吸洪涛、枯干北海，使巨波、浇灌西湖。","自舒敷。","水纹花面，此日是金铺。","光珠。","盈盈照耀，恰如明月，晃晃方隅。","普遍腾辉，尽成霞彩环纡。","见圆珠、深深渐见，结宝丹、空外超逾。","得临大罗天上，永永惺苏。"]},{"t":"玉胡蝶","f":"曲","c":["为甚夜来添病，强临宝鉴，憔悴娇慵。","一任钗横鬓乱，永日薰风。","恼脂消、榴花径里，羞玉减、蝶粉丛中。","思悠悠，垂帘独坐，倚遍熏笼。","朦胧。","玉人不见，罗裁囊寄，锦写笺封。","约在春归，夏来依旧各西东。","粉墙花、影来疑是，罗帐雨、梦断成空。","最难忘，屏边瞥见，野外相逢。"]},{"t":"玉液泉","f":"曲","c":["这消息，几人知，独我全真好。","大悟来，心地清凉，便分晓。","本来面目常照。","最玄妙。","金关开，玉户闭，来往通关窍。","遍三田，觉上下和冲，降银雪，黄芽遍生芝草。","姹婴舞跳。","透引动龙吟虎啸。","搬运在，斡旋中，坎离颠倒。","龟蛇战斗，水火抽添，炉内烧丹，结就明珠晃耀。","玉皇深恩宣诏。","祥云攒罩。","恁时稳跨青鸾，归蓬岛。"]},{"t":"甘露滴乔松","f":"曲","c":["光阴迅速，叹世人朝朝，贪生无已。","假若富过石崇，金玉堆积。","谩赢得业相随，镇日假瞒心昧己。","阎王请也，从前罪业，待交谁替。","争如早早修持，伴物外仙家，抛离凡世。","默默湛寂，别有壶中天地。","显森罗，月辉辉，观法界、神光一体。","归去也，清风送朝上帝。"]},{"t":"生查子","f":"曲","c":["夜来忽睹一场希，乍见几个灯蛾儿，堪人嗟呀。","爱欲贪嗔不肯舍。","错认灯光，随高随下。","火焰根前，百般颠耍。","十分烧着，全然不怕。","直待灯盏内做个焦巴。","这回休也。","休也。","休也。","奉劝你诸公，略听予劝。","休似灯蛾儿，心生爱恋。","恋着恩爱老了面。","面皱发白，腰曲头低，耳聋眼暗，觅个回转。","把往日风流，一刀两断。","闻身康健。","早做个惺惺洒洒汉。","猛跳出凡笼，便是一个了办。"]},{"t":"如梦令","f":"曲","c":["猛悟百年弹指。","泪似迸珠不止。","急解死生忧，管甚石中火起。","石中火起。","一任停丧在地。"]},{"t":"如梦令","f":"曲","c":["学道非难非易。","怎敢已而不已。","专下死工夫，悟得长生活计。","长生活计。","收拾精光神气。"]},{"t":"导引 大定二十七年三月皇太孙受册谢庙","f":"曲","c":["璇源浚发，衍庆自灵长。","圣运日隆昌。","震闱显册遵彝典，基绪焕重光。","拣时庙见严昭报，礼乐粲成章。","精诚潜格神明助，福禄永无疆。"]},{"t":"导引 大定三年十月祫享顺銮应钟宫","f":"曲","c":["礼行清庙，华黍荐年丰。","圣孝与天通。","六龙回驭千官卫，玉振佩环风。","黄麾金辂严天仗，霏雾郁葱葱。","工歌迭奏升平曲，福禄自来崇。"]},{"t":"导引 天德二年三月祫享回銮姑洗宫","f":"曲","c":["礼成庙享，御卫拱飞龙。","诸家起翔风。","太平天子多受福，孝德与天通。","凤箫龙管韶音奏，声在五云中。","粲然文物昭治世，万亿祀无穷。"]},{"t":"导引 正隆六年六月驾幸南京林钟宫","f":"曲","c":["神宫壮丽，宫殿压蓬莱。","向晓九门开。","圣明天子初巡幸，遥驾六龙来。","五云影里排仙仗，清跸绝尘埃。","都人齐唱升平曲，更进万年杯。"]},{"t":"导引 贞元元年三月驾幸中都姑洗宫","f":"曲","c":["銮舆顺动，嘉气满神京。","辇路宿尘清。","钩陈万旅随天仗，缥缈转霓旌。","都人望幸倾尧日，鳌抃溢欢声。","临观八极辰居正，寰宇庆升平。"]},{"t":"曲江秋","f":"曲","c":["如何是道。","这一点、古今寻求颠倒。","人人有分，个个不亏少。","皆因动念错，染着处、便生烦恼。","若也般般放下，有何微奥。","随分随缘且过，究本来面目，直须分晓。","寒炉冷灶。","对虎龙吟啸。","目前便是了。","更不向、外边寻讨。","不问神仙与佛，共同觉照。"]},{"t":"江城子","f":"曲","c":["林泉养素拙。","放落魄、慵居世缘绝。","志如铁。","翛然处、一味真欢杂说。","日逍遥，野鹤岩畔为道侣，松轩下、沉烟犹未歇。","夜深独听孤猿，高峰上叫明月。","他年功成行满，驾祥云、直至瑶池仙阙。","个时节。","神游自有鸾鹤迎接。","舞空碧。","仙仗飘飘来迎竭。","桃源会、琼林方信别。","到此无限逍遥，作蓬莱客。"]},{"t":"江城子","f":"曲","c":["人生七十古来稀。","叹愚迷。","不修持。","光阴有限，成败是和非。","盖世功名都占取，空赢得，业相随。","暂时花酒气财迷。","得便宜。","落便宜。","暗里朱颜，渐改气神亏。","阳少阴多染患，命尽也，更推谁。"]},{"t":"红窗迥","f":"曲","c":["情欲消亡，脱了根尘。","乐虚恬淡崇真。","形如野鹤，性似孤云。","到处为家，风为伴，月为邻。","住世无心，异俗超群。","握玄机、哩啰哩仑。","省一点颜貌常新。","得至真功，全真行，侍真君。"]},{"t":"行香子","f":"曲","c":["寂寂寥寥。","洒洒潇潇。","淡生涯、一味逍遥。","傍临谷口，斜枕山腰。","有竹篱门，荆扫帚，草团标。","宽布麻袍。","大绪长绦。","拄一条、曲律藤梢。","黄精自煮，苍术亲熬。","有瓦汤瓶，砂釜灶，葫芦瓢。"]},{"t":"行香子","f":"曲","c":["短短横墙。","矮矮疏窗。","忔憎儿、小小池塘。","高低叠障，绿水边傍。","却有些风，有些月，有些凉。","日用家常。","木几藤床。","据眼前、水色山光。","客来无酒，清话何妨。","但细烹茶，热烘盏，浅浇汤。"]},{"t":"行香子","f":"曲","c":["阆苑瀛洲。","金谷重楼。","算不如、茅舍清幽。","野花绣地，莫也风流。","却也宜春，也宜夏，也宜秋。","酒熟堪篘。","客至须留。","更无荣、无辱无忧。","退闲一步、着甚来由。","但倦时眠，渴时饮，醉时讴。"]},{"t":"行香子","f":"曲","c":["净扫尘埃。","惜取苍苔。","任门前、红叶铺阶。","也堪图画，还也奇哉。","有数株松，数竿竹，数枝梅。","花木栽培。","取次教开。","明朝事、天自安排。","知他富贵几时来，我且优游，且随分，且宽怀。"]},{"t":"行香子 原误作南香子","f":"曲","c":["一个苍蝇，飞入腥盆。","顾甜时、直入中心去，忘了抬身。","沾其足，沾其翅，丧其形。","我好嗟吁，怎不动心。","甜中有苦，福内灾生。","既知滋味，便好抽身。","你好不惺惺，不伶俐，一个大苍蝇。"]},{"t":"西江月","f":"曲","c":["九九乾坤已定，清明节后开花。","米田天下乱如麻。","直待龙蛇继马。","依旧中华福地，古月一阵还家。","当初指望瓮生涯。","死在西江月下。"]},{"t":"西江月","f":"曲","c":["世有学人无数，愚痴妄意如麻。","铅汞错认结为砂。","运火欲觅黄芽。","千日虚劳心力，人人尽破其家。","真铅似火本无瑕。","将凤欲比狂鸦。"]},{"t":"西江月","f":"曲","c":["水火运来周岁，四六勿错如初。","水多火少失功夫。","胜地方始安炉。","直须认鼎与药，却如鸡子无殊。","内黄处白结凝酥。","一颗圆明汞珠。"]},{"t":"西江月","f":"曲","c":["彼此离于生处，火遭水破惊忙。","分身各自拟深藏。","半路再遣萧郎。","夫为无衣裹体，妻因水浸衣黄。","丙丁甲乙有形相。","刚遣令合阴阳。"]},{"t":"西江月","f":"曲","c":["听说金公两字，何物唤作金孙。","寻枝寻叶必知根。","无智便乃心昏。","若用凡铅为体，都来少魄无魂。","水银渐结必难存。","秘诀要处谁论。"]},{"t":"西江月","f":"曲","c":["丹是色身妙宝，法身即是真心。","从来无色亦无音。","一体不须两认。","万法非无非有，有无亦莫搜寻。","二边俱遣弃中心。","选佛斯为上品。"]},{"t":"西江月","f":"曲","c":["真假两般玄字，金公所料重遗。","凡铅纵与岳山齐。","不肯假与金妻。","听说真铅住处，他家跳在深溪。","两情恩爱事因媒。","义重争敢东西。"]},{"t":"贺圣朝","f":"曲","c":["一理无今无古，此心何喜何嗔。","无相乃为真相。","色身即是法身。","不消一句半句，活得千人万人。","咦，这里便是到头，何须只管翻身。"]},{"t":"西江月","f":"曲","c":["至道不烦不远，至人只在目前。","淮王炼石得冲天。","汉世已经千年。","全在低心下人，事该缘分偶然。","安炉致数尽周圆。","须得汞去投铅。"]},{"t":"齐天乐","f":"曲","c":["自清都别后，人间梦中游戏。","性本玄虚，君临社稷，洪福齐天康济。","冬温夏清，任春水秋山，放怀如意。","外物多情，幻身无奈生憔悴。","深穷仙方道术，固炼形神，内观返调元气。","四大冲和，三彭遁匿，熟境繁华何忌。","真空妙有，况千古灵明，自然凋弊。","梦觉心开，廓然超万岁。"]},{"t":"吴音子","f":"曲","c":["欲要神仙做，抱元气，胎息绵绵。","一回气满一回煎。","阴阳媾，赤龙蟠。","地户牢封玄门启，滚丹砂、透入泥丸。","昆仑上，明珠晃朗，玛瑙珊珊。","一炉火灭一炉丹。","灰心显、五色光鲜。","双关路上气连连。","拥真花，上丹田。","姹女婴儿交欢笑，驾河车、地火雷迁。","醴泉酒，时时饮罢，醉卧桃源。"]},{"t":"折桂令","f":"曲","c":["叹世间多少痴人，多是忙人，少是闲人。","酒色迷人，财气昏人，缠定活人。","钹儿鼓儿终日送人，车儿马儿常时迎人。","精细的瞒人。","本分的饶人。","不识时人，枉只为人。"]},{"t":"折桂令 微雪","f":"曲","c":["朔风寒吹下银沙，蠹砌穿帘，拂柳惊鸦，轻若鹅毛，娇如柳絮，瘦似梨花。","多应是怜贫困天教少洒，止不过庆丰年众与农家。","数片琼葩，点缀槎丫。","孟浩然容易寻梅，陶学士不彀烹茶。"]},{"t":"添声杨柳枝","f":"曲","c":["已谢芳华更不留。","几经秋。","故宫台榭只荒邱。","忍回头。","塞外风霜家万里，望中愁。","楚魂湘血恨悠悠。","此生休。"]},{"t":"步步娇","f":"曲","c":["真行与真功。","刀圭快如风。","不遇真师匠，难明。","你若做时第一功。","浑身百关节，齐通。"]},{"t":"步步娇","f":"曲","c":["传得一口诀。","教我去栽接。","自从栽接后，全别。","玉蕊金花果结子，哑子吃饧蜜，难说。"]},{"t":"步步娇","f":"曲","c":["遍地有灵芝。","人人都不识。","作得业又大，难敌。","我今欲待说与你，只恐你不信，谈非。"]},{"t":"步步娇","f":"曲","c":["休执性为真。","如何出阳神。","十个九个守，顽空。","若得命基带了性。","白面做烧饼，有准。"]},{"t":"步步娇","f":"曲","c":["柔弱好家风。","大道不脱空。","真个真个有，铅汞。","水火既济上下冲。","文武两交战，齐功。"]},{"t":"步步娇","f":"曲","c":["无为自然道。","清净长芝草。","默默相知了，便好。","杳杳冥冥闭了灶。","工夫片时间，成了。"]},{"t":"步步娇","f":"曲","c":["俺在炕上坐。","唱个啰哩啰。","困来睡一觉，如何。","俺把阴阳颠倒过。","俺笑俺笑你，空坐。"]},{"t":"步步娇","f":"曲","c":["贫子吃好酒，吃得酩酊休。","万事都不挂心头。","任毁任谤落一筹。","痴聋喑哑汉，真修。"]},{"t":"步步娇","f":"曲","c":["信则你自信，不信你休行。","莫待临渴时，掘井。","每日见尔费辛苦，不济不济事，休论。"]},{"t":"步步高（北曲）","f":"曲","c":["二更里，白牛溪边睡。","牧童醺醺醉。","蓑笠堆。","月下方堪把笛吹。","乐然后，归去华胥国。","得到华胥宽怀抱。","闲把瑶琴操。","声韵高。","火里乌龟产，白鹤弄云萧。","紫雾红光照。"]},{"t":"步步高（北曲）","f":"曲","c":["三更里，银汉星移淡。","出户将身探。","月正南。","二八娇娥配童男。","炼三三。","手把天关撼。","五明宫里元辰聚。","七宝山头去。","祷玉虚。","元始高悬黍米珠。","演金书。","国泰民安富。"]},{"t":"步步高（北曲）","f":"曲","c":["一更里，澄心披襟坐。","猿马牢擒锁。","慧剑磨。","六贼三尸尽奔波。","退群魔。","困也和衣卧。","醒觉朦胧清风送。","悟人桃源洞。","阆苑中。","闲访三茅兴无穷。","透窗风。","惊觉游仙梦。"]},{"t":"步步高（北曲）","f":"曲","c":["四更里，玄圃清风细。","来往无凝滞。","解垢衣。","心月高悬照云溪。","上天梯。","独折蟾宫桂。","三界十方惟独步。","认得曹溪路。","一物无。","真欢真乐饮醍醐。","不须沽。","高唱无声曲。"]},{"t":"步步高（北曲）","f":"曲","c":["五更里，架上金鸡叫。","路上行人俏。","方欲晓。","没底篮儿杖头挑。","跨风飙。","同赴蓬莱岛。","此个家风谁知道。","得也无衰老。","琅板敲。","碧波深处钓鲸鳌。","出波涛。","采就长生药。"]},{"t":"沁园春","f":"曲","c":["切劝学人，悟取灵台，休得外求。","这天机玄妙，非容易，与君今日，细说根由。","没口婆婆，偏能言语，没脚童儿，擅蹴戏球。","真消息，见云埋玉洞，月照金楼。","有谁似我能修。","把狮子擒来变作牛。","向黄河浪里翻筋斗。","太阳宫里，捉住猕猴。","白雪花开，青云子结，占得玄关第一筹。","仙宫舍，跨骊龙归去，永玩瀛洲。"]},{"t":"沁园春","f":"曲","c":["遇此荒年，天下门徒，受魔受难。","过此番才显真诚，道友杀那，慷慨应过天仙。","广化天尊，忠昭烈士，甲子旬中要五千。","加刚志，九天仙阙，无数金莲。","逢魔一志当先。","心上休教邪共偏。","举刀时，一性如山不动，三清上圣，到处随现，不在功全。","不须行满，一志无疑，上圣劝诸门弟，肯忘形忘体，随我升天。"]},{"t":"沁园春","f":"曲","c":["瑞雪翻云，长风舞浪，仙家画图。","问城南老树，如今在否，洛中强客，还再来无。","独上君山，渺观磊石，八百里清波漾巨区。","何曾错，有茶中上灶，酒里仙姑。","终须度了肩吾。","却稽首终南众老夫。","自太平寺里，题诗去后，东林沉宅，大醉归欤。","天上巡多，人间到少，更不向庐山索鲙鱼。","相怜否，好借君黄鹤，上我清都。"]},{"t":"沁园春","f":"曲","c":["古往今来，一刹那间，又早百年。","任石崇富贵，陈平贫贱，颜回短命，盗蹠长年。","南陌新阡，北邙旧冢，尽是许多愚共贤。","全不见，金钗十二，珠履三千。","只因不炼还丹。","个个道凡夫无宿缘。","庭前顽石，尚能听法，城南老树，犹解成仙。","斗酒篇诗，张琴只剑，且结人间欢喜缘。","人问我，如何是道，笑指青天。"]},{"t":"沁园春","f":"曲","c":["大道无名，大音希声，大器晚成。","笑迷人管见，不言便了，似钻冰取火，纽石为绳。","使尽精神，虚劳神用，缘木求鱼甚日烹。","愚痴辈，磨砖作镜，怎睹光明。","何须百计经营。","守朴朴淳淳绝爱憎。","澄虚心实腹，谷神不死，深根固蒂，久视长生。","湛湛澄澄，先天先地，一气寥寥混杳冥。","希夷理，这一轮皎月，无缺无盈。"]},{"t":"沁园春","f":"曲","c":["不喜轻裘，布衣芒履，任春与秋。","傍人笑我生涯拙，尘寰碌碌，毕竟何求。","物外蓬瀛，壶中方寸，论此宗风没价酬。","谁知道，无为快乐，不羡王侯。","多谋转使多愁。","恰似吞他名利钩。","看日前些子升沉事，把天机丧尽，不肯抽头。","蜂为花忙，蛾因灯逝，只恁迷前忘后忧。","嗟身事，庄周蝶梦，蝶梦庄周。"]},{"t":"沁园春","f":"曲","c":["瑞雪长空，布满周天，色似银。","况此物不论贫富，应无深远，触处皆均。","片片不教尘污，落处冥冥不听声。","江天静，见天华宇宙，景物皆新。","教人蓦地欢欣。","似一派银河彻底清。","聚时节如铺玉，散来后，无迹无影无形。","此是天机真造化，一比寻常假造成。","阴消尽，待三阳数足，别换新春。"]},{"t":"沁园春","f":"曲","c":["昨夜南京，今朝北岳，倏焉忽然。","遇洞中有酒，渴来好饮，君山作枕，醉后高眤。","出入无迹，往来不定，半似痴呆半似颠。","随身处，有一襟风月，两袖云烟。","人间漂荡多年。","又排办东华第二筵。","把玉楼推倒，种吾琪树，黄河放浅，栽我金莲。","击碎珊瑚，翻身蓬岛，稽首虚皇御座前。","无难事，功成八百，行满三千。"]},{"t":"沁园春","f":"曲","c":["绝品龙团，制造幽微，建溪路赊。","向南山采的，蟾酥乌血，和合北海，七宝灵芽。","时遇阳春，收归璚室，碾磨捣、香尘腻水加。","玉瓯内，仗仙童手巧，烹出金花。","奇茶堪献仙家。","但啜罢香生两腋，侥幸赵州难遇，卢仝不见，苦中甘味，意与谁夸。","涤尽凡心，洗开道眼，返老还童鬓似鸦。","真奇瑞，愿人人解饮，同赴烟霞。"]},{"t":"沁园春","f":"曲","c":["打破疑团，谢了空花，饮啄随缘。","有蒲团禅版，消磨白日，临风对月，可度流年。","携个山童，拖条藜杖，闲趁松风影里眠。","从今后，袖金针玉线，顿锁为烟。","何须祖祖相传。","被渭水松风泄尽禅。","昔年会向，水中摸月，如今却解，火里生莲。","向上宗乘，别无玄妙，十百元来是一千。","翻身处，见沤停巨海，云散长天。"]},{"t":"沁园春","f":"曲","c":["自古神仙，隐迹终南，万代流传。","说经台上，针活枯柏，炼丹炉下，化女石泉。","四皓商山，十老古洞，尹喜亲闻道德篇。","结庵处，有青牛系柏，白鹿升天。","翊圣古迹依然。","雪样三朝画得全。","有元真文涧，松阴一梦，钟离悟道，跨鹤金仙。","二祖披毡，甘河引度，传受重阳七朵莲。","全真教，洞天福地，象帝之先。"]},{"t":"苏幕遮","f":"曲","c":["精气神，须保爱。","一粒金丹，每在街头卖。","四十年来无人买。","闹花丛里，还了鸳鸯债。","九三爻，地天泰。","离上金乌，飞入银蟾界。","百尺竿头做一解。","这些工夫，任使傍人赛。"]},{"t":"苏幕遮","f":"曲","c":["叹人身，如傀儡，五彩妆成，尽是虚瞒昧。","叉手棚头谈今古。","相呼相唤，空向人前舞。","出来时，如风雨。","气断之时，七魄三魂去。","饶你棚前捶画鼓。","唤不回头，终没回来路。"]},{"t":"苏幕遮","f":"曲","c":["子细听吾教诲。","说与门生，莫把真心昧。","若是不除堕口债。","走入轮回，今世人身败。","鬓发苍，休得怪。","莫恋凡胎，假合终须坏。","无事清闲炼丹台。","自尔纯阳，随我蓬莱会。"]},{"t":"苏幕遮","f":"曲","c":["日常行游四海。","每日街前，闹处为乞丐。","口口相违化不回。","暗损精神，只为凡情昧。","苦劝君，生死大。","颇奈顽愚，作业贪心煞。","不肯修真犯天戒。","堕落酆都，受苦无年代。"]},{"t":"孤鸾","f":"曲","c":["虾须初揭。","正社日停针，窗风鸣铁。","懒自梳妆，乱挽鬟儿非滑。","追想昨宵瞥见，有多少、动情谁说。","枉在屏风背后，立歪罗袜。","听玉人言去苦难泄。","任树上黄莺叹离别。","强欲排余恨，反寸肠悲裂。","试使侍儿挽住，想未离、画桥东折。","传道行踪已远，但垂杨烟结。"]},{"t":"念奴娇","f":"曲","c":["鸳帏睡起，正飞花兰径，啼莺琼阁。","对镜梳妆，愁见那、怯怯容颜瘦弱。","一任仙郎，题诗寄简，屡订西厢约。","墙花拂影，独眠何事如昨。","谁怜潘果空投，贾香难与，愁肠安托。","带眼轻拴须看取，杨柳腰肢如削。","珠履玲珑，罗衫雅淡，件件无心着。","何时厮近，得偿今日萧萦。"]},{"t":"枕屏子","f":"曲","c":["涉历名山，岩峦尽皆游过。","上高坡。","登峻岭，劳神怎么。","道在身，心着物，交加相躲。","终不失、本来这个。","白日同行，晚来同眠同卧。","到天明、相逐定，同行共坐。","蓦然地，忽然间，分明识破。","元来是大哥。"]},{"t":"武陵春","f":"曲","c":["物物般般都放下，熟境自然休。","忙里偷闲闹处收。","不挂一丝头。","动静不拘无动静，法界莫能归境丘。","逍遥物外，游性似水晶球。"]},{"t":"青门引 题古阳关","f":"曲","c":["凭雁书迟，化蝶梦速，家遥夜永，翻然已到。","稚子欢呼，细君迎迓，拭去故袍尘帽。","问我假使万里封侯，何如归早。","归运且宜斟酌。","富贵功名，造求非道。","靖节田园，子真岩谷，好记古人真乐。","此言良可取，被驴嘶、恍然惊觉。","起来时，欲话无人，赋与黄沙衰草。"]},{"t":"青玉案","f":"曲","c":["无为大道人难晓。","只为工夫少。","猛悟回光常返照。","三田之内，六府之中，尘垢频频扫。","诸缘断处清怀抱。","一点虚灵自耀。","认得玄元清静道。","百关调畅，一性圆明，得出游仙岛。"]},{"t":"青梅引","f":"曲","c":["我笑迷人，不信乖劣。","痴心恋，贪名利萦系。","落魄狂游，每将术艺养道，用安身己。","道知和息。","藜杖药瓢，蓑衣蛮笠。","纵大地有满地正珠，那的直甚闲气。","无限峰峦耸翠。","略撰个茅庵，用做栖心，幸有灵苗裔。","更兼泉水。","饥渴自然无痴。","独坐深山里。","闷看乾坤间隔，望落落如晓星之势。","再遇何年，驾云朝上帝。"]},{"t":"临江仙","f":"曲","c":["昨夜惊眠梅雨大，枕前窗上频敲。","天明翻觉梦魂遥。","起来看女伴，薰袖已香消。","云锁房栊烟锁竹，卷帘水湿鲛绡。","菱花低照拂眉梢。","玉梳云发润，不喜上兰膏。"]},{"t":"临江仙","f":"曲","c":["达道逍遥无事客，狂歌度日欣欣。","孤然一性朗然真。","清如三岛月，闲似九霄云。","语话参差绝世梦，心头不挂微尘。","四时游玩百花亲。","壶中天不夜，物外景长春。"]},{"t":"临江仙","f":"曲","c":["花影半帘初睡起，绣鞋着罢慵移。","窥妆强把绿窗推。","隔花双蝶散，犹似梦初回。","纤指弹瓯呼女伴，出帘那共徘徊。","闲将罗袖倚朱扉。","楼台临水处，日午燕争飞。"]},{"t":"南乡子","f":"曲","c":["生甲更生庚。","此是丹头切要明。","药嫩采来归土釜，煎烹。","文武刚柔次第行。","片饷结丹成。","沐浴防危更守城。","到此不须行火候，持盈。","火若加临必定倾。"]},{"t":"挂金索（北曲）","f":"曲","c":["三更里，阳生子母朝金阙。","海底灵龟，吸尽金乌血。","一气绵绵，三关都透彻。","万道霞光，捧出西江月。"]},{"t":"挂金索（北曲）","f":"曲","c":["一更里，澄心下手端然坐。","赶退群魔，队队白羊过。","剔起心灯，照见元初我。","方寸玲珑，宝珠悬一颗。"]},{"t":"挂金索（北曲）","f":"曲","c":["养元初。","心猿意马牢栓住。","六贼尽、不曾贪图。","杳杳冥冥，昏昏默默处。","湛湛澄澄，性停命住。"]},{"t":"挂金索（北曲）","f":"曲","c":["聪明君子，一一听分诉。","甲子天年，看看降真数。","跳出凡笼，一个长生路。","免教阎王，鬼使来勾取。"]},{"t":"挂金索（北曲）","f":"曲","c":["二更里，人静万事都无染。","一对金蟾，上下来盘旋。","吓退三尸，奔走如雷电。","白雪漫漫，降下琼花片。"]},{"t":"挂金索（北曲）","f":"曲","c":["无忧虑。","孤云野鹤无拘束。","草庵内、闲看金书。","窗外林泉，隈山傍水竹。","明月清风，堪为伴侣。"]},{"t":"挂金索（北曲）","f":"曲","c":["过了一年，又是添一岁。","每日随缘，争甚闲和气。","可怜韶华，奔走如拈指。","莫待临头，腊月三十日。"]},{"t":"挂金索（北曲）","f":"曲","c":["行功足。","蓬莱三岛群仙聚。","瑶池会、圣贤无数。","尽是修真，学道列仙侣。","侍奉高真，西王圣母。"]},{"t":"挂金索（北曲）","f":"曲","c":["认真趣。","木金间隔通玄路。","驱四象、五行圆聚。","气结神凝，阴阳自返复。","遍体薰蒸，周天火足。"]},{"t":"挂金索（北曲）","f":"曲","c":["法轮鼓。","河车稳稳三十幅。","搬日月、辊入金炉。","玉鼎烹煎，九阳真火煮。","万道霞光，千重翠雾。"]},{"t":"挂金索（北曲）","f":"曲","c":["境堪图。","翱翔云水纵横步。","曲江上、飞乌走兔。","虎绕龙蟠，坎离相会聚。","斡转天关，运动地轴。"]},{"t":"挂金索（北曲）","f":"曲","c":["我爱闲居，心境常皎洁。","境灭情忘，自然无分别。","云散长空，露出清霄月。","此个家风，有口难分说。"]},{"t":"挂金索（北曲）","f":"曲","c":["斋罢闲行，独唱无人和。","山里樵夫，也唱哩凌啰。","上了一个坡。","下了一个坡。","便做高官，也只不如我。"]},{"t":"挂金索（北曲）","f":"曲","c":["享天厨。","仙衣挂体身轻举。","乘鸾凤、玩赏清都。","宝殿璚楼，金钉满朱户。","不夜长春，无来无去。"]},{"t":"挂金索（北曲）","f":"曲","c":["四更里，无事四边都宁静。","内放心花，赏玩长春景。","戊己门开，有个真人进。","一粒金丹，运上昆仑顶。"]},{"t":"挂金索（北曲）","f":"曲","c":["有中无。","无中更有些儿做。","有无中、里面搜取。","无内藏真，有内却如无。","有无双忘，还同太虚。"]},{"t":"挂金索（北曲）","f":"曲","c":["五更里，天行还了修行愿。","龙虎相交，倒把黄河卷。","半空里雷声，鬼神难测辩。","认得元初，本来真头面。"]},{"t":"挂金索（北曲）","f":"曲","c":["应仙举。","汞铅黑白希夷路。","端的下、苦志工夫。","昼夜无眠，粗衣淡饭足。","乞化街头，十方父母。"]},{"t":"挂金索（北曲）","f":"曲","c":["破昏衢。","地雷震动山头雨。","黄芽长、白雪飞舞。","露洒琼浆，瑞草满园圃。","玉蕊纷纷，金花绽吐。"]},{"t":"挂金索（北曲）","f":"曲","c":["奉劝人人，一一听分诉。","不晓阴阳，怎知修行路。","始初下手，炼就铅汞体。","自有龟蛇，引入曹溪路。"]},{"t":"挂金索（北曲）","f":"曲","c":["罩明珠。","化生养就胎仙舞。","真庆会、姹女圆聚。","渴饮琼浆，玉琴自然抚。","韵定仙音，敲金击玉。"]},{"t":"春从天上来","f":"曲","c":["识破荣枯。","万事俱忘，宴处村墟。","盖世功名，掀天富贵，不免被物驰驱。","叹南柯梦里，断送了、多少贤愚。","这田庐。","算人人有分，谁肯归欤。","独余洒然脱颖，任运止逍遥，自在无拘。","蓑笠间堆，琴书高挂，活计冷淡潇疏。","向松间石上，吟风月、云水情摅。","伴清虚，枕烟霞高卧，真乐无余。"]},{"t":"春从天上来","f":"曲","c":["乐道安贫。","叹自古英雄，林下无人。","满堂金玉，谓授儿孙。","毕竟与属亲。","问当初无物，被贪爱、引入迷津。","早抽身。","向槐安宫内，刚恁劳神。","朝菌蟪蛄短景，又岂信壶中，别有长春。","暂游万里，少别千年，归去跨凤骖麟。","念浮生一瞬，几度见、沧浪扬尘。","莫因循。","彼空华扬艳，轻丧天真。"]},{"t":"春从天上来","f":"曲","c":["日月高奔。","这奥妙机，尘世难闻。","太一壶中，清江谷口，芝草发兰薰。","看金莲佳景，吐庆云、开显生门。","道惟尊。","更资成万化，覆载乾坤。","如何四时受用，要绵绵默默，固蒂深根。","逆顺阴阳，穷通今古，应变无有如神。","此希夷至理，超名相、顿了天真。","到头人向华胥相会，同赏阳春。"]},{"t":"昭君怨","f":"曲","c":["学道须凭一志。","无志难逃生死。","对境志如山。","自然安。","万法不离清净。","性定方能得命。","会得这玄空。","道必通。"]},{"t":"昭君怨","f":"曲","c":["坐后谈禅说道。","起后不依些少。","心口自寻思。","好呆痴。","目用机关千万。","何曾灭了一件。","欲望做神仙。","好难天。"]},{"t":"朝中措","f":"曲","c":["布袍草履历天涯。","朝市与云霞。","随分有些活计，杖挑周易南华。","客来问我浮世事，无言指落花。","炼就水云情性，脚踏到处为家。"]},{"t":"柳梢青","f":"曲","c":["悟个不生不灭。","更不许、拈花摘叶。","兴则高歌，醉眠芳草，梦游仙阙。","有时苦劝人人，莫呀我、叮咛切切。","走骨行尸，贪财恋色，枉消年月。"]},{"t":"点绛唇","f":"曲","c":["小小瓢儿，生得天然诧。","身矬矮。","瓢儿元有口，难开解。","认得乾坤，此理谁能解。","腰间常道人偏爱。","不换金鱼袋。"]},{"t":"贺圣朝","f":"曲","c":["野僧归后，渔舟才缆，绿桧生烟。","对寒灯、潇洒枕书眠。","听石漱流泉。","丹炉火灭，琴房人静，风自调弦。","待孤峰顶上月明时，正一梦游仙。"]},{"t":"贺圣朝","f":"曲","c":["草堂初寐，青衣扃户，丹项归巢。","抱瑶琴高枕，梦游仙岛，待闲访三茅。","中宵睡觉，声如鸣佩，竹被风敲。","隔疏林斜望，隔疏林斜望断云飞，正月上松梢。"]},{"t":"贺新郎 题西湖官驿水阁","f":"曲","c":["倩来鸾传语，问陆家、兄弟翩翩，今归何处。","留下文章藏万壑，时作云烟吞吐。","谩徙倚、朱兰凝伫。","阑外瑁湖谁管领，叹先生、旧宅僧分住。","天下事，尽如许。","英雄总被虚名误。","览遗编浩叹，寂寞一抔寒土。","惟有春风长往，催却几多人去。","但岁岁、垂杨自舞。","今日我来怀古后，算后人又以今为古。","留此曲，伴鸥鹭。"]},{"t":"浪淘沙令","f":"曲","c":["一个主人翁。","住在灵宫。","无形无影亦无踪。","铁眼铜睛观不见，体似虚空。","出入不通风。","天地难笼。","被吾擒在药炉中。","运起周天三昧火，锻炼真容。"]},{"t":"浪淘沙令","f":"曲","c":["修竹间青松。","翠影重重。","道家楼阁白云中。","隔岸红尘飞不到，水浸寒空。","此景与谁同。","洞口仙翁。","素琴弹罢倒金钟。","笑傲烟霞无一事，明月清风。"]},{"t":"烛影摇红","f":"曲","c":["金菊初开，玉蟾新满升天皎。","重阳佳致始恢弘，圆鉴亭亭照。","上界中央奋矫。","桂花鲜、云收八表。","绿枝袅袅。","素魄团团，于中奇妙。","细蕊繁英，洞天幽圃知多少。","高台深夜最堪观，得遇圆明了。","风动清香盘绕。","烂银霞、交光池沼。","一丛霜气，万古冰轮，冲和谁晓。"]},{"t":"粉蝶儿","f":"曲","c":["欲识还丹，认取自家宗祖。","便不计、当初来处。","是谁人，椿胎骨，谁人捏塑捉住。","这一灵性，元来是铅结聚。","既已为人，要了自家龙虎。","便不会却擒捉住。","把金丹一粒，吞来入腹。","恁时免得，转回受苦。"]},{"t":"绣薄眉","f":"曲","c":["化愚鲁。","抛离火院夫儿女。","凭慧剑、斩断三涂。","人我山崩，是非海己枯。","旧业消除，新殃不做。"]},{"t":"莺啼序","f":"曲","c":["三峰路险，雪满空崖，瑞祥烟雾起。","涧畔听、龙吟虎啸，电闪星辉，迸出红光，鬼神惊避。","铅凝汞结，炉中养就丹点，瓦史成至宝，愚人餐一粒，延年纪。","那堪更有，神珠万颗，流霞晃耀，遍穿宫里。"]},{"t":"逍遥乐","f":"曲","c":["天边月，初似弓。","庚地又无踪。","龙寻虎，虎寻龙。","两相逢。","结一朵、金花弄风。","天边月，似偃炉。","铅汞鼎中居。","须凭火，炼流珠。","一葫芦。","三百八十有四铢。"]},{"t":"减字木兰花","f":"曲","c":["并州霜早。","禾黍离离成腐草。","马困人疲。","惟有郊原雀鼠肥。","分明有路。","好逐衡阳征雁去。","鼓角声中。","全晋山河一半空。"]},{"t":"探春令","f":"曲","c":["草堂三鼓梦游仙，到蓬壶阆苑。","正白云满地无人扫，信幽圃，香风旋。","群真朝列黄金殿。","醉流霞璚宴。","顿觉来一片清凉意，似明月，山头见。"]},{"t":"望梅花","f":"曲","c":["日向南窗犹睡。","疏篁外、柴门从闭。","蓦有人来，轻轻敲户，才是转身慵起。","正浓美。","一味黑甜，问人间、甚物堪比。","除是沉沉烂醉。","忘惊悸、又忘乘坠。","乘也不知，坠也不知，齐生死、一同天地。","这些意。","味悟难知，却如同、哑子做谜。"]},{"t":"望梅花","f":"曲","c":["死生于身最大。","从来与我为害。","饥则求餐，渴而索饮，寒来又寻衣盖。","好难挨。","昼夜相随，殃得我来忒杀。","舍了娘生皮袋。","分付了、两家自在。","行则穿云，倦则卧月，游戏太虚无碍。","甚轻快。","捉住风轮，跨神鳌、遍超法界。"]},{"t":"望梅花","f":"曲","c":["百岁韶华如电。","空回首、又来一遍。","贩骨轮回，千生万死，只管改头换面。","要得免、捉住清风，把虚空、打破一片。","不诵南华经卷。","也不要、葛藤相伴。","截断中流，剔开心眼。","射透玉楼金殿。","莫回转。","一志无移，看山头、明月出现。"]},{"t":"望梅花","f":"曲","c":["莫见他人长短。","搜己过、不教自乱。","旧日心猿，元来意马，却唤醒、渐驯羁绊。","澄心内观。","炼就冲和，把凡胎抽换。","事到眼前决断。","教神仙、别无手段。","地久天长，虚心实腹，善计者、不须筹算。","行功满。","跨朵祥云，去朝元、得居仙馆。"]},{"t":"望梅花","f":"曲","c":["是是非非休辩。","好弱到头自见。","莫说他人，休昧自己，暗里圣贤自见。","听我劝。","自古今，何曾放过一件。","好把尘缘拂散。","清清净净，始终莫变。","固蒂深根，长生久视，难免韶华易换。","气神炼。","遇个知音，希夷理、说与一遍。"]},{"t":"望梅花","f":"曲","c":["密密彤云覆地。","蓬蓬然、朔风又起。","大块呼吸，阳凝阴结，遍四野、玉花呈瑞。","这些意。","圣感丰年，显唐虞、再来治世。","敬道尊儒修义。","崇三教、共同一体。","子孝孙贤，臣忠朝正，上下尽成和气。","宝鼎内。","爇炷名香，祝皇王、寿延万岁。"]},{"t":"梅花引","f":"曲","c":["嵋山老。","头白早。","人间善恶都曾造。","也曾穷。","也曾通。","穷通得失，浑如一梦中。","因穷落得身无辱，因闲落得心无事，莫才高。","莫名高。","才名高显，于身展转劳。","知事少。","烦恼少。","心忘腹热何时了。","眼休抬。","口休开。","纷纷是非，如何得到来。","独来独往无伴侣，自斟自酌无荣辱，任人非。","任人疑。","心闲自有，清风皓月知。"]},{"t":"梧叶儿 失题","f":"曲","c":["青铜镜，不敢磨，磨著后照人多。","一尺水，一尺波，信人唆，那一个心肠似我。"]},{"t":"梧叶儿 秋","f":"曲","c":["秋来到。","渐渐凉。","寒雁儿往南翔。","梧桐树。","叶又黄。","好凄凉。","绣被儿空闲了半张。"]},{"t":"梧桐树 其二","f":"曲","c":["二更里，传宇宙。","一点灵光渐通透。","虎龙功交严抵备，三尸莫教走。","慧剑空中报冤雠。","斩却群魔首。"]},{"t":"梧桐树 其三","f":"曲","c":["三更里，一阳动。","金鼎熬煎玉炉烹。","炼就真铅汞。","匠手凿开玉莲蓬。","两道霞光照昆顶。","万颗珍珠迸。"]},{"t":"梧桐树 其一","f":"曲","c":["一更里，调神气。","意马心猿尽拘系。","莫放闲游戏。","昏昏默默炼胎息。","开却天门地户闭。","果然通玄理。"]},{"t":"梧桐树 其五","f":"曲","c":["五更里，朦胧定。","心养皓月一轮镜。","照破贪嗔病。","这回须要鬼神惊。","只要真清为真静。","功满朝上圣。"]},{"t":"梧桐树 其四","f":"曲","c":["四更里，云收彻。","海底星龟弄明月。","处处琼花结。","火候抽添按时节。","子午氤氲降红屑。","猛把天机泄。"]},{"t":"渔家傲","f":"曲","c":["我有光珠无买价。","光明常照芝田下。","更无之乎并者也。","知音寡。","世间谁是能行者。","一万精光神守舍。","四百四病都齐罢。","透出火龙归造化。","回仙驾。","更无一点尘随马。"]},{"t":"渔家傲 四首","f":"曲","c":["至道不遥只在迩。","毫厘差失如千里。","道是难求元却易。","如相契。","一超直入如来地。","水火交时为既济。","三尸六贼都回避。","只此长生仍久视。","身口意。","化成一点冲和气。"]},{"t":"眼儿媚 更闺","f":"曲","c":["石榴花发尚伤春。","草色带斜曛。","芙蓉面瘦，蕙兰心病，柳叶眉颦。","如年长昼虽难过，入夜更消魂。","半窗淡月，三声鸣鼓，一个愁人。"]},{"t":"菩萨蛮","f":"曲","c":["家家尽有长生药。","时人取用皆差错。","气候若飞沉。","问君何处寻。","眼看犹不识。","误向铅中觅。","此物没黄芽。","徒劳岁月赊。"]},{"t":"谒金门","f":"曲","c":["真堪惜。","锦帐夜长虚掷。","挑尽银灯情脉脉。","绣花无气力。","女伴声停刀尺。","蟋蟀争题四壁。","自起卷帘窥夜色。","天青星欲滴。"]},{"t":"喜迁莺","f":"楚辞体","c":["欲调真息。","论根源参到，生前实际。","气是心兮，神为气主，心动神气分离。","心宁子母相抱，意定自成真液。","莫错识。","这内调息，非干扭捏，不晓胎元理。","开目和鼻指。","灵龟蛇戏。","祖道家风，回光返照，呼吸自归根蒂。","清风瞥然透户，水火刹那既济。","至此理。","要真常咫尺，三生佛出世。"]},{"t":"喜迁莺","f":"曲","c":["利名抛却。","入广莫乡闾，委蛇盘礴。","水曲山隈，烟村云屋，随分葛衣藜藿。","任他玉堂轩冕，争似茅庐丘壑。","志廖廓。","向东篱消遣，西园吟酌。","绵邈。","无为作。","不遇个人，何处谈玄略。","书笈琴囊，石坛瓦鼎，此外并无真乐。","幽雅淡然风范，端的凭谁光烁。","自消索。","有一溪松月，千年猿鹤。"]},{"t":"喜迁莺","f":"曲","c":["莫寻玄妙。","我分明说破，修行关窍。","战睡敌魔，忘情绝念，此是圣贤正教。","饮食则定除疑，每日勤修觉照。","莫差了。","待无眠无睡，心方合道。","别有玄和妙。","炼气成神，自有金光罩。","五气朝元，三花聚顶，水火运行颠倒。","九阳结就还丹，射透灵台八表。","功行了。","向长生路上，闲游三岛。"]},{"t":"喜迁莺","f":"曲","c":["万缘多暇。","便杖屦闲游，田园邻舍。","雨笠风巾，鹑衣鹤骨，韬晦翠微峰下。","眼底世情群扰，方外天机独霸。","德风化。","乐清虚恬淡，无为华夏。","幽雅。","云鹤驾。","归去故园，莺燕吟王谢。","水石清华，岩壑深远，高迈软红车马。","千古是非成败，一枕烟霞溪野。","妙哉也。","这生涯欲卖，谁能酬价。"]},{"t":"喜迁莺","f":"曲","c":["返观尘世。","便摆脱羁么，逍遥能几。","短褐纶巾，斑筇焦尾，便是自家归计。","个人问为何隐，遥指松萝苍翠。","碧霞里。","有洞庭猿鹤，交朋知己。","无比。","清闲贵。","高枕老庄，不尚公侯位。","水夸山鞋，烟蓑月笛，别是一般风味。","安得这些消息，自古神仙网纪。","遂吾忘。","任桑田改变，浮生兴废。"]},{"t":"喜迁莺","f":"曲","c":["死生都怕。","这轮回贩骨，如何得罢。","不悟真常，强生枝节，性命了达不下。","有中不解，无中无里，难明真假。","离万法。","这本来一点，何处安搭。","敢问些儿话。","修真养性，如何凭执把。","甚是明心，甚为见性，甚是万缘不挂。","甚为明月清风，甚是玲珑脱洒了。","真法告，师父慈悲，提携点化。"]},{"t":"喜迁莺","f":"曲","c":["顿消缘虑。","觉梦蝶劳生，鹑居蓬户。","饭蚁醯鸡，尘衫风帽，赢得百年虚度。","利如断霞残照，名若落花飞絮。","岂坚固。","似风中秉烛，枝头垂露。","谁悟。","独归去。","收拾水云，高卧曹溪路。","竹外流泉，篱边丛菊，妆点野棠闲趣。","五柳槛前吟醉，一笑人间今古。","欲分付。","叹烟波渺渺，知音何处。"]},{"t":"喜迁莺","f":"曲","c":["死生不怕。","仗刚风一扫，般般都罢。","独露真常，不生枝节，性命亦无高下。","亦无内外，其中就里，元无真假。","明万法。","这真如一点，不须安搭。","悟得无生话。","无作无为，大道无执把。","六二明心，时时见性，只此万缘不挂。","处处明月清风，端的玲珑脱洒了。","真法真空自在，不生不化。"]},{"t":"喜迁莺","f":"曲","c":["厌离尘垢。","便志乐虚闲，清净为友。","剑挂寒光，兵安云将，战胜五行之寇。","收得洞玄灵宝，跳出阴阳之壳。","大丹就。","炼摘骑日月，摩挲星斗。","英秀。","超前后。","随应万机，明显神通手。","铁板门庭，金针玉线，到处七穿八透。","引出锦麒狮子，振水禽山兽。","速回首。","向碧霞堆里，高眠清昼。"]},{"t":"喝马一枝花","f":"曲","c":["雨过山花绽。","雾敛云收天汉。","清闲幽雅处游玩。","古洞岩前，时把金丹炼。","不爱乘肥马，富贵荣华，是非多不须管。","独坐茅斋看，闲把道经时展。","横琴膝上抚、鹤来见。","紫绶金章，是则是、官高显。","五更忙上马，争似我仙家，日午柴门犹掩。"]},{"t":"遍地锦","f":"七言绝句","c":["十九抛家弃俗缘。","磻溪下志便安然。","悟得长春不夜天，大教门开万古传。"]},{"t":"遍地锦","f":"七言绝句","c":["吾本当初马半州。","因与先师说根由。","独坐圜墙向内修。","功成行满赴瀛洲。"]},{"t":"遍地锦","f":"七言绝句","c":["三宣赐紫住天长。","便是云光铁脚王。","因遇先生赴洛阳。","功成行满到仙乡。"]},{"t":"遍地锦","f":"七言绝句","c":["吾本当初本姓孙。","马家门下结婚姻。","因为先师点破心。","各自分头觅主人。"]},{"t":"遍地锦","f":"七言绝句","c":["太古今日说因由。","赵州桥下度春秋。","唱住桥边水不流。","一叶落时天下秋。"]},{"t":"遍地锦","f":"七言绝句","c":["吾本当初水竹村。","甘河镇上便狂风。","七朵金莲朵朵新。","丘刘谭马郝王孙。"]},{"t":"遍地锦","f":"七言绝句","c":["四大假合本姓谭。","前缘相遇弃俗缘。","天下云游不住庵。","功成行满赴仙坛。"]},{"t":"遍地锦","f":"七言绝句","c":["莱州武观是吾乡。","因遇先生号长生。","穿街柳巷也无妨。","不染尘埃性月朗。"]},{"t":"满江红","f":"曲","c":["买得青山，便收□、草鞋藜杖。","更不过建章宫下，灞陵桥上。","天地蜗牛蛮触待，功名蚁穴槐安相。","近新来、白发几多长，三千丈。","从今脱，红尘网。","青石枕，松风响。","有商山四皓，□闲来往。","火枣便宜秋露滴，交梨正要春温养。","算古来、谁似我逍遥，陶元亮。"]},{"t":"满江红","f":"曲","c":["一片闲心，髑髅子、无穷生灭。","被化机搬弄，驰骤许多颠□蹶。","贩骨如山成底事，迷情似海难超越。","痛亘初、灵物被尘埋，尘沙劫。","求出离，须猛烈。","寻知友，谈冰雪。","下工夫磨炼，灵光明彻。","风定波澄潭底见，云开冷浸天心月。","问哑人、食餐蜜味如何，无言说。"]},{"t":"满江红","f":"曲","c":["今古高情，都缘在林泉江曲。","知此身如幻，宁羡锦衣华屋。","雅志偏怜雕浦月，达人岂羡金山玉。","喜满庭、花影日筛金，苔斑绿。","终焉计，东篱菊。","虚心杖，南轩竹。","枕琴书高卧，坦然无辱。","万古兴亡春梦觉，一溪云水平生足。","看武陵三秀喷幽香，芝田熟。"]},{"t":"满江红","f":"曲","c":["元本当初，无一物、万缘蒙漠。","叹同流学道，谁肯死前除削。","两掌三拳空热闹，扬眉瞬目千般作。","看眼光、落地见贤家，抬手脚。","绝妄念，忘人我。","名利断，是非躲。","伴烟霞深处，坦然行乐。","境灭心忘无生豁，断云来往寥天廓。","显一轮孤月射寒潭，实无错。"]},{"t":"满江红","f":"曲","c":["雨过东郊，溪痕浅、山堂春晓。","堪爱处，桃花流水，闲云幽鸟。","物表群分红日□，天涯一点青山小。","向绿阴、竹影卷柴扉，终焉了。","清闲处，谁知道。","方外客，人间少。","且襟风杯月，醉眠芳草。","大志含容天地考，真情卓立希夷杳。","谩将消息寄林泉，烟霞老。"]},{"t":"满江红","f":"曲","c":["一片闲心，明洞达、天心无曲。","身未能轻举，权作道家梁屋。","壶内时看吞日月，世间不羡堆金玉。","任自□、虚幻转光阴，披红绿。","丹砂井，黄金菊。","灵芝草，琅玕竹。","对无情潇洒，有何荣辱。","大梦百年方外去，平生万事心头足。","向人间三度见河清，蟠桃熟。"]},{"t":"满庭芳","f":"曲","c":["恬淡家风，寂寥活计，无为无作无言。","行住坐卧，莫放马猿颠。","性有调和柔弱，触来无火无烟。","通真理，无情无欲，无罪亦无愆。","诸公休外觅，天真一点，元在心间。","被黑云遮障，不计余年。","好用清风吹散，云收处、露出青天。","森罗见，一轮明月，光耀照无边。"]},{"t":"满庭芳","f":"曲","c":["过去休思，未来莫想，见前一念俱忘。","三心灭去，显出法中王。","便是生前面目，无形貌、独露堂堂。","玄玄理，四方真气，攒结聚中黄。","闲闲常内守，胜如尘世，苦海茫茫。","任随缘随分，柔弱和光。","渐渐轮回路出，看看近、来到蓬庄。","功成日，携云独步，朝见礼虚皇。"]},{"t":"满庭芳","f":"曲","c":["大道无形，难言难说，世人不晓其根。","不凭清净，数墨强寻文。","若是只凭经典，世间有、多少能人。","都成道，九天之上，塞满玉皇庭。","何须开辩利，休穷周易，罢讲黄庭。","真清真净，心上要无尘。","自有神仙提挈，恁时节、得赴玄门。","幽微处，逍遥快乐，终日啰哩凌。"]},{"t":"满庭芳","f":"曲","c":["道教初兴，释门微显，一兴一废如然。","达磨阐教，东土至西天。","都是后学晚辈，贪酒色、损坏真源。","争财气，不依教法，也望到西天。","三千年一遇全真，大教甲子天年。","丘公阐教，万朵金莲。","上界群仙。","在世诸魔，难道化才贤。","君知否，今番不遇，更待万余年。"]},{"t":"满庭芳","f":"楚辞体","c":["归去来兮，不如归去，算来都是便宜。","也无烦恼，也没是和非。","选个岩前净处，好盖个、小小庵儿。","黄昏后，安眠一觉，直睡到大齐斋时。","此外别无事，逍遥快乐，几个人知。","高官好做，也要追陪。","假若前遮后拥，金鱼袋、厌损朝衣。","思量后，一个口里，插得几张匙。"]},{"t":"满庭芳","f":"曲","c":["昨日花开，今朝花谢，算来眼下时光。","成家立计，劫劫与谁忙。","才见青春年少，霎时间、绿鬓成霜。","堪嗟叹，人身不识，自恁苦无常。","不如早悟，金银过斗，难免无常。","思乡岭上，空滴泪成行。","儿女无个肯替，到头来、独自承当。","听吾劝，回光返照，相伴马丹阳。"]},{"t":"满庭芳","f":"曲","c":["一向沉空，偏枯着静，痴人枉费工夫。","磨砖作镜，缘木欲求鱼。","见月何须用指，观花悟、总是真如。","聪明士，随机解物，无愠无愉。","为仙为佛事，不增不减，非实非虚。","露堂堂，光赫赫，一颗神珠。","混俗凝然不染，居众处、尘法难拘。","知常用，巍巍荡荡，何所不虚无。"]},{"t":"满庭芳","f":"曲","c":["百岁光阴，浑如一梦，不觉过春秋。","憨痴愚昧，日夜为家忧。","衣食前生注定，更何须、物外贪求。","当思忖，深坑火院，终日个如囚。","诸公听我劝，儿孙福禄，莫与为牛。","把恩情挫碎，物外精求。","管甚红轮西坠，尽教他、月出东头。","降心定，回头是岸，咫尺到瀛洲。"]},{"t":"满庭芳","f":"曲","c":["二气旋还，三宫升降，往来于数无穷。","透关神水，铅汞过三峰。","返复周流八脉，戊己炼、阴虎阳龙。","凝精处，金花的的，外见形容。","灵光真造化，天机深远，推测难通。","算利名酒色，恰似秋风。","大道玄炉进火，三田内、养出神功。","功成后，天书来诏，平步赴瑶宫。"]},{"t":"满庭芳","f":"曲","c":["今日荣华，前生福善，悟来更好重修。","百年光景，生灭水浮沤。","贩骨无休歇，劝未尽、又遭愁。","然嗟人世，忙忙造业，几个肯抽头。","清闲归物外，逍遥独步，身内闲搜。","把汞铅颠倒，性月如秋。","直待功成行满，超三界、永列仙俦。","乘云去，真容不朽，免再卧荒丘。"]},{"t":"满庭芳","f":"曲","c":["道释儒门，三教归一，算来平等肩齐。","道分天地，万化总归基。","佛在灵山证果，六年后、雪岭修持。","儒家教，温良恭俭，万代帝王师。","道传秘诀，佛流方便，忍辱慈悲。","大成至圣，岂辩高低。","都是后学晚辈，分人我、说是谈非。","休争气，三尊一体，瞻仰共皈依。"]},{"t":"满庭芳","f":"曲","c":["寿竹长青，寿松高耸，寿山寿水俱全。","寿星寿夜，寿象现中天。","寿祝长生不老，寿香一炷，宝鼎龙涎。","寿童引，寿龟寿鹤，寿烛比金莲。","寿盘添寿果，寿桃初熟，寿满三千。","寿筵歌寿曲，寿酒与流连。","寿从今，去福寿无边。","寿仁者，寿门高大，福寿永绵绵。"]},{"t":"满庭芳","f":"楚辞体","c":["减饭除情，敌魔战睡，圣贤学道根基。","进人退己，用事契心机。","遇境休生烟火，安闲处、性要无疑。","争知道，洪波跳出，却还入希夷。","罢贪酒色酒气，掣开利锁，截断嗔痴。","完全性命，物外何为。","悟彻元初色相，功成也、归去来兮。","乘丹凤，蓬莱宫里，独步访钟离。"]},{"t":"满庭芳","f":"曲","c":["儿女如花，妻颜似玉，算来眼下时光。","积财千万，难买不无常。","蓦地阴公来请，无辞诉、更不推忙。","空归去，资财换主，儿女各分张。","聪明贤达者，早离火院，躲了忙忙。","逍遥散诞，落个清闲，饥后巡门化饭，寒来纸布衣裳。","无牵系，神仙未了，落得寿延长。"]},{"t":"满庭芳","f":"曲","c":["身是庵儿，性为庵主，耳目便是门窗。","壁中为舍，腹是厨房。","心是当厨博士，运水火、炼就元阳。","心宁守，依时饭熟，盛与主人尝。","休出庵外去，些儿迷路，难奔家乡。","端然庵内坐，修补中央。","运就金梁玉柱。","透清风明月灵光。","安然坐，不摇不动，怕甚恶风霜。"]},{"t":"满庭芳","f":"曲","c":["搭手寻思，百年如梦，算来何不清闲。","逍遥快乐，且乐一身安。","日月韶光似箭，不觉人老花残。","思今古，从前勇猛，尽葬在北邙山。","不如心行善，无烦恼，养就朱颜。","怕无常限到，意马牢拴。","神气休教败坏，锁白牛、常在金栏。","修行事，自家性命，莫作等闲看。"]},{"t":"满庭芳","f":"曲","c":["石火光阴，人身不久，算来生死难防。","忽生或灭，恰似电争光。","识破形骸假合，寻得个、出世仙方。","思量后，回心向道，要认个法中王。","时时常见面，同行同坐，同饮霞浆。","同伴清风明月，同一志、同见天光。","同相会，同师访道，同唱满庭芳。"]},{"t":"满庭芳","f":"曲","c":["这炷名香，天然清秀，生于象帝之先。","金炉焚处，袅袅起祥烟。","不是沉檀乳降，亦不是、四和龙涎。","括来献，先贤后化，五祖大罗天。","此香灵妙处，遍周法界，气味真全。","开人鼻窍，入至通玄。","愿八荒四海，同沾至化，道气绵绵。","从今后，一人有庆，万万余年。"]},{"t":"满庭芳","f":"曲","c":["稽首诸兄，略听吾劝，化饭朝日随缘。","残余好恶，只要自心坚。","饱后归庵静坐，无益语、闭口藏言。","他人过，见如不见，方寸得安然。","且休寻玄妙，牢拴意马，紧锁心猿。","去除人我，灭火消烟。","昼夜敌魔战睡，常寂静、调息绵绵。","君知否，如斯妙用，子母自团圆。"]},{"t":"满庭芳","f":"曲","c":["命似清风，性如朗月，莹然独见辉辉。","灵光普照，何日不归依。","常在无明之处，任升腾、斗转星移。","通真理，不无不有，动静应神机。","其间多少事，皆是方寸，或是或非。","在人人运用，志见高低。","悟者头头皆是，未明时、处处皆迷。","修真士，观天行道，功满步云归。"]},{"t":"满庭芳","f":"曲","c":["辰出街头，酉归堂内，切须规矩随身。","志诚香火，早晚去朝真。","遍历名山福地，不耻问、参访高人。","休夸逞，断除人我，心地放教平。","烧丹并炼药，琴棋书画，各有司存。","应干请祈法术，都是谩劳神。","且任随缘乞化，省多少、劳碌精神。","团圞坐，齐同慈爱，异骨总成亲。"]},{"t":"满庭芳","f":"曲","c":["男作行尸，女为走骨，爷娘总是骷髅。","子孙后代，番作小骷髅。","日久年深长大，办资财、匹配骷髅。","聚满堂活鬼，终日玩骷髅。","当家骷髅汉，忙忙劫劫，长养骷髅。","有朝身丧，谁替你骷髅。","三寸主人气断，活骷髅、相送死骷髅。","休悲痛，劝君早悟，照管你骷髅。"]},{"t":"满庭芳","f":"曲","c":["甘草人参，天麻芍药，薄荷荆芥川芎。","乳香没药，白芷共甘松。","玉金□芦桔梗，甘菊花、藁本茯苓。","防风等，细辛分两，各自要均停。","问甚浑身壮热，管甚偏正，夹脑头风。","着将一字嗅鼻中，当下神功有准。","李贵妃曾坏双睛。","竭的效章宗见喜，加做一提金。"]},{"t":"满庭芳","f":"曲","c":["清净家风，如常合道，本来面目休迷。","行住坐卧，何处不相随。","达理头头解脱，明心无作无为。","君还悟，丝毫放过，画饼不充饥。","古今贤达者，仗无情慧剑，斩断昏迷。","把三尸赶退，六贼分离。","云散天心独露，吐红霞、烹炼须弥。","真功至，长生活计，能有几人知。"]},{"t":"满庭芳 武当降笔","f":"曲","c":["玉皇传宣，搜求仙子，六百余员。","仙官仙位，补阙大罗天。","敕下诸神采访，随方所、选觅高贤。","三元日，书人功行，飞奏御炉前。","全真门弟子，修功积行，专要心坚。","猛降龙伏虎，炼汞烹铅。","一旦天书选举，云霄路、快着仙鞭。","朝金阙，三清殿下，作个状元仙。"]},{"t":"满路花岩","f":"曲","c":["四大元无我，五蕴本来空。","休争人与我，逞英雄。","贵贱贤愚，到了梦魂中。","百年亲眷属，电里红光，早宜各自牢笼。","劝君勤修炼，常照主人公。","来时无一物，去时空。","人生有限，贪爱转无穷。","不如随分过，一点灵光，自然明月清风。"]},{"t":"瑞鹤仙","f":"曲","c":["百年如梦蝶。","叹古往今来，多少豪杰。","图王霸业。","谩得渔樵，一场闲说。","秦宫汉阙。","今只有狐踪兔穴。","想荣华秉烛当风，富贵似汤浇雪。","省也，损身薄利害己，虚名却如吴越。","随缘养拙。","柴门掩，是非绝。","向午窗容膝，小溪垂钓，坐对云山万叠。","夜横琴，伴我知音，碧天皓月。"]},{"t":"蓦山溪","f":"曲","c":["不如归去，作个清闲汉。","着甚来由，惹别人、三长两短。","天公许大，何处不容身，且谩着，有生涯，试待寻思看。","鉴湖里面。","浅山林畔。","住个小庵儿，且随分、粗衣淡饭。","嘲风咏月，萧散过平生，尘世事，尽如麻，我也谁能管。"]},{"t":"解红","f":"曲","c":["洞天深处。","道非远，咫尺人难悟。","浮沉内景。","须凭匠手工夫。","专候晓来，一点阳生通玄路。","尽藏在碧波深深处，恁时主。","地雷震动山头雨。","渐浇灌黄芽，乍离土。","婴儿采得携篮去。","向真霞六阳，鼎内烹煮。","搬运转，东西与南北，铺八卦九宫，要知宗祖。","十干数内分左右，要显龙虎。","玄武后随，朱雀当先，祥云布。","曲江上，万神都来聚，夫与妇。","癸母跨赤龙，归洞府。","要寻觅金翁，问凭据。","阴阳会合三千数。","指天地海山，同寿坚固。"]},{"t":"解红","f":"曲","c":["杖藜徐步。","过小桥，逍遥游南浦。","韶华暗改，俄然又翠红疏。","东郊雨霁，何处绵蛮黄鹂语。","见云山掩映，烟溪外，斜阳暮。","晚凉趁，竹风清香度。","这闲里光阴向谁诉。","尘寰百岁能几许。","似浮沤出没，迷者难悟。","归去来，田园恐荒芜。","东篱畔，坦荡笑傲琴书。","青松影里，茅檐下，保养残躯。","一任世间物态，翻腾催今古。","争如我，懒散生涯贫与素。","兴时歌，因时眠，狂时舞。","把万事纷纷总不顾。","从他人笑真愚鲁。","伴清风皓月，幽隐蓬壶。"]},{"t":"解佩令","f":"曲","c":["穇行之士，功勤不小。","识五行、逆顺颠倒。","妙理玄玄，玉炉中、龙蟠虎绕。","金鼎内、炼成至宝。","阳神离体，杳杳冥冥，刹那间、游遍三岛。","出入纯熟按捺住，别寻玄妙。","合真空、太虚是了。"]},{"t":"解佩令","f":"曲","c":["一生蒙懂，世事不晓。","吃茶饭、不知饥饱。","坐处生根，立一似、顽石当道。","任傍人、笑我虚矫。","文艺不解，岂知典教。","说修行、无分剖。","面上尘埃，发髼松、身披衲袄。","永长生、浩劫不老。"]},{"t":"锦堂春","f":"曲","c":["活骷髅。","算来有甚风流。","着衣衫、遮形盖体，弄精神、虚度春秋。","又不念、无常近也，又不怕、阎老来勾。","巧使机关，张罗活计，忙忙劫劫苦贪求。","空热闹虚名薄利，分外惹闲愁。","三寸气，一朝断了，独卧荒丘。","叹古今、几番成败，光阴迅速难留。","好翛闲、修真养性，把从前、伎俩都休。","放下尘劳，悟明心地，凌风飘荡野云收。","江山静，太虚空廓，星月照瀛洲。","真个好，逍遥快乐，不羡王侯。"]},{"t":"锦堂春","f":"曲","c":["睡魔王。","百般作害为殃。","白日间、犹教可，夜更深、无处潜藏。","恼得人、昏如痴醉，怀修行、轻送无常。","眼若胶粘，头如山压，一团昏闷转羸尪。","相勾引，三尸六贼，梦里盗元阳。","般般飞腾法界，万种颠狂。","似这般、无端乖劣，劝诸公、各自堤防。","念死生、前程事大，要殷勤、保护三光。","莫得偎佣，全凭觉悟，神通勇猛赛关张。","相争战，威锋刚硬，一志向前当。","追赶退，云收雾敛，湛湛清凉。"]},{"t":"锦堂春","f":"曲","c":["话衷肠。","悟南柯一梦黄粱。","破繁华、云龛布素，认宗派、返照回光。","凭慧剑、挥开爱网，横藜杖、击碎尘寰。","那里相逢，峨嵋山下，韬光速迸，东华山旁。","林泉隐，南辰北斗，日月袖中藏。","朱颜久，天崩地塌，真性如常。","舞袍袖、乾坤恨窄，但展手、天地平量。","醉陶陶、囊盛四海，笑盈盈、腹注三江。","几度瑶池，龙华会上，诸仙筵宴捧霞觞。","钟离至，玉皇御宴，无我不成行。","重阳会，金莲七朵，齐放神光。"]},{"t":"鹊桥仙 大雨","f":"曲","c":["城中黑潦，村中黄潦，人都道天瓢翻了。","出门溅我一身泥，这污秽、如何可扫。","东家壁倒，西家壁倒，窥见室家之好。","问天工还有几时晴，天也道、阴晴难保。"]},{"t":"鹊桥仙 月蚀","f":"曲","c":["前年蚀了，去年蚀了，今年又盏来了。","姮娥传语这妖蟆，逞脸则管不了。","锣筛破了，鼓擂破了，谢天地早是明了。","若还到底不明时，黑洞洞、几时是了。"]},{"t":"瑶台月","f":"曲","c":["黄粱梦断。","把眼底浮华，须当猛省，凡笼跳出，物外有何萦绊。","镇相随、霞友云朋，任到处、风邻月伴。","逍遥客，无拘管。","游绿水，玩青山，疏散。","这些儿快乐，千金不换。","任人争名夺利权。","且俺咱，觅个左转。","处箪、瓢活计，占断人间慵懒。","乐终朝、一枕高眠，放四大、长舒短展。","红尘内，君试看。","算谁似我清闲。","堪羡。","向闲中，别有拿云手段。"]},{"t":"瑶台第一层 咏茶","f":"曲","c":["一气才交，雷震动一声，吐黄芽。","玉人采得，收归鼎内，制造无差。","铁轮万转，罗撼渐急，千遍无查。","妙如法用，工夫了毕，随处生涯。","堪夸。","仙童手巧，泛瓯春雪妙难加。","睡魔赶退，分开道眼，识破浮华。","赵州知味，卢仝达此，总到仙家。","这盏茶。","愿人人早悟，同赴烟霞。"]},{"t":"酴醾香","f":"曲","c":["自小孤云，身外无萦系。","披一片，搭一片，逍遥快活计。","破葫瓢，腰间挂，别无行李。","是人笑我没操持。","尽教傍人点指。","古庙祠堂，且共泥神作戏。","破砂盆，泼瓦罐，折匙无筋。","破纸被，糊包定，弯跧打睡。","只等待、行满功成朝玉帝。","方表男儿有志。"]},{"t":"踏莎行","f":"曲","c":["花径争穿，珠帘屡认。","正逢梅雨芹泥润。","画梁无处可安巢，玉纤为把花枝衬。","社日才来，端阳已近。","寻巢为甚偏迟钝。","算来一似凤鸾期，蹉跎渐觉无真信。"]},{"t":"踏莎行","f":"曲","c":["香罢宵薰，花孤昼赏。","粉墙一丈愁千丈。","多情春梦苦抛人，寻郎夜夜离罗幌。","好句刊心，佳期束想。","甫愁春到还愁往。","消魂细柳一时垂，断肠芳草连天长。"]},{"t":"踏莎行","f":"曲","c":["一领布袍，一床纸被。","葫芦拄杖为行李。","三杯两盏乐天真，谁能与你争闲气。","满眼苍生，争名夺利。","朝朝只要巴家计。","教他吃个土馒头，方知里面□滋味。"]},{"t":"踏雪行","f":"曲","c":["晓古通今，明经解义。","纷纷说得天花坠。","逐朝看画饼怎充饥，竹影难扫堂前地。","寡欲少思，忘言得意。","诸家放下难为贵。","若离方寸这些儿，踏破铁鞋无觅处。"]},{"t":"正宫 醉太平 讥贪小利者","f":"曲","c":["夺泥燕口，削铁针头，刮金佛面细搜求，无中觅有。","鹌鹑嗉里寻豌豆，鹭鸶腿上劈精肉。","蚊子腹内刳脂油，亏老先生下手。"]},{"t":"正宫 醉太平 无题","f":"曲","c":["堂堂大元，奸佞专权。","开河变钞祸根源，惹红巾万千。","官法滥，刑法重，黎民怨。","人吃人，钞买钞，何曾见。","贼做官，官做贼，混愚贤，哀哉可怜。"]},{"t":"醉桃源","f":"曲","c":["本来无说本无言。","澄寂湛然。","湛然常寂气神全。","希内自观玄。","玄中妙，妙中玄。","无相貌，莫团圆。","往来去，怎遮拦。","清风明月前。"]},{"t":"霜天晓角","f":"曲","c":["浮生碌碌。","尽飘流世欲。","空恁苦争活计，被情爱海没。","梦中竞利禄。","谩俦机狡，纵有百般荣贵，谁念光阴迅速。"]},{"t":"霜天晓角","f":"曲","c":["世事促促。","莫劳心役役。","弃尘早归林下，盖个低低茅屋。","映窗疏竹。","洒洒风生玉。","万叠青山为友，那管桑田翻覆。"]},{"t":"中吕 其二 红绣鞋","f":"曲","c":["孤雁叫教人怎睡，一声声叫的孤凄，向月明中和影一双飞。","你云中声嘹亮，我枕上泪双垂，雁儿我争你个甚的。"]},{"t":"红绣鞋 赠妓","f":"曲","c":["长江水流不尽心事，终条山隔不断情思。","想著你，夜深沉，人静悄，自来时。","来时节三两句话，去时节一篇词，记在你心窝儿里直到死。"]},{"t":"中吕 快活三过朝天子四换头 叹四美","f":"曲","c":["良辰媚景换今古，赏心乐事暗乘除。","人生四事岂能无，不可教轻辜负。","唤取，伴侣，正好向西湖路，花前沉醉倒玉壶，香滃雾，红飞雨。","九十韶华，人间客寓，把三分分数数，一分是流水，二分是尘土，不觉的春将暮。","西园杖屦，望眼无穷恨有馀，飘残香絮，歌残白苧，海棠花底鹧鸪，杨柳梢头杜宇，都唤取春归去。"]},{"t":"普天乐 失题","f":"曲","c":["他生得脸儿峥，庞儿正。","诸馀里耍俏，所事里聪明。","忒可憎，没薄幸。","行里坐里茶里饭里相随定，恰便似纸幡儿引了人魂灵。","想那些个滋滋味味，风风韵韵，老老成成。"]},{"t":"雁儿落带过得胜令 失题","f":"曲","c":["一年老一年，一日没一日，一秋又一秋，一辈催一辈，一聚一离别，一喜一伤悲。","一榻一身卧，一生一梦里。","寻一伙相识，他一会咱一会，都一般相知，吹一回，唱一回。"]},{"t":"正宫 塞鸿秋","f":"曲","c":["爱他时似爱初生月，喜他时似喜梅梢月，想他时道几首西江月，盼他时似盼辰钩月。","当初意儿别，今日相抛撇，要相逢似水底捞明月。"]},{"t":"正宫 塞鸿秋 山行警","f":"曲","c":["东边路、西边路、南边路，五里铺、七里铺、十里铺，行一步、盼一步、懒一步。","霎时间、天也暮、日也暮、云也暮，斜阳满地铺。","回首生烟雾，兀的不、山无数、水无数、情无数。"]},{"t":"喜春来","f":"曲","c":["海棠过雨红初淡。","杨柳无风睡正酣。","杏烧红，桃剪锦，草拖蓝。","三月三。","和气盛东南。"]},{"t":"醉太平","f":"曲","c":["钗分凤凰。","被剩鸳鸯。","锦笺遗恨爱花香。","写新愁半张。","晚妆楼阁空凝望。","旧游台榭添惆怅。","落花庭院又昏黄。","正离人断肠。"]},{"t":"仙方诗","f":"七言绝句","c":["纷纷墓土黄金屑，片片花飞白玉芝。","君主一斤臣四两，调和服下即平夷。"]},{"t":"晚翠亭诗","f":"五言律诗","c":["一径入青松，飞流澹晴绿。","道人晚归来，长歌振林谷。","山深不知秋，落叶下枯木。","须臾翠烟开，月色照綵服。"]},{"t":"荆州鬼语","f":"曲","c":["苦也苦，几时泥到襄阳府。","苦也苦，几时泥到成都府。"]},{"t":"元初童谣","f":"曲","c":["塔儿红，北人来作主人翁；","塔儿白，南人是主北为客。"]},{"t":"元谶","f":"七言古诗","c":["大元之后有庚申。"]},{"t":"法服歌诀","f":"七言绝句","c":["袜履中单黄带先，裙袍蔽膝绶绅连。","方心曲领蓝腰带，玉佩丁当冠笏全。"]},{"t":"滨州民歌","f":"七言古诗","c":["田野桑麻一倍增，昔无粗麻今纩缯，太守之德如景星。"]},{"t":"马氏铁券谶","f":"五言古诗","c":["至元十五六，狗儿坏我屋。"]},{"t":"信州路谶","f":"五言古诗","c":["水打巷村园，永丰出状元。"]},{"t":"嘲洪起畏","f":"曲","c":["家在临安，职守京口。","北骑若来，不降则走。"]},{"t":"皇舅墓谣","f":"五言绝句","c":["皇舅墓门闭，运粮向北去；","水渰墓门开，运粮却回来。"]},{"t":"井字谜","f":"曲","c":["四十零八个头，一头还对一脚。","中间全无肚肠，外面许多棱角。"]},{"t":"用字谜","f":"五言律诗","c":["三山自三山，山山甘倒悬。","一月复一月，月月还相连。","左右排双羽，纵横列二川。","阖家都六口，两口不团圆。"]},{"t":"大明寺水隐语","f":"曲","c":["一人堂堂，两曜垂光。","井深尺一，点去冰旁。","二人同行，不欠一边。","三梁四柱足火然，若有双钩日月全。"]},{"t":"颂程雪楼","f":"七言古诗","c":["闽中有雪方为贵，天下无楼如此高。"]},{"t":"无名状","f":"曲","c":["老书生，小书生，二书生坏了中书省。","不言不语张左丞，铺眉扇眼董参政，也待学魏徵一般俸请。"]},{"t":"宁都州民歌","f":"曲","c":["去年雪，今年雨。","微计侯，那得此。","民既悦，天应喜。"]},{"t":"宣城民哭邑令","f":"五言绝句","c":["公来何其迟，公去何其速。","使我宣城民，何以遂生育？"]},{"t":"雷州民歌","f":"楚辞体","c":["潟卤为田兮，孙父之教。","渠之泱泱兮，长我粳稻。","自今有年兮，无旱无涝。"]},{"t":"浮梁民谣","f":"七言绝句","c":["桃李阴阴六万家，下居民不识官衙。","甘棠喜有千年政，美玉终无一点瑕。"]},{"t":"太仓谣","f":"五言绝句","c":["打碗花子开，今搬州县来。","黄郎屋上走，州县住不久。"]},{"t":"至治间占","f":"七言古诗","c":["天狗坠地为赤犬，其下有大军覆境。"]},{"t":"李好文谚","f":"七言古诗","c":["目耕夜分李好文。"]},{"t":"绍兴乡人语","f":"曲","c":["欲学孝妇，当学俞母。"]},{"t":"斛铭","f":"曲","c":["出以是，入以是。","是子孙，永如是。"]},{"t":"浙西谚","f":"五言古诗","c":["年年防火起，夜夜防贼来。"]},{"t":"无锡谶","f":"曲","c":["无锡平，天下宁。"]},{"t":"三险谚","f":"七言古诗","c":["馩香吸髓倚阑干。"]},{"t":"巴豆黄连谚","f":"五言古诗","c":["巴豆未开花，黄连先结子。"]},{"t":"金银珠谣","f":"七言古诗","c":["活银病金死珠子。"]},{"t":"明宗时童谣","f":"曲","c":["牡丹红，禾苗空。","牡丹紫，禾苗死。"]},{"t":"十七字诗","f":"曲","c":["自谓非其子，如今作天子。","传语老蛮子，请死。"]},{"t":"元统间谣","f":"曲","c":["天雨氂，事不齐。"]},{"t":"菩萨线谣","f":"曲","c":["天雨线，民起怨。","中原地，事必变。"]},{"t":"京师童谣","f":"五言古诗","c":["白雁望南飞，马札望北跳。"]},{"t":"京师语","f":"曲","c":["上把君欺，下把民虐，太皇太后倚恃著。"]},{"t":"书省壁","f":"七言绝句","c":["人皆谓我不办事，天下办事有几人？","袖里屠龙斩蛟手，埋没青锋二十春。"]},{"t":"至正中谚","f":"曲","c":["李如黄瓜，民皆无家。"]},{"t":"江西福建怨谣","f":"曲","c":["九重丹诏颁恩至，万两黄金奉使回。","奉使来时，惊天动地；","奉使去时，乌天黑地。","官吏都欢天喜地，百姓却啼天哭地。","官吏黑漆皮灯笼，奉使来时添一重。"]},{"t":"石人谣","f":"七言古诗","c":["莫道石人一只眼，此物一出天下反。"]},{"t":"平江郡石上谶","f":"曲","c":["三十八，十八子，寅卯年，至辰巳。","合收张翼，同为列国。","不在常，不在祥，切须款款细思量。","旦卜水，暮愁米，浮图倒地莫扶起。","修石岸，重开河，军民拍手笑呵呵。","日出屋东头，鲤鱼上山游。","星从月里过，会在午年头。"]},{"t":"嘲三宝奴","f":"七言古诗","c":["茶盐酒醋都提举，僧道医工总相公。"]},{"t":"粘国门诗","f":"曲","c":["虾蟆水上浮，雪雪见日消，定住不开口。","汪家奴，只一朝，国事休矣。"]},{"t":"上海县谣","f":"五言古诗","c":["鸡啼不拍翅，鸦鸟不转更。"]},{"t":"至正中大理童谣","f":"曲","c":["莫道君为山海主，山海笑咳咳。","园中花谢千万朵，别有明主来。"]},{"t":"至正中燕京童谣三首","f":"曲","c":["牵郎郎，拽弟弟，打破碗儿便作地。","阴凉阴凉过河去，日头日头过山来。","脚驴斑斑，脚躐南山。","南山北斗，养活家狗，家狗磨面，三十弓箭。","上马琵琶，下马琵琶，驴蹄马蹄，缩了一只。"]},{"t":"台温处树旗谣","f":"五言绝句","c":["天高皇帝远，民少相公多。","一日三遍打，不反待如何？"]},{"t":"方国珍谣","f":"曲","c":["杨氏青，出贼精。"]},{"t":"京师童谣","f":"七言绝句","c":["一阵黄风一阵沙，千里万里无人家。","回头雪消不堪看，三眼和尚弄瞎马。"]},{"t":"松江谣","f":"五言绝句","c":["满城都是火，府官四散躲。","城里无一人，红军府上坐。"]},{"t":"张士信杨完者谣","f":"曲","c":["死不怨，泰州张；","生不谢，宝庆杨。"]},{"t":"闽清民歌","f":"楚辞体","c":["彼寇来雠兮，得吾侯而蒙休。","彼寇远遁兮，吾侯锡我室家之无忧。"]},{"t":"武冈民颂","f":"曲","c":["前有公绰，武冈父母；","今之郡侯，毋乃其后。","足我衣食，安我田亩。","我子我孙，与侯同久。"]},{"t":"曲沃民歌","f":"曲","c":["泮宫之崇，以扶儒宗。","社稷之封，以祈年丰。","肇之者谁？","令尹之功。"]},{"t":"福宁州谣三首 其一","f":"七言古诗","c":["吾侬生长莆山曲，三尺茅檐四尺屋。","大男终岁食无盐，老妇蒸藜泪盈掬。","阿郎辛苦学弄兵，年年贩盐南海滨。","担头有盐兵一束，群行大队惊四邻。","迩来红巾掠州县，沃野平民不知战。","贤哉太守死作灰，勇矣林僧命如线。","林僧一战功业单，策马东走来莆山。","山人踯躅喜相遇，邀我邻社东南旋。","我邻我社轻死士，苦竹长枪兼丈五。","自从行劫出社来，社甲吹螺整行伍。","时维癸巳夏五月，暍暑微民正愁绝。","螺声隐隐入郭门，白旆央央下林樾。","饥儿寡妇常咨咨，老弱奔走趋道隅。","鹙鸧翻羽动天哭，虎豹掉尾何时需。","空城一炬灰烬后，车盖归来仍白授。","阿娘垢面迎相公，西邻椎牛唤新酒。","酒酣拍掌浩浩歌，天地虽大如吾何！","女儿朝餐餍粱肉，走卒出市陈干戈。","市人累累丧家狗，路上相逢尽缠首。","儒巾惊骇迎先锋，小儿号哭畏郎吼。","老翁再拜乞见怜，自从乱后无一钱。","舍人官买鸡豕尽，有田未种蚕未眠。","先锋拔刀倍嗔怒，缚得家翁出门去。","妻儿哭泣投社官，愿获生全拜君赐。","社官点头见始欢，年来钱钞交莫悭。","尔田傥入莆社籍，尔屋老稚从居安。","我田我庐不足惜，应当门户谁出入。","生男愿作社中吏，生女愿作先锋妾。","胡然太府亶不聪，有书辄上莆社公。","柏台主人任刀笔，札札按覆皆相同。","向来壤地方万里，比屋豪华皆武士。","五侯同封不足誇，一家十轮未为易。","匹夫势转千乘强，驱役百姓如驱羊。","编民贡税入私室，小大驱合无边方。","手提文印绿衣者，饥食无鱼出无马。","流离安集无定期，蓬蒿猎猎故城下。","道旁遗老问行人，泰安有社民未贫。","行人蹙额皆相语，我闻公社吏更仁。","前年泰安挹城邑，未曾入城先报捷。","前师失利后师奔，一市横尸更稠叠。","至今大厦环州营，一门公相皆弟兄。","豺狼盘踞食人肉，一叱一咤风云生。","我闻有命不敢告，俯首未言胆先破。","老翁闻此双泪垂，风雨洗天何人到。"]},{"t":"福宁州谣三首 其二","f":"七言古诗","c":["袁君袁君诚儿嬉，东山之下筑城池。","掘人冢石叠墙堑，占民田土开营基。","欲谋于此胚汉业，井蛙尊大情何痴。","役民荷锸任犁穴，无骸不露堪欷歔。","前人尽辞长夜室，天阴露冷凉啾悲。","山中独存袁氏墓，若堂之封何巍巍。","又见若坊若夏屋，芙蓉筑城芳飞飞。","无归之鬼欲托处，游目一见动所思。","鬼灵相率语其下，主人肃入安便宜。","众鬼夜深苦啼哭，主人慰勉甘其辞。","惟桑与梓焉有旧，颠危自合相扶持。","儿孙祭扫同尔享，佳城爽垲同尔归。","且叙平生受苦语，又奚深夜啼悲为。","众鬼致词恤久远，天地循环何所期。","城池恐为他人得，他人又嫌墙堑卑。","发号令民更增筑，吾家已破墙无基。","恐人掘石及君墓，嗟余与君俱无依。"]},{"t":"福宁州谣三首 其三","f":"楚辞体","c":["山巍巍兮无麦原，白面细粉常盈盆。","林森森兮无桑柘，锦绣绫罗色相亚。","出门见岭不见江，案前罗列皆鲈鲂。","儿童吼鬨南山下，剩逐牛羊与驴马。","山妻嘻笑临堂前，满头珠翠垂翩翩。","自言获功始三载，胜如仕宦数十年。","但愿魁寇未殄灭，与我增财广置山间田。"]},{"t":"安乡谣","f":"曲","c":["罗长卿，罗长卿，朝朝打鼓捷蛮兵。","一朝打发蛮兵去，千门万户乐太平。"]},{"t":"嘲许敬仁","f":"五言绝句","c":["祭酒许敬仁，入门鞑靼唤。","出门传圣旨，口口称先人。"]},{"t":"绩溪歌","f":"五言古诗","c":["前有苏黄门，后有叶令君。"]},{"t":"书楮衾语","f":"曲","c":["的的的，孰令尔纸被似钞角。","问我何处住，五色云中住。","问我是何姓，杓子少个柄。","尔也错，我也错，不如归去！","的的的。"]},{"t":"元末湖湘中童谣","f":"曲","c":["不怕水中鱼，只怕岸上猪。","猪过水，见糠止。"]},{"t":"赵烈妇歌","f":"七言古诗","c":["四月三日兵挠湖，妇女多被辱与驱，殉节伊谁天水姝。"]},{"t":"萧彝翁书衣带语","f":"曲","c":["男子之贞，犹女之烈。","一有玷焉，万善难雪。"]},{"t":"羊儿年谣","f":"五言绝句","c":["富汉莫起楼，贫汉莫起屋。","但看羊儿年，便是吴家国。"]},{"t":"黄菜叶谣","f":"曲","c":["张王做事业，只凭黄蔡叶。","一夜西风来，乾瘪。"]},{"t":"仙吕 寄生草 其一 闲评","f":"曲","c":["问什么虚名利，管什么闲是非。","想著他击珊瑚列锦幛石崇势，则不如卸罗裾纳象简张良退，学取他枕清风铺明月陈抟睡。","看了那吴山青似越山青，不如今朝醉了明朝醉。"]},{"t":"仙吕 寄生草 其二 闲评","f":"曲","c":["争闲气、使见识，赤壁山正中周郎计，乌江岸枉费重瞳力，马嵬坡空洒明皇泪。","前人勋业后人看，不如今朝醉了明朝醉。"]},{"t":"正宫 塞鸿秋","f":"曲","c":["一对紫燕儿雕梁上肩相并，一对粉蝶儿花丛上偏相趁，一对鸳鸯儿水面上相交颈，一对虎猫儿绣凳上相偎定。","觑了动人情，不由人心儿硬，冷清清偏俺合孤零。"]},{"t":"商调 梧叶儿 嘲谎人","f":"曲","c":["东村里鸡生凤，南庄上马变牛，六月里裹皮裘。","瓦垄上宜栽树，阳沟里好驾舟。","瓮来大肉馒头，俺家茄子大如斗。"]},{"t":"商调 梧叶儿 嘲贪汉","f":"曲","c":["一粒米针穿著吃，一文钱剪截充，但开口昧神灵。","看儿女如衔泥燕，爱钱财似竞血蝇。","无明夜攒金银，都做充饥画饼。"]},{"t":"正宫 其一 叨叨令","f":"曲","c":["黄尘万古长安路，折碑三尺邙山墓。","西风一叶乌江渡，夕阳十里邯郸树。","老了人也么哥，老了人也么哥，英雄尽是伤心处。"]},{"t":"正宫 其二 叨叨令","f":"曲","c":["只见青帘高挂垂杨树，朱帘暮卷西山雨。","谁待向禁城狼虎丛中去，我则待侬家鹦鹉洲边住。","倒大来快活也么哥，快活也么哥，抵多少梦回明月生南浦。"]},{"t":"中吕 其一 红绣鞋","f":"曲","c":["窗外雨声声不住，枕边泪点点长吁，雨声泪点急相逐。","雨声儿添凄惨，泪点儿助长吁。","枕边泪倒多如窗外雨。"]},{"t":"中吕 朝天子 志感","f":"曲","c":["不读书有权，不识字有钱，不晓事倒有人誇荐。","老天只恁忒心偏，贤和愚无分辨。","折挫英雄，消磨良善，越聪明越运蹇。","志高如鲁连，德高如闵蹇，依本分只落的人轻贱。"]},{"t":"醉太平 无题","f":"曲","c":["利名场事冗。","林泉下心冲。","小柴门画戟古城东。","隔风波数重。","华山云不到阳台梦。","溪水不接桃源洞。","洛阳城不到武夷峰。","老先生睡浓。"]},{"t":"醉中平 无题","f":"曲","c":["泪溅端溪砚。","情写锦花笺。","日暮帘栊生暖烟。","睡煞梁间燕。","人比青山更远。","梨花庭院。","月明闲却秋千。"]},{"t":"喜春来 闺情","f":"曲","c":["窄裁衫裉安排瘦。","淡扫蛾眉准备愁。","思君一度一登楼。","凝望久。","雁过楚天秋。"]},{"t":"朝天子 庐山","f":"曲","c":["早霞。","晚霞。","装点庐山画。","仙翁何处炼丹砂。","一缕白云下。","客去斋馀。","人来茶罢。","叹浮生指落花。","楚家。","汉家。","做了渔樵话。"]},{"t":"金字经 秋夜","f":"曲","c":["我来山中宿。","夜深云满衣。","月皎风清星斗稀。","惊鸟无所依。","乖秋意。","卧将箫管吹。"]},{"t":"庆东原 奇遇","f":"曲","c":["参旗动。","斗柄挪。","为多情揽下风流祸。","眉攒翠蛾。","裙拖绛罗。","袜冷凌波。","耽惊怕万千般。","得受用些儿个。"]},{"t":"清江引 九日","f":"曲","c":["萧萧五株门外柳。","屈指重阳又。","霜清紫蟹肥。","露冷黄花瘦。","白衣不来琴当酒。"]},{"t":"驻马听 无题","f":"曲","c":["月小潮平。","红蓼滩头秋水冷。","天空云净。","夕阳江上乱峰青。","一蓑全却子陵名。","五湖救了鸱夷命。","尘劳事不听。","龙蛇一任相吞并。"]},{"t":"凭阑人 无题","f":"曲","c":["点破苍苔墙角萤。","战退西风檐外铃。","画楼风露清。","玉阑桐叶零。"]},{"t":"雪花曲","f":"七言古诗","c":["苦篁猎猎吹北风，黄河水流疑不通。","天孙手持白鸾尾，笑拂琪花飞碧空。","昆山玉碎琼楼裂，老龙起舞惊明月。","梦觉游魂不觉寒，醉吟纸帐春云热。","东家娇娘厌桃李，学绣宫花锁窗里。","冷袖擎来欲细观，隔帘火气催成水。"]},{"t":"车中女","f":"七言律诗","c":["青青帷幄映彤车，浅露新妆不自遮。","绣带垂膺明彩凤，茜罗帕首护云鸦。","青夷关外东风柳，丞相园中上日花。","亦有携鞭年少者，雕鞍并坐是谁家。"]},{"t":"美人纱带","f":"七言律诗","c":["满眼春娇倚绣床，玉钩新绾藕丝长。","鸳鸯机上舒晴雪，翡翠帘前蹴晚霜。","拾翠不知罗袜润，踏花犹隔绣鞋香。","几回暗忆吹箫侣，背立东风咏凤凰。"]},{"t":"仙坛","f":"七言律诗","c":["碧坛纛影荫龙蛇，骑鹤归来枣似瓜。","仙语风前飘玉屑，道衣天上剪云霞。","寒潭六月犹无暑，老木千年尚有花。","采药青童来借问，苍烟起处是谁家。"]},{"t":"庞涓夜走马陵道・仙吕/赏花时","f":"曲","c":["想着咱转笔抄书几度春，常则是刺股悬梁不厌勤。","你今日践红尘，只愿你此去呵功名有准，早开阁画麒麟。"]},{"t":"庞涓夜走马陵道・幺篇","f":"曲","c":["抵多少西出阳关无故人，一种离愁两断魂。","我越送越关亲，好割不断弟兄的义分，(带云)兄弟，你稳登前程。","(唱)早过了五里这坐杏花村。","(下)。"]},{"t":"庞涓夜走马陵道・仙吕/点绛唇","f":"曲","c":["遮莫他盖世英雄，驱兵拥众，你可也休惊恐。","若是和俺孙膑交锋，只当似掌股上婴儿弄。"]},{"t":"庞涓夜走马陵道・油葫芦","f":"曲","c":["我这里布网张罗打大虫，谁着你将军校冲，早沙场上杀的血染马蹄红。","(郑安平打阵科，云)哥也，到的这阵里面，可怎生东西南北都不省的了也？(正末云)是甚么人？快与我拿将来。","(卒子拿郑安平科)(正末唱)则你那三更不应君王梦，可兀的一身枉请皇家俸。","我将你捉在马前，你今日落在彀中。","谁着你不明白撞入我这迷魂洞，不由我忿气欲填胸。","(郑安平云)师父可怜见，不干我事，都是庞元帅来。","(正末唱)。"]},{"t":"庞涓夜走马陵道・天下乐","f":"曲","c":["可不道将在谋不在勇，哎，只你个英也波雄，枉用功，我如今捉获你对咱妆懵懂。","(云)大小三军，将那厮夺下鞍马，剥去衣甲，休教走了也。","(郑安平云)将我鞍马衣甲都收了，教我怎么回去见元帅？(正末唱)一壁厢扯了锦袍，一壁厢牵了玉骢，我看你怎生还本阵中？。"]},{"t":"庞涓夜走马陵道・后庭花","f":"曲","c":["我喜的是弟兄每两意同，你则待执轮竿作钓翁。","哀告这掌军权的燕孙膑。","(带云)兄弟请起。","(唱)请起你个梦非熊的姜太公。","若到那殿庭中，怎忘了弟兄的情重，(庞涓云)哥也，若公子问呵，休说哥哥好、兄弟歹，则说俺两个摆阵势是一般儿的。","(正末云)兄弟，我知道了也。","(唱)我对大人行会脱空。","(庞涓云)哥哥，这都是兄弟的不是了，只愿哥哥想咱旧日契交朋友。","今日举荐为官，也是不忘盟誓之意。","假若公子问呵，谁输谁赢，哥哥您则善言咱。","(正末云)兄弟，你放心者。","我和你见公子去来。","(公子云)孙先生。","我问你，两家摆阵势，谁输谁赢？你从头实说咱。","(正末云)公子，贫道与元帅都是鬼谷先生弟子。","虽同传授，各用心机。","便是元帅也有不知贫道演习的去处，贫道也有不知元帅的去处，总之一般。","(公子云)虽然如此，好歹岂没个赢没个输的？(正末唱)。"]},{"t":"庞涓夜走马陵道・金盏儿","f":"曲","c":["他那里一一问行踪，俺兄弟悄悄的嘶过从。","好教我意踌躇，两下里可兀的难趋奉。","我待不说呵，怎生支对主人公；待说呵，我和他书窗曾最密。","怎宦路个不相容。","(公子云)孙先生，你怎生不言语？(正末唱)我正是满怀心腹事，尽在不言中。","(公子云)孙先生，你恰才摆阵时毕竟是谁输谁赢？(正末云)公子，听贫道说咱。","(唱)。"]},{"t":"庞涓夜走马陵道・仙吕/赏花时","f":"曲","c":["我如今奉敕蒙宣统士卒，则为这荧惑离宫失位所。","我望帝阙近皇都连发了三枝箭羽，早没半霎儿将火星除。","(下)。"]},{"t":"庞涓夜走马陵道・正宫/端正好","f":"曲","c":["祸临头，谁人救，则我这泼残生眼见的千死千休。","谁着你把箭三枝连射三更后，哎！你也合将那传令的人追究。"]},{"t":"庞涓夜走马陵道・滚绣球","f":"曲","c":["我可也为国愁，为国忧，为知心数年交厚，我恨不的并吞了六国诸侯。","这江山和宇宙，士女共军州，都待着俺邦情受，怎知道运拙也志愿难酬。","哎，孙膑也！不争你谗言谮语遭人构，直感的野草闲花满地愁。","那里也正首孤丘。"]},{"t":"庞涓夜走马陵道・倘秀才","f":"曲","c":["哎！我说一句钢刀豁口，觑一觑金瓜碎首，我可甚一旦无常万事休。","我不合鸣金鼓、统戈矛，(带云)我本无罪过，怎要杀坏我也？(唱)这便的是我犯由。"]},{"t":"庞涓夜走马陵道・滚绣球","f":"曲","c":["这法场近御沟，对凤楼，(带云)冤屈也！(唱)我这里叫尽屈有谁来分剖。","送的我眼睁睁有国难投。","强缚住我这调羹补衮的手，掩住我这衔冤负屈的口。","这都是我自作自受，也不专为那人怨人仇。","哀哉故国难回首。","可正是烦恼皆因强出头，便死何求！(宠涓上，云)我教郑安平代做监斩官，起建法场，杀坏孙膑。","如今往法场上过，我则推不知道。","摆开头躇，慢慢的行。","我是个朝中有功之人，今日敕赐与我十瓶黄封御酒，我多饮了几杯，我好快活也。","(做唱科)(唱)今宵酒醒伺处。","杨柳岸晓风残月。","(正末云)兀的不是宠涓过来也！我明知道他杀坏我，我着他救我咱。","我临行时师父曾与我一计，若遇祸难临头。","有人唱道：今宵酒醒何处，杨柳岸晓风残月。","你可诉出心间之事，就得不死。","我如今不说，等待何时！两街百姓，我死不紧，只可惜我腹中有卷《六甲》天书。","不曾传授与人。","若有人救了我的性命。","我情愿传写与他，决无隐讳。","(宠涓惊私，云)嗨！师父好歹也！将这《六甲》天书倒传与他。","传与我的天书，原来是假的。","我如今独霸六国，料无对手，若再得这天书呵，还有谁人近的我？当日他摆出阵来。","我不认的那个阵势，可知道他在天书里面摘下来的。","我若杀了这厮，便是绝了这天书也。","我自有个妙计，赚他这天书哩。","(刽子云)午时三刻到了，开刀！(庞涓云)是斩谁？(刽子云)斩孙膑哩！(庞涓云)是孙膑？且留人者！(做悲云)哥哥。","你为甚么来！(正末云)兄弟也，杀我的罪过，你敢知情么？(庞涓云)我若知情呵。","唾是命随灯而灭。","哥哥，你端的为甚么来？(正末唱)。"]},{"t":"庞涓夜走马陵道・白鹤子","f":"曲","c":["他对着我急煎煎的忙问取。","我对着他悄促促的说情由。","(庞涓云)哥也。","我若知情呵，唾是命随灯而灭。","(正末唱)只道他含着泪苦滴滴的假慈悲，却原来指着灯碜可可的言盟咒。"]},{"t":"庞涓夜走马陵道・脱布衫","f":"曲","c":["我道你搜寻出百样机谋，翻惹下千种闲愁。","则你个为昔日同堂故友，怎惜得这殷勤尽心儿搭救。"]},{"t":"庞涓夜走马陵道・滚绣球","f":"曲","c":["你休那里信口诌，(刽子云)我不说谎。","(正末唱)则管里无了收，这言语你也合三思然后，俺兄弟怎肯道东涧东流。","(带云)俺两个说誓来，(唱)他亏我似猪狗。","我亏他似马牛，俺两个曾对天说咒，俺兄弟他怎肯火上浇油。","俺两个胜如管鲍分金义，休猜做孙庞刖足仇，枉惹得万代名留。"]},{"t":"庞涓夜走马陵道・二煞","f":"曲","c":["我饮过这香喷喷三盏儿安魂酒，则被你闪杀我也血渌渌一双脚指头。","刀落处鼻痛心酸，皮开肉绽，筋骨相离，鲜血浇流。","哎，可怎生神嚎鬼哭，雾惨云昏，白日为幽。","耳边厢只听得半空中风吼，莫不是相天地替人愁！。"]},{"t":"庞涓夜走马陵道・煞尾","f":"曲","c":["兄弟，则这功名成就合成就，我得好休时便好休。","养可疮海上游，洗了耳觅许由，学太公把钓钩，逐范蠡一叶舟。","想荣华风内烛，富贵如水上沤，将利名一笔勾，再不向杀人场揽祸尤，白白的将性命丢。","攒住眉头懒转眸，咬定牙儿且忍羞。","打熬着足上浸浸血水流。","哎，你个行刃的哥哥，你畅好是下的手。","(下)。"]},{"t":"庞涓夜走马陵道・双调/新水令","f":"曲","c":["打独磨来到画桥四，恰便似出笼鹰剪折厂我这双翼。","自知毛羽短，怎敢扑天飞。","我则索做哑妆痴，儿回家阁不住眼中泪。"]},{"t":"庞涓夜走马陵道・步步娇","f":"曲","c":["想当初在云梦山中把天书习，定道是取将相能容易。","谁知有这日，生把俺七尺长躯打灭的无存济。","哎哟！天那！甚日得遂风雷？也吐出俺这三千丈虹霓气。"]},{"t":"庞涓夜走马陵道・搅筝琶","f":"曲","c":["见一个狠公吏，叫一声似春雷，唬的那几个作耍顽童，都一时间潜在那里。","(卒子云)兀那风子，你脚上疮疤疼痛，如今可好了么？(正末唱)起动你问我疮疾，我可也皱定双眉。","(做悲科，云)我好疼哩！我好疼哩！(唱)堪悲！休则管絮絮聒聒，扯扯拽拽，痛不痛我足下须自知，索甚猜疑。","(卒子云)兀那风子，你看我这手里拿的甚么？(正末云)是馒头。","(卒子云)这个是甚么？(正末云)这个你则道我不知哩，这个是糕糜。","(卒子云)你吃馒头好，吃糕糜好？(正末云)我则吃糕糜。","(卒子云)你吃糕糜，要发病伤人也。","(正末云)我则要吃糕糜。","(唱)。"]},{"t":"庞涓夜走马陵道・雁儿落","f":"曲","c":["我常担着空肚皮，(卒子云)你几曾见这等好茶饭来？(正末唱)好茶饭几曾道尝滋味。","虽然我脚尖上有病疾，(卒子云)你休吃，则怕发了你的疮。","(正末唱)我心儿里倒也无闲气。"]},{"t":"庞涓夜走马陵道・挂玉钩","f":"曲","c":["我这里吐胆倾心说与伊，难道你不解其中意？(卜商云)先生何不跟我馆驿中去来。","(正末云)你先行，我随后便到也。","(卜商云)你不与我同去。","可是为何？(正末唱)我则怕路上行人口胜碑，(卜商云)先生，我须不是故意来赚你的。","(正末唱)咱两个都心会。","(卜商云)小官此一来。","专为先生，别无他干。","(正末唱)既然是你为我来，须回避。","且做个面北眉南，你东咱西。"]},{"t":"庞涓夜走马陵道・殿前欢","f":"曲","c":["那唤我的却为谁？(卜商云)先生，你在那里来？(正末唱)在那摘星楼上我便做筵席。","安排下脱壳金蝉计，我则索躲是逃非。","(卜商云)庞涓贼，你好狠也。","(正末唱)这的是他下的我也下的。","(卜商云)先生，庞涓又来了也。","(正末唱)哎！缠杀我也天魔祟，我便似小鬼般合扑地。","(卜商云)你躲时节谁知道来？(正末唱)这公事则除天知地知，(带云)庞涓。","你怎知我在这里吃茶饭哩。","(唱)只半合儿使碎我这心机。"]},{"t":"庞涓夜走马陵道・中吕/粉蝶儿","f":"曲","c":["打一轮皂盖轻车，按天书把三军摆设，谁识俺这阵似长蛇。","端的个角生风，旗掣电，弓弯秋月。","喊一声海沸山裂，管杀的他众儿郎不能相借。"]},{"t":"庞涓夜走马陵道・醉春风","f":"曲","c":["我将这乌龙墨恰研浓，我将这紫兔毫深蘸彻。","(写科)(诗云)白杨树下白杨峪，正是庞涓合死处。","今夜不斩魏人头，孙膑不还齐国去。","(公子云)你看写着甚么哩？(正末唱)道不离此处斩庞涓，我亲自的写、写。","一来是孙膑的计谋：二来是主公的福分，第三来单注着那人合灭。"]},{"t":"庞涓夜走马陵道・石榴花","f":"曲","c":["笑庞涓敢逞尽十分劣，逐定咱不相撇。","争知这马陵道上有拦截，山崖一斗绝，树林稠叠。","万张强弩齐攒射，敢立化了一堆鲜血。","总便有三头六臂天生别，到其间那里好藏遮。"]},{"t":"庞涓夜走马陵道・斗鹌鹑","f":"曲","c":["俺和他同堂友至契至交，须不是被傍人厮间厮渫。","俺可也为甚么相贼相残，都是他平日里自作自孽。","他把切骨的冤仇死也似结，怎教俺便忘了者。","俺如今拚的个不做不休，这就是至诚心为人为彻。"]},{"t":"庞涓夜走马陵道・幺篇","f":"曲","c":["他那里语未绝，俺这里箭早拽。","则见他蓦涧穿林，钻天入地，急切难迭。","脚趔趄，眼乜斜，恰便似酒酣时节，庞涓也休猜做杨柳岸晓风残月。","(庞涓云)此处莫不有埋伏的军马么？不中，我只索倒回干戈，领军去也。","(孙膑云)庞涓，你那里去？大小三军，与我围定了峪口者。","休教走了庞涓！(庞涓云)兀的不唬杀我也！高阜处说话，好似我孙膑哥哥。","我是叫他一声咱。","孙膑哥哥！(正末云)叫我的是谁？(庞涓云)是您兄弟庞涓。","(正末云)你叫我怎么？(庞涓云)多时不见哥哥，我心中好生想你也！(正末云)你那贼，却元来也有今日哩！(唱)。"]},{"t":"庞涓夜走马陵道・快活三","f":"曲","c":["俺把心中事明诉说，您把诗中句细披阅。","大古来有甚费周折，多咱是您勾魂帖。","(庞涓云)哥哥可怜见！是您兄弟的不是了也。","(正末唱)。"]},{"t":"庞涓夜走马陵道・朝天子","f":"曲","c":["我可也不为别，是你亲曾把誓设，(庞涓云)兀的不灭了这盏灯也，(正末唱)正应着唾是命随灯灭。","(庞涓做拜科，云)哥哥可怜见，只饶过您兄弟咱。","(正末唱)庞涓你既做了这业又何必恁怯，枉了也参拜无休歇。","哎！则你个脸儿假热，心儿似铁，忍下的眼睁睁把我双足刖。","你如今死也，再休想放舍，恰便似水底捞明月。"]},{"t":"庞涓夜走马陵道・十二月","f":"曲","c":["他那里自推自跌，从今后义断恩绝。","(庞涓云)哥哥。","咱和你是同心共胆的好朋友，饶过我者！(正末唱)你道是同心共胆，还待要骗口张舌。","我问你三回两歇，怎送的我二足双瘸？。"]},{"t":"庞涓夜走马陵道・尧民歌","f":"曲","c":["你道是若拿住活剁做两三截，(庞涓云)哥哥，旧话休题。","(正末唱)今日个马陵道上把大冤雪。","我剑锋亲把树皮揭，写着道今夜里此处斩豪杰。","伤也波嵯，我和你从今便永决，(带云)庞涓，您要不死呵，(唱)则除是半空中飞下滴溜溜一纸郊天赦。","(公子云)军师，则管和他说到几时。","先把这厮刖了双足，切下了驴头，然后将尸首分开做六段，散与六国去罢。","(孙膑云)小校，将铜钅算斤来先刖了这厮双足者！(庞涓云)罢、罢、罢，大丈夫睁着眼做，合着眼受。","这也不必说了，只可惜那六甲天书还不曾传授。","(正末唱)。"]},{"t":"庞涓夜走马陵道・煞尾","f":"曲","c":["再言语豁了这厮口，再言语截了这厮舌。","将那一颗驴头慢慢钢刀切。","才把我刖足的冤仇报了也。"]},{"t":"汉钟离度脱蓝采和・仙吕/点绛唇","f":"曲","c":["俺将这古本相传，路歧礼面，习行院，打诨通禅，穷薄艺知深浅。"]},{"t":"汉钟离度脱蓝采和・混江龙","f":"曲","c":["试看我行针步线，俺在这梁园城一交却又早二十年。","常则是与人方便，会客周全。","做一段有憎爱劝贤孝新院本，觅几文济饥寒得温暖养家钱。","俺这里不比别州县。","学这几分薄艺，胜似千顷良田。","(云)来到这勾栏里也。","兄弟有看的人么？好时候也，上紧收拾。","(净云)我方才开了勾栏门，有一个先生坐在乐床上。","我便道：先生，你去神楼上或是腰棚上那里坐，这里是妇女每做排场的坐处。","他倒骂俺。","(正末云)好歹你每冲撞着他来。","我自看去。","(做见科，云)稽首，老师父。","(钟云)你那里散诞去来？(正末云)这先生你与我贴招牌。","老先生不知，街市上有几个士夫，请我吃了一杯茶。","因此上来迟。","(钟云)我在这勾栏里坐了一日，你这早晚才来。","宁可乐待于宾，不可宾待于乐。","我特来看你做杂剧，你做一段甚么杂剧我看。","(正末云)师父要做甚么杂剧？(钟云)但是你记的，数来我听。","(正末云)我数几段师父听咱。","(唱)。"]},{"t":"汉钟离度脱蓝采和・天下乐","f":"曲","c":["或是做雪拥蓝关马不前。","(钟云)别做一段。","(正末唱)小人其实本事浅，感谢看官相可怜。","(云)王把色，你将旗牌。","帐额、神峥、靠背都与我挂了者。","(净云)我都挂了。","(正末唱)一壁将牌额题，一壁将靠背悬。","(云)有那边方来看的见了呵，传出去说，梁园棚勾栏里末尼蓝采和做场哩。","(唱)我则待天下将我的名姓显。"]},{"t":"汉钟离度脱蓝采和・那吒令","f":"曲","c":["据着你那口食离糟麸膳缘，身遇着薄藤冠驾轩，我则道稳跨着仙鹤上天。","(钟云)我游遍天下，不曾见你这个末尼。","(正末唱)太平身插入市楼，将天下都游遍，一对脚背地坚叫声冤。"]},{"t":"汉钟离度脱蓝采和・鹊踏枝","f":"曲","c":["你道我谎人钱，胡将这传奇扮。","(云)则许官员上户财主看勾栏散闷，我世不会见个先生看勾栏。","(唱)几曾见歌舞丛中，出了个大罗神仙。","(云)沿门儿乞化，又无那好的与你。","(唱)指大众抄化些郎头絮茧。","(云)那化缘处攒令各整集攒凑上来，见那钱物多也，利心又早动也。","(唱)你又不纳常住自趱做家缘。"]},{"t":"汉钟离度脱蓝采和・赚煞","f":"曲","c":["你合不着圣贤机，我觑不的他人面。","我看你几时到蓬莱阆苑，则你那六道轮回怎脱免？使不的你九伯风颠。","(云)我锁了勾栏门，看你怎生出的去。","(唱)遮莫你驾云轩，白日升天，怎敢相饶到面前。","(云)你若恼了我，十日不开门，我直饿杀你。","(唱)则你那身躯不坚，折。"]},{"t":"汉钟离度脱蓝采和・南吕/一枝花","f":"曲","c":["白莲插玉瓶，黄篆焚金鼎，斟一杯长寿酒，挂一幅老人星，来贺长生。","感承你相钦敬，量小人有甚么能，动劳你火伴邻里街坊，谢承你亲眷相知弟兄。"]},{"t":"汉钟离度脱蓝采和・梁州","f":"曲","c":["直吃的簌簌的红轮西坠，焱焱的玉兔东生。","常言五十而后知天命，我年过半百，诸事曾经。","人有灵性，鸟有飞腾，常言道蠢动含灵，做场处谁敢消停。","(云)咱行院打识水势(唱)俺、俺、俺做场处见景生情，你、你、你上高处舍身拚命，咱、咱、咱但去处夺利争名。","若逢，对棚，怎生来妆点的排场盛，倚仗看粉鼻凹五七并，依着这书会社恩官求些好本令。","(云)君子务本，本立而道生。","(唱)那的愁甚么前程。","(净把盏科云)哥哥饮一杯寿酒。","(钟离上云)今日是蓝采和生辰之日，度脱他走一遭去，早来到门首去。","(做哭三声、笑三声科，正末云)王把色是听的么，谁人在门首唱叫？(净云)哥哥也闲管事，知他是谁。","俺则吃酒。","(正末唱)。"]},{"t":"汉钟离度脱蓝采和・贺新郎","f":"曲","c":["是谁人啼天哭地两三声。","(云)我开开这门，原来是这泼先生，好无道理也呵！(唱)可做的魇镇俺家私，你端的是扇摇百姓。","(钟云)你去告我去，我不怕你。","(正末唱)咱告去来到官司呵和你敢无干净。","(云)我待告你去呵，着老的便道你是个上戏台的末尼，和他那风魔先生一般见识。","(唱)看着我生辰面不和你相执挣。","(云)今日我生辰，我是寿星，不和你计较。","(钟云)谁是寿星？(正末云)我是寿星。","(钟云)你今日是寿星，明日敢做了灾星也。","(正末云)这先生好无礼也，说这等不吉利的话。","(唱)你休这般胡做胡称。","(钟云)这句话又不曾伤着你。","(正末唱)这言语也不中使，这言语也不中听。","你敢化些淡齑汤且把你那皮囊撑。","(钟云)我见你受用。","(正末唱)可知可知俺吃的是大馒头阔片粉，你吃的是菜饺馅淡齑羹。","(云)这泼先生打搅俺吃酒。","王把色闭上门者。","众弟兄每坐着，则管里吃酒。","(钟云)他那里肯省悟，他若不见恶境头，他不肯出家。","兀那许坚，你若跟贫道出家去呵，逍遥散诞，清闲快乐，倒大来幽哉！(正末云)我知你做神仙的道路。","(钟云)你既知道，你说来我听。","(正末唱)。"]},{"t":"汉钟离度脱蓝采和・斗虾蟆","f":"曲","c":["见人家排斋供，请先生念忏经。","正面儿挂下一幅三清，檀越人家念经。","荒忙准备斋供，见放一轴老君，挂下十王神幅，待诏他也世情，说着的便决应，画的十分可碜。","怎觑那般行径，我则见城狱里画何真，油镬油铛，里头札定，偌多生灵，都是俺俗人，元来无一个和尚，先生徐神翁。","道无干净，这句话不觑听，我这等末尼你这等先生！。"]},{"t":"汉钟离度脱蓝采和・乌夜啼","f":"曲","c":["这先生言语真实信，果然道寿星做了灾星。","眼睁睁不敢往前进，不敢明闻。","谁敢道是弹筝。","想咱人是仲尼行，怎道是犯着萧何令。","(云)想圣人的言语说着都不信。","(唱)一个个，难凭信，都做了狂言诈语，信口胡喷。"]},{"t":"汉钟离度脱蓝采和・尾声","f":"曲","c":["再不将百十口火伴相将领，从今后十二瑶台独自行。","我那时财散人离陪下情，打喝处动乐声，戏台上呼我乐名。","我如今浑不浑浊不浊醒不醒，蓝采和泼声名贯满州城，几曾见那扮杂剧乐官头得悟醒。","(下)。"]},{"t":"汉钟离度脱蓝采和・正宫/端正好","f":"曲","c":["腰间将百钱拖，头上把唐巾裹，舞绿衫拍板高歌，逐朝走向街头过。","有几个把我相着么？。"]},{"t":"汉钟离度脱蓝采和・倘秀才","f":"曲","c":["再不听耳边厢焦焦聒聒，儿女是金枷玉锁，道不的儿女多来冤业多。","闲时节手执着板，闷来时口扬着歌。","谁似我快活。"]},{"t":"汉钟离度脱蓝采和・滚绣球","f":"曲","c":["从今后我独自个，休想我做过活。","再不去乔妆扮打拍撺掇，再不去戏台上信口开合。","(云)你又着我做场处唤王把色李薄头快疾快疾。","(唱)又着俺媳妇每，那一火。","快疾忙去梳裹，不争我又做场又索央众父老每妆喝。","(净云)自从哥哥去了，勾栏里就没人看。","(正末唱)为甚么勾栏里看的十分少，则你那话不投机一句多。","(净云)你说风话哩。","(正末唱)不是我风魔。"]},{"t":"汉钟离度脱蓝采和・快活三","f":"曲","c":["假若是无常到怎奈何。","(云)婆婆，你去波。","(唱)我如今得磨跎处且磨跎，待学庄子鼓盆歌，误了我亡身祸。"]},{"t":"汉钟离度脱蓝采和・朝天子","f":"曲","c":["行院每趱家私过活。","(旦云)都是一般行院，你多拿了几文钱出来，我务要平分。","(正末唱)问甚么你死我活。","(云)见别人朝来暮去，干家做活，瞒心昧己。","(唱)那一个肯依本分随缘过。","(云)我如今闲来看一卷道德经，困来睡一觉。","(唱)但得合处把我这眼皮儿合，得卧处和衣儿卧。","(旦云)都摆着你看，你那兄弟幼子娇妻许多家眷，怎下的撇了俺去出家！(正末唱)摆列着幼子娇妻，儿孙许多。","(云)则听得误了官身那一日，扣厅要打四十。","若不是师父救了我呵！(唱)假若是我无常谁替我。","(旦云)：既是这等，你也度脱我出家去。","(正末唱)你待着，不合把你来度脱。","(旦云)你回去罢，不济事。","(正末唱)赤紧的我也在壕中坐。"]},{"t":"汉钟离度脱蓝采和・尾声","f":"曲","c":["虽然俺便不得正果，把你个贤妻度脱。","你且与我安乐守分随缘过，只落得一日清闲兀的不快活杀我。","(下)。"]},{"t":"汉钟离度脱蓝采和・双调/新水令","f":"曲","c":["道门中法礼炼修持，俺师父度了个乐官徒弟。","俺师父明明的使道法，暗暗的说禅机，待和我同赴瑶池。","怎承望有今日。"]},{"t":"汉钟离度脱蓝采和・庆东园","f":"曲","c":["那里每人烟闹。","(云)是乐声响哩。","(唱)是一火君路歧，料应在那公科地，持着些枪刀剑戟，锣板和鼓笛。","更有那帐额牌旗，行院每是谁家，多管是无名器。"]},{"t":"汉钟离度脱蓝采和・沽美酒","f":"曲","c":["叹光阴忒紧急，嗟岁月苦奔驰。","重惜浮生如梦里。","我如今省得，无生死绝名列。"]},{"t":"汉钟离度脱蓝采和・太平令","f":"曲","c":["咱须是吾兄我弟，幼年间逐队相随。","止不过逢场学艺，出来的偌大小年纪，这个道七十，那个道八十，婆婆道九十，这厮淡则淡到长命百岁。","(净云)你是谁？(正末云)则我就是蓝采和。","(净云)你去了三十年，还不老。","只是这等模样。","(正末云)我去了只三年光景，你怎生都老了？(净云)我们都是老人家，你正是中年，还去勾栏里做几日杂剧，却不好？(正末唱)。"]},{"t":"汉钟离度脱蓝采和・川拨棹","f":"曲","c":["你待着我做杂剧，扮兴亡贪是非，待着我擂鼓吹笛，打拍收拾。","莫消停殷勤在意，快疾忙莫迟疑。"]},{"t":"汉钟离度脱蓝采和・七弟兄","f":"曲","c":["那时，我对敌，不是我说嘴，我着他笑嘻嘻将衣服花帽全新置。","旧么麽院本我须知，论同场本事我般般会。"]},{"t":"汉钟离度脱蓝采和・梅花酒","f":"曲","c":["他每都怎到的，论指点谁及，做手儿无敌，识紧慢迟疾。","(净云)哥哥，你那做杂剧的衣服等件，不曾坏了。","哥哥，你揭起帐幔试看咱；(正末唱)听言罢心内喜，不由我笑微微，我揭开帐幔则。","(做揭科)(钟离洞宾在内坐科，钟云)许坚，你凡心不退哩那！(正末唱)唬的我悠悠魂魄飞，我则道我哥哥我兄弟，我姊妹我姨姨，似南柯梦惊回。"]},{"t":"汉钟离度脱蓝采和・收江南","f":"曲","c":["呀，原来是开坛阐教汉钟离，有洞宾师父紧相随。","我这里云阳板撒上阶基，你都来这里，八仙相引赴瑶池。"]},{"t":"朱太守风雪渔樵记・仙吕/点绛唇","f":"曲","c":["十载攻书，半生埋没，学千禄。","误杀我者也之乎，打熬成这一付穷皮骨。"]},{"t":"朱太守风雪渔樵记・油葫芦","f":"曲","c":["说甚么年少今开万卷余，每日家长叹吁，想他这阴阳造化果非诬。","常言道是小富由人做，咱人这大富总是天之数。","我空学成七步才，谩长就六尺躯。","人都道书中自有千钟粟，怎生来偏着我风雪混樵渔？。"]},{"t":"朱太守风雪渔樵记・天下乐","f":"曲","c":["我一会家时复挑灯来看古书，我可便踌也波躇，那官职有也无，一会家受饥寒便似活地狱。","则俺这朱买臣，虽不做真宰辅，(云)我虽然不做官，却也和那做官的一般。","(杨孝先云)哥哥，可怎生与做官的一般？(正末唱)俺可也伴着他播清名一万古。","(杨孝先云)哥哥说的是。","(正末云)那江岸边不是哥哥的渔船？待我叫他一声。","(做叫科，云)哥哥。","(王安道云)俺两个兄弟来了也，快上船来！(做上船科)(王安道云)你两个兄弟请坐，老汉沽下一壶儿新酒，等你来荡寒，咱就此处闲攀话咱。","(杨孝先云)雪下的紧，着哥哥久等也。","(王安道做递酒科，云)兄弟满饮一杯。","(正末云)哥哥先请。","(王安道云)兄弟请。","(正末做饮酒科)(王安道再递酒科，云)孝先兄弟，满饮一杯。","(孝先做饮科)(王安道云)兄弟，咱闲口论闲话。","我想来这会稽城中有钱的财主每，不知他怎生受用，兄弟细说一遍。","我试听咱。","(正末云)哥哥，便好道风雪酒家天。","据着哥哥说呵，也有那等受苦的人；据着你兄弟说呵，也有那等受用的人。","(王安道云)兄弟也，可是那一等人受用？(正末云)哥哥且休题别处，则说会稽城中有那等仕户财主每，遇着那太热的时节，他也不受热；遇着那太冷的时节，他也不受冷。","哥哥不信时，听你兄弟说一遍咱。","(王安道云)兄弟，你道那财主每，他冬月间不受冷，夏月间不受热，你说的差了也。","可不道冷呵大家冷，热呵大家热，偏他怎生受用？你说，你说！(正末唱)。"]},{"t":"朱太守风雪渔樵记・村里迓鼓","f":"曲","c":["他道下着的是国家祥瑞，(带云)哥哥，这雪呵，(唱)则是与那富家每添助，(王安道云)那富贵的人家，怎生般受用快活？(正末唱)他向那红垆的这暖阁，一壁厢添上兽炭，他把那羊羔来浅注。","(王安道云)红垆暖阁，兽炭银瓶，饮着羊羔美酒，遇着这等大雪，果然是好受用也。","(正末云)哥哥，他一来可也会受用，第二来又遇着这般好景致。","(唱)门外又雪飘飘，耳边厢风飒飒，把那毡帘来低簌，(王安道云)看这等凛冽寒天，低簌毡帘，羊羔美酒正饮中间，还有甚么人扶侍他？(正末唱)一壁厢有各刺刺象板敲，听波韵悠悠佳人唱，醉了后还只待笑吟吟酒美沽，(王安道云)兄弟，这一会儿雪大风紧越冷了也！(正末唱)哎，哥也，他每端的便怎知俺这渔樵每受苦？(王安道云)兄弟，我想来你学成满腹文章，受如此穷暴，几时是你那发达的时节也？(正末唱)。"]},{"t":"朱太守风雪渔樵记・元和令","f":"曲","c":["总饶你似马相如赋《子虚》，怎比的他石崇家夸金谷。","(王安道云)那有钱的怎如你这有学的好也？(正末唱)岂不闻冰炭不同垆，也似咱贤愚不并居。","(王安道云)兄弟，我见这会稽城市中的人，有穿着那宽衫大袖的乔文假醋，诗云子曰，可不知他读书也不曾？(正末唱)他则待人前卖弄些好妆梳，扮一个峨冠士大大。"]},{"t":"朱太守风雪渔樵记・上马娇","f":"曲","c":["那一等本下愚，假扮做儒，他动不动一刻地谎喳呼。","见人呵闲言长语三十句，(王安道云)怕不的他外相儿好看，只是那腹中文章须假不得。","(正末唱)他虚道是腹隐九经书。"]},{"t":"朱太守风雪渔樵记・胜葫芦","f":"曲","c":["可正是天降人皮包草躯，(王安道云)他也曾看书么？(正末唱)学料嘴不读书。","他每都道见贤思齐是说着谬语。","那里也温良恭俭？(王安道云)那礼节上便不省的，倘遇着人说起诗词歌赋来，怎生答应？(正末唱)那里也诗词歌赋？端的个半星无。","(王安道云)兄弟，我今日也捕不的鱼，两个兄弟也打不的柴，咱各自还家去罢。","孝先兄弟，你家中借一担柴，与你哥哥将的家去，争奈媳妇儿有些不贤慧，免得他又要吵闹。","(正末唱)。"]},{"t":"朱太守风雪渔樵记・寄生草","f":"曲","c":["见哥哥把那鱼船缆，冻的我手怎舒？(王安道云)兄弟，好大雪也。","(正末唱)正值着扬风搅雪可便难停住。","你待要收纶罢钓还家去，哎，哥也！只怕你披蓑顶笠迷归路。","似这等战钦钦有口不能言，(带云)看了哥哥和兄弟这个模样呵，(唱)还说甚这晚来江上堪图处？。"]},{"t":"朱太守风雪渔樵记・后庭花","f":"曲","c":["想当日傅说曾板筑，(孤云)传说板筑，殷高宗建为太宰。","还再有谁？(正末唱)更有那倪宽可便曾抱锄。","(孤云)倪宽是我武帝时御史大夫，还再有谁？(正末唱)有一个宁戚曾歌牛角，(孤云)宁戚叩角而歌，齐桓公举为上卿。","还再有谁？(正末唱)有一个韩侯他也曾去钓鱼。","(孤云)韩侯就是那三齐王韩信，果然曾钓鱼来。","可再有谁？(正末唱)有一个秦白起是军卒，(孤云)那白起是秦将，起于卒伍之中。","再呢？(正末唱)有一个冻苏秦田无半亩。","(孤云)苏秦后来并相六国，可怎么冻的他死？再呢？(正末唱)有一个公孙弘曾牧猪，(孤云)那公孙弘也是我汉朝的宰相，曾牧猪于东海。","再呢？(正末唱)有一个灌将军曾贩屦。","(孤云)那灌婴我只知他贩缯，却不知他贩屦。","(正末唱)朱买臣一略数，请相公听拜覆。"]},{"t":"朱太守风雪渔樵记・青哥儿","f":"曲","c":["哎，我这里叮咛、叮咛分诉，这都是始贫、始贫终富。","(带云)且休说别的，则这一个古人，堪做小生比喻。","(孤云)可是那个古人？(正末唱)则说那姜子牙，正与区区可比如。","他也曾朝歌市里为屠，蟠溪水上为渔，直捱到满头霜雪八旬余，才得把文王遇。"]},{"t":"朱太守风雪渔樵记・赚煞","f":"曲","c":["一转眼选场开，发了愿来年去，直至那长安帝都，(孤云)据凭贤士锦绣文章，何所不至！(正末唱)凭着我锦绣也似文章敢应举。","(孤云)明年去，也是迟了。","(正末云)大人，你道为何，这几年不进取功名来？(孤云)这可是为何？(正末唱)也是我不得时可便韫椟藏诸，我若是的鳌鱼，怕不就压倒群儒？(孤云)贤士，你若去进取功名，岂在他人之下。","(正末唱)我着普天下文人每，那一个不拱手的伏！(孤云)请贤士收拾琴剑书箱，来年应举去也。","(正末云)大人，别的书生用那琴剑书箱，小生则用着身边一般儿物件，夺取皇家富贵。","(孤云)贤士，可那一般儿物件？(正末唱)凭着这砍黄桑的巨斧，端的便上青霄独步，(云)别的书生说道月中丹桂，若到的那里，折得一枝回来，足可了一生之愿。","不是我朱买臣敢说大言也，(唱)落可便我把那月中仙桂剖根除。","(下)。"]},{"t":"朱太守风雪渔樵记・滚绣球","f":"曲","c":["头直上乱纷纷雪似筛，耳边厢飒刺刺风又摆，(带云)可端的便这场冷也呵，(唱)哎哟，勿、勿、勿！畅好是冷的来奇怪，(带云)天那、天那！(唱)也则是单注着这穷汉每月值年灾。","(带云)似这雪呵，(唱)则俺那樵夫每怎打柴？便有那渔翁也索罢了钓台，(带云)似这雪呵，(唱)则问那映雪的书生安在，便是冻苏秦也怎生去搠笔巡街？则他这一方市户有那千家闭，抵多少十谒朱门九不开，(带云)似这雪呵，(唱)教我委实难捱。"]},{"t":"朱太守风雪渔樵记・快活三","f":"曲","c":["你怎不学贾氏妻，只为射雉如皋笑靥开？(旦儿云)我有甚么欢喜在那里，你着我笑？(正末云)你不笑，敢要哭，我就说一个哭的。","(唱)你怎不学孟姜女，把长城哭倒也则一声哀？(旦儿云)朱买臣，穷叫化头！我也没工夫听这闲话。","将休书来，休书来！(正末唱)你则管哩便胡言乱浯将我厮花白，你那些个将我似举案齐眉待？。"]},{"t":"朱太守风雪渔樵记・醉太平","f":"曲","c":["卓文君你将那书桌儿便快抬，(旦儿云)你可似谁？(正末唱)马相如，我看你怎的把他去支划，(旦儿云)纸笔在此，快写了罢。","(正末唱)你、你、你，把文房四宝快安排。","(云)刘家女，我写则写，只是一件，人都算我明年得官，我若得了官呵，把个夫人的名号与了别人，你不干受了二十年的辛苦！(旦儿云)我辛苦也受的勾了，委实的捱不过。","是我问你要来，不干你事。","(正末云)请波，请波。","(唱)你也索回头儿自揣，(旦儿云)我揣个甚么？是我问你要休书来，不干你事。","(正末唱)非是我朱买臣不把你糟糠待，赤紧的玉天仙忍下的心肠歹。","(带云)罢、罢、罢。","(唱)这梁山伯也不恋你祝英台，(云)任从改嫁，并不争论。","左手一个手模。","将去！(唱)我早则写与你个贱才！。"]},{"t":"朱太守风雪渔樵记・二煞","f":"曲","c":["那知道岁寒然后知松柏，你看我似粪土之墙朽木材。","断然是捱不彻饥寒，禁不过气恼，怎知我守定心肠，留下形骸。","但有日官居八座，位列三台，日转千阶。","头直上打一轮皂盖，那其间谁敢道我负薪来？。"]},{"t":"朱太守风雪渔樵记・仙吕/赏花时","f":"曲","c":["十载诗书晓夜习，(杨孝先云)哥哥此去，必然为官也。","(正末唱)一举成名天下知，(王安道云)兄弟，你哥哥专听喜信哩！(正末唱)你是必耳打听好消息。","(做拜别科)(王安道云)兄弟，你小心在意者。","(正末唱)休嘱付小心在意，我可敢包夺的一个锦衣归。","(下)。"]},{"t":"朱太守风雪渔樵记・醉春风","f":"曲","c":["你看我抖搜着老精神，我与你便花白么娘那小贱人。","想着你二十载夫妻怎下的索休离，这妮子你畅好是狠，狠。","道不的个一夫一妇，一家一计，你可甚么一亲一近。"]},{"t":"朱太守风雪渔樵记・迎仙客","f":"曲","c":["我则见那公吏一字儿摆，那父老每两边分。","(云)无一时则见那西门骨刺刺的开了，我则见那骨朵衙仗，水罐银盆，茶褐罗伞，那五明马上坐着的呵，(刘二公云)可是谁那？(张云)我买卖忙，不曾看，我忘了也。","(刘二公云)我央及你波，那做官的可是谁？(张云)等我想，哦，我想起来了也。","(唱)是你那前年索了休离的唤做朱买臣！(刘二公云)惭愧，俺家女婿做了官也！(张云)老弟子孩儿！你道不要便宜，去年时节不说是你家女婿，今日得了官，便说是你家女婿，一个好相公也！(唱)他可不托大不嫌贫，(云)他不看见我，万事都休；一投得见了我，便认的俺是本村里张伯伯，连忙滚鞍下马，按我在那银交椅上，纳头的拜了两拜。","(唱)他先下拜险些儿可便惊杀那众人。","施礼罢复叙寒温，(云)那相公问道：王安道哥哥好么？杨孝先兄弟好么？那四村上下、姑姑姨姨、婶子伯娘、兄弟妹子，都好么？我道：都好，都好。","(唱)他把那旧伴等可便从头儿问。"]},{"t":"朱太守风雪渔樵记・喜春儿","f":"曲","c":["刚只是半星儿道着呵，(张做嘴脸科)(旦儿云)老的，你怎么做这嘴脸？(张唱)他把你十分恨，(旦儿云)他恨我些甚么那？(张唱)他无非想着你一夜夫妻有那百夜恩。","(旦儿云)他还说甚么？(张唱)他道汉相如伸意你个卓文君，(旦儿云)伸个甚的意思？(张云)他道你把车驾的稳，(旦儿云)他敢是要来取我么？(张唱)没着便嫁他人？。"]},{"t":"朱太守风雪渔樵记・上小楼","f":"曲","c":["你道他忘人大恩，又道他记人小恨。","谁着你生勒开他，生则同衾，死则同坟。","(旦儿云)他每日家偎妻靠妇，四十九岁，全不把功名为念。","我生逼的他求官去，我是歹意来？(张唱)你道他过四旬，还不肯把那功名求进，(云)老的也，你记的俺庄东头王学究说的那一句书儿么？(刘二公云)是那一句书？(张唱)他则是个君子，可便固守本分。"]},{"t":"朱太守风雪渔樵记・幺篇","f":"曲","c":["那妮子强勒他休，这老子又绝了他亲。","眼见的身上无衣，肚里无食，(带云)大雪里赶出他来，(唱)可着他便进退无门。","(刘二公云)我孩儿又不曾别嫁了人，是斗他耍，怎么这等认真，就说嘴说舌，背槽抛粪？(张唱)你道他才出身，便认真，和咱评论，(云)他在你家做了二十年女婿，只是打柴做活，不曾受了一些好处，临了着个妮子大风大雪里勒了休书，赶他出去，你则说波，(唱)这个是谁做的来背槽抛粪？(刘二公云)哎，他如今做了官，便不认的俺家里，眼见的是忘恩背义了也！(张唱)。"]},{"t":"朱太守风雪渔樵记・满庭芳","f":"曲","c":["这的是知恩哎报恩，(旦儿云)他再说些甚么来？(张唱)他着你便别招女婿，再嫁取个郎君。","(旦儿云)他再说些甚么来？(张唱)他道你枉则有蛾眉螓首堆鸦鬓，可怎生少喜多嗔。","道你是个木乳饼钱亲也那口紧，道你是个铁扫帚扫坏他家门。","(旦儿云)他再说些甚么来？(张唱)他道你便无些儿淹润，又道你不和那六亲，端的是雌太岁，母凶神！(云)误了我买卖也，(摇鼓做走科)(旦儿云)老的，还有甚说话，一发说了罢。","(张云)他说来，说来！(唱)。"]},{"t":"朱太守风雪渔樵记・耍孩儿","f":"曲","c":["他肩将那柴担担，口不住把书赋温，每日家穿林过涧谁瞅问？他和那青松翠柏为交友，野草闲花作近邻。","但行处有八个宇相随趁，(刘二公云)是那八个宇？(张唱)是那斧镰绳担、琴剑书文。","(旦儿云)他如今做了官，比那旧时模样，可是如何？(张唱)。"]},{"t":"朱太守风雪渔樵记・一煞","f":"曲","c":["他如今得了本处官，端的是别换了一个人，那的是貌随福转你可也急难认。","他往常黄干黑瘦衣衫破，(带云)你觑去波，(唱)到如今白马红缨彩色新。","一弄儿多豪俊，摆列着骨朵衙仗，水罐银盆。","(刘二公云)这话不是他说的，都是你说的。","(旦儿云)说了这一日，都是你这老苘麻嘴，没空生有，说谎吊皮，片口张舌，口困出来的！(张唱)。"]},{"t":"朱太守风雪渔樵记・煞尾","f":"曲","c":["这的是他道来，他道来，可着我转伸，我转伸。","(刘二公云)他做了官呵，便把我怎的？(张云)他敢怎的你？(唱)他将你扌朋扒吊栲施呈尽！(旦儿云)呸！我是他的夫人，他敢怎么的我？(张云)误了我买卖！(摇鼓叫科，云)笊篱马杓，破缺也换那！(唱)直将你那索休离的冤仇他待证了本！(下)。"]},{"t":"朱太守风雪渔樵记・川拨棹","f":"曲","c":["我则待打张干，(云)且问那吃打的是谁？(杨孝先云)哥哥，是你兄弟杨孝先。","(正末唱)原来是同道人杨孝先。","(孝先做拜、踞倒酒瓶科)(正末回科，云)兄弟免礼！(杨孝先云)哥哥喜得美除！(王安遭云)兄弟你也来了？(正末云)兄弟好么？(杨孝先云)哥哥，您兄弟好。","(正末唱)俺也曾合火分钱，共起同眠，间别来隔岁经年。","(云)兄弟也，你如今做甚么营生买卖？(杨孝先云)哥哥，你兄弟依旧打柴哩。","(正末唱)还靠着打柴薪为过遣，怎这般时命蹇？(刘二公同旦儿上，云)孩儿，俺和你同见朱买臣去来。","(旦儿云)父亲，我先过去。","(刘二公云)孩儿你先过去，看他认也不认。","(旦儿见跪科，云)相公喜得美除，我道你不是个受贫的么！(正末云)俺这朋友饮酒处，张千，谁着你放他这妇人来？打起去！(唱)。"]},{"t":"朱太守风雪渔樵记・七弟兄","f":"曲","c":["这是那一家宅眷？稳便。","(王安道云)夫人也，来了也。","(正末做见、怒科，唱)请起波玉天仙！去年时为甚耽疾怨？觑绝时不由我便怒冲天，今日家咱两个重相见。"]},{"t":"朱太守风雪渔樵记・梅花酒","f":"曲","c":["呀，做多少假腼腆，咱须是夙世姻缘，今世缠绵，可怎生就待不到来年？(旦儿云)相公，旧话休题。","(正末唱)当初你要休离我便休离，你今日呵要团圆我不团圆。","(云)刘家女，你不道来那。","(旦儿云)我道甚么来？(正末唱)你道你正青春正少年，你道你好描条好眉面，善裁剪善针线，无儿女厮牵连，别嫁取个大官员。"]},{"t":"朱太守风雪渔樵记・雁儿落","f":"曲","c":["你这卓王孙呵，怎生便不重贤？(王安道云)他是刘二公，怎做的那卓王孙？(正末云)他既不是卓王孙，(唱)索怎生则搬调的个文君女嫌贫贱？我则问你，逼相如索了休，你当初可也对苍天曾罚愿？(云)今日座上的众人，你可认得么？(旦儿云)认的。","这个是王安道伯伯，这个是杨孝先叔叔。","(正末唱)。"]},{"t":"朱太守风雪渔樵记・甜水令","f":"曲","c":["折莫你便奔井投河，自推自跌，自埋自怨！","(旦儿云)王伯伯，你劝一劝儿波！","(正末唱)便央及煞俺也不相怜！","折莫便一来一往，一上一下，将咱解劝，总盖不过你这前愆。"]},{"t":"朱太守风雪渔樵记・折桂令","f":"曲","c":["从来你这打渔人顺水推船，想着那凛冽寒风，大雪漫天。","想着我那身上无衣，肚里无食，怀内无钱。","(云)刘家女，你不道来？(旦儿云)我道甚么来？(正末唱)你怕甚舍不得我那南庄北园，撇不了我那东阁西轩？我如今旱地上也无田，水路里也无船。","只除这紫绶金章，可不的依还是赤手空拳？(云)刘家女，你欲要我认你也，你将一盆永来。","(张千云)水在此。","(王安道云)相公，你只认了夫人罢！(正末唱)。"]},{"t":"朱太守风雪渔樵记・沽美酒","f":"曲","c":["我只道你泼无徒心太偏，元来是姜太公使机变，不钓鱼儿只钓贤。","你可便施恩在我前，暗赍发与盘缠。"]},{"t":"朱太守风雪渔樵记・太平令","f":"曲","c":["从来个打渔人言如钩线，道的我羞答答闭口无言。","明明的这关节有何难见，险些把一家儿恩多成怨。","我如今意转，性转，也是他的运转，呀，不独是为尊兄做些颜面。"]},{"t":"朱太守风雪渔樵记・鸳鸯煞尾","f":"曲","c":["方知是皇明日月光非遍，天恩雨露沾还浅。","道我禄薄官卑，岁加二千，昔日穷交，都皆赐田。","便是妻子何缘，早遂了团圆愿。","倒与他后世流传，道这风雪渔樵也只落的做一场故事儿演。","(刘二公云)天下喜事，无过夫妇团圆。","今日既是认了，便当杀羊造酒，做一个庆贺的筵席！(词云)玉天仙容貌多娇媚，恋恩情进取偏无意。","假乖张故逼写休书，到长安果得登高第。","除太守即在会稽城，显威风谁不惊回避。","怀旧恨夫妇两参商，覆盆水险做傍州例。","若不是严司徒赍敕再重来，怎结末朱买臣风雪渔樵记？。"]},{"t":"瘸李岳诗酒玩江亭・仙吕/点绛唇","f":"曲","c":["则我这宝篆氤氲，麝兰香喷，家滋润。","瑞气迎门，端的是人物偏丰韵。"]},{"t":"瘸李岳诗酒玩江亭・金盏儿","f":"曲","c":["你则是怕当军，倦为民，两桩儿曾与高人论。","你有则得半仙之分，你更不全真。","速离了八仙洞，飞下那九天门。","你则是个逍遥云外客，特地来点化俺这世间人。"]},{"t":"瘸李岳诗酒玩江亭・尾声","f":"曲","c":["俺这梅他粉包了心，檀黄嫩，插在那银瓶里宜得水温，如麝如兰香喷喷，端的有欺霜傲雪的精神。","哎，你个许真人，白日飞升，比不的岳阳楼下枯干了的柳树神。","他也无那神仙的福分，则有些江梅丰韵，冷清清今夜待黄昏。","(下)。"]},{"t":"瘸李岳诗酒玩江亭・南吕/一枝花","f":"曲","c":["良辰晓雾浓，美景韶光丽。","草茵轻荏苒，则他这桃李任芳菲。","春日迟迟，槛外黄莺呖，帘前紫燕飞。","幸开怀宴乐欢娱，俺可便宜赏玩，情甘意美。"]},{"t":"瘸李岳诗酒玩江亭・十二月","f":"曲","c":["穿的是麻袍和这草履，(云)呸！是草鞋，错唱了草履。","便也罢，则是难为我唱了，从头都改过哩。","也罢，也罢，一言既出，驷马追而不及。","我若不改了，显的我就无才学了。","(唱)穿的是麻袍和这草鞋，更强似着绿穿白。","我伴的是鲇鱼和这鲤鱼，铺的是杆草茅柴。","采的是不老长生的药材，俺可便每日家厮捱，(云)你不知道怎么捱，俺师父有两个徒弟，一递一日打柴。","他打柴，我学道。","我打柴，他学道。","该我我便去，该他他便去。","他不去，我肯去。","(唱)俺可便每日家厮捱。"]},{"t":"瘸李岳诗酒玩江亭・尧民歌","f":"曲","c":["我则待要引着狗骑着猫逍遥散澹乘兴歌曲过南台，(云)我是出家人，我心里待要往南台，就往南台，要往北闸口去，谁敢当拦住我？(唱)我则待靠着水偎着山小小低低急留圪刺椽儿捧儿拴拴抓抓盖一座茅庐那幽哉。","一似那乱纷纷急穰穰蜂衙蚁阵受禁害，稽首，则不如跟贫道打简子掴渔鼓抢着吃挝着吃抹油嘴无扰无虑那开怀。","伤也波哉，寻着李太白，我着你便一个人生一身疥。"]},{"t":"瘸李岳诗酒玩江亭・锦上花","f":"曲","c":["则不如我展放开愁眉，休争闲气。","今日容颜，老似昨日。","古往今来，我须尽知。","贤的愚的。","贫的共富的，到头这一场，难逃那一日。","则不如快活了一日，一日便宜。","百岁光阴，七十又早稀。","咸的酸的，香的共臭的。"]},{"t":"瘸李岳诗酒玩江亭・隔尾","f":"曲","c":["你挟着这半截家竹桶闲行立，你可甚么一部笙歌出入随。","几曾见子弟舍里新添了个八仙队。","不争你在这里，俺门前立地，着人道出落着你个先生少可有二十嘴。"]},{"t":"瘸李岳诗酒玩江亭・红芍药","f":"曲","c":["你和他每日炼修持，可待要说是谈非。","(牛员外云)俺师徒二人，这一向在山中修炼。","师父也离不的我，我也离不的师父，吃饭的工夫也没了。","(正旦唱)你与他每日不曾离，直这般废寝忘食。","(牛员外云)我与你做个师父，你与我做个徒弟，我把手捏腕，传与你金丹大道，可是如何？(正旦唱)我则道因个甚的。","我这里便谢吾师说破玄机。","厮抹着肩胛手相携，说您那弄盏传杯。"]},{"t":"瘸李岳诗酒玩江亭・菩萨梁州","f":"曲","c":["你道是先生，与你回席，灌的你十分沉醉。","长留做共薄醅，真乃是水酒三杯。","(先生上，云)牛郎说与赵江梅。","(牛员外做吃惊科，云)道可道，非常道；名可名，非常名。","(笑科)(正旦唱)你道是牛郎说与赵江梅，(云)可也怪不着也。","(唱)你可甚么一枝泄漏春消息。","他别人铜斗儿般好家计，指空划空信着你，你搬调的他弃子抛妻。","(先生云)他不合说与外人知。","(正旦唱)。"]},{"t":"瘸李岳诗酒玩江亭・贺新郎","f":"曲","c":["你道是他不合说与外人知，(先生云)打这厮口发虚言。","(正旦唱)你打他口发虚言，你大古里脚踏着实地。","(先生云)我踏罡步斗驱邪祟，仗着剑书符咒水。","(正旦唱)则你那踏罡步斗驱邪祟，你杖剑书符也那咒水，休阿则你那不济事谎话儿休题。","(先生云)跟我出家去呵，我着你全身无病疾，远害免灾危。","(正旦唱)你着俺全身无病疾，远害免灾危，见如今拄着一条粗拐瘸着一条腿。","那些个满川缚虎意，犹自说兵机！。"]},{"t":"瘸李岳诗酒玩江亭・中吕/粉蝶儿","f":"曲","c":["今日个横饮金瓯。","吃的来醉醺醺不知一个前后，(云)若见俺牛员外呵，(唱)我和他话不相投。","我可便见他呵，相逢处，这一场迤逗。","将他那衣快忙揪。","拽起运绿罗裙揎拳裸袖。"]},{"t":"瘸李岳诗酒玩江亭・石榴花","f":"曲","c":["你道是将恩爱变为仇。","(牛员外云)我随缘过的便合休。","(正旦唱)你道是随缘过的便合休，(牛员外云)我与你做个师父。","(正旦唱)打一个稽首，(牛员外云)兀的不是也。","(正旦唱)便要回头。","(牛员外云)我清风明月为知友。","(正旦唱)倚仗着你清风明月为知友，那的是阆苑神洲。","(牛员外云)我每日家麻绦草履垂袍袖。","(正旦唱)你道你那麻绦草履垂袍袖，这的是你拄杖恰过头。"]},{"t":"瘸李岳诗酒玩江亭・十二月","f":"曲","c":["你可便坚心儿强口，他可便不害那惭羞。","(牛员外云)我这般躬身叉手。","曲脊低头，背着你，街上人都捻舌，排说我哩。","(正旦唱)长街上躬身叉手，我见他便曲脊低头。","长街上惹的人家嘴口，不争你厌背着娇羞。"]},{"t":"瘸李岳诗酒玩江亭・尧民歌","f":"曲","c":["呀，着人道牧童归去倒骑牛，呀，敢抵多少一千个刘盼盼闹衡州。","这的是前街后巷滴滴蹬蹬马和牛，这的是恋酒迷花风风魔魔下场头。","(牛员外云)我如今去见了师父说知，着你跟我也做神仙去。","(正旦唱)休也波诌，待学马半州，去也我可也做不的刘行首。"]},{"t":"瘸李岳诗酒玩江亭・耍孩儿","f":"曲","c":["我身将跨凤乘鸾友，都做了参辰卯酉。","(牛员外云)我如今等闲恩爱等闲休。","(正旦唱)你道是等闲恩爱等闲休，空着咱一任难酬。","(牛员外云)我如今饱谙世事慵开口。","(正旦唱)你如今饱谙世事慵开口，会尽人间只点头。","把浮生梦都参透，撇了这酒色财气，真个是谭马丘刘。"]},{"t":"瘸李岳诗酒玩江亭・二煞","f":"曲","c":["我为甚先打你这头？(牛员外云)你为何赠我这一击。","怎么说？(正旦唱)我则是到来年吃贱牛，则你那一天和气恩情厚。","你行处春日风动，你过处春山春水流，你模佯忒出丑。","(牛员外云)我模样忒出丑？哦，他也则是嗓磕我这牛哩。","你再有何比并？(正旦唱)你抛了这朝云暮雨，则恐怕误了你那春种秋收。"]},{"t":"瘸李岳诗酒玩江亭・尾声","f":"曲","c":["准备着硬绳去你那鼻窍里穿，(牛员外云)你怎生则嗓磕我这牛？(正旦唱)粗鞭杖把你那胯骨上丢。","则你那偷寒送暖村皮肉，我教你绰见我这庞儿望风儿似走。","(同下)。"]},{"t":"瘸李岳诗酒玩江亭・双调/新水令","f":"曲","c":["则您这出家儿受用似比那富家郎，哎，你个鼓盆歌老先生休强。","吃了些无是非的稀解粥，忍了些受饥饿瘦皮囊。","空着我腹热肠慌，则不如葫芦提吃的来粉红样。"]},{"t":"瘸李岳诗酒玩江亭・川拨棹","f":"曲","c":["这厮狠心肠，没道理别势样。","好教我急急忙忙，腹热肠慌。","(牛员外云)阿，罢了，歪了船，淹上水来了。","踏着这边晃一晃，看他怕也不怕。","(正旦唱)这晰他撑的个小船儿摇摇晃晃，我心中慌上慌，我心中忙上忙。"]},{"t":"瘸李岳诗酒玩江亭・七兄弟","f":"曲","c":["这厮便指望，大纲要成双，(牛员外云)你走的那里去？(正旦唱)百般的不肯将咱放。","身躯儿左右怎遮拦，手脚儿怎生难遮当？。"]},{"t":"瘸李岳诗酒玩江亭・梅花酒","f":"曲","c":["呀，谁承望这一场，我恰才身命在长江。","面对看沙滩。","空腹热肠慌。","不见卷云涛波浩浩，翻滚滚水茫茫。","谁承望这一场，(先生上，云)赵江梅，你省也么？(正旦云)师父，弟子省也。","(唱)我则道是画眉郎，睡梦里厮魔障。"]},{"t":"瘸李岳诗酒玩江亭・喜江南","f":"曲","c":["呀，今日个刘行首省悟也波马丹阳，不求白日赴仙乡，落花深处水茫茫。","俺可便玩赏，今日个拜三清同赴上天堂。"]},{"t":"摩利支飞刀对箭・仙吕/点绛唇","f":"曲","c":["万里青霄，四方明照，行仁道。","俺父亲他则着我耕种锄刨，似恁的几时上凌烟阁？。"]},{"t":"摩利支飞刀对箭・混江龙","f":"曲","c":["我如今五陵年少，不能够夺旗扯鼓显英豪，恰便似天边老雁，更和那云外孤鹤。","我不能够边塞上统军居帅府，丹墀内束带立于朝，我干受了半生苦志，十载劬劳。","姜太公渭河边垂钓，伍员在丹阳县吹箫。","待进来眼前有八荒荆棘，待退来脑后有万丈波涛。","我如今修不成活计，垒不就窝巢。","每日家苦淹淹守定这座大黄庄，空着我便眼巴巴盼不到长安道。","我不能够奋青云雕鹗，我倒不如那傲夏日鹪鹩！(云)薛仁贵也，几时是你那发达的时节也呵！(唱)。"]},{"t":"摩利支飞刀对箭・天下乐","f":"曲","c":["几时能够宫殿风微燕雀高？我这里便量也波度，不由我心内焦，则我那上天梯若还寻觅着。","龙能够致雨风，虎能够奋牙爪，将我这严生志须应了。"]},{"t":"摩利支飞刀对箭・那吒令","f":"曲","c":["我这里见父亲，烦烦恼恼；(卜儿云)老的，休打孩儿，且饶过这一遭者。","(正末唱)母亲那里劝着，俺父亲他忄敝忄敝噪噪；(旦儿云)哎约！这个父亲，今日也说打，明日也说打，不付能寻将来，父亲可又不打他。","(正末云)噤声！(唱)他那里嘴不剌的，他也聒聒噪噪！(孛老儿云)我说着他，他倒寻媳妇儿的不是。","孩儿也，你也似不的那闵子贤，曾参孝。","(正末唱)我似不的那闵子般贤，我学不的曾参般孝，和你一个鼓瞍把我闲瞧。"]},{"t":"摩利支飞刀对箭・鹊踏枝","f":"曲","c":["动不动黄桑棒拷折腰，是不是坐囚牢。","我可甚恭俭温良，你可甚善与人交？(孛老儿云)你不做庄农生活，每日则是刺枪弄棒，你怎么能够长进？(正末唱)有一日长全我这六梢，(孛老儿云)你可待往那里去？(正末唱)我可敢飞腾过万里青霄。","(孛老儿云)俺庄农人家，欲要富，土里做；欲要牢，土里刨。","你说你会武艺，你就在这草堂上敷演一遍，我试看者。","(正末云)我在这草堂上敷演一遍，父亲、母亲，你试看者。","(唱)。"]},{"t":"摩利支飞刀对箭・寄生草","f":"曲","c":["我若是临军阵，恶战讨。","遮莫他扑碌碌队伍在这杀场上闹，乱纷纷土雨在空中落，慢腾腾杀气头直上罩。","遮莫便骨刺刺杂彩绣旗摇，遮莫便扑冬冬画鼓征鼙噪！。"]},{"t":"摩利支飞刀对箭・后庭花","f":"曲","c":["休将你这歹孩儿留恋着，枉把我这功名来耽误了。","(孛老儿云)你这一去，凭着你甚么武艺那？(正末唱)凭着我这四海五湖量，(孛老见云)孩儿也，则做庄农罢。","(正末唱)我怎肯深村里穷到老？(孛老儿云)两阵之间，你怎生与他拒敌？(正末唱)你看我便显英豪，听您这歹孩儿言道，马头前若撞着，仗英雄显荣耀！(卜儿云)孩儿也，便好道父母在堂，不可远游也。","(正末唱)见母亲留恋着，老家尊心内焦。","(孛老儿云)好共歹不要你去。","(正末云)父亲，您孩儿若不去呵，(唱)。"]},{"t":"摩利支飞刀对箭・青哥儿","f":"曲","c":["休阿！枉惹的乡人、乡人耻笑，(云)父亲，您孩儿尽忠，不能尽孝也。","(唱)我报不的哀哀父母劬劳，(孛老儿云)孩儿也，你伴着那沙三、伴哥、王留，饮酒耍子，可不好？(正末唱)我可甚么人伴贤良智转高。","(孛老儿云)你听的谁说来？(正末唱)则听的绛州人道，黄榜上名标。","我将这义军来投了，骨刺刺摆开旗号。","二马相交，王吉玎的箭对了飞刀。","轻舒猿猱，磕答的扌昝住征袍，滴溜扑摔下鞍鞒，将背唐朝高丽一只手扌昝住头梢，把那厮扌蚩扌蚩的拖来到。","(孛老儿云)孩儿也，便好道心去意难留，留下结冤仇。","去则去，得官不得官，你则早些儿回来，休着老汉忧心也。","(正末云)则今日好日辰，辞别了父亲、母亲，便索长行也。","(卜儿云)孩儿也，你这一去，得官不得官，则要你早些儿回来，休着我忧心也。","(正末云)大嫂，你在家中，好生看觑一双父母。","我若为了官呵，你便是夫人县君也。","(旦儿云)住、住、住！薛仁贵，父亲在上，依着妾身说呵，可以待时守分，耕种为活，堪可度日，侍奉一双父母，不强似名利奔波？你坚心要去，我未知你的主意如何也？(正末唱)。"]},{"t":"摩利支飞刀对箭・尾声","f":"曲","c":["我则要身到凤凰池，有心待标写在凌烟阁。","与敌兵相持战讨，下寨安营边塞遥。","我胸中虎略龙韬，看杀气阵云高，荡征尘土雨潇潇，则我这马到处贼兵都退了。","(孛老儿云)你这一去，凭着你些什么手策也？(正末唱)倚仗我拨天关手爪，凭着我这撼乾坤勇跃，舍着我这一腔鲜血立唐朝！(下)(孛老儿云)孩儿去了也。","这一去，他必然为官也。","老汉无甚事，回我那家中去也。","眼观旌捷旗，耳听好消息。","(同下)。"]},{"t":"摩利支飞刀对箭・正宫/端正好","f":"曲","c":["看别人云滚滚省台登，看别人云滚滚省台登，几时能够闹穰穰公侯做。","则他那谒朱门缘木求鱼，则这书中自有他这黄金屋，将我久困在红尘路。"]},{"t":"摩利支飞刀对箭・滚绣球","f":"曲","c":["每日家听钟声山寺里斋，赶宿头古庙里居，有那等财主每，听笙簧则在那画堂深处，如今那有学的酩子里韫椟藏诸。","我看了这今世图，这时务，杠了我交语，赤紧的满眼卫不辨贤愚。","存的我这胸中三卷黄公略，我愁甚么架上三封天子书，恰便似饿虎当途。"]},{"t":"摩利支飞刀对箭・快活三","f":"曲","c":["小人在龙门镇是我祖居，(张士贵云)你可在那里居住？(正末唱)大黄庄有我的家属。","(张士贵云)你从小里习学甚么武艺来？(正末唱)自小里习文演武用工夫。","(张士贵云)你可来俺这元帅府做什么？(正末唱)特地来夺富贵争名目。"]},{"t":"摩利支飞刀对箭・朝天子","f":"曲","c":["遮莫待开弓也那蹬弩，(张士贵云)你敢扬威耀武么？(正末唱)扬威也那耀武。","(张士贵云)你敢阵面上相持去么？(正末唱)我情愿阵面上相持去，(张士贵云)我就用你在我军阵中，做个小卒，你意下如何？(正末唱)但能够军阵里做一个小卒，(张士贵云)我着你合后当先，你敢去么？(正末唱)遮莫便合后等当先去，(张士贵云)兀那厮，你是军健汉，逢山开路，遇水叠桥，你敢去么？(正末唱)遮莫待遇水叠桥，逢山开路，(张士贵云)你敢施威、敢射虎么？(正末唱)我可便敢施威、敢射虎。","(张士贵云)就用了这厮。","(正末唱)大人若是用度、用度了这勇夫，我马到处写满了您那功劳簿。"]},{"t":"摩利支飞刀对箭・齐天乐","f":"曲","c":["当街里马头来拦住，听小人从头细说当初。","(徐懋功云)你那里人氏？姓甚名谁？(正末唱)小人是农夫，大黄庄有我的家属。","来时节欢娱，到的这龙门镇揭黄榜过去。","正犯着大人名讳，他道是不用俺这村夫。","磕答的弓拽折，急恼的元帅怒，他道我该斩该徒。"]},{"t":"摩利支飞刀对箭・红衫儿","f":"曲","c":["军兵牢拿住，绑在长街去，好教我气长吁，气长吁，仰面嚎啕哭。","大人也，薛仁贵委实的衔冤负屈。"]},{"t":"摩利支飞刀对箭・尾声","f":"曲","c":["愿吾皇慑夷狄，降边国，千千年九五飞龙齐天福。","愿吾皇永坐着宗庙旧，家邦老，万万载百二山河壮帝居。","到来日看排兵，列士卒；荡征尘，腾土雨，旱路上亡，水面上浮；成不的功，变不的虎。","我直杀的他呐不的喊，摇不的旗，放心也，我着他便擂不的鼓！(下)。"]},{"t":"摩利支飞刀对箭・仙吕/赏花时","f":"曲","c":["那厮便耀武扬威说大言，怎敢今番夺众权？(摩利支云)我飞刀起！(正末云)箭对了！(摩利支云)飞刀起！(正末云)箭对了！(摩利支云)飞刀起！(正末云)箭对了！(摩利支云)五口飞刀，对了我三口，留着两口防身。","不中，我也近不的他，拨回马，我与你走、走、走！(下)(正末唱)他那里飞刀起，我这里箭离弦。","杀的他身躯倒偃，我见他拨回马走当先。"]},{"t":"摩利支飞刀对箭・幺篇","f":"曲","c":["你可甚为看青山懒赠鞭，看的俺唐十宰公卿如芥藓。","遮莫他变做神鬼化做飞仙？(云)待走往那里去？(唱)离不了天涯和那海边！(云)众军校跟我去来。","(唱)我与你直赶到他这个焰魔天！(下)。"]},{"t":"摩利支飞刀对箭・越调/斗鹌鹑","f":"曲","c":["走的我汗似汤浇，浑身上水洗。","恰离了乱撺军营，急煎煎盼不到元帅府里。","两只脚飞腾，一声儿踹起。","苦亡家，倾败国，恶战敌。","人着箭踉跄身歪，马中枪惊急里脚失。"]},{"t":"摩利支飞刀对箭・紫花儿序","f":"曲","c":["焰腾腾火烧了寨栅，浪滔滔水淹了营垒，不剌剌马踏碎丁城池。","英雄虎将，世上无敌，难及。","一个个擐甲披袍那气势，耀武扬威，擂鼓筛锣，呐喊摇旗！。"]},{"t":"摩利支飞刀对箭・寨儿令","f":"曲","c":["鼓震的山岳摧，喊一声鬼神悲，荡征尘翻滚滚火门辉。","领雄兵迎敌，厮杀相持，(云)出马来，出马来！(唱)则听的高叫一声似春雷。","(高丽将云)这壁厢是俺摩利支出马。","好将军也，顶盔擐甲，挂剑悬鞭，弯弓插箭。","张士贵见了俺摩利支，可是怕也不怕？探子，你喘息定，慢慢的再说一遍。","(正末唱)。"]},{"t":"摩利支飞刀对箭・幺篇","f":"曲","c":["垓心里耀武扬威，阵面上扯鼓夺旗。","摩利支冠簪着金獬豸，甲挂着锦唐猊，坐下马浑一似赤狻猊。"]},{"t":"摩利支飞刀对箭・秃厮儿","f":"曲","c":["两员将各施武艺，两员将比并高低。","他两个棋逢对手难摘离，两员将费心机，好跷蹊。"]},{"t":"摩利支飞刀对箭・尾声","f":"曲","c":["高丽家休占那中原地，年年进金珠宝贝。","十万里锦绣江山，愿陛下永坐定蟠龙元金椅！(下)(高丽将云)摩利支输了也，白袍小将赢了也。","俺收拾方物，与大唐进奉，走一遭去。","饶你深山共深处，到头都属帝王家。","(下)。"]},{"t":"摩利支飞刀对箭・甜水令","f":"曲","c":["我在这班部丛中，秉笏披袍，抽身忙褪，我这里独步出辕门。","(孛老儿云)一个大人来了也。","(正末唱)我则见他便老弱虺羸，腰屈头低，霜髯雪鬓，(孛老儿云)兀的唬杀老汉也。","(正末云)兀的不是我父亲母亲也！(唱)年迈个也堂上双亲。","(孛老儿云)媳妇儿，扶着你母亲靠后些。","(正末云)休道俺父母不老。","(唱)。"]},{"t":"摩利支飞刀对箭・折桂令","f":"曲","c":["和我那赛杨香憔悴了精神，(孛老儿云)大人，你是谁？(正末云)父亲、母亲，你认的你孩儿薛驴哥么？(孛老儿云)谁是薛驴哥？(正末)则您孩儿，便是薛驴哥。","(孛老儿云)孩儿，你做了官也？兀的不欢喜杀老汉也。","(正末唱)我这里便展脚舒腰，安乐者波堂上双亲？(卜儿云)大人请起。","兀的不唬杀老身也。","(正末唱)我如今状貌堂堂，威风赳赳，志气凌云。","(孛老儿云)孩儿也，你如今得了个甚么官也？(正末唱)我如今下马为朝中宰臣，上马为阃外将军。","(孛老儿云)孩儿，你多受了些辛苦也。","(正末唱)我受了些热血相喷，万苦干辛，恰便似翻滚滚的雪浪里逃生，您儿今日个便跳过龙门。"]},{"t":"摩利支飞刀对箭・乔牌儿","f":"曲","c":["酩子里添笑忻，十载受劳困。","老来也又得官一品，(云)父亲，您孩儿不道来？(孛老儿云)你道甚么来？(正末唱)你儿道是改家门有定准。","(孛老儿云)孩儿也，大人赏我黄金千两，香酒百瓶，玉柱杖一条，喜欢杀老汉也。","(正末唱)。"]},{"t":"摩利支飞刀对箭・挂玉钩","f":"曲","c":["索强如段段田苗，可便接远村；(孛老儿云)这个原来是玉柱杖。","(正末云)这玉柱杖，(唱)索强似您打麒麟的黄桑棍，(孛老儿云)又与俺香酒百瓶也。","(正末云)父亲，您休吃了，留者。","(孛老儿云)留者做甚么？(正末唱)咱可索答荷天公雨露恩。","(孛老儿云)孩儿也，休题旧话。","(正末唱)我将这勇烈施逞尽。","(孛老儿云)我老汉老了也，拂绰了土满身，梳掠起白髭鬓。","这的是一日为官，强似千载为民也。","(正末唱)拂绰了土满身，梳掠起白髭鬓。","这的是一日为官，索强如千载为民。"]},{"t":"张公艺九世同居・仙吕/点绛唇","f":"曲","c":["九世同居，故家乔木，传今古。","则俺这远近宗族，端的是上下皆和睦。"]},{"t":"张公艺九世同居・混江龙","f":"曲","c":["尊卑有序，俺一团和气霭门闾。","立身的有士农工贾，传家的有礼乐诗书。","想着那累代功名天下有，似俺家满门忠孝世间无。","为男的孝于父母，做女的善侍公姑。","人力众数百家眷，田宅广无限仓庾。","亲戚同高楼大厦，朋友共肥马轻车。","乐天年幽居田野。","播芳声喧满江湖。","但存忠孝以齐家，不求荣显学干录。","常能如此，更待何如。"]},{"t":"张公艺九世同居・油葫芦","f":"曲","c":["似俺般富贵荣华天付与，俺端的心自足。","(大末云)喜遇明君治世。","(正末昌)时遇着舜天尧日乐安居，堪叹的是西山日迫桑榆暮。","喜的是高堂月旦芝兰聚，自北齐千乘君，大隋仁圣主，省差徭免赋税加优恤，见如今旋表耀门闾。"]},{"t":"张公艺九世同居・天下乐","f":"曲","c":["两度天书出帝都，家也波声，传父祖，一家儿孝慈成化俗。","士民俱赞扬，乡闾皆敬伏，俺端的播清风一万古。"]},{"t":"张公艺九世同居・鹊踏枝","f":"曲","c":["左右行列昭穆，定亲疏，追思这祖考音容，洋洋乎在生规模。","再拜虔诚告祝，保护一家儿上下无虞。"]},{"t":"张公艺九世同居・寄生草","f":"曲","c":["你做须做文章伯，学则学君子儒，可不道书中自有千钟粟。","你为人要比连城玉，济时须作擎天柱。","(带云)孟子云：穷则独善其身，达则兼善天下。","(唱)你达时腰金佩紫掌丝纶，不达时沦黄数黑寻章句。"]},{"t":"张公艺九世同居・幺篇","f":"曲","c":["你学济世安邦策，按六韬三略书。","则要你识安危动变驱兵旅，察虚实攻守安营戍，分奇正左右依行伍，但能够雄赳赳虎豹帐中居，煞强如冷清清鹦鹉洲边住。"]},{"t":"张公艺九世同居・六幺序","f":"曲","c":["我这里频嘱付，孩儿每自喑伏。","休得恣荒淫酒色欢娱，为儒的早趁三余，笃志诗书休得闲遥遥惰却身躯。","少年莫道儒冠误，索将他经史熟读。","圣人言不贰过不迁怒，修其天爵，人爵从诸。","(云)孩儿也。","你两个学的文武全才，即今便上朝应举去，则要你着志者。","(二末云)您孩儿即今便行也。","(正末唱)。"]},{"t":"张公艺九世同居・幺篇","f":"曲","c":["想为官的要辨贤愚，休要弄权术。","爱恤民庶，教化风俗，一片心常思报主。","想民瘼不易除，为农的竭力耕锄，休教他田野荒芜。","到头来勤苦是亨衢。","饱衣暖食供朝暮。","不勤时仓禀空虚，礼义廉耻为先务。","毋忝尔祖，以保身躯。"]},{"t":"张公艺九世同居・赚煞尾","f":"曲","c":["便好道养育受亲恩。","仁宦食天禄，这的是父生汝君子食汝。","自古君亲两不殊，不忠孝天理何如！慎其独，似十目视十手指严乎。","(带云)则要你上合天心下协民望，(唱)天网恢恢本不疏。","你索温恭自虚，制竹谨度，行藏须鉴圣贤书。","(同下)。"]},{"t":"张公艺九世同居・南吕/一枝花","f":"曲","c":["镜添白发新，人对黄花瘦。","光阴驹过隙，世事水浮沤。","寒暑相逐，乌免搬昏昼。","昨日春今日秋，过中年万事俱休，空枉了堆金北斗。"]},{"t":"张公艺九世同居・隔尾","f":"曲","c":["逐朝春镜容颜瘦，一枕黄粮梦境熟。","往事回头尽参透，吾心已休，甘心退守，老却当年钓鳌手。"]},{"t":"张公艺九世同居・幺篇","f":"曲","c":["庄田与我亲标拨，钱粮与我别项收，恐有那一等受贫穷朋友干求。","倘有那连丧不举的人家，久定难成的配偶。","(大末云)丧不举呵，怎的？(正末唱)丧不举呵，我与他斋僧道营坟墓，(大末云)婚不了呵，如何？(正末唱)女不嫁呵，我与他办首饰置衾绸。","须教他嫁娶心无憾，免得他居丧礼不周。","(云)下次小的每门首看着，有甚么人来？(大末云)理会的。","(王伯清上云)小生王伯清是也。","因父丧不举，到此张公艺家，借些小钱物，埋殡父亲。","可早来到也。","兀那门公报复去，道有王原举之子来见老员外。","(行钱云)理会的。","(做报科，云)报的员外得知，有王原举之子来见员外。","(正末云)行钱，当初王原举，与老夫有一面之交，请他过来。","(行钱云)理会的。","有请。","(王伯清做见施礼科)(正末云)孩儿也。","你有甚么事，来到此处也。","(王伯清云)不瞒长者说，我父亲曾与长者有一面之交。","我父不辛，身亡三载，停柩在堂，无线殡葬。","止有老母在堂，并无亲故。","想长者有疏财仗义之心，全望长者可怜，借些钱物，以葬我父亲。","若蒙俯允，此恩不忘也。","(正末唱)。"]},{"t":"张公艺九世同居・红芍药","f":"曲","c":["他从头至尾说因由，和我也雨泪交流。","他道父亡三载久停留，并无-个亲识追求。","则你那文齐来福未酬，则要你显男儿得志之秋。","(正末做悲科)老夫一一记在心头，我必有个主意相周。","(正末取银子鞍马衣服科，云)这拾两银子，与你埋殡父亲。","你埋殡了父亲，你上朝求官应举去。","这拾两银子，与你做盘缠，这鞍马权与你代步。","孩儿，你则着志者。","(王伯清做谢科，云)多谢了长者也。","(正末云)路远不及吊问，休怪也。","(王伯清云)不敢不敢。","(行钱云)我倒好笑，拿着细丝银子儿，鞍马衣服，白与了别人去了。","我整日家与他做买卖，倒不与我，真乃是夹脑风也。","(正末唱)。"]},{"t":"张公艺九世同居・菩萨梁州","f":"曲","c":["你与我疾便登舟，休辞生受。","显文章魁首，免你那倚门尊母忧愁。","蟾宫独步占鳌头，门庭改换传家后。","此言语不虚谬，不枉了灯窗学业修，万古名留。"]},{"t":"张公艺九世同居・骂玉郎","f":"曲","c":["声名不落他人后，心已遂更何求。","人情世事皆虚谬，想如今故友稀，叹鬓边白发新，喜榻上青毡旧。"]},{"t":"张公艺九世同居・感皇恩","f":"曲","c":["呀，爱的是山水清幽，喜的是菊松芳秀。","伴风月两闲人，渺乾坤双醉眼，乐诗酒一儒流。","闲散心青山故友，暂忘机沧海盟鸥，梦义皇，谢尘世，卧糟丘。"]},{"t":"张公艺九世同居・采茶歌","f":"曲","c":["做一个醉乡侯，老风流，得优游处且优游。","对酒当歌开笑口，一杯消尽古今愁。","(云)分付你的言语，你牢记着。","(大末云)您孩儿理会的。","(正末唱)。"]},{"t":"张公艺九世同居・煞尾","f":"曲","c":["把我那西园池馆从新构，北院山亭即便修。","留得闲身漫迤逗，栽花种柳，携琴载洒，我和那松竹梅花做心友。","(众下)。"]},{"t":"张公艺九世同居・双调清江引","f":"曲","c":["别人做了状元喜满腮，咱两个如之奈？他两个都为三品官，齐向金阶拜。","咱两个躲在那背巷里悄悄的家去来。","(同下)。"]},{"t":"张公艺九世同居・正宫/端正好","f":"曲","c":["人事尚炎凉，世态轻忠信，似这般不义富于我如浮云。","小人若得十年运，早忘了贫时分。"]},{"t":"张公艺九世同居・滚绣球","f":"曲","c":["向人前敢自尊，胡议论，出言语无半星儿谦逊，气昂昂傍若无人。","倚仗着千两金，万两银，见一等穷相识并不亻秋问，若见他富豪人便和气若雷陈。","他亲的是朱楼翠阁风流子，他敬的是白马红缨衫色新。","何足云云。"]},{"t":"张公艺九世同居・倘秀才","f":"曲","c":["传圣旨火臣到门，忙惊讶心中自忖，有甚事传言达至尊，抬香案，引儿孙，向前接引。","(使命云)圣命至此，张公艺你焚香接待也。","(正末唱)。"]},{"t":"张公艺九世同居・脱布衫","f":"曲","c":["炷余炉宅篆氤氲，遥瞻拜玉阙丹宸。","顿首诚惶谢恩，有何事感蒙君问？。"]},{"t":"张公艺九世同居・小梁州","f":"曲","c":["止不过草芥微躯一庶民，隐迹山村。","(使命云)圣人的命，问你九世不分居，有何齐家之道？(正末唱)圣人问齐家之道何因，为甚么家和顺，九世不曾分。"]},{"t":"张公艺九世同居・幺","f":"曲","c":["老夫自小蒙家训，止不过慈爱宽仁。","非老夫能，家无他论，则我这齐家之本，诚意与修身。","(使命云)你有何言语，我与你上达也。","(正末云)将纸墨笔砚过来者。","(行钱云)纸笔在此。","(正末唱)。"]},{"t":"张公艺九世同居・醉太平","f":"曲","c":["纸光如素粉，墨浓似春云，抵多少蘸霜毫笔阵扫千军。","(做沉吟科)口无言门哂，待对这万言长策无高论，待答那表章无学问。","(做写忍字科)写到百十个忍字对天臣，望传达至尊。"]},{"t":"张公艺九世同居・叨叨令","f":"曲","c":["假如道饭食不周衣服不备为下的道心偏逊，恭敬不至礼节不到为上的道他生忿。","上责下下怨上即渐的生嗔恨，上不慈下不孝必定相争论。","(带云)我家不分呵为何？(唱)彼各都忍了也波哥，彼各都忍了也波哥，因此上父为子隐上下家和顺。","(使命云)原来是如此，我怎知道也。","(正末云)天使，不则齐家之法，有此忍字，上至宰臣，下及庶民，皆有此忍。","能忍者全身保命，不忍者丧家取祸，天使，听我说一遍。","(使命云)你说，小官试听者。","(正末唱)。"]},{"t":"张公艺九世同居・随煞尾","f":"曲","c":["这忍字向不平心上安刀刃，呵，心地清能忍清凉绝斗纷。","守口如瓶要安分，防意如城主忠信。","能忍呵怨恨成欢仇变恩，不能忍呵恩爱为仇喜作嗔。","能忍呵谁是谁非尽休问，他弱他强莫争论。","能忍呵宽裕温柔保六亲，你若要远害全身止不过在于忍。","(下)。"]},{"t":"张公艺九世同居・双调/新水令","f":"曲","c":["揭清天一派动箫韶，聚春风玉骢争道。","锦斓斑仙仗拥，花烂熳彩楼高。","县宰官僚，头踏尽来到。"]},{"t":"张公艺九世同居・殿前欢","f":"曲","c":["天使索劬劳，事君王束带立于朝。","承宣走马长安道，胸卷江涛。","(王伯清云)长者请坐受礼也。","(正末唱)偶迎逢一面交，惹议论诸公笑，则道是没见识村夫傲。","(王伯清云)长者有德，小官年幼也。","(正末唱)俺年高呵则是个山林潦倒。","您年幼呵则当代的英豪。"]},{"t":"张公艺九世同居・川拨棹","f":"曲","c":["仿佛记旧丰标。","偶相逢恐认错。","老人多病年高，老景萧条，僻处荒郊，多因是间别久时间忘了。","隔关河途路杳。"]},{"t":"张公艺九世同居・七兄弟","f":"曲","c":["天臣道了，老夫记着。","那一朝，为父丧足下亲来到。","(云)多蒙厚赐也。","(唱)谢君不责礼轻薄，(王伯清做递银子与正末科，云)长者当时所赐银两，今在此奉还也。","多蒙长者厚赠，葬我父亲之恩也。","(正末唱)暂用急怎敢思君报。"]},{"t":"张公艺九世同居・梅花酒","f":"曲","c":["今日个事已了，乃朋友之交。","我投以木桃，君报以琼瑶。","感足下情分好，并不受半分毫。","(行钱云)这些银子你不要，我拿去买酒吃哩。","(正末唱)谢天臣敬重老，对县宰众官僚，他举金杯劝香醪，谈今古恣酬酢，喜欢会在今朝。"]},{"t":"张公艺九世同居・鸳鸯煞","f":"曲","c":["感君王亲赐皇宣诏，谢大臣远践红尘道。","送别临歧，走马还朝。","唱道顿首诚惶，瞻天拜表。","感谢深蒙雨露恩难报。","华胄遥遥，千古清风播皇阁。"]},{"t":"包龙图智赚合同文字・仙吕/点绛唇","f":"曲","c":["拙妇熬煎，主家方便，相留恋。","直着俺住到来年，谁想天不从人愿。"]},{"t":"包龙图智赚合同文字・油葫芦","f":"曲","c":["量小生有甚人情有甚钱，苦痛也波天。","则为那家私生受了二十年，要领旧席铺停柩无一片，要领好衣服妆裹无一件。","(张秉彝云)君子，你不须烦恼。","我这里都已备下了也。","(正末唱)谢员外厮济惠，谢员外肯见怜。","(带云)小生若不得员外呵。","(唱)则俺这人离财散央亲眷，兀良谁赍发与我一根椽。","(做悲科)(唱)。"]},{"t":"包龙图智赚合同文字・天下乐","f":"曲","c":["妻也，知他是你命难逃我命蹇，我想从也波前，也是宿世缘，将重孝不披轻孝来穿。","想着你恩共情，想着你贞共贤，我甘心儿与你驾灵车，哭少年。"]},{"t":"包龙图智赚合同文字・那吒令","f":"曲","c":["念不出，消灾的善言；烈不得，买路的纸钱；(张秉彝云)我代你送出去。","(正末云)怎敢劳动员外。","(唱)我可也放不下，殃人的业冤。","一片心迷留没乱焦，两条腿滴羞笃速战，恰便似热地上蚰蜒。","(做走科)(唱)。"]},{"t":"包龙图智赚合同文字・鹊踏枝","f":"曲","c":["我甫抬身到灵柩边，待亲送出郊原，不觉的肉颤身摇，眼晕头旋。","挪一步早前合后偃，(正末做倒科)(唱)哎哟！叫一声覆地翻天。"]},{"t":"包龙图智赚合同文字・柳叶儿","f":"曲","c":["则被那官司逼遣，他道是没收成千里无烟，着俺分房减口为供膳。","因此上携宅眷，撇家缘，图一个苟活偷全。"]},{"t":"包龙图智赚合同文字・青哥儿","f":"曲","c":["虽则是一张儿合同、合同文券，上写着一家儿庄田宅院，这便我久后归宗的证明显。","趁如今未丧黄泉，叮咛你大德高贤。","等孩儿长大时年，交付他收执依然。","遮莫杀颠沛流连，休迷失水木根源。","这便是你张员外种下的福无边，天须见。"]},{"t":"包龙图智赚合同文字・寄生草","f":"曲","c":["他目下交三岁，你若抬举他更数年。","常则是公心教训诚心劝，教的他为人谨慎于人善，不许他初年随顺中年变。","俺便死也难忘你这天高地厚情，员外你则可怜见，小冤家少母无爹面。"]},{"t":"包龙图智赚合同文字・赚煞尾","f":"曲","c":["不争我病势正昏沉，更那堪苦事难支遣，忙赶上头里的丧车不远，眼见得客死他乡有谁祭奠？(带云)儿也，你若得长大成人呵。","(唱)你是必休别了父母遗言：将骨殖到梁园，就着俺那祖父的坟前，古树林峰好墓田。","员外，则你便是我三代祖先，我又无甚六神亲眷。","可怜见俺两房头这几口儿，都不得个好团圆。","(下)。"]},{"t":"包龙图智赚合同文字・正宫/端正好","f":"曲","c":["我将着这一所草堂开，聚几个蒙童训，常则是对青灯黄卷埋身。","苦了我也十年窗下无人问，何日得功名进？。"]},{"t":"包龙图智赚合同文字・滚绣球","f":"曲","c":["我可也为甚的甘受贫，不厌勤，抵多少策顽磨钝，也只为不如人学做儒人。","指望待跃锦鳞，过禹门，才是俺男儿发愤，终有日际会风云。","不枉了严亲教训能酬志，须信道古圣文章可立身，改换家门。"]},{"t":"包龙图智赚合同文字・倘秀才","f":"曲","c":["俺父亲口快心直怎隐？","您孩儿鼻痛心酸怎忍？","想着那冻饿死的爷娘，兀的不痛杀人！","别了兄嫂，离了家门，养下这个毒害的子孙。"]},{"t":"包龙图智赚合同文字・呆骨朵","f":"曲","c":["想着俺人亡家破，留下这个儿生忿，我直啼哭的地惨天昏。","不争将先父母思量，又怕俺这老爷娘议论。","则道把十月怀耽想，可将这数载情肠尽。","(张秉彝做叹科，云)嗨！他亲的则是亲。","(正末唱)他道亲的则是亲，我怎肯知恩不报恩？。"]},{"t":"包龙图智赚合同文字・倘秀才","f":"曲","c":["待奉着俺先人的教训，怎敢道别了家尊的义分，您孩儿两下里爷娘一样的亲。","怎敢道分真假，辩清浑，天地也就着俺亡家丧身。"]},{"t":"包龙图智赚合同文字・滚绣球","f":"曲","c":["想当日盘缠无一文，遗留托二亲，痛杀我也命绝禄尽，谢父亲，将您孩儿抬举成人。","离了这潞州下马村，早来到东京义定门，将俺这骨殖埋殡，认了伯父伯娘呵，您孩儿便索抽身。","先安定了俺这十五年无主亡魂魄，回来报答你一双的高年养育恩，怎避的艰辛。"]},{"t":"包龙图智赚合同文字・倘秀才","f":"曲","c":["远远望高山隐隐，近近听黄河滚滚，我则见段段田灯接远村。","到祖宅，造亲坟，尽了我这点儿孝顺。"]},{"t":"包龙图智赚合同文字・滚绣球","f":"曲","c":["这般担呵我生怕背了母亲，这般提呵又则怕背了父亲，好着俺孝心难尽，做不得郭巨、田真。","兀的不厌掉魂，唬煞人，原来是至诚的天顺，可又早动鬼惊神。","曾闻的古来孝子担继母，感得闷林两处分，俺今日也脚底生云。"]},{"t":"包龙图智赚合同文字・煞尾","f":"曲","c":["披星带月心肠紧，过水登山脚步勤。","意急不将昼夜分，心愁岂觉途路稳。","痛泪零零雨洒尘，怨气腾腾风送云。","客舍青青柳色新，千里关山劳梦魄。","归到梁园认老亲，恁时节才把我这十五载流离证了本。","(下)。"]},{"t":"包龙图智赚合同文字・中吕/粉蝶儿","f":"曲","c":["远赴皇都，急煎煎早行晚住，早难道神鬼皆无。","我将饭充饥，茶解渴，纸钱来买路。","历尽了那一千里程途，几曾道半霎儿停步。"]},{"t":"包龙图智赚合同文字・醉春风","f":"曲","c":["俺心儿里思想杀老爷娘，则待要墓儿中埋葬俺这先父母。","一会家烦恼上眉头，安住到大来是苦，苦！我则道孤影孤身，流落在他州他县，惭愧也，不想还认了这伯娘伯父。"]},{"t":"包龙图智赚合同文字・红绣鞋","f":"曲","c":["他、他、他，可也为甚么全没那半点儿牵肠割肚？全没那半声儿短叹长吁？莫不您叔嫂妯娌不和睦？(云)伯娘，俺伯伯那里去了？(搽旦云)甚么伯伯？我不知道。","(正末唱)伯伯可又无踪影。","伯娘那里紧支吾，可教我那搭儿葬俺父母？。"]},{"t":"包龙图智赚合同文字・普天乐","f":"曲","c":["我意慌速，心犹豫，若无显证，怎辩亲疏？(递合同科)(搽旦云)争奈我不识字？如何？(正末唱)伯娘可也不会读，将去着伯父亲身觑。","(云)好一个贤达的伯娘也，我错埋怨了他。","(唱)他元来是九烈三贞贤达妇，兀的个老人家尚然道出嫁从夫。","(搽旦入门科)(正末云)呀！伯娘入去了，可怎么这一晌还不见山来？我早猜着了也。","(唱)一来是收拾祭物，二来是准备孝服，第三来可是报与亲属。"]},{"t":"包龙图智赚合同文字・迎仙客","f":"曲","c":["因歉年趁熟上，别家乡临外府。","怎知道命儿里百般无是处。","先亡了俺嫡亲的爷娘，守着这别人家父母。","整受了十五载孤独，(刘天祥云)你叫做甚么名字？(正末唱)则俺呵，便是您作儿刘安住。","(刘天祥云)你那里见刘安住来？(正末去)则我便是刘安住。","(刘天祥做悲科，云)婆婆，你欢喜咱，俺刘安住孩儿回家来了也。","(搽旦云)甚么刘安住？这里哨子每极多，见咱有些家私，假做刘安住来认俺。","他爷娘去时，有合同文书，若有便是真的，无便是假的。","(刘天祥云)婆婆也道的是。","我出去问他。","刘安住，你去时节有合同文书，你将的来我看。","(正末云)有文书来，适才交付与伯娘了也。","(刘天祥云)婆婆，休斗我耍，我问刘安住来，他道你拿着文书了也。","(搽旦云)我不曾拿。","(刘天祥云)刘安住，婆婆道他不曾拿。","孩儿也，你等我来波，怎么就与了他？(正末唱)。"]},{"t":"包龙图智赚合同文字・石榴花","f":"曲","c":["俺一生精细一时粗，直恁般不晓事忒糊涂。","则他那口如蜜钵说从初，并无间阻，索看文书。","我则道是亲骨血这搭儿里重完聚，一家儿世不分居。","我将这合同一纸慌忙付，倒着俺做了扁担脱两头虚。"]},{"t":"包龙图智赚合同文字・斗鹌鹑","f":"曲","c":["我将那百诈的虔婆，错认做三移孟母。","我又不索您钱财，又不分您地土。","只要把无主的亡灵归墓所，你可也须念兄弟每如手足。","便做道这张纸为有为无，难道我姓刘的不亲不故。"]},{"t":"包龙图智赚合同文字・上小楼","f":"曲","c":["想着俺劬劳父母，遇了这饥荒时务。","辞着兄嫂，引着妻男，趁着丰熟。","怎知道寿短促，命苦毒，再没个亲人看顾，闪的这两把骨殖儿不着坟墓。"]},{"t":"包龙图智赚合同文字・幺篇","f":"曲","c":["伯娘你也忒狠酷，怎对付！则待要瞒了侄儿，背了伯伯，下了埋伏。","单则是他亲女，和女夫，把家缘收取，可不俺两房头灭门绝户？(刘天祥云)安住孩儿，你那合同文书委实在那里也？(正末云)恰才是伯娘亲手儿拿进去了。","(搽旦云)这个说谎的小弟子孩儿，我几曾见那文书来？(正末云)伯娘，休斗您孩儿妥。","你恰才明明的拿进去，怎说不曾见？(搽旦云)我若见你那文书，着我邻舍家害疔疮。","(刘天祥云)婆婆。","你若是拿了，将来我看。","(搽旦云)这老儿也糊突。","这纸文书，我要他糊窗儿？有甚么用处？这厮故意的来捏舌，待诈骗咱的家私哩。","(正未)伯伯，您孩儿不要家财，则要傍着祖坟上埋葬了俺父母这两把儿骨殖。","我便去也。","(搽旦打破正末头科，云)老的，你只管与他说甚么？咱家去来。","(关门科)(下)(正末云)认我不队我便罢，怎么将我的头打破了？天那！谁人与我做主咱！(哭科)(李社长上，云)老汉李社长是也。","打从刘天祥门省经过，看见一个后生，在那里啼哭，不知为何？我问他波。","这小的，你是甚么人：(正末云)我是十五年前趁熟去的刘天瑞儿子刘安住，(社长认科，云)是谁打破你头天？(正末云)这不干我伯父事，是伯娘不肯认我，拿了我合同文书，抵死的赖了，又打破我的头来。","(社长云)刘安住，你且省烦恼。","你是我的女婿，我与你做主。","(正末唱)。"]},{"t":"包龙图智赚合同文字・满庭芳","f":"曲","c":["谢得你太山做主，我是他嫡亲骨血，又不比房分的家奴。","将骨殖儿亲担的还乡，故走了些偌远程途。","你道俺那亲伯父因何致怒，赤紧的打尧婆先赚了我文书。","(社长云)难道不认就罢了？(正末唱)我可也难回去，但能勾葬埋了我父母，将安住认不认待何如？。"]},{"t":"包龙图智赚合同文字・十二月","f":"曲","c":["可怜我时乖命苦，只在张秉彝家暂寓权居。","生受了些风餐水宿，巴的到祖贯乡闾。","我只道认着了伯娘伯父，便欢然复旧如初。"]},{"t":"包龙图智赚合同文字・尧民歌","f":"曲","c":["怎知俺伯娘啊，他是个不冠不带泼无徒，才说起刘家安住便早嘴卢都。","他把俺合同文字赚来无，尽场儿揣与俺个闷葫芦。","似这冤也波屈，教俺那里诉，只落得自吞声，暗啼哭。"]},{"t":"包龙图智赚合同文字・收尾","f":"曲","c":["他清耿耿水一似，明朗朗镜不如。","他将俺一行人都带到南衙去，我拚把个头磕碎金阶，叫道委实的屈。","(同下)。"]},{"t":"包龙图智赚合同文字・双调/新水令","f":"曲","c":["只俺这小人不解大人机，把带伤人倒监了十日。","干连人不问及，被论人尽勾提。","暗暗猜疑，怎参透就中意。"]},{"t":"包龙图智赚合同文字・乔牌儿","f":"曲","c":["他是个老人家多背悔，大人须有才智。","外人行白打了犹当罪，可不俺关亲人绝分义。","(包待制云)你只打着他，问一个谁是谁非，便好定罪也。","(正末唱)。"]},{"t":"包龙图智赚合同文字・挂玉钩","f":"曲","c":["相公道谁是谁非便得知，(包待制做怒科，云)兀那刘安住，你可怎生不着实打者，(正未唱)俺父亲尚兀是他亲兄弟。","却教俺乱棒胡敲忍下的，也要想个人心大理终难昧。","我须是他亲子侄，又不争甚家和计。","我本为行孝而来，可怎么生忿而归？(包待制诗云)老夫低首自评论，就中曲直岂难分。","为甚侄儿不将伯父打。","可知亲者原来则是亲。","兀那小厮，我着你打这老儿，你左来右去。","只是不肯打。","张千，取枷来将那小厮枷了者。","(做枷正末科)(正末唱)。"]},{"t":"包龙图智赚合同文字・雁儿落","f":"曲","c":["他荆条棍并不曾汤着皮，我荷叶枷倒替他耽将罪。","稳放着打尧婆在一壁，急的那个社长难支对。"]},{"t":"包龙图智赚合同文字・得胜令","f":"曲","c":["呀！这是我独自落便宜，好着我半晌似呆痴。","俺只道正直萧丞相，元来是风魔的党太尉。","堪悲，屈沉杀刘天瑞，谁知可怎了葫芦提包待制？(包待制云)张千，将刘安住下在死囚牢里去。","你近前来。","(打耳喑科)(张千云)理会的。","(张千做枷正末下)(包待制云)这小厮明明要混赖你这家私，是个假的，(搽旦云，大人见的是。","他那里是我亲侄儿刘安住？(张千云)禀爷，那刘安住下在牢里发起病来，有八九分重哩。","(包待制云)天有不测风云，人有旦夕祸福：那小厮恰才无病，怎生下在牢里便有病？张千你再去看来。","(张千报，云)病重九分了也。","(包待制云)，你再看云。","(张千又报，云)刘安住太阳穴被他物所伤，观有青紫痕可验，是个破伤风的病症，死了也。","(搽旦云)死了，谢天地。","(包待制云)怎么了这桩事？如今倒做了人命，事越重了也。","兀那婆子，你与刘安住关亲么？(搽旦云)俺不亲。","(包待制云)你若是亲呵，你是大他是小，休道死了一个刘安住，便死了十个，则是误杀子孙不偿命，则罚些铜纳赎；若是不亲呵。","道不的杀人偿命，欠债还钱。","他是各白世人，你不认他罢了，却拿着甚些仗打破他头，做了破伤风身死。","律上说：殴打平人，因而致死者抵命。","张千将枷来，枷了这婆子，替刘安住偿命去。","(搽旦慌科，云)大人，假若有些关亲，可饶的么？(包待制云)是亲便不偿命。","(搽旦云)这等，他须是俺亲侄儿哩。","(包待制云)兀那婆子，刘安住活时你说不是，刘安住死了，可就说是。","这官府倒由的你那？既说是亲侄儿，有甚么显证？(搽旦云)大人，现有合同文书在此。","(包待制词云)这小厮本说的丁一确二，这婆子生扭做差三错四。","我用的个小小机关，早嫌出合同文字。","兀那婆子，合同文书有一样两张，只这一张，怎做的合同文字？(搽旦云)大人，这里还有一张。","(包待制云)既然合同文字有了也，你买个棺材。","葬埋刘安住去罢。","(搽旦叩头科，云)索是谢了大人。","(包待制云)张千，将刘安住尸首，抬在当面，教他看去。","(张千领正末上)(搽日见科，云)呀！他原来不曾死。","他是假的，不是刘安住。","(包待制云)刘安住，被我赚出这合同文书来了也。","(正末云)若非青天老爷，兀的不屈杀小人也！(包待制云)刘安住，你欢喜么？(正末云)可知欢喜哩。","(包待制云)我更着你大欢喜哩。","张千，司房中唤出那张秉彝来者。","(张秉彝上，见正末悲科)(正末唱)。"]},{"t":"包龙图智赚合同文字・甜水令","f":"曲","c":["我只为认祖归宗，迟眠早起，登山涉水，甫能勾到庭帏。","又谁知伯母无情，十分猜忌，百般驱逼，直恁的命运低微。"]},{"t":"包龙图智赚合同文字・折桂令","f":"曲","c":["定道是死别生离，与俺那再养爹娘，永没个相见之期。","幸遇清官，高抬明镜，费尽心机。","赚出了合同的一张文契，才许我埋葬的这两把儿骨殖。","今日个父子相依，恩义无亏，早则不迷失了百世宗支，俺可也敢忘味了你这十载提携。"]},{"t":"包龙图智赚合同文字・水仙子","f":"曲","c":["把白褴衫换了绿罗衣，抵多少一举成名天下知。","为甚么皇恩不弃孤寒辈，似高天雨露垂，生和死共戴荣辉。","虽然是张秉彝十分仁德，李社长一生信义，也何如俺伯父家有贤妻。"]},{"t":"风雨像生货郎旦・仙吕/点绛唇","f":"曲","c":["你把解库存活，草堂工课，都耽阁。","终日波波，白日休空过。"]},{"t":"风雨像生货郎旦・混江龙","f":"曲","c":["到晚来早些来个，直至那玉壶传点二更过。","(李彦和云)大嫂，你可怜见，我实不相瞒，这妇人他一心待要嫁我哩。","(正旦唱)你教我可怜见，你待敢是无奈之何。","你比着东晋谢安才艺浅，比着江州司马泪痕多，也只为婚姻事成抛躲。","劝不醒痴迷楚子，直要娶薄幸巫娥。"]},{"t":"风雨像生货郎旦・天下乐","f":"曲","c":["你正是引的狼来屋里窝，娶到家，也不和，我怎肯和他轮车儿伴宿争竞多。","你不来我行呵我房儿中作念着，你来我行呵他空窗外咒骂我，(带云)咱两个合口唱叫，(唱)你中间里图甚么？(李彦和云)大嫂，他须不是这等人，我也不是这等人。","(正旦唱)。"]},{"t":"风雨像生货郎旦・那吒令","f":"曲","c":["休信那黑心肠的玉娥，他每便乔趋抢取撮，休犯着黄蘖肚小么。","数量着哝过，紧忙里做作，似蝎子的老婆。","你便有洛阳田，平阳果，钞广银多。"]},{"t":"风雨像生货郎旦・鹊踏枝","f":"曲","c":["有时节典了庄科，准了绫罗；铜斗儿家私，恰做了落叶辞柯。","那其间便是你郑孔目风流结果，只落得酷寒亭刚留下一个萧娥。"]},{"t":"风雨像生货郎旦・寄生草","f":"曲","c":["你爱他眼弄秋波色，眉分青黛蛾。","怎知道误功名是那额点芙蓉朵，陷家缘唇注樱桃颗，啜人魂舌吐丁香唾。","只怕你飞花儿支散养家钱，旋风儿推转团圆磨。"]},{"t":"风雨像生货郎旦・柳叶儿","f":"曲","c":["你道他为甚来眉峰暗锁？则要我庆新亲茶饭张罗。","(云)李彦和，他那伙亲眷，我都认的。","(李彦和云)可是那几个？(正旦唱)都是些胡姑姑假姨姨厅堂上坐。","待着我供玉馔，饮金波，可不道谁扶侍你姐姐哥哥？。"]},{"t":"风雨像生货郎旦・赚煞","f":"曲","c":["气勃勃堵住我喉咙，骨噜噜潮上痰涎沫。","气的我死没腾软瘫做一垛，拘不定精神衣怎脱，四肢沉寸步难那。","若非是小孤撮，叫我一声娘呵，兀的不怨恨冲天气杀我。","你没事把我救活，可也合自知其过，你守着业尸骸学庄子鼓盆歌。","(死科，下)(李彦和悲科，云)我那大嫂也！(外旦云)李彦和，你张着口号甚的？有便置，没便弃。","(李彦和云)这是甚么说话！大嫂亡逝已过，便须高原选地，破木造棺，埋殡他入土。","大嫂，只被你痛杀我也！(下)(外旦云)这也是我脚迹儿好处，一入门先妨杀了他大老婆，何等自在，何等快活。","那李彦和虽然娶了我，不知我心下只不喜他。","想那魏邦彦，这些时也来家了。","我如今暗地里央着人去，与他说知，这早晚敢待来也。","(净上，云)自家魏邦彦的便是。","前月打差便去，叵耐张玉娥无礼，投到我来家，早嫁了别人。","如今又使人来寻我，不知有甚么事？我见他去，此间就是。","家里有人么？(外旦出见净科，云)你来家里来。","(净云)敢不中么？(外旦云)不妨事。","(净云)你嫁了人唤我怎的？(外旦云)我和你有说的话。","(净云)有甚么说话？(外旦取砌末付净科，云)我虽是嫁了他，心中只是想着你。","我如今收拾些金银财宝，悄地交付了你，可便先到洛河边，寻下一只小船。","等着我在家点起一把火，烧了他房子，俺同他躲到洛河边，你便假做梢公，载俺上船。","到的河中间，你将李彦和推在河里，把三姑和那小厮，也都勒死了，咱两个长远做夫妻，可不好那？(净云)你那是我老婆，就是我的娘哩。","我先去在洛河边等你，明日早些儿来。","(下)(外旦云)魏邦彦去了也。","我如今不免点火去。","在这房后边，放起火来。","(诗云)那怕他物盛财丰，顷刻间早已成空。","这一把无情毒火，岂非是没毛大虫？(下)。"]},{"t":"风雨像生货郎旦・步步娇","f":"曲","c":["送的我背井离乡遭灾勾，这贱才敢道辞生受。","断不得哄汉子的口，都是些即世求食鬼狐犹。","(外旦云)我几曾在黑地行走，教我受这般的苦也。","(副旦云)你道你不曾黑地里行呵，(唱)咱如今顾不得你脸儿羞，(云)你也曾悬着名姓，靠着房门，你也曾卖嘴料舌，推天抢地，你也曾挟着毡被，挑着灯球。","(唱)可也曾半夜里当祗候。"]},{"t":"风雨像生货郎旦・雁儿落","f":"曲","c":["只管里絮叨叨没了收，气扑扑寻敌斗。","有多少家乔断案，只是骂贼禽兽。"]},{"t":"风雨像生货郎旦・沽美酒","f":"曲","c":["逞末浪不即留，只管里卖风流，看他这天淡云开雨乍收。","可便去寻一个宿头，觅一碗浆水饭润咱喉。"]},{"t":"风雨像生货郎旦・太平令","f":"曲","c":["住了雨也晒甚娘褐袖，只愿的下雹子打你娘驴头。","(外旦骂科，云)这泼妇，我打不的你那！(打科)(副旦唱)只见他百忙里眉梢一皱，公然的指尖儿把颊腮剜透。","似这般左瞅，右瞅，只不如罢手，俺也须是那爷娘皮肉。"]},{"t":"风雨像生货郎旦・川拨棹","f":"曲","c":["慌走到岸边头，仓卒间怎措手。","风雨飕飕，地上浇油。","扭颈回眸，那里寻个梢公搭救？我将他衣领揪，他忙将我腰胯木刍。"]},{"t":"风雨像生货郎旦・殿前欢","f":"曲","c":["这一片水悠悠，急忙里觅不出钓鱼舟。","虚飘飘恩爱难成就，怕不的锦鸳鸯立化做轻鸥。","他、他、他，趁西风卒未休，把你来推落在水中浮，(外旦云)他自吃醉了，这等脚高步低，立也立不住，干我甚么事，说我推他？要你来嚼舌！(副旦唱)抵多少酒淹湿春衫袖。","(李彦和云)这里水浅，自过去了罢。","(副旦唱)现淹的眼黄眼黑，你尚兀自东见东流。","(净扮梢公上，云)官人，娘子，我这里是摆渡的船，你每快上来。","(外旦和净打手势科)(副旦云)哥哥，你休上船去。","这婆娘眼脑不好，敢是他约着的汉子哩！(做扯李科)(李彦和云)你放手，不妨事。","我上的这船来，自有分晓。","(净推李下河)(副旦扯住净)(净勒杀副旦科)(丑扮梢公上救，喊云)拿住这杀人贼！(副旦揪住丑云)有杀人贼！(净同外旦走斗)(丑云)苦也娘子，不干我事。","勒杀你的是那个梢公，他走了也。","我是来救你的，你休认差了也。","(副旦唱)。"]},{"t":"风雨像生货郎旦・鸳鸯尾煞","f":"曲","c":["乞与你不痛亲父母行施恩厚，我扶侍义养儿使长多生受。","你途路上驱驰，我村疃里淹留。","畅道你父亲此地身亡，你是必牢记着这日头。","大厮八做个周年，分甚么前和后。","那时节遥望着西楼，与你爷烧一陌儿纸，看一卷儿经，奠一杯儿酒。","(同孛老下)(孤云)那老儿领着妇人去了。","老夫也引着这孩儿抱上马，还我私宅中去来。","(下)(丑哭科，云)好苦恼子也！只一个妇人，领着个小的，几乎被人勒杀。","恰好撞见我，我救了他性命。","他又把这个小的卖与那个官人，那个官人又将他那个小的领着去了。","这等孤孤凄凄，怎教我不要伤感？(做跌倒起科，云)呸！可干我甚么事？(诗云)随他自卖男，随他自认女。","我只去做梢公，不管风和雨。","(下)。"]},{"t":"风雨像生货郎旦・正宫/端正好","f":"曲","c":["口角头饿成疮，脚心里踏成趼，行一步似火燎油煎。","记的那洛河岸一似亡家犬，拿住俺将麻绳缠。"]},{"t":"风雨像生货郎旦・滚绣球","f":"曲","c":["见一个旋风儿在这榆柳园，古道边，足律律往来打转，刮的些纸钱灰飞到跟前。","是神祗，是圣贤，你也好随时呈变，居庙堂索受香烟。","可知道今世里令史每都挝钞，和这古庙里泥神也爱钱，怎能勾达道升仙？。"]},{"t":"风雨像生货郎旦・倘秀才","f":"曲","c":["沿路上身轻体健，这搭儿筋乏力软，到庙儿外不曾撒纸钱。","爷爷你厮余闰，厮哀怜，我这老妇人咒愿。"]},{"t":"风雨像生货郎旦・上小楼","f":"曲","c":["唬的我身心恍然，负急处难生机变。","我只索念会咒语，数会家亲，诵会真言。","这几年，便着把哥哥追荐，作念的个死魂灵眼前活现。","(李彦和云)我不是鬼，我是人。","(副旦唱)。"]},{"t":"风雨像生货郎旦・幺篇","f":"曲","c":["对着你咒愿，休将我顾恋。","有一日拿住奸夫，摄到三姑，替你通传。","非足我不意专，不意坚，搜寻不见，是早起店儿里吃羹汤不曾浇奠。","(李彦和云)三姑，我不曾死，我是人。","(副旦云)你是人呵，我叫你，你应的一声高似一声；是鬼呵，一声低似一声。","(叫科)李彦和哥哥！(李彦和做应科)(三唤)(做低应科)(副旦云)有鬼也！(李彦和云)我斗你耍来。","(做打悲、认科)(李彦和云)三姑，我的孩儿春郎，那里去了也。","(副旦云)没的饭食养活他，是我卖了也。","(李彦和做悲科，云)原来是你卖了，知他如今死的活的？可不痛杀我也！你如今做甚么活计？穿的衣服，这等新鲜，全然不像个没饭吃的，你可对我说。","(副旦云)我唱货郎儿为生。","(李彦和做怒科云)兀的不气杀我也！我是甚么人家？我是有名的财主。","谁不知道李彦和名儿？你如今唱货郎儿，可不辱没杀我也！(做跌倒)(副旦扶起科，云)休烦恼，我便辱没杀你。","哥哥，你如今做甚么买卖？(李彦和云)我与人家看牛哩，不比你这唱货郎的生涯这等下贱。","(副旦唱)。"]},{"t":"风雨像生货郎旦・十二月","f":"曲","c":["你道我生涯下贱，活计萧然。","这须是衣食所逼，名利相牵。","你道我唱货郎儿辱没杀你祖先，怎比的你做财主官员。"]},{"t":"风雨像生货郎旦・尧民歌","f":"曲","c":["与人家耕种洛阳田，早难道笙歌引入画堂前。","趁一村桑梓一村田，早难道玉楼人醉杏花天。","牵，也波牵，牵牛执着鞭，杖敲落桃花片。","(云)哥哥，你肯跟我回河南府去，凭着我说唱货郎。","儿，我也养的你到老，何如？(李彦和云)罢、罢、罢，我情愿丢了这般好生意，跟的你去。","(副旦云)你可辞了你那主人家去。","(李彦和向古门云)主人家，我认着了一个亲眷，我如今回家去也。","牛羊都交还与你，并不曾少了一只。","(副旦云)跟的我去来波。","(唱)。"]},{"t":"风雨像生货郎旦・随尾","f":"曲","c":["袄庙火，宿世缘，牵牛织女长生愿。","多管为残花几片，误刘晨迷入武陵源。","(同下)。"]},{"t":"风雨像生货郎旦・梁州第七","f":"曲","c":["正遇着美遨游融和的天气，更兼着没烦恼丰稔的年时。","有谁人不想快平生志。","都只待高张绣幕，都只待烂醉金卮。","我本是穷乡寡妇，没甚的艳色矫姿。","又不会卖风流弄粉调脂，又不会按宫商品竹弹丝。","无过是赶几处沸腾腾热闹场儿，摇几下桑琅琅蛇皮鼓儿，唱几句韵悠悠信口腔儿。","一诗，一词。","都是些人间新近希奇事，扭捏来无诠次。","倒也会动的人心谐的耳，都一般喜笑孜孜。"]},{"t":"风雨像生货郎旦・转调货郎儿","f":"曲","c":["也不唱韩元帅偷营劫寨，也不唱汉司马陈言献策，也不唱巫娥云雨楚阳台。","也不唱梁山伯，也不唱祝英台。","(小末云)你可唱甚么那？(副旦唱)只唱那娶小妇的长安李秀才。"]},{"t":"风雨像生货郎旦・二转","f":"曲","c":["我只见密臻臻的朱楼高厦，碧耸耸青檐细瓦，四季里常开不断花。","铜驼陌纷纷斗奢华，那王孙士女乘车马，一望绣帘高挂，都则是公侯宰相家。","(云)话说长安有一秀才，姓李名英，字彦和。","嫡亲的三口儿家属，浑家刘氏，孩儿春郎，奶母张三姑。","那李彦和共一娼妓，叫做张玉娥，作伴情熟，次后娶结成亲。","(叹科，云)嗨！他怎知才子有心联翡翠，佳人无意结婚姻。","(小末云)是唱的好，你慢慢的唱咱。","(副旦唱)。"]},{"t":"风雨像生货郎旦・三转","f":"曲","c":["那李秀才不离了花街柳陌，占场儿贪杯好色，看上那柳眉星眼杏花腮。","对面儿相挑泛，背地里暗差排。","抛着他浑家不理睬，只教那媒人往来，闲家擘划，诸般绰开，花红布摆。","早将一个泼贱的烟花娶过来。"]},{"t":"风雨像生货郎旦・五转","f":"曲","c":["火逼的好人家人离物散，更那堪更深夜阑，是谁将火焰山移向到长安？烧地户，燎天关，单则把凌烟阁留他世上看。","恰便似九转飞芒，老君炼丹，恰便似介子推在绵山，恰便似子房烧了连云栈，恰便似赤壁下曹兵涂炭，恰便似布牛阵举火田单，恰便似火龙鏖战锦斑斓。","将那房檐扯，脊梁扳。","急救呵可又早连累了官房五六间。"]},{"t":"风雨像生货郎旦・六转","f":"曲","c":["我只见黑黯黯天涯云布，更那堪湿淋淋倾盆骤雨，早是那窄窄狭狭沟沟堑堑路崎岖。","知奔向何方所。","犹喜的消消洒洒、断断续续、出出律律、忽忽噜噜阴云开处，我只见霍霍闪闪电光星炷。","怎禁那萧萧瑟瑟风，点点滴滴雨，送的来高高下下、凹凹凸凸一搭模糊，早做了扑扑簌簌、湿湿渌渌疏林人物。","倒与他妆就了一幅昏昏惨惨潇湘水墨图。"]},{"t":"风雨像生货郎旦・七转","f":"曲","c":["河岸上和谁讲话，向前去亲身问他，只说道奸夫是船家。","猛将咱家长喉咙掐，磕搭地揪住头发，我是个婆娘怎生救拔！也是他合亡化，扑冬的命掩黄泉下。","将李春郎的父亲，只向那翻滚滚波心水淹杀。"]},{"t":"风雨像生货郎旦・八转","f":"曲","c":["据一表仪容非俗，打扮的诸余里俏簇，绣云胸背雁衔芦。","他系一条兔鹘、兔鹘，海斜皮偏宜衬连珠，都是那无瑕的荆山玉。","整身躯也么哥，缯髭须也么哥，打着鬓胡。","走犬飞鹰，驾着鸦鹘，恰围场过去、过去。","折跑盘旋骤着龙驹，端的个疾似流星度。","那行朝也么哥，恰浑如也么哥，恰浑如和番的昭君出塞图。"]},{"t":"风雨像生货郎旦・九转","f":"曲","c":["便写与生时年纪，不曾道差了半米。","未落笔花笺上泪珠垂，长吁气呵软了毛锥，忄西惶泪滴满了端溪。","(小末云)他去了多少时也？(副旦唱)十三年不知个信息。","(小末云)那时这小的几岁了？(副旦唱)相别时恰才七岁，(小末云)如今该多少年纪也？(副旦唱)他如今刚二十。","(小末云)你可晓的他在那里？(副旦唱)恰便似大海内沉石。","(小末云)你记的在那里与他分别来？(副旦唱)俺在那洛河岸上两分离，知他在江南也塞北？(小末云)你那小的有甚么记认处？(副旦唱)俺孩儿福相貌双耳过肩坠，(小末云)再有甚么记认？(副旦云)有、有、有，(唱)胸前一点朱砂记。","(小末云)他祖居在何处？(副旦唱)他祖居在长安解库省衙西。","(小末云)他小名唤做甚么？(副旦唱)那孩儿小名唤做春郎身姓李。"]},{"t":"风雨像生货郎旦・煞尾","f":"曲","c":["我只道他州他府潜逃匿，今世今生没见期。","又谁知冤家偏撞着冤家对。","(净云)原来这就是李春郎，这就是张三姑。","当日勒他不死，就该有今日的晦气了。","(做叩头科，云)大人，可怜见，饶了我老头儿罢。","这都是我少年间不晓事，做这等勾当。","如今老了，一口长斋，只是念佛。","不要说杀人，便是苍蝇也不敢拍杀一个。","况是你一家老小现在，我当真谋杀了那一个来？可怜见，放赦了老头儿罢。","(外旦云)你这叫化头，讨饶怎的？我和你开着眼做，合着眼受，不如早早死了，生则同衾，死则共穴，在黄泉底下，做一对永远夫妻，有甚么不快活？(副旦唱)你也再没的怨谁，我也断没的饶伊。","(小末斩净、外旦科，下)(副旦唱)要与那亡过的娘亲现报在我眼儿里。","(李彦和云)今日个天赐俺父子重完，合当杀羊造酒，做个庆喜的筵席。","孩儿，你听者。","(词云)这都是我少年间误作差为，娶匪妓当局者迷。","一碗饭二匙难并，气死我儿女夫妻。","泼烟花盗财放火，与奸夫背地偷期。","扮船家阴图害命，整十载财散人离。","又谁知苍天有眼，偏争他来早来迟。","到今日冤冤相报，解愁眉顿作欢眉。","喜骨肉团圆聚会，理当做庆贺筵席。"]},{"t":"诸葛亮博望烧屯・仙吕/点绛唇","f":"曲","c":["数下皇极，课传《周易》，知天理。","饱养玄机，常有那尊道德参玄意。"]},{"t":"诸葛亮博望烧屯・混江龙","f":"曲","c":["有朝一日，我出茅庐指点世人迷。","凭着我剑挥星斗，我志逐风雪。","圣明君稳坐九重龙凤阙，显出那大将军八面虎狼威。","(云)道章，你见么？(道童云)师父，您徒弟见甚么？(正末唱)见风筛竹影，日射松穿。","我恰才袖中发课，你去那门外观窥。","安排着香桌，准备着烹茶，(云)道童，这一来。","(道童云)师父，可是何人到此也。","(正末唱)必定是关云长、张翼德和刘备。","(云)道童。","(道童云)师父有何话说？(正末唱)你与我忙铺下席簟，，你与我半掩得这些扉。","(道童云)师父，您徒弟安排下香桌，烹了茶汤，铺下席簟，洒扫的干净了也。","(正末云)道童，你门首觑者，看有甚么人来。","(刘末同关末、张飞上)(刘末云)兄弟，可早来到也。","远远的看见茅庵，将俺的军马屯在这山峪口，安营下寨。","咱弟兄三人，直至茅庵中请师父去，可早来到也。","二位兄弟，俺见师父去来。","(张飞云)二位哥，今番第三遭，这村夫若下山去呵，我和他佛眼相看，若不下山去呵，我不道的烧了他哩。","(关末云)兄弟，你休这等躁暴，俺求贤用士哩。","(刘末云)兄弟，你不得躁暴，休误了大事。","(刘末见道童科，云)道童，你师父庵中有么？(道童云)俺师父正在庵中盹睡哩。","(张飞做揪住道童科，云)你师父在那里？(道童慌科，云)老官儿，我才不说来，师父昨日酒多了，还不曾睡醒哩。","老官儿休要动手。","(张飞云)这村夫到不纳房钱。","则是睡。","(关末云)兄弟休要躁暴。","(张飞做放了道童科，云)去，我且饶你。","(道童云)呸！可不是晦气。","此人就是个村牛一般。","(刘末云)道童，对你师父说去，有新野太守刘、关、张弟兄三人，特来拜见。","(道童云)理会的。","(报科，云)报的师父得知，庵门首有刘、关、张弟兄三人，来拜见师父。","(正末云)既然一年三访，此人诚心，我必索与他相见者。","道童，你请那姓刘的过来。","(道童云)理会的。","(做见刘末科，云)那个是那姓刘的老官儿？俺师父有请。","(刘末云)您二位兄弟，则在门首等者，我见了师父，着人来请您二位兄弟。","(刘末做见科)(正末唱)。"]},{"t":"诸葛亮博望烧屯・醉中天","f":"曲","c":["我见他挪身起，他忙挪步上阶基。","(刘末拜科，云)师父，孤穷刘备，来两次不遇，今番是第三遭也。","刘备特来相访。","(正末唱)玄德公你这般两次三番劳贵体，(刘末云)小官特来相请也。","(正末唱)你请贫逆因何意？(刘末云)一年三访不遇，今日得见吾师，实乃孤穷刘备之万幸也。","(正末唱)我请你个玄德公安然坐的，(刘末云)孤穷刘备，断然不敢。","(正未唱)他口声声道是孤穷刘备，那一个孤穷的他生这般舜目尧眉？。"]},{"t":"诸葛亮博望烧屯・油葫芦","f":"曲","c":["我则待仿学巢由洗是非，我一心待习道德。","我可便喜登吕望钓鱼矾，谁待要蜗牛角上争名利？谁待要蜘蛛网内求官位？(刘末云)师父隐迹于此，不知主何意也？(正末唱)我但穿些布草衣，但吃些粗粝食。","我则待日高三丈我便朦头睡，一任教乌兔走东西。"]},{"t":"诸葛亮博望烧屯・天下乐","f":"曲","c":["我则是除睡人间总不知，我可便其也波实，其实可便无甚智，(刘末云)师父若肯下山去呵，同扶汉室，再立炎刘，有何不可也？(正末唱)你今日请贫道下山待出些气力。","(云)贫道便下山去呵。","(唱)我其实当不的寒，我可便济不的饥，便请下这个卧龙冈做甚的？。"]},{"t":"诸葛亮博望烧屯・金盏儿","f":"曲","c":["他生的高耸耸俊英鼻，长挽挽卧蚕眉。","红馥馥面皮有似胭脂般赤，黑蓁蓁三绺美髯垂。","这将军内藏着君子气，外显出渗人威。","这将军生前为将相，他若是死后做神祗。"]},{"t":"诸葛亮博望烧屯・尾声","f":"曲","c":["把您这孙刘曹、吴蜀魏，鼎足三分不可缺矣。","曹操天时为第一，想孙权地利合宜，玄德公掌人和，稳胜磬石。","先占了西蜀四千里，我对你个玄德公说知。","哎！你个张将军赌气，我则见笑谈间一阵卷征旗。","(同众下)。"]},{"t":"诸葛亮博望烧屯・南吕/一枝花","f":"曲","c":["我则见遮天杂彩旗，震地花腔鼓。","关云长青龙偃月刀，张翼德银蟒可兀的点钢毒。","齐臻臻铠甲结束，银缠杆花稍弩，兽吞金蘸斧。","有五千员越岭奔彪，有百万只爬山猛虎。"]},{"t":"诸葛亮博望烧屯・牧羊关","f":"曲","c":["则要你鱼鳞般排军阵，雁行般列队伍，依着我运计铺谋。","我不要你战斗相持，我则要你扬尘也那播土。","你休去那垓心里撞，你则向草坡早伏。","(刘封云)军师，则怕不中么？(正末唱)哎，你个义子休心怕，你正是贼儿胆底虚。"]},{"t":"诸葛亮博望烧屯・贺新郎","f":"曲","c":["你向那博望城多准备着火葫芦，(云)等他入的城来，着鹿角叉住巷口，当住城门。","(唱)你与我先点着粮车，后烧着窝铺。","您四下里火箭一齐去，火烧的他神嚎也那鬼哭，火烧的他马死人无。","着他在火坑中丧了性命，都着他火阵内丧了残躯。","(糜竺云)则怕三将军他要去么？(正末唱)你着那张将军不索阶前怒，这的是黄公《三略》法，更压着那吕望《六韬》书。"]},{"t":"诸葛亮博望烧屯・隔尾","f":"曲","c":["关云长你去漏陵渡，(关末云)师父，潺陵渡怎生堰住水口？(正末唱)用土布袋把长江紧当住，水淹杀的军兵死无数。","他活时节是战夫，死后做了水卒。","(云)二将军云长。","(关末云)有。","(正末唱)你若是得胜还营，你将我来自然许。"]},{"t":"诸葛亮博望烧屯・双调/新水令","f":"曲","c":["管教这数千员敢战的铁衣郎，则有个莽张飞他可便不伏诸葛亮。","则因恶战讨，我可便懒下卧龙冈。","则他这战马刀枪，多无那半个时分见明降。"]},{"t":"诸葛亮博望烧屯・风入松","f":"曲","c":["您众将军武艺委实强，(云)好将军也。","(唱)更那堪状貌堂堂。","舍性命便往垓心里撞，恰便似闹垓垓虎荡群羊。","饮过酒今番不忘，为将帅显高强。"]},{"t":"诸葛亮博望烧屯・雁儿落","f":"曲","c":["眼见的鞭敲金镫响，将凯歌齐声唱。","紧绑绑拴住臂膊，直挺挺舒着脖项。"]},{"t":"诸葛亮博望烧屯・得胜令","f":"曲","c":["张飞也，你不道是架海紫金梁，他不是那托搭的李天王？得胜掌军师印，你道是不拿住不姓张。","你凭着马壮人强，你道是鞭督邮魂飘荡。","你曾摔袁祥，(带云)张飞你不道来那，(张飞云)我道甚么来？(正末唱)你道是，男儿当自强。"]},{"t":"诸葛亮博望烧屯・鸳鸯煞尾","f":"曲","c":["今日个领三军坐金顶莲花帐，披七星锦绣云鹤氅。","早定了西蜀，我便访南阳。","畅道觑曹操、孙权，似浮云瘙痒。","我请您玄德、关、张，威镇住曹丞相。","今日个稳定家邦，史策留名后人讲。","(同下)。"]},{"t":"诸葛亮博望烧屯・中吕/粉蝶儿","f":"曲","c":["自从和曹操争锋，恰如同一场春梦。","摆列着盖国英雄，一个个善相持，能挑战，他可便超群出众。","一个个都建了头功，真乃是世之梁栋。"]},{"t":"诸葛亮博望烧屯・醉春风","f":"曲","c":["想昔日梦非熊，您今朝请卧龙。","我可甚两三番懒下卧龙冈，我其实怕冗，冗。","我今日当权，掌军师名项，则不如我在那半坡里养性。","(云)玄德公安排酒果，准备的齐整者。","不到半时，必有说客至此。","则要糜竺、糜芳在此，其余将军都承听令。","赵云附耳来，可是恁的。","(做打耳喑科)(赵云云)师父连主公也着回避，您众将听师父将令。","糜竺、糜芳，紧守着师父，小心在意者。","(正末云)是也。","(刘末云)师父，连刘备也着回避，众将听师父将令。","糜竺、糜芳，紧守着师父，小心在意。","(赵云云)俺回避也。","(同众下)(管通上，云)贫道管通是也。","自离魏地，可早来到新野。","小校报复去，道有一云游先生，乃是管通，特来相访。","(卒子云)理会的。","喏，报的军师得知，有一云游的先生管通，在于门首。","(正末云)我须索接待哥哥，走一遭去。","(见科，云)哥哥有请。","(管通云)不敢。","(正末云)哥哥，俺一向相别，拳拳在意，终日无忘。","不想哥哥今日来到，实乃诸葛之万幸也。","(管通云)贤兄久别情怀，常思快怏。","叹美景无多，流光易迈。","想音容切切于心、思大德悬悬在念。","自庵中作别以来，无一时忘于左右，今日得遇尊颜，实乃贫道之万幸也。","(正末云)哥哥请坐，小校抬上果桌来者。","(卒子云)理会的。","(正末云)将酒来。","(做递酒科，云)哥哥满饮一杯。","(管通云)不敢，贤兄请。","(做饮酒科)(正末唱)。"]},{"t":"诸葛亮博望烧屯・剔银灯","f":"曲","c":["非是我厅阶前卖弄，你众将休要打哄。","若猜着众将休惊恐，您试看变化的这神通。","这的是真术艺，又不是说脱空，睁着眼不要转动。"]},{"t":"诸葛亮博望烧屯・十二月","f":"曲","c":["这个是常山赵云，(管通云)这个是谁？(正末唱)这个是义子刘封。","(管通云)这个是谁？(正末唱)这个是燕人翼德。","(管通云)这个是谁？(正末唱)这个是勇烈关公。","(管通云)贫道相的不差也。","(正末唱)哎，这个能相法哥哥管通，你可也比众难同。","(云)哥哥，这四间房，哥哥都相过了。","哥哥，你看这间房里如何？(管通云)我观这间房中，气象全别。","你看那样云笼罩，紫气腾腾，必是贵人之相，都压着这几位将军。","兄弟不信呵，开了门我试看者。","(正末做怒科，云)休开门。","(管通云)开了者。","(正末云)休开门。","(管通云)你为何不开，(正末云)哥哥，不争您兄弟开开这门，(唱)。"]},{"t":"朱砂担滴水浮沤记・仙吕/端正好","f":"曲","c":["躲非灾，离乡故，相别罢便践程途。","(旦儿云)王文用，今日分别，好生凄凉也。","(正末唱)方信道人生唯有别离苦，眼看着向那海角天涯去。","(下)。"]},{"t":"朱砂担滴水浮沤记・仙吕/点绛唇","f":"曲","c":["带月披星，忍寒受冷，离乡井。","过于些芳草长亭，再不曾半霎儿得这脚头定。"]},{"t":"朱砂担滴水浮沤记・混江龙","f":"曲","c":["你看那人间百姓，在红尘中部要干营生，两下里行船走马，各要夺利争名。","船尾分开横水绿，马蹄踏破乱山青。","则他这摇鞭举棹可便也休相竞，多则为两匙儿羹粥干忙了那一世，落的这前程。","(云)天色晓了也，我在这店肆中觅个宵宿咱。","小二哥，开门，开门。","(店小二云)有人唤门哩，我开开这门来。","(见科，云)我道谁，原来是老客。","隔的两个月不见，一发吃的好了。","老客，如今未做甚么？(正末云)我来你这店里，觅一个宿，我与你二百文房钱。","(店小二云)勾了，勾了。","老客请进里面来。","用些甚么茶饭？(正末云)茶饭都不用。","你只与我点一盏灯来。","(店小二云)理会的。","灯在此。","(正末云)小二哥，你把房钱收去，我明日五更前后，早起便行，我也不辞你了。","(店小二云)哦，你明日不辞我，天明就去。","既然如此，你歇息罢。","我自家睡去。","(下)(正末云)我关上这门。","走的我身子困倦了，我歇息咱。","(做睡、打梦科)(云)王文用也，甚睡儿到的我这眼里？我开开这门，我来这里，下了两遭，倒不曾细看。","可怎生这里有一个小角门儿？我开开这门，元来是一所花园。","是好花也。","(唱)。"]},{"t":"朱砂担滴水浮沤记・醉中天","f":"曲","c":["我则见牡丹花堪人赏宜人敬，可人意动人情。","又则见青芍药白蔷薇红锦樱，又则见紫纹桃间着那黄花杏。","(云)是好花也，我待折一朵儿咱。","(唱)不由我心中自警，百般的把拿不定。","(云)这所在也无人，我便折一朵儿怕做甚么？(做惊科)(唱)呀，可怎生扑簌簌枝叶凋零？。"]},{"t":"朱砂担滴水浮沤记・青歌儿","f":"曲","c":["天也。","好着我又不敢问他、问他名姓，早则是打了个浑身痴挣。","(做杀正末，打推下)(正末做醒科，云)有杀人贼也，呸！(唱)我恰才哄的觉来忽的醒。","(云)好个恶梦也。","我开了这门。","(唱)我才出门程，向花苑闲行。","见风弄残灯，正月白三更。","亲见个妖精，待把我欺凌。","只一拳险送了这泼残生，天也，兀的不忧成我病。"]},{"t":"朱砂担滴水浮沤记・醉扶归","f":"曲","c":["我则见那野水穿花径，村犬吠柴扃。","合剌剌辘轳响，可正和着各琅琅的捣碓声，更那堪绿柳相遮映。","(做见店小二科，云)这是一个小酒务儿，小二哥，有酒么？(店小二云)有酒、有酒。","(正末云)小二哥，打二百文长钱的酒来。","(店小二云)酒在此。","你有量尽着你吃，只不要撒酒风。","(正末唱)则你这醇糯酒浑如靛青。","我且饮一盏消闲兴。"]},{"t":"朱砂担滴水浮沤记・金盏儿","f":"曲","c":["忙浇奠谢神明，凭买卖做经营，大古来贫穷富贵皆前定。","(邦老云)那壁角子里有人说话。","我试听他说甚么。","(正末做浇奠酒科，云)一点酒入地，愿万民安乐。","两点酒入地，愿五谷丰登。","三点酒入地，愿好人相逢，恶人远避。","(邦老拍卓科，云)兀那村弟子孩儿，那恶人恼着你甚么来？(店小二云)老权，不要打破了我的卓子。","(正末唱)我这里扭回脖颈，他那里闪双睛。","(邦老云)这厮好无礼也。","(正末唱)我见他忽的眉剔竖，秃的眼圆睁。","唬的我腾的撒了抬盏，哄的丢了魂灵。"]},{"t":"朱砂担滴水浮沤记・赚煞尾","f":"曲","c":["他觑我似炉畔弄冬凌，他觑我似碗里拿蒸饼。","若不是灌的来十分酩酊，怎按住他一场火气性。","我如今在虎口逃生，急腾腾，再不消停，抵多少遥指空中雁做羹。","比及那贼徒酒醒，我已自家胆正，遮莫他赶将来我与你先走了两三程。","(下)。"]},{"t":"朱砂担滴水浮沤记・南吕/一枝花","f":"曲","c":["那厮他入门来便紧瞅了咱这小本的装，则被我买下子些新槽的酒。","连珠儿灌到有五六碗，他承兴饮吃到有两三瓯，尽醉方休。","那好饮的也是天生就，一会儿直灌的那厮瓠子头。","他和衣儿稳睡安眠，怎知我悄声儿逃席便走。"]},{"t":"朱砂担滴水浮沤记・梁州第七","f":"曲","c":["若不是我使见识一杯也那一跪，天那！可不将我这泼残生早做了千死千休！我从那早辰间直走到申时候。","过了些青山隐隐，绿水悠悠。","荒祠古庙，沙岸汀洲。","七林林低陇高丘，急旋旋浅涧深沟。","刚抹过另巍巍这座层峦，还隔着碧遥遥几重远岫，又接上白茫茫一带平畴。","巴的到绿杨渡口，早则是云迷雾锁黄昏后，我去那野店上觅一宿。","这的便是东海鳌鱼脱钓钩，我可也再不回头。"]},{"t":"朱砂担滴水浮沤记・牧羊关","f":"曲","c":["我将这灯吹灭，身倒抽，唬的我浑身上冷汗交流。","莫是取命的阎王，杀人的领袖？唬的我呆打颏空张着口，惊急力怕抬头。","恰待要睁开两个眼，可早则软塌了一对手。"]},{"t":"朱砂担滴水浮沤记・隔尾","f":"曲","c":["一领布衫我与你刚刚的扣，八答麻鞋款款的兜。","我又不敢高声大咳嗽，我将这厮左瞅，右瞅。","哎！天也！怎的他一阵儿昏迷稳放我走。","(云)行李衣服都摸着了也，且喜那厮正睡着哩。","此时不走，更待何时！(唱)。"]},{"t":"朱砂担滴水浮沤记・牧羊关","f":"曲","c":["只道他猛翻身，睡觉秋，且喜得眼朦胧又打鼻勾鼻勾。","他土鲁鲁嗓内涎潮，我也急煎煎心下刀抽。","有如秋夜雨，一点一声愁。","正待要展开脚忙移步，百忙里腿转筋甚腌证候。"]},{"t":"朱砂担滴水浮沤记・黄钟尾","f":"曲","c":["罢、罢、罢，我这性命呵，似半轮残月三更后，一日无常万事休。","苦奔波，枉生受，有谁人，肯搭救，单只被几颗朱砂，送了我头。","拚的向阎罗告究，着铁幡竿等候。","遮莫你板门似手掌儿，也掩不得俺这叫屈的口。"]},{"t":"朱砂担滴水浮沤记・滚绣球","f":"曲","c":["你道为甚么森森的透骨寒？","却元来是茫茫的云雾繁，遮断著红尘无限，刚则见衰草斑斑，兀的不是地府间、黑水湾？","早来到这奈河两岸，兀的不是剑树刀山？","两只眼紧把冤魂来觑，一只手轻将他鬼力扌班，何处也蹒跚。"]},{"t":"朱砂担滴水浮沤记・倘秀才","f":"曲","c":["见地曹手捧着温良玉盏，我这里忙擎起花纹象简，(净云)上圣，许久不会了也。","(正末唱)我和你间别来早已数载间。","绝音信，少平安，今日得见面颜。"]},{"t":"朱砂担滴水浮沤记・煞尾","f":"曲","c":["则我这硬邦邦指爪将那厮头稍来挽，粗滚滚麻绳将那厮脖项来拴。","丢天灵剪子腕，着凌迟受磨难，那怕他泼顽皮绰号做铁幡竿。","只消我这一对儿拦关，把那厮死狗也似拖将来我直着见了您眼。","(下)。"]},{"t":"朱砂担滴水浮沤记・幺篇","f":"曲","c":["我将这厮琅琅铁索把那厮肩膀绑，沉点点铁棍将那厮臂膊搪。","打碎天灵共眼眶，踢折蛮腰和脑浆。","(做嘴脸科)(鬼力云)怎么做这个嘴脸？(净唱)把那厮直拿到酆都那边，着他慢慢的想。","(同下)。"]},{"t":"朱砂担滴水浮沤记・双调/新水令","f":"曲","c":["正黄昏庭院景凄凄，哎哟天那！走的我软兀剌一丝两气。","淅零零的山路冷，昏惨惨的晚风吹。","脚步儿刚移，一步步行到枉死地。","(做行科，云)来到这个所在，是十字坡口儿上酒店，正是我当初遇着那贼处。","他见着我甚些动静，便起这点狠心？所算的我好苦也。","(唱)。"]},{"t":"朱砂担滴水浮沤记・沉醉东风","f":"曲","c":["若不是我失时落势，怎生的便揽祸招危。","我和他这搭儿才相见，平日里又不相识。","刚道个一声儿恶人回避，早激的他恶哏哏闹是非，那里也见财起意。"]},{"t":"朱砂担滴水浮沤记・乔牌儿","f":"曲","c":["我既是抽身儿悄脱离，又何苦直赶上这田地？","我和他又没甚杀爷娘抢道路深仇隙，可怎便舍残生做到底？","。"]},{"t":"朱砂担滴水浮沤记・甜水令","f":"曲","c":["我只合紧闭房门，吹残灯火，且图安睡，怎好去一颗颗数着这东西。","早被他识咱行藏，听咱声响，见咱踪迹，可不是自落的便宜。","(做行科，云)这所在是东岳太尉庙。","那贼汉好狠也，我把一担儿朱砂都送了你，只要留俺的性命，你怎么还要将我杀了？我记的临死时曾指滴水浮沤为证。","我如今冤魂不散，少不的和你索命。","太尉爷爷，你是个掌生死的活神道，须与我屈死的王文用做主咱。","(做拜科)(唱)。"]},{"t":"朱砂担滴水浮沤记・折桂令","f":"曲","c":["我忙合手顶礼神祗，现掌着死生文簿，何曾错善恶毫厘。","(做再拜科，云)太尉爷爷，(唱)你怎不怜见我屈死的冤魂？放过了他行凶的泼贼，待强夺了俺无主的娇妻。","我亲指着滴檐前浮沤为记，难道你坐殿上神圣无知？(做再拜科)(唱)只愿你检验轮回，速显灵威，将那厮直押送十八层地狱阿鼻，才见的你百千年天性忠直。"]},{"t":"朱砂担滴水浮沤记・落梅风","f":"曲","c":["我只道你灵性归天上，却元来幽魂沉井底，总便是铁石人也见了心碎。","我和他这冤仇结的来甚尽期，只除非各一家天地。"]},{"t":"朱砂担滴水浮沤记・沽美酒","f":"曲","c":["并不曾见烈纸钱将咱祭，倒去熬粥汤送他吃，元来你个水性婆娘易转移。","干着我生受了半世，眼睁睁看你做歹人妻。"]},{"t":"朱砂担滴水浮沤记・太平令","f":"曲","c":["我痴心想望贞洁，你做事忒杀非为，铁幡竿满怀得济，王文用手稍儿着地。","你这个泼贼，就里，落可便下的，白占了俺家缘家计。"]},{"t":"朱砂担滴水浮沤记・收尾","f":"曲","c":["死生难遏我心头气，冤仇有似檐间水。","哎，你个图财致命的狠心贼，也少不得做个落堑拖坑的没头鬼。"]},{"t":"雁门关存孝打虎・仙吕/赏花时","f":"曲","c":["止不过漠漠平沙际碧天，又不比夕贬潮阳路八千，我忙传着一纸圣人宣。","(殿头官云)则是路途较远难行，须要小心在意者。","(正末唱)避不的山遥路远，(云)大人放心。","(唱)我可也无明夜到居延。","(下)。"]},{"t":"雁门关存孝打虎・隔尾","f":"曲","c":["我则见八而威的猛兽偎深涧，他可早一跳身番飞过浅山，把我这贪水食的群羊尽哄散。","这厮将咱恼犯。","我这里将皮裘紧拴，大踏步望前舍死的赶。"]},{"t":"雁门关存孝打虎・牧羊关","f":"曲","c":["血鼻凹扑碌碌连打十余下，死尸骸骨鲁鲁滚到四五番，恨不的莽拳头打挫牙关。","八面威气象全无，十石力身躯软瘫。","泥污了数尺金椽尾，血模糊几道剪刀斑。","舒不出钢钩似十八爪，闪不开金铃也一对眼。"]},{"t":"雁门关存孝打虎・贺新郎","f":"曲","c":["小人本家住在雁门关，(李克用云)你做甚买卖营生？(正末唱)与人家牧牛羊，(李克用云)你和他同财合本？(正末唱)则是苟图些衣饭。","(李克用云)你有甚么亲眷？(正末唱)没亲眷独自个单身汉。","(李克用云)你姓甚名谁？(正末唱)名敬思小人姓安。","(李克用云)你十八般武艺，那一般精熟？(正末唱)我学的十八般武艺熟闲。","(李克用云)你既然学成十八般武艺，见如今黄巢作乱，纵横天下，你肯去破黄巢去么？(正末唱)不是这习兵书的好汉少，赤紧的养剑客的主人难。","(李克用云)看了你威风凛凛，状貌堂堂，何不进取功名？(正末唱)觑了这穷身泼命难把功名干，(李克用云)你既有打虎之威，取功名有何难哉。","(正末唱)端的是入山擒虎易，叉手告人难。","(李克用云)兀那壮士，既学成十八般武艺，何不进取功名，在此受这等艰难？(正末唱)。"]},{"t":"雁门关存孝打虎・哭皇天","f":"曲","c":["只为俺衣饭难迭办，不得已在他人眉睫间。","(李克用云)你在那里居住。","(正末唱)则这安敬思在飞虎峪，(李克用云)你为何在此受苦？(正末云)大人，不争小人一个受苦，上辈古人，多有受窘的哩。","(李克用云)可是那几个古人受窘？(正末唱)便似班定远在玉门关。","空学的兵书战策，争柰运拙时艰。","淹留在此去住无门，便似苏武般陷番。","打虎的壮士，牧羊的家奴，似梁园采木，把我做凡花、凡花-例看。","你觑的黄巢利害，我看似等闲。"]},{"t":"雁门关存孝打虎・乌夜啼","f":"曲","c":["也不要锦衣绣袄军十万，我手里要恢复你大唐江山。","可怜见荒荒百姓遭涂炭，见如今地乱天番，我直教国泰民安。","不能勾开疆展土笑谈间，算甚么顶天立地男儿汉。","枉了你厮听使，相调慢，花根本艳，虎体元斑。"]},{"t":"雁门关存孝打虎・二煞","f":"曲","c":["凭着我忠心扫荡烟尘散，捉将手扶持社稷安。","华严大战那其问，上的那骏马雕鞍。","恁般儿虽不似跨海征辽那汉，黄金铠不须擐，凭着背上雕弓月样弯，我则要定了天山。"]},{"t":"雁门关存孝打虎・越调/斗鹌鹑","f":"曲","c":["你看我对垒交锋，相持厮杀。","则听的呐喊摇旗，天摧地塌。","则我这耀武扬威，披袍擐甲。","非小可，不要耍。","则这八水三川，屯着千军万马。"]},{"t":"雁门关存孝打虎・金蕉叶","f":"曲","c":["我则见黑黯黯云遮日华，昏邓邓风吹塞沙。","见一人雄纠纠被袍擐甲，嗔忿忿横枪跃马。","(二净云)来将何人？(正末唱)。"]},{"t":"雁门关存孝打虎・调笑令","f":"曲","c":["不索你搦咱，更怕你会征伐，(二净云)来者何人？通名道姓。","(正末唱)你存孝爹爹出阵咱。","(云)你是何人？(二净云)吾乃黄巢手下大将张归霸、张归厚。","你那牧羊子，早早下马来受死。","(正末唱)原来是黄巢手下张归霸，嗔道这般气高胆大。","向前来二人挑战咱。","不索你冬冬战鼓频挝。","(二净云)颇柰牧羊子无理，你敢与我决战三合么？(正末云)交马来。","(唱)。"]},{"t":"雁门关存孝打虎・秃厮儿","f":"曲","c":["鞍上将威风转加，坐下马筋力堪夸。","我则见纱灯儿般转到十数匝，我看你怎生收煞？(二净云)我儿李存孝，早早下马罢。","(正末云)这厮好无理也。","(唱)。"]},{"t":"雁门关存孝打虎・圣药王","f":"曲","c":["叵耐他，小觑咱，匣中宝剑定中华。","凭着我坐下马，手中挝，李存孝非是自矜夸，我扶立起大唐家。"]},{"t":"雁门关存孝打虎・雪里梅","f":"曲","c":["猛然间入京华，谁敢道当阑咱？则这京城中可是俺大唐天下，不刺刺忙催战马。","(云)进的这城来，大小三军，摆开阵势，看有甚么人来。","(黄圭上，云)某乃御弟黄圭是也。","叵耐大唐家去沙陀取将李克用来，他手下新收的一个牧羊子，叫做存孝，来杀俺二三十阵。","今杀到长安城里，无人敢当，某亲身与他交战一遭去。","兀那牧羊子，来与某交手咱。","(正末云)这厮好无礼也，走将来交马便战，不要看这厮披挂，到骑着一匹好马。","大小三军，看我拿那厮来。","(唱)。"]},{"t":"雁门关存孝打虎・古竹马","f":"曲","c":["也不索征鞍轻压，征靴微抹，征马宛紧跨，不刺刺直赶到海角天涯。","生熬的两事家，心惊胆战，力困神乏。","见他，见他，战战兢兢，怯怯乔乔，黄甘甘容颜如蜡渣，全不见武艺熟滑。"]},{"t":"雁门关存孝打虎・幺","f":"曲","c":["我从来劣性难拿，正恼犯如何收煞。","见咱，赶他，撞阵冲军，倒戈弃甲。","纵辔加鞭催战马，恨不的剪断紫稍，踏斜宝镫，顿宽玉勒，摆损金算刂。"]},{"t":"雁门关存孝打虎・尾声","f":"曲","c":["把那仓廒府库随风化，不落根椽片瓦。","这勤王存孝得功回，教这反国黄巢没乱杀。","(下)。"]},{"t":"雁门关存孝打虎・黄钟/醉花阴","f":"曲","c":["一托气直奔数十里，遍体汗浑如水洗。","非是我说兵机，若论相持，大会垓应难比。"]},{"t":"雁门关存孝打虎・喜迁莺","f":"曲","c":["火速的上阶基，一径的搀先队，(云)报、报、报，喏。","(唱)来报喜。","(李克用云)好探子也，从那阵面上来，喜色旺气。","一张弓弯秋月，两枝箭插寒星，三尺剑挂小貂裘，四方报喜问探子，五花营中来往有如撺梭，六队军中上下有如蛟龙，七尺躯肩担令字旗，八角红缨桶子帽，久久等待许多时，实实数说军情事。","(探子唱)当日个华严川内，众诸侯聚会云集。","端的，阿谁不会，尽是些使争好斗显气势。","一个个挟人捉将，一个个挝鼓夺旗。"]},{"t":"雁门关存孝打虎・出队子","f":"曲","c":["齐臻臻军卒摆列，韵悠悠画角吹。","扑冬冬振地凯征鼙，赤力力遮天磨绣旗，不剌刺追风战马嘶。"]},{"t":"雁门关存孝打虎・乱地风","f":"曲","c":["则见张归霸军前猛叫起，咱两个比试高低。","李存孝怒从心上起，呀，可早变了容仪，倒竖神眉。","踏宝镫滴溜扑跳上乌骓，吼风雷吐虹霓，一怒千斤力。","拚性命，厮对敌，手拿定两柄挝槌。","(李克用云)俺存孝与贼将交马十数合，那家赢？那家输？你喘息定，再说一遍。","(探子唱)。"]},{"t":"雁门关存孝打虎・四门子","f":"曲","c":["恶口音欠口音欠撞入垓心内，张归霸走似飞，料应他武艺敌不的。","打征马宛捻玉勒，畅好是慌，好是急。","飞虎将早来望后追，畅好是慌，好是急，误撞入长安市里。"]},{"t":"雁门关存孝打虎・古水仙子","f":"曲","c":["赶来到灞河里，见一只舡来有似飞。","摇橹的水手又心忙，把柁的梢公胆碎，恨不的两下里纳降旗。","一齐的马前忙跪膝，告爹爹委实敌不的，来、来、来，似小鬼见钟馗。"]},{"t":"雁门关存孝打虎・寨儿令","f":"曲","c":["端的，端的，全无半点疏失，又不见敌军武艺低。","虽存孝，善兵机，也托赖着当今帝。","(李克用云)好探子也，与你两只羊，两瓶酒，十个免帖。","回本营去。","(探子唱)。"]},{"t":"雁门关存孝打虎・尾","f":"曲","c":["到不得底，千寻浪头里。","看时节显出些头盔，我则见尸堰断灞陵桥下水。"]},{"t":"逞风流王焕百花亭・仙吕/点绛唇","f":"曲","c":["锦绣铺设，翠红罗列，酬佳节。","莺燕调舌，惜春光苦问东君借。"]},{"t":"逞风流王焕百花亭・混江龙","f":"曲","c":["管弦拖拽，王孙仕女斗豪奢。","梨花院秋千蹴鞠，牡丹亭宝马香车。","唤游人芳树啼残锦鹧鸪，采香蕊粉墙飞困玉蝴蝶。","杨柳映，杏花遮，东风外，酒旗斜。","四时中惟有春三月，光阴富贵，景物重叠。"]},{"t":"逞风流王焕百花亭・油葫芦","f":"曲","c":["则见来往佳人教我难应接，离百花亭将近也，就儿中这一个尤娇绝，(云)世间有此女子，岂不是施朱太赤，施粉太白？(唱)端的是腻胭脂红处红如血，润琼酥白处白如雪。","比玉呵软且温，比花呵花更别。","若不是嫦娥降下瑶宫阙，尘世里怎遇这活冤业。"]},{"t":"逞风流王焕百花亭・天下乐","f":"曲","c":["这的是美玉生香花解说，(旦见将扇遮科)(正末唱)他见人有些矫怯，忙将罗扇遮，(旦做意科，云)那生好一表人物也。","我折朵兰花儿咱。","(正末唱)则见他寄幽情故将兰蕊儿折。","端的个眉尖上芳信传，眼角头春意窃，(做俯觑科，唱)元来那脚踪儿也把心事写。"]},{"t":"逞风流王焕百花亭・醉中天","f":"曲","c":["他把我先勾拽，引的人似痴呆，哉和他四目相窥两意协。","好也风召他生的有芙蓉面，桃花颊，说不尽他百般娇千般艳冶。","(六儿云)官人，你看他眼似明星，眉如秋月，生的庄庄重重，是一个好女子也！(正末唱)你道他点星眸眉湾秋月，(做暗笑科，云)你怎知他不庄重的时节。","(唱)他可也有玉簪横云鬓偏斜。"]},{"t":"逞风流王焕百花亭・后庭花","f":"曲","c":["我也曾把柳条攀花蕊折，将那云雨期风月赊。","(旦云)你看这生说海口那。","(正末唱)你道我说海口王明彦，则要你放宽心贺大姐。","不是我咨娇奢，凭着我拈花摘叶，那愁他没鸾胶将弦断接。","(旦云)既然解元要与妾身为伴，怎也推辞。","但是俺娘举手大，枷棒重，只怕你当他不起。","(正末云)只要姐姐肯许了王焕，便是你奶奶利害，这等门户差拨，王焕也当的过来。","(六儿云)委的俺官人是惯家。","(正末唱)。"]},{"t":"逞风流王焕百花亭・一半儿","f":"曲","c":["他狠毒呵似两头蛇，乖劣呵浑如双尾蝎，我将明珠一斛亲弃撇。","(小二云)官人，你敢是心邪了也。","(正末唱)不是俺心邪，我只是一半儿支吾一半儿者。"]},{"t":"逞风流王焕百花亭・醉春风","f":"曲","c":["从今后牢收起爱月惜花心，紧抄定偷香窃玉手。","刁风拐月畅好是没来由，出这场丑，丑！从小着迷，少年吃闷，几时参透。"]},{"t":"逞风流王焕百花亭・迎仙客","f":"曲","c":["你两个元同舍，本儒流，那白捉鬼比小卿不姓苏比玉仙不姓周。","双通叔一般双，柳耆卿同是柳。","柳殿试实止望明月玩江楼，双解元干闪在金山后。"]},{"t":"逞风流王焕百花亭・普天乐","f":"曲","c":["水晶球，铜豌豆。","红裙中插手，锦被里舒头。","金杯浮蜡蚁春，红炭灸肥羊肉。","惜玉怜香天生就，另一种可喜风流。","淹润惯熟，玲珑剔透，软款温柔。"]},{"t":"逞风流王焕百花亭・十二月","f":"曲","c":["则为我攀花折柳，致令的有国难投。","止望待天长地久，谁承望雨歇云收。","他为我胭僬粉瘦，我为他绿惨红愁。"]},{"t":"逞风流王焕百花亭・尧民歌","f":"曲","c":["呀！恰便似一江春水向东流，谁想俺锦鸳鸯翻做了浪中鸥。","只落得十分人带九分愁，(云)我想贺姐姐原与小生恩爱深厚，今日又嫁了高将军。","(唱)正是一家儿女百家求。","休也波休！也是官差不自由，泪拚湿春衫袖。"]},{"t":"逞风流王焕百花亭・快活三","f":"曲","c":["这书词是亲手修，重新把密情兜。","也不枉我虚名赢的上青楼，早展放蚁眉皱。","(做拜科，云)我试拜告天地咱。","(唱)。"]},{"t":"逞风流王焕百花亭・鲍老催","f":"曲","c":["我这里展脚舒崾忙顿首，引的我口角顽涎溜。","我只道姻缘簿消除-笔勾。","又谁知今日还能够。","这书词则是纸摄人魂的下贴，摘人心的公案，追人命的勾头。","(王小二云)官人，你愁除病减，都在这封书上，早则喜也。","(正未唱)再休题愁除病减，花成蜜就，叶落归秋。"]},{"t":"逞风流王焕百花亭・耍孩儿","f":"曲","c":["我便似被困围的败将专求救，哎，高君也咱两个棋逢对。","也不索推轮捧毂，筑坛台专仗你那妙策神谋。","则你是添兵减灶齐孙膑，唤雨呼风蜀武侯，将巧计亲传授。","这一番若得贺氏逢上焕，便似织女址牵牛。"]},{"t":"逞风流王焕百花亭・随尾煞","f":"曲","c":["皂头巾著额颅，斑竹篮提在手，叫歌声习演的腔儿溜。","新得了个查梨条除授，则这的是郎村爱女下场头。","(同下)。"]},{"t":"逞风流王焕百花亭・商调/集贤宾","f":"曲","c":["若论妆孤苦表俺端的夺了第一，(带云)说起风流王焕四个字呵。","(唱)这洛阳郡有谁知？较文呵有贾马班扬藻思，较武呵有孙吴管乐神机。","王焕也空学的文武双全，培养得材能兼备。","指望待整乾坤定江山安社稷，辅皇家救困扶危，似恁的名标莺燕集，几时勾身到凤凰池？。"]},{"t":"逞风流王焕百花亭・挂金索","f":"曲","c":["松阳柿全别，滋润能清肺。","婺州枣为魁，细嚼堪平胃。","嘉庆子家风，制度实奇美。","枝头干流传，可口真佳味。"]},{"t":"逞风流王焕百花亭・山坡羊","f":"曲","c":["梨条清致，金橘无对，荔枝圆眼多浇些蜜。","这枣子要你早聚会，这梨条休着俺抛离。","这柿饼要你事事都完备，这嘉庆这场嘉乐喜。","荔枝，离也全在你，圆眼，圆也全在你。"]},{"t":"逞风流王焕百花亭・梧叶儿","f":"曲","c":["俺只见舍利塔侵云汉，罗汉堂煞整齐，人静悄景幽微。","那孙飞虎声名大，小红娘识见低，闪的我张君瑞自惊疑，天也知他这普救寺莺莺在那里？(盼儿云)俺姐姐着我在这门首等着俺姐夫，怎么这早晚还不见来？(正末做见科，云)梅香姐，我来了也！(盼儿云)姐夫，你怎么这般模样了也？这是甚么打扮那？(正末唱)。"]},{"t":"逞风流王焕百花亭・后庭花","f":"曲","c":["熬煎的你愁似织，想念着我意似痴。","因此上酝酿就蜂儿蜜，调和成燕子泥。","费心机，恨不的钻天掘地。","则图个得见你，生这般穷智识，做这般贼所为，妆这般乔样式。"]},{"t":"逞风流王焕百花亭・双雁儿","f":"曲","c":["王焕也到如今犹兀自说兵机，得道也，夸经纪，东行不见西行利。","为风月，担是非，惹英雄皆笑耻。"]},{"t":"逞风流王焕百花亭・青哥儿","f":"曲","c":["有一日功成、功成名遂，那时节耀武、耀武扬威。","云路鹏程九万里，气吐虹霓，志逞风雷。","宫花飘曳，御酒淋漓。","我不是斗筲之器，粪土这泥。","则恐怕等闲间泄漏了春消息，因此上用脱壳金蝉计。"]},{"t":"逞风流王焕百花亭・酣葫芦","f":"曲","c":["姐姐你烦恼除我知，我烦恼除你知。","再休说坐儿不觉立儿饥，常言道海深须见底。","各办着个真心实意，这的是有情谁怕隔年期。"]},{"t":"逞风流王焕百花亭・金菊香","f":"曲","c":["唬的我手忙脚乱紧收拾，意急心慌没整理。","(高净云)甚么人在此？好无礼也。","(正末唱)可正是船到江心补漏迟，只着我魄散魂飞，(做叫科，云)查梨条卖也！查梨条卖也！(唱)我则索向前来陪着笑卖查梨。"]},{"t":"逞风流王焕百花亭・醋葫芦","f":"曲","c":["俺也是文齐福不齐，你正是官不威牙爪威。","(高净云)兀那厮，敢来俺这里胡厮哄！(祗从喝科)(正末唱)只听的一声高叫若轰雷，(旦做慌科)(正末唱)唬的那黄莺儿怎敢向上林啼。","抵多少惊回绿窗春睡早，难道爱月夜眠迟。"]},{"t":"逞风流王焕百花亭・金菊香","f":"曲","c":["凭着俺驱兵领将万人敌，稳情取一举成名天下知。","俺怎肯做男儿有身空七尺，任他人夺去娇妻，将比翼两分飞。"]},{"t":"逞风流王焕百花亭・醋葫芦","f":"曲","c":["这逆贼，好没礼。","盗军资误军务失军期，他所犯那桩儿不是有条划的罪？还待向婆娘行孝当竭力，则著他得便宜翻做了落便宜。"]},{"t":"逞风流王焕百花亭・浪里来煞","f":"曲","c":["则今朝别了玉人，多感承谢了盘费。","(旦云)解元，你也姓王，那王魁也姓王，则愿你休似王魁，负了桂英者。","(正末做悲科，唱)怎将我正焕比做王魁？我向西延边上建功为了宰职。","你管取那五花诰夫人名位，则不要你个桂英化做一块望夫石。","(同下)。"]},{"t":"逞风流王焕百花亭・双调/新水令","f":"曲","c":["起蛰龙吐云雾上天时，下河西第一阵节使。","威风驰海外，名誉播京师。","端的个男儿，不枉了四方志。"]},{"t":"逞风流王焕百花亭・驻马听","f":"曲","c":["引领群师，罚其罪赏其功无徇私。","募招猛士，攻必取战必胜决雄雌。","常拚著马革里残尸，生图他麟阁题名字。","不信呵观古史，大都来豪杰皆如是。"]},{"t":"逞风流王焕百花亭・得胜令","f":"曲","c":["笑孙武少神思，病白起不仁慈。","赛韩信十功立，胜孔明八阵施。","无半点瑕疵，展万里鲲鹏翅。","真一表英姿，建千年龙虎祠。"]},{"t":"逞风流王焕百花亭・风人松","f":"曲","c":["高常彬差使洛阳时，有多少过犯公私。","克军需盗把官钱使，恋烟花艳质娇姿。","强夺人他妻我妇，成就他燕子莺儿。"]},{"t":"逞风流王焕百花亭・乔牌儿","f":"曲","c":["这厮逞权豪忒放肆，不想正遇著敌头至。","(高净云)节使休怪，我实是不知误娶了他。","(正末唱)自待闻钟始觉山藏寺，(经略云)军政司，与我查那高邈所犯，当得何罪？(正末云)他盗使官钱，失误军期，强娶有夫之妇为妻，那一桩儿不是该死的？(唱)贼也，这的是罪当刑无怨死。"]},{"t":"逞风流王焕百花亭・水仙子","f":"曲","c":["你可待碧梧栖老凤凰枝，谁承望东岳新添速报司。","早则西风了却黄花事，今日个雪消也见死尸，祸临头有甚嗟咨。","使不的你论黄数黑，遮个的你夺朱恶紫，快招成罪犯无辞。"]},{"t":"逞风流王焕百花亭・殿前欢","f":"曲","c":["这的是证明师，决撒了也春风骄马五陵儿。","可不道不知命无以为君子，则索退而自省其私。","(高净做叫屈科，云)这妇人明明是我娶到的媳妇哩，怎当他官官相为，强断与王节使去，可不冤屈也！(正末云)噤声！(唱)这里是经略府军政司，又不比风月所莺花市。","错认做洛阳地面承天寺，花费了些精银饷钞，收买些腻粉胭脂。"]},{"t":"逞风流王焕百花亭・鸳鸯尾煞","f":"曲","c":["从今后美恩情一似调琴瑟，泼生涯再不窥构肆。","共立琼筵，满酌金卮，唱道是绝胜新婚，休夸燕尔，咱两个喜气孜孜。","这眷爱如天赐，也不枉费尽相思，早证果了卖查梨那风流少年子。"]},{"t":"冯玉兰夜月泣江舟・仙吕/点绛唇","f":"曲","c":["则见那马足车尘，往来无尽。","频询问，何处前津。","可兀的日远长安近。"]},{"t":"冯玉兰夜月泣江舟・混江龙","f":"曲","c":["你把那行装整顿，无过是一琴一鹤紧随身。","我是个闺中少女，更和这堂上慈亲。","着甚的家使奴先教开道路，也只为俺女孩儿不惯出房门。","你一行行一步步休得辞劳困。"]},{"t":"冯玉兰夜月泣江舟・油葫芦","f":"曲","c":["休那里说短论长语话频，(家童云)您每坐着车儿，自自在在的，我从五更鼓起来，打点行李，走了这半日，你便不知饥，我可肚里饥哩。","(正旦唱)我须是有量忖，又没个村庄道店好安存。","只我这各书达礼当恭谨，怎肯着出乖露丑遭谈论。","他那里苦厮缠，好教我越怒嗔。","我巴不得两三朝飞到泉州郡，可甚的沿路只逡巡。"]},{"t":"冯玉兰夜月泣江舟・那叱令","f":"曲","c":["俺父亲呵待明朝早晨，便拜辞也禁门；待明朝早晨，便到来也水滨；待明朝早晨，便开船也动身。","淅零零风乍生，白茫茫波流紧，看一派江景凄人。"]},{"t":"冯玉兰夜月泣江舟・鹊踏枝","f":"曲","c":["恰才个日斜曛，可又早月黄昏，则见那渔火孤村，罢网收纶。","掩篷窗且捱过了今宵时分，不觉的困腾腾越减精神。"]},{"t":"冯玉兰夜月泣江舟・青哥儿","f":"曲","c":["呀，则见他忙将、忙将兵刃，可教我怎生、怎生逃遁？你若是留得我残生过几春。","我可也答报你深恩，敬似俺严亲。","奉侍晨昏，不避辛勤。","衣进时新，食献奇珍。","情愿与你做孩儿左右不离身，甘承认。"]},{"t":"冯玉兰夜月泣江舟・赚煞","f":"曲","c":["百般的盼不到晓鸡鸣，强搭伙这鲛绡盹。","水声儿偏傍着孤舟滚滚，怕流不尽俺心头忄敝忄敝的闷。","猛想起梦儿中遇见强人，尚销魂，带着满面啼痕，休道睡眼蒙胧不是真。","(内做鸡叫科)(带云)可早天明了也。","(唱)渐见晨光隐隐，(家童上，云)天明了也，叫梢公早些开船，叠在官厅傍边，恐怕老爷将次来也。","(正旦唱)移到这官厅侧近，(带云)只等俺父亲来呵，(唱)去向成都肆里访着那个卜钱人。","(下)。"]},{"t":"冯玉兰夜月泣江舟・正官/端正好","f":"曲","c":["恰开船抬头觑，早行了数里程途。","只为一帆风肯把行人助，来到这渺渺烟霞处。"]},{"t":"冯玉兰夜月泣江舟・滚绣球","f":"曲","c":["芦花岸如雪堆，蓼花滩似锦铺，野鸥闲自来自去，彩云轻时卷时舒。","帆影儿荡碧波，橹声儿过绿浦，恰便是走马般不停不住，见白茫茫远接天隅。","烟光半向江心敛，树色全从水面浮，江景也模糊。"]},{"t":"冯玉兰夜月泣江舟・倘秀才","f":"曲","c":["我这里款款的掐春葱来细数，何日见泉州景物？(冯太守云)孩儿也，那泉州府终有到的日子哩。","(正旦唱)经了些风雨声中听鹧鸪。","(梢公云)远远望见前面，那一片大水，就是大江了也。","(冯太守云)兀那梢公，且慢慢的行者。","是好大水也。","(正旦云)父亲、母亲，你看水连着天，天连着水。","(唱)你看那水大连四野，莫是洞庭湖？(冯太守云)孩儿，这是大江，不是洞庭湖。","(正旦云)父亲，着船家将这船，略住一住儿咱。","(唱)且将这船来缆住。"]},{"t":"冯玉兰夜月泣江舟・滚绣球","f":"曲","c":["我只道渚烟生逐好风，却原来海潮回催暮雨。","动乡愁暗伤情绪，(夫人云)小姐，俺几曾见这般大江水也！(正旦唱)都则为俺家尊受职迁除。","(冯太守云)孩儿，若不是我为泉州太守呵，你子母儿一世也到不的此处。","(正旦唱)若不是逐功名如转蓬，怎能勾对江山似画图？看东溟渐升玉免，早西山坠尽金乌。","见渔家灯火明还灭，听野寺钟声断又续，此景非俗。"]},{"t":"冯玉兰夜月泣江舟・呆骨朵","f":"曲","c":["我见他假醺醺上下将娘亲觑。","不由我战钦钦魄散魂无。","(屠世雄云)左右，与我唤将那心腹的人来，我有事分付他。","(卒子云)理会的。","(做唤科，云)兀那船上的小军儿，屠爷唤你哩。","(卒子持枪刀土，云)家将都来了也。","(正旦惊科，唱)忽听的大叫高呼，摆列下长枪的这巨斧。","(屠世雄云)小校，将我的兵器来！(卒子递刀科)(屠世雄做接刀科，云)口退！兀那冯太守，你认的我么？(冯太守云)呀，大人，老夫怎生不认的你？(夫人云)不中，俺索回避者。","(屠世雄拦科，云)你那里去？众军校，与我围住这船者！(正旦唱)一个个挺霜锋相拦截，(带云)母亲，怎不回避咱？(众喝科，云)那里去？(正旦唱)好着我无处个寻门路。","(屠世雄云)你趁早儿随顺了我者。","(冯太守云)你要老夫随顺甚么来？(正旦云)父亲，原是你差了也。","(唱)都是你没来由揽祸灾。","(屠世雄云)休教走了一个！(正旦云)哎，父亲也，(唱)到如今急煎煎怎当堵？。"]},{"t":"冯玉兰夜月泣江舟・伴读书","f":"曲","c":["今日个子共母应难顾，夫共妇生离去。","奸教我负屈衔冤无申诉。","只有个椎天抢地号啕哭。","(屠世雄喝科，云)口退！兀那女孩儿，哭甚的来，你看我这刀么？(正旦唱)倒惹他努睛突眼生嗔怒，一谜的将俺奔呼。"]},{"t":"冯玉兰夜月泣江舟・煞尾","f":"曲","c":["怎又刮起这大风，把俺船吹去，又不知吹去何方，可着的个边际无。","眼睁睁放着娘亲被他掳，痛煞煞把俺兄弟爹爹都杀取，刚只一个家僮不留与。","兀那驾船的梢公和你有甚毒，也着他跟了俺一家儿入地府。","待叫来又被气堵住咽喉叫不出苦，待走来又被船打在江心走不上路。","却教俺守着这血泊里尸骸怎发付？哎哟！天那！你也可怜见俺个没倚靠的青春少年女！(下)。"]},{"t":"冯玉兰夜月泣江舟・商调/集贤宾","f":"曲","c":["正沧江夜寒明月皎，觑地远叩天遥。","这船呵在风中簸荡任东西，水上浮漂。","又无人把舵推篷，那里也举棹撑篙。","我则听的古都都泼天也似怒涛，斗合着忽剌刺风声儿厮闹。","这水也流不尽俺千端愁思积，这风也抵不过俺一片哭声高。","(带云)父亲和兄弟，你都死的好苦也！(唱)。"]},{"t":"冯玉兰夜月泣江舟・逍遥乐","f":"曲","c":["俺也几番价把爹爹连叫，只见他七魄悠然，三魂去杏。","(做哭科，云)痛杀我也！父亲、兄弟也，(唱)好着我独自嚎啕，这杀人恨何日才消？怎得个清耿耿的官员斯撞着，劈头儿把冤情披告。","告他将父亲杀死，兄弟亏图。","娘亲来占了。"]},{"t":"冯玉兰夜月泣江舟・金菊香","f":"曲","c":["我这里低头不语眼偷瞧，(金御史云)兀的不是有人说话也！","(正旦唱)呀，小可如昨夜停舟那一遭，莫不是狠贼徒把咱寻见了？","你直待要断尽根苗，俺的命恁般薄。"]},{"t":"冯玉兰夜月泣江舟・醋葫芦","f":"曲","c":["则听的叮咛频问取，(金御史云)你是那家妻小，因何在此？(正旦唱)我是那闺门中女艳娇。","(金御史云)原来还是个未嫁的女孩儿。","你说，你说。","(正旦唱)俺父亲是泉州太守恰离朝，(金御史云)泉州太守恰离朝，是到任去么？(正旦唱)不堤防半途逢祸恶。","(金御史云)哦，敢是被甚么强盗劫杀了。","你家里还有人么？(正旦唱)俺母亲被他驱掠，自使掩一家的两相抛。"]},{"t":"冯玉兰夜月泣江舟・金菊香","f":"曲","c":["你道是除冤理枉的久官僚，你与我那屈死的亲爷将冤恨削。","不承望这搭儿卫偏凑巧，这一个天理昭昭，谁想道有今朝！。"]},{"t":"冯玉兰夜月泣江舟・幺篇","f":"曲","c":["则这个年迈的是父亲，(金御史云)又有个小孩儿可是谁？(正旦唱)可怜呵俺弟兄年纪小。","(金御史云)那小孩儿原来是你兄弟，可怜！可怜！那个女人是谁？(正旦唱)他是俺梅香小字唤春娇，(金御史云)还有三个男子是谁？(正旦唱)俺家童未将人事晓。","(金御史云)是了，那两个呢？(正旦唱)那两个是船家将钱觅到，也都在劫数里不能逃。"]},{"t":"冯玉兰夜月泣江舟・梧叶儿","f":"曲","c":["这江洋真贼盗，怎当俺众冤魂缠定着。","他犯了杀人条，现放着大质照，刀头儿血染高。","请大人自量度，若不沙只俺小妮子敢平空的将命讨！(金御史云)天明了也。","老夫体察公事，一夜不曾睡。","左右，分付开了船者，径到清江浦官厅边湾船，问理这一桩公事也。","(祗候云)理会的。","梢子快开船哩。","(梢公云)知道了，慢慢的来。","牌子，昨晚那个女孩儿在那里？(祗候云)在舱里。","你要问他怎的？(梢公云)和老爷说一声，赏一与我做媳妇罢。","(祗候云)噤声！是官宦人家的小姐，如今带着他要办理人命公事哩。","你则开了船者！(梢公做使船跌倒科)(金御史云)兀那女子，你跟我到清江浦，问理公事去来。","(正旦云)俺到的那里，怎生能见那贼汉也？(金御史云)你却不知。","但是巡江官，少不的要来参见老夫。","(正旦唱)。"]},{"t":"冯玉兰夜月泣江舟・浪里来煞","f":"曲","c":["我见他怎恕饶，他见我难推调。","怕不来一问一承招，只俺那山海般仇恨须当报。","再不用荆条细拷，拚的亲手儿也还上一千刀！(同下)。"]},{"t":"冯玉兰夜月泣江舟・双调/新水令","f":"曲","c":["急忙忙盼不到接官厅，那一个杀人贼今番拿定。","休道那人间无报应，方信是头上有神明。","我看他着甚推称，只俺这大人呵清似水朗如镜。"]},{"t":"冯玉兰夜月泣江舟・驻马听","f":"曲","c":["暗自凝睛，不由我不丧胆销魂忽地惊。","(金御史云)兀那女子，你怕他怎的？(正旦唱)浑如痴挣，他是个图财致命杀人的精。","(金御史云)左右，把那厮与我打着者！(祗候做打科)(正旦唱)这番推勘见分明，则你那夜来凶恶可也还侥幸。","眼见的恶贯盈，今朝对了俺亲爷命。"]},{"t":"冯玉兰夜月泣江舟・乔牌儿","f":"曲","c":["你将俺一家儿性命倾，又抢了俺母亲呵忒施逞。","(云)大人可怜见，须索追出俺母亲来。","(屠世雄云)我屠世雄并不曾抢他母亲。","(正旦唱)眼睁睁现放着俺亲身证，(金御史云)屠世雄，你不实说呵，等甚么那？(正旦唱)还待要嘴巴巴不肯应。","(金御史云)这厮坚意的不肯认来，我想他抢着去，必然就藏在他船上。","左右，领着这冯小姐。","直到他船上高声的叫他，那为母的听见，是他那女孩儿声音，必然答应。","你可小心在意，疾去早来！(祗候云)理会的。","小姐，我和你到他船上寻你母亲去来。","(正旦云)祗候哥哥，他的船只知他在那里也？(祗候云)他这巡江官的船只，都在那壁厢湾着哩。","你如今只沿岸边叫你那母亲咱。","(正旦同祗候至船边叫科，云)偌多的船只，着我那里寻去也？母亲！母亲！(唱)。"]},{"t":"冯玉兰夜月泣江舟・雁儿落","f":"曲","c":["我这里连声不住声，(带云)母亲！母亲！(唱)可怎生应也无人应？(带云)母亲！母亲！(夫人上，哭云)这是我玉兰孩儿的声气，待我叫他着。","玉兰儿也，我在这里。","(正旦唱)是那个贼船中叫小名，恰便似军帐里听严令。"]},{"t":"冯玉兰夜月泣江舟・得胜令","f":"曲","c":["呀，今日个相遇在江亭，莫非是死去再问生？(祗候云)兀那小姐走动，老爷等着哩。","(正旦唱)与俺这母亲重觌面。","怎么俺兄弟爹爹也不见影？(云)母亲，那屠世雄拿了也。","(夫人云)他如今在那里？只怕问不倒他，终着他手。","(正旦云)母亲。","我和你同见大人去来。","(唱)现如今审出了真情，那怕这逆贼偏头硬。","疾忙的前行，只怕那清官专意等。","(做见御史跪科，云)大人，则这个是俺母亲。","(金御史云)兀那女子，这个是你母亲么？(正旦云)正是。","(金御史云)在那里寻着来？(祗侯云)禀爷。","在屠世雄船上寻来的。","(正旦云)兀那贼汉，你道是不曾抢俺母亲，如今在那个船上藏着哩？(唱)。"]},{"t":"冯玉兰夜月泣江舟・侧砖儿","f":"曲","c":["你道我平白地把你来、把你来供攀定，只我这官司里世不曾经。","俺冯家的娘亲怎倒着你屠家领，你也自思省。"]},{"t":"冯玉兰夜月泣江舟・竹枝哥","f":"曲","c":["你倚着那巡江的威风敢横行，恶哏哏便待生迪俺娘亲为为匹聘。","兀的不是把河桥的孙飞虎抢莺莺。","今日个大人呵做了白马将，我玉兰呵倒做了惠明僧。","贼精，看你去那里逃生？。"]},{"t":"冯玉兰夜月泣江舟・水仙子","f":"曲","c":["今门个从头一一尽招承，国法王条不顺情。","也显的你有忠直儿偏佞，赤心的将公事整，端的个播清风万载标名。","若不是你金大人势剑铜铡，将贼徒分腰断颈，可不干着俺泣江舟这一段冤情。","(金御史云)你一行人听老夫下断！(词云)都则为你父亲除授泉州，黄芦荡暮夜停舟。","巡江官相邀共饮，出妻子礼意绸缪。","你母亲遭驱被掳，全家儿惹祸招忧。","单撇下钢刀一口，积尸骸鲜血交流。","老夫奉朝命江南巡抚，路途间访出情由。","将贼徒问成死罪，登时决不待深秋。","冯小姐虽能雪恨，奈余生无管无收。","请夫人同车载去，赴京都择配公侯。","这的是金御史秋霜飞白简，才结末了冯玉兰夜月泣江舟。"]},{"t":"孟德耀举案齐眉・仙吕/点绛唇","f":"曲","c":["你看这春满皇都，落花无数，飘香雨。","蝶翅蜂须，犹兀自留春住。"]},{"t":"孟德耀举案齐眉・混江龙","f":"曲","c":["恰离了兰堂深处，倩东风扶策我这困身躯。","懒设设梳云掠月，意迟迟傅粉施朱。","你道是春睡不禁啼鸟唤，我则待日长偷看古人书。","(梅香云)老相公唤哩，你也梳妆打扮些儿波！(正旦唱)我这里荡香尘忙把扇儿遮，踏残红软衬着鞋儿去。","再提掇绮罗衣袂，重整顿珠翠冠梳。"]},{"t":"孟德耀举案齐眉・油葫芦","f":"曲","c":["这须是五百年前天对付，(梅香云)这也只凭你自家主意，有甚么天缘在那里？(正旦唱)怎教咱自做主？(云)这三人里面，(唱)除梁鸿都是些小人儒，(梅香云)小姐，你差了也，这梁鸿穷的怕人子哩！(正旦唱)你道他现贫穷合受贫穷苦，他有文章怕没文章福？(梅香云)那文章是肚里的东西，你怎么就看的出？(正旦唱)常言道贤者自贤，愚者自愚。","就似那薰莸般各别难同处，怎比你有眼却无珠？(梅香云)世间多少穷秀才，穷了这一世，不能发迹！你要嫁他，好不颓气也！(正旦唱)。"]},{"t":"孟德耀举案齐眉・天下乐","f":"曲","c":["哎，屈沉杀三尺龙泉万卷书，何也波如？","非浪语，便道是秀才每秀而不实有矣夫！","想皇天既与他十分才，也注还他一分禄，包的个上青云平步取。"]},{"t":"孟德耀举案齐眉・村里迓鼓","f":"曲","c":["咱为人且贫且富，为官的一荣一辱。","(孟云)做官的有甚么辱来？(正旦唱)他请的是皇家俸禄，又科敛军民钱物。","直等待削了官职，卖了田地，散了奴仆，那时节方悔道不知止足。"]},{"t":"孟德耀举案齐眉・元和令","f":"曲","c":["你道他一介儒，消不的千钟粟。","料应来尽世里困穷途，嫁他时空受苦。","有一日万言长策献銮舆，才信他是真丈夫。"]},{"t":"孟德耀举案齐眉・上马娇","f":"曲","c":["这的是时命乖，非是他文学疏。","须知道天不负诗书。","则看渭水边吕望将文王遇，哎，怎笑的霜雪也白头颅？。"]},{"t":"孟德耀举案齐眉・胜葫芦","f":"曲","c":["这都是荫庇骄奢泼赖徒，打扮出谎规模，睁眼苫眉捻鬓须。","带包巾一顶，系环绦一付，怎知他不识字一丁无！。"]},{"t":"孟德耀举案齐眉・幺篇","f":"曲","c":["哎，兀的是豹子峨冠士大夫，何必更称誉？也非我女孩儿在爷娘行敢抵触。","富时节将亲偏许，贫时节把亲偏阻，可不道君子断其初！(孟云)这妮子既然要嫁梁鸿，我如今只问他要两件宝贝，有便嫁他。","(正旦云)父亲，可是那两件宝贝？(孟云)我要那带秋色羊脂玉，赛明月照夜珠。","(正旦唱)。"]},{"t":"孟德耀举案齐眉・后庭花","f":"曲","c":["他是个守青毡一腐儒，捱黄齑忍饿夫，那里取带秋色羊脂玉、赛明月照夜珠？父亲阿你坏风俗，枉了你清廉名目。","你断别人家不是处，下财钱要等足，少分文不放出，敢如何违法度？(孟云)可不道在家从父那？(正旦唱)。"]},{"t":"孟德耀举案齐眉・柳叶儿","f":"曲","c":["我如今在家从父，枉教那穷书生一世孤独。","他家寒冷落无他物，每日沿门儿题诗句。","投至的攒下些须，(带云)父亲，你则想波。","(唱)那秀才少不的搜索尽者也之乎。"]},{"t":"孟德耀举案齐眉・赚煞","f":"曲","c":["他富则富，富不中我志诚心；这秀才穷则穷，穷不辱我姻缘簿。","我若是合快乐不遭受苦，若是我合受苦强寻一个荣贵处，也只怕无福消除。","教人道这乔男女，则是些牛马襟裾，(孟云)孩儿也，有钱的好。","(正旦唱)父亲你原来不敬书生敬财主。","我又不曾临邛县驾车，他义不曾升仙桥题柱，早学那卓文君拟定嫁相如！(同梅香下)。"]},{"t":"孟德耀举案齐眉・正宫/端正好","f":"曲","c":["又不是卓文君抚琴悲，又不是秦弄玉吹箫恨，为甚些家务事晓夜伤神。","则为俺不峥嵘女婿相招进，可着我怎打叠闲愁闷。","(云)我也听的有人说我哩。","(梅香云)说小姐甚的来？(正旦唱)。"]},{"t":"孟德耀举案齐眉・滚绣球","f":"曲","c":["人都道孟德耀有议论，梁秀才甚气愤。","这其间又不是女孩儿暗传芳讯，父亲呵，你瞒人怎瞒过空里灵神？道当初许了的亲，他不曾来谢肯，因此上无主意的爹娘失信。","依着他则待要别选高门，依着我宁可乱铺着云鬓为贫妇，怎肯巧画蛾眉别嫁人，燕尔新婚？。"]},{"t":"孟德耀举案齐眉・笑歌赏","f":"曲","c":["莫不是老嬷嬷欠供待的勤？莫不是小梅香有些的言词蠢？莫不是太夫人不曾与你相通问？莫不是妾身行做甚的多回避？莫不是老相公近新来有甚么别处分？你、你、你，只管里这等不邓邓含嗔忿。","(梁鸿背叹科，云)早知如此挂人心，悔不当初莫相识。","(正旦唱)。"]},{"t":"孟德耀举案齐眉・醉春风","f":"曲","c":["你悔则悔咱须是百年恩，你恼则恼咱须是两意肯。","又不曾强逼你结了婚姻，我当初将你来尽，尽。","又不留五载十年，止不过三朝两门，便恁般万愁千恨！。"]},{"t":"孟德耀举案齐眉・石榴花","f":"曲","c":["往常时画堂娇惯数年春，锦绣四时新，凌波罗袜不生尘。","(梅香云)小姐，这是个甚么打扮？你当初嫁那富贵的，可不好来？(正旦唱)暗想着当初二人调弄精神，他指望官员、财主咱须顺，岂知我甘心的则嫁寒门。","(梁鸿云)似小生这等衣衫褴褛，只怕你也心困哩。","(正旦唱)你是我亲男儿岂怨身贫困？(梁鸿云)小姐，你当初何不嫁那富贵的来？(正旦唱)我怎肯将颜色嫁他人？。"]},{"t":"孟德耀举案齐眉・斗鹌鹑","f":"曲","c":["重整顿布袄荆钗，收拾起娇红腻粉。","(梁鸿云)小生这几日好生伤感也。","(正旦唱)你道是往日堪怜，到今日更亲。","可不道一夜大妻百夜恩？我见你便忒认真。","须是在夫妇行殷勤，也要去爷娘行孝顺。","(孟暗上，云)隔墙须有耳，窗外岂无人？这小贱人无礼，瞒着老夫，引着梅香去书房中看梁鸿去了。","兀的不气杀老夫也。","我到那里就将他二人赶出去者。","(做见科，云)好大胆的小贱人也。","(正旦唱)。"]},{"t":"孟德耀举案齐眉・上小楼","f":"曲","c":["又不是挑牙料唇，只待要寻争觅衅。","(孟云)这小贱人辱没杀老夫也。","(正旦唱)我有甚的败坏风俗，羞辱爷娘，玷累家门？你将这赤的金，白的银，饕餮都尽，又道是女孩儿背槽抛粪。"]},{"t":"孟德耀举案齐眉・十二月","f":"曲","c":["父亲呵，你既然恁般发狠，怎教我不要半语支分？这秀才书读万卷，有一日笔扫千军。","他须是黄阁宰臣，休猜做白屋穷民。"]},{"t":"孟德耀举案齐眉・尧民歌","f":"曲","c":["你道是儒人今世不如人，只合齑盐岁月自甘贫。","直等待凤凰池上听丝纶，宫袍赐出绿罗新。","青也波云，男儿一致身，父亲呵，那些时你可便休来认。"]},{"t":"孟德耀举案齐眉・耍孩儿","f":"曲","c":["你看举头日远长安近，则把这读过的经书自温。","当今天子重贤臣，大开着海也似的贤门。","早遂了从龙从虎风云气，稳受些滋草滋花雨露恩。","这是咱逢时运，父亲呵，休错认做蚌鸣井底、鹤立鸡群。","(孟云)我观那梁鸿，则当是蓬蒿苹底尘土一般。","(正旦唱)。"]},{"t":"孟德耀举案齐眉・煞尾","f":"曲","c":["你看他是蓬蒿草底尘，我觑他是麒麟阁上人。","(云)则今日辞别了父亲出去，久以后不发迹，也不见父亲之面了。","(唱)须有日御帘前高捧三台印。","都省里安身正一品。","(同下)。"]},{"t":"孟德耀举案齐眉・越调/斗鹌鹑","f":"曲","c":["我本生长在仕女图中，到今日权充在佣工队里。","刚备下布袄荆钗，又加着这一副苕帚簸箕。","(梁鸿云)当初你不嫁我，可不好也。","(正旦云)我嫁你也不为别。","(唱)则为你书剑功能，因此卜甘受这糟糠气息。","我避不的人笑耻，人是非。","(梁鸿云)你看咱住的这房舍么。","(正旦唱)住的是灰不答的茅团，铺的是干忽剌的苇席。"]},{"t":"孟德耀举案齐眉・金蕉叶","f":"曲","c":["你道他有甚的高官重职，也须要承欢奉喜。","虽不曾夫贵妻荣，我只知是男尊女卑。","(嬷嬷云)我看梁官人也是三十以外的人了，还是这般模样。","几时能勾发迹也？(正旦唱)。"]},{"t":"孟德耀举案齐眉・调笑令","f":"曲","c":["你道他发迹已无期，眼睁睁早虚过了三四十。","(嬷嬷云)量他打甚不紧？(正旦唱)你道他根前还讲甚尊卑礼，常言道是夫唱妇随。","为甚那男儿死了咱挂孝衣？这消不的我举案齐眉。"]},{"t":"孟德耀举案齐眉・秃厮儿","f":"曲","c":["你道他无聪明智慧，折莫他便鲁坌愚痴，常言道嫁的鸡儿则索一处飞，与梁鸿既为妻，也波相宜。"]},{"t":"孟德耀举案齐眉・圣药王","f":"曲","c":["折莫他从早起，到晚夕，不得口安闲饭食与充饥。","虽然是运不齐，他可也志不灰。","只等待桃花浪暖蛰龙飞，平地一声雷。"]},{"t":"孟德耀举案齐眉・鬼三台","f":"曲","c":["咱与你甚班辈？自来不相会，走将来磕牙料嘴。","(张云)兄弟，你看这女人，他这般受苦，倒说咱磕牙料嘴。","(正旦唱)陪着笑卖查梨，(马云)小姐，你嫁了我时，比别人不强多着哩？(正旦唱)调弄他舌巧门疾。","这厮村的来恁般村性格，俺穷则穷不曾折了志气！(张云)小姐，你当初嫁了俺呀，可不好那？(正旦唱)只管里故意干乔，(张做扯正旦衣服科，云)小姐，向前来，我和你说一句话儿咱。","(正旦推科，唱)去波，你歪缠些怎的！。"]},{"t":"孟德耀举案齐眉・麻郎儿","f":"曲","c":["我穷则穷是秀才的妻室，你穷则穷是府尹的门楣。","那些儿输与这两个泼皮，白白的可干受了一场恶气！。"]},{"t":"孟德耀举案齐眉・幺篇","f":"曲","c":["想起就里事体，(带云)我待和他计较来。","(唱)与这嘶争甚么闲是闲非。","(带云)我待不计较来。","(唱)我又做不的那没羞没耻。","哎哟天呵，怎生家博得个一科一第！。"]},{"t":"孟德耀举案齐眉・络丝娘","f":"曲","c":["但得你旨赍发到皇都帝里，我怎敢便忘了你这深恩大德？","自将你一倍加增做十倍，也还表不的我相酬之意。"]},{"t":"孟德耀举案齐眉・收尾","f":"曲","c":["只愿的丹墀早把千言对，施展你男儿壮气。","休得要做了无名金榜不回归，空教我斜倚定柴门盼望着你。","(下)。"]},{"t":"孟德耀举案齐眉・双调/新水令","f":"曲","c":["疑怪这叫喳喳义鹊噪花梢，却元来得除授状元来到。","若不是萤窗义史足。","怎能勾虎榜姓名际？谁想今朝，天开眼自然报。"]},{"t":"孟德耀举案齐眉・沉醉东风","f":"曲","c":["我则见这一堆捧养的光闪闪金花紫诰。","那一壁捧着的齐臻臻珠翠鲛鱼肖。","(梁鸿云)夫人，今日才表的你有冰清玉洁之心也。","(正旦唱)你道是才表我冰清玉洁心，(粱鸿云)厮称你云锦花枝之貌。","(正旦唱)又道是厮称我云锦花枝貌。","我今日呵做夫人岂敢妆幺？(梁鸿云)夫人，请穿上者。","(正旦云)相公，我不敢穿，(梁鸿云)可是为何？(正旦唱)争奈我两次三番不待着，则怕不稳如荆钗布袄。"]},{"t":"孟德耀举案齐眉・庆宣和","f":"曲","c":["元来这象简乌纱出圣朝，若是没福的也难消。","只为俺读书人受过凄凉合荣耀，因此上把儒衣换了，换了。"]},{"t":"孟德耀举案齐眉・雁儿落","f":"曲","c":["他曾习读占圣学，枉惹的儒人笑。","今门个折将丹桂来，(梁鸿云)这厮你当初可道来。","(张云)小的不曾道甚么来。","(正旦唱)可不道俺则会打莲花落！。"]},{"t":"孟德耀举案齐眉・得胜令","f":"曲","c":["俺如今行处马头高，人面上逞英豪。","则俺那美玉十分俊，不似你花木瓜外看好。","哎，你个儿曹，谁着你行无道？(张云)夫人可怜见，这都是旧活。","休题也。","(正旦云)左右那里？(唱)准备着荆条，将他扣厅阶吃顿拷。"]},{"t":"孟德耀举案齐眉・乔牌儿","f":"曲","c":["往常时独自焦，到今日大家乐。","(带云)想在皋大公庄儿上呵。","(唱)那其间头扑面糠飞绕，今日个玉玲珑金凤翘。"]},{"t":"孟德耀举案齐眉・挂玉钩","f":"曲","c":["这的是举案齐眉有下梢，(嬷嬷云)小姐，你如今还守着旧时的节操哩？(正旦唱)你道我不改初时操。","我从来贫不忧愁富不骄，怎肯败坏了闺门教？(云)嬷嬷请上，受我夫妻一拜。","(唱)你昔日恩，今朝报。","不是你拨散浮云，怎能勾得上青霄？(嬷嬷云)小姐稳重，有老相公同老夫人在于门首，你接待他去咱。","(正旦云)我有甚么老相公、老夫人，今日要来认我？(唱)。"]},{"t":"孟德耀举案齐眉・折桂令","f":"曲","c":["却元来晏平仲善与人交，(梁鸿云)这本是嬷嬷赍发俺来。","(正旦唱)难道他掩耳偷铃，则待要见世生苗？(云)相公，认了丈人丈母罢。","(唱)俺和你夫妇商量，休教外人把俺评跋。","你是个君子人个念旧恶，想一双哀哀的父母劬劳。","他虽然不采分毫，我如今怎敢轻薄。","(云)父亲、母亲请上，孩儿则认便了也。","(唱)且只索做小伏低，从今后啡爹爹权把俺耽饶。"]},{"t":"孟德耀举案齐眉・鸳鸯煞","f":"曲","c":["荷君恩特降黄麻沼，谢天臣远践红尘道。","却教我一介书生，早做了极品随朝。","畅道顿首诚惶，瞻天拜表，则俺这犬马微劳，知甚日能图效。","且自快活逍遥，两口儿夫妻共谐老。"]},{"t":"都孔目风雨还牢末・仙吕/赏花时","f":"曲","c":["每日衙中案事勤，无事街头饮数巡。","与妻子作生辰，更和着这几个弟兄识认，把一杯酒同乐太平春。","(同下)。"]},{"t":"都孔目风雨还牢末・仙吕/点绛唇","f":"曲","c":["刷卷才回，从头省会来家内。","大嫂又染病耽疾，空着我两下里难支对。"]},{"t":"都孔目风雨还牢末・混江龙","f":"曲","c":["则为这虚名薄利，生忧的鬓边白发故人稀。","孩儿又语言焦聒，大嫂又性命颠危。","都则为一二载烟花新眷爱，送了俺二十年儿女旧夫妻。","他与我生男长女。","立计成家。","如今便眼睁睁亲看见搂着别人睡，他便心肠似铁，怎不的怒气如雷。"]},{"t":"都孔目风雨还牢末・油葫芦","f":"曲","c":["俺家积趱下干柴籴下米，咱可便少甚的？(带云)大嫂。","这病若痊可了呵。","(唱)我可便谢天谢地谢神祗。","我不愿金玉重重贵，只愿的儿女年年会。","我这里自窨约，多半日。","更有城中房店田中地，我可便愁着不愁衣。"]},{"t":"都孔目风雨还牢末・那吒令","f":"曲","c":["你惩般病，也是自己害的；我但开口，便说顺着小的；他虽不中，你也不是个善的。","那婆娘重一斤，你十六两无偏坠，不由我冷笑微微。"]},{"t":"都孔目风雨还牢末・鹊踏枝","f":"曲","c":["你骂他泼东西，我心知。","您两个等秤称来，都一般轻重高低。","谁与你挑唇料嘴，辨别个谁是谁非？。"]},{"t":"都孔目风雨还牢末・寄生草","f":"曲","c":["哎，你个狠公吏休唱叫，(带云)刘唐靠前来，你看波(唱)俺家里有不快的。","(刘唐云)衙门中勾你哩。","(正末唱)为甚么苫眉努目闲淘气，你来我去无些礼，揎拳罗袖乔声势？适才个打门时叫的你嘴皮干，(带云)有一日到衙门中呵。","(唱)我敢粗棍子杵的你腰节碎！。"]},{"t":"都孔目风雨还牢末・醉中天","f":"曲","c":["那里有令史每结勾强贼理，如今世上媳妇论丈夫的稀！这金环也只在我家权顿寄，我应当吃不出首的官司罪。","他乱打拷教我招承个甚的？一壁厢官司又临逼。","我可甚家有贤妻！。"]},{"t":"都孔目风雨还牢末・后庭花","f":"曲","c":["告你个掌王法的党太尉，告你个葫芦提的包待制。","哎，你个有丈夫的萧行首，天也送了我的匾金环柳盗跖。","一杖起一层皮，畅好是腕头着力。","可正官不威牙爪威，直恁般有气势？打到有五六十，你休学俺做小的。","将普天下小妇每拘刷来，一搭里砧刀上剁做肉泥，大锅里熬做汁。"]},{"t":"都孔目风雨还牢末・青哥儿","f":"曲","c":["他则是一般、一般滋味，我吃了六问、六问三推，我如今手掴着胸膛悔后迟。","我当初凭着良媒取到我家里，换套儿穿衣，拣口儿吃食。","这婆娘饱病难医，把赃物收执，早报与官知，断送我头皮。","我劝你这一火良吏，再休把妓女娶为妻，则我是傍州例。"]},{"t":"都孔目风雨还牢末・离调/集贤宾","f":"曲","c":["想着俺二十年把笔将儒业学，(带云)兄弟，我为这妇人呵。","(唱)折倒了铜斗儿好窠巢。","怎承望浪包娄官司行出首，送的个李孔目坐禁囚牢。","岂不闻天网恢恢，也是我自受自作。","赤紧的有疼热大浑家亡过了，想俺那小冤家苦痛嚎啕。","我不合痴心娶妓女，倒将犯法罪名招。"]},{"t":"都孔目风雨还牢末・醋葫芦","f":"曲","c":["我恰才困腾腾盹睡着，牢门外谁唱叫？听多时认的语声高。","为甚两三番把兄弟厮定搅？多敢是小冤家来到，告兄弟休得怕勤劳。"]},{"t":"都孔目风雨还牢末・梧叶儿","f":"曲","c":["把孩儿相凌辱，折倒的黄瘦了，使不的你家富小儿骄。","头上虱如喷饭，我心中如刀搅。","把衣服扯得似纸提条，(带云)哎哟、僧住、赛娘儿也，(唱)这是儿女每没爷娘的下梢。"]},{"t":"都孔目风雨还牢末・后庭花","f":"曲","c":["你看我痛煞煞怎动摇？脊梁上粗棍子拷。","(刘唐云)这两个业种是那里来的？(正末唱)把僧住支杀的拖将去，连赛娘合扑的带了一交。","哥哥，你莫心焦，把往事从头还报。","白日里非草草，牢狱中闹吵吵。","将军柱钉头发梢，十字下滚肚索，紧邦邦匣定脚。"]},{"t":"都孔目风雨还牢末・双雁儿","f":"曲","c":["我可甚上床犹自想明朝，养小来，防备老。","不提防哥哥蓦来到，哥哥，你休躁暴，孩儿难打熬。"]},{"t":"都孔目风雨还牢末・柳叶儿","f":"曲","c":["这都是后尧婆凶恶，把孩儿打拷挝揉。","狠牢子又来添绳索，教我怎禁着！哎，你个女多娇，则被你断送我也地网天牢。"]},{"t":"都孔目风雨还牢末・浪里来煞","f":"曲","c":["我眼见的一命抛，也留不得三更到。","孩儿也，你则去街坊邻里宿今宵，赤紧的着疼热的亲娘亡化早。","害的人七颠八倒，天那！这都是我五行中恶限怎生逃。","(史进押末下)。"]},{"t":"都孔目风雨还牢末・沉醉东风","f":"曲","c":["又不是梦儿中精神惚恍，又不是身死后魂气悠扬。","又不是实丕丕地狱间，又不是席飘飘天堂上。","多咱在鬼门关被叫转还乡，待我手摸着心头暗酌量，毕竟个是真是慌？。"]},{"t":"都孔目风雨还牢末・胡十八","f":"曲","c":["是那个扳我脊梁？","是那个摸我胸膛？","是那个把头发水揪、胳膊来搪？","是那个喳喳的高叫在耳边厢？","原来是僧住和赛娘！","他救到有半响，也则为父子每情切切，因此上儿女每意慌慌。"]},{"t":"都孔目风雨还牢末・乔牌儿","f":"曲","c":["这几时在那方？","怎不见频来往？","莫不是晨昏茶饭无人掌？","瘦的你也损伤。"]},{"t":"都孔目风雨还牢末・沽美酒","f":"曲","c":["他、他、他假提着泪两行，怎觑他这趋跄。","(搽旦云)孔目也送衣服与你穿。","(正末唱)你大古是送千里寒衣女孟姜，可教我忙也那不忙，穿不的你那好衣裳！。"]},{"t":"都孔目风雨还牢末・太平令","f":"曲","c":["令史呵赛张鼎千般智量，哎，你个萧行首八步周行。","尽着你风流情况，做出些轻狂势相！我这里左想、右想，不见了僧住、赛娘，(搽旦云)这不是僧住、赛娘？(正末唱)儿也和俺李孔目一般悲怆。","(搽旦云)孔目，你敢饿了，我去备些茶饭来与你吃。","(下)(正末唱)。"]},{"t":"都孔目风雨还牢末・川拨棹","f":"曲","c":["那婆娘，他觑咱如粪壤。","公然的作祸为殃，巴不得中箭着枪。","还有甚心忙意慌。","待将咱好供养！。"]},{"t":"都孔目风雨还牢末・七弟兄","f":"曲","c":["这场去向，又做出甚商量？","浪包娄转眼机谋广，恶公人狠似虎和狼，恨不的把我泼残生逼勒登时丧！","。"]},{"t":"都孔目风雨还牢末・梅花酒","f":"曲","c":["哀告你个刘唐，可怜我媳妇先亡，儿女凄惶，我又遭着官防。","你也曾共府同堂，岂没半点情畅？只指望旱苗逢澍雨，怎忍教枯草打严霜？愿哥哥做主张。","暂宽我片时光。","便今生死甘当，来世里把恩偿。"]},{"t":"都孔目风雨还牢末・收江南","f":"曲","c":["呀，他把我死羊般拖奔入牢房，依旧硬邦邦匣定在囚床，便铁石人看见也心伤。","非是俺口强，则不如早些儿死了落可便早收场。"]},{"t":"都孔目风雨还牢末・中吕/粉蝶儿","f":"曲","c":["躲难逃灾，行行里两步一蓦，行不动东倒西歪。","则我这五魂绝七魄散。","撇在九霄云外。","流泪盈腮，恰便似蝴蝶儿滚成一块。"]},{"t":"都孔目风雨还牢末・醉春风","f":"曲","c":["则我这两只脚似腾空，魂灵儿如渡海。","想着那婆娘一片狠心肠，畅好是歹、歹！这都泼令史使的机谋，狠公人出的气力，争些儿李孔目被他残害！。"]},{"t":"都孔目风雨还牢末・上小楼","f":"曲","c":["你可便恰才到来，他便待将咱杀坏。","唬的我战战兢兢，悠悠荡荡，跪在尘埃。","猛抬头，观觑了，失惊打怪，(带云)我道是准。","(唱)原来是匾金环故人犹在。"]},{"t":"都孔目风雨还牢末・十二月","f":"曲","c":["这一场天来大利害，则为那匾金环惹祸招灾。","(李逵云)哥哥，你既在牢里，怎能勾出来？(正末唱)这都是刘唐打开了牢狱，史进救了我尸骸。","今日得遇你个英雄剑客，恰便似鬼使神差。","(李逵云)哥哥，这事怎生犯了来？(正末唱)。"]},{"t":"都孔目风雨还牢末・快活三","f":"曲","c":["我连忙将绳解开，早是我快疾来。","猛然见了觑明白，险些儿活惊杀。"]},{"t":"都孔目风雨还牢末・朝天子","f":"曲","c":["早是我到来，救的你醒来，怎忍见屈死在荒郊外。","想着他淫妇奸夫其情忒歹，只待要斩绝了咱家代。","他使着毒害，做这场布摆，据情理难容贷。","天也不盖，地也不载，哎，则俺那贤慧嫂今何在？(李逵同刘、史拿赵今史、搽旦上，云)哥哥，拿住奸夫、淫妇了也。","将他两个剖腹剜心，俺做按酒。","(阮小五云)将这两个泼男女拿到梁山上杀坏。","与李孔目同见我宋头领去。","(正未唱)。"]},{"t":"都孔目风雨还牢末・耍孩儿","f":"曲","c":["你将咱做死的般相看待，怎知道还能挣□？却原来你也自投下舍身崖，倒要我替你扛抬。","萧娥呵，你在丈夫面上偏生狠，令史呵，你在官府前头使尽乖。","到今日还咱债，可不道仇人相见，分外明白！。"]},{"t":"都孔目风雨还牢末・二煞","f":"曲","c":["想着你黑的是心，白的是财，只要图人性命将人害。","且看鬼门关上谁先到，枉死城中那个该。","毕竟是行短的天教败，少不得将你心肝百叶，做七事家分开。"]},{"t":"都孔目风雨还牢末・煞尾","f":"曲","c":["谢仁兄拔救死再生，似枯枝得雨花再开。","将奸夫淫妇都杀坏，方显的义气仁风播四海。","(宋江诗云)俺梁山泊远近驰名，要替天行道公平。","忠义堂施呈气概，结交尽四海豪英。","差李逵下山探听，到东平偶见相争。","只一拳将人打死，被官司拷打招承。","论律法本该抵命，李孔目搭救残生。","李山儿知恩图报，送金环聊表微情。","被小妇当官出首，将孔目熬尽严刑。","阮小五入牢打探，兼请他刘史同行。","萧行首剜心剖腹，赵令史号令山城。","今日个英雄聚会，一个个上应罡星早准备庆喜筵席，显见的天理分明。"]},{"t":"罗李郎大闹相国寺・仙吕/端正好","f":"曲","c":["咱意相投。","情相睦，索甚立质当文书。","(苏文顺云)则望哥哥看觑这两个孩儿。","(正末唱)您儿女就是咱儿女。","技怎肯两三般觑。","(苏、孟悲科。","云)孩儿呵，也是我出于尤余。","(正末唱)。"]},{"t":"罗李郎大闹相国寺・幺篇","f":"曲","c":["你则放心怀心举求官去，相别后便进长途，更休辞跋涉耽辛苦。","抛家业，赴皇都；凭才艺，仗诗书；同射策，觐銮舆；登御宴，饮芳醑；衣紫绶，带金鱼。","我言语，并无虚，则愿你早上青霄路。","(下)(苏文顺云)咱兄弟蒙赐盘缠，两个儿女又蒙看觑。","则今日拜辞了哥哥，收拾琴剑书箱，上朝取应走一遭去也。","(诗云)为功名无柰相催，便登程趱赴春闱。","(孟仓士诗云)可怜我一家骨肉，泪盈盈两处偷垂。","(同下)。"]},{"t":"罗李郎大闹相国寺・仙吕/点绛唇","f":"曲","c":["蜗角蝇头，利名营勾，空生受。","浮世悠悠，岁月频回首。"]},{"t":"罗李郎大闹相国寺・混江龙","f":"曲","c":["假若便功名成就，算来则是抱官囚。","挣□的封妻荫子，拜相封侯。","可正是今日不知明日事，前人田土后人收。","到头来只落得个谁消受？如风中秉烛，似水上浮沤。"]},{"t":"罗李郎大闹相国寺・油葫芦","f":"曲","c":["身似飘飘不缆舟，几时得巴到岸口？想当初庄子叹骷髅，一朝身死无人救，三寸气在千般有。","今日春，明日秋。","金乌玉兔东西走，断送一生休。","(带云)想老夫少年时做家呵。","(唱)。"]},{"t":"罗李郎大闹相国寺・天下乐","f":"曲","c":["俺也曾蚤起迟眠使计谋，营也波求，肯罢手？使行钱在城打着课头。","村里有大叶桑，阔角牛，每年家田蚕百倍收。"]},{"t":"罗李郎大闹相国寺・后庭花","f":"曲","c":["逐朝家饮兴酬，全不将学业修。","教你向芸窗下把书埋首，却元来糟屋中酒浸头，直恁般好风流。","半年不勾，早吃下一千瓶香糯酒。","(云)侯兴，该多少一瓶，算还了罢。","(侯兴问云)多少钱一瓶？(外云)两贯一瓶。","(侯兴云)你算该多少？(外云)两贯一瓶，二瓶四贯，四瓶八贯，八瓶十六贯。","(做咳嗽呵，云)是这等算还我。","(侯兴云)还了你钱，你去罢。","(外下)(外扮乐人上，云)汤舍在家么？(正末云)怎么又这般闹炒？(侯兴看科，云)你要甚么？(外云)我讨乐歌钱。","(侯兴云)老爹，讨乐歌钱的。","(正末云)怎生唤做乐歌钱？(侯兴云)阿！这老爹一窍也不通。","乐歌钱是和小娘每吃酒耍子，乐人弹唱伏侍的。","(正末唱)。"]},{"t":"罗李郎大闹相国寺・醉中天","f":"曲","c":["这厮结缆着章台柳，铺买下谢家楼。","我但到官陈词见的勾，(带云)若不受状呵。","(唱)我将皇城叩。","索共那五奴虔婆出头，这债到底俺汤哥儿承受，休、休、休！免得定刑名笞杖徒流。"]},{"t":"罗李郎大闹相国寺・一半儿","f":"曲","c":["你这般借钱取债结交游，做大妆幺不害羞，知你那爷贫也富也活也死也那无共有。","你那一日不秦楼，正是几处笙歌儿处愁。"]},{"t":"罗李郎大闹相国寺・后庭花","f":"曲","c":["你因酒上没做有，为花上恩变做仇。","你交财上不应口，争气处打破头。","这四件忒精熟，诸般懒就，这便是你男儿得志秋。"]},{"t":"罗李郎大闹相国寺・金盏儿","f":"曲","c":["你待纵酒饮深瓯，花带大开头。","因花为酒添憔瘦，还道是有花方酌酒，无月不登楼。","早辰间因酒病，到晚来为花愁。","可不道野花村务酒，(带云)定奴儿，靠后。","(唱)知滋味便合休。","(云)谁着你又吃醉了？躺着，须要痛决。","(净躺下科)(旦儿云)父亲看定奴面上，饶了汤哥者。","(净叫疼科)(正末云)你看这厮波，谁曾打着你来？(净云)你打几下倒好。","(正末云)怎生打几下倒好？(净云)父亲，今日打您孩儿几下，明日我那众弟兄知道呵，汤哥着他老爹打了一顿，众人安排酒软痛又是一醉。","(正末云)你看他波，你从今须断了酒者。","(净云)父亲教我断酒，我不敢不断，我则告宽我三日假。","(正末云)怎生告三日假？(净云)头一日杀五个羊请众兄弟每来吃一醉，唤做辞酒。","第二日再安排一席，可便是断酒。","第三日再安排一席，唤做开酒。","(正末云)你看这厮波，你快与我断了酒者。","(净云)你孩儿再吃酒，赌一个痛咒。","(正末云)你赌甚么咒？(净云)你孩儿再吃酒，我就吃蜜蜂儿的屎。","(正末唱)。"]},{"t":"罗李郎大闹相国寺・赚煞","f":"曲","c":["你少不的卖了庄田，折了孳畜，将我这逆耳良言不瞅。","愚滥荒淫出尽丑，我一片干家心话不相投。","没来由，枉把你收留，莫为儿孙作马牛。","你恋着红裙翠袖，折倒的你黄干黑瘦，(带云)古人言的不错呵：要儿自养，要谷自种。","(唱)这是我养别人儿女下场头。","(下)。"]},{"t":"罗李郎大闹相国寺・仙吕/赏花时","f":"曲","c":["我不是引的狼来屋里窝，寻的蚰蜒钻耳朵？问甚么山险峻，路嵯峨，山遥水阔，我则你手里要汤哥。","(下)。"]},{"t":"罗李郎大闹相国寺・南吕/一枝花","f":"曲","c":["这些时闷恹恹心不欢，愁戚戚情不乐。","直争争发似揪，热烘烘面如烧。","心痒难揉，都为他无消耗。","汤哥儿那里去了，去不到半月十朝，只恁的鱼沉雁杳。"]},{"t":"罗李郎大闹相国寺・梁州第七","f":"曲","c":["把不定心乔意怯，立不定肉颤身摇。","出门去没一个人知道。","恰便似石沉大海，铁坠江涛。","知他在何方归着？甚处流落？只为他孤身去梗泛萍漂。","撇的俺三口儿梦断魂劳。","(带云)汤哥儿，自从去了你呵。","(唱)我是你堂上尊撇的来这般忄敝忄敝焦焦，怀内子、(带云)道俺爹爹这早晚不来家呵。","(唱)也这般烦烦恼恼，哎！连你这娇滴滴脚头妻、也这般酒洒潇潇。","我如今与他定约。","侯兴那厮若是寻来到，(带云)你若回来呵。","(唱)我合道处再不道。","任凭他把铜斗儿家私使尽了，常言道口是心苗。"]},{"t":"罗李郎大闹相国寺・菩萨梁州","f":"曲","c":["不由我不峨峨的身摇，拂拂的心跳，烘烘的气倒，悠悠的魄散魂消。","天那！恶风儿吹折嫩枝条，严霜偏打枯根草。","我别无人则把你个孩儿靠，儿呵，你休做了猫儿向屋头溺。","似你这血气方刚怎便夭？倒叫我衰老子为儿穿孝。"]},{"t":"罗李郎大闹相国寺・牧羊关","f":"曲","c":["我安了灵位，排了果桌，向人门外将纸钱忙烧。","一灵儿荡荡悠悠，冥冥杳杳。","(带云)我那定奴儿呵。","(唱)你现放着父死无人葬，怎做得家富小儿娇？(悲科)(唱)哎！可怜我孤影空相吊，那里也养小防备老。"]},{"t":"罗李郎大闹相国寺・梧桐树","f":"曲","c":["教我战笃速如发疟，汗淋漓似水浇。","见一个旋风儿足律律将人绕，莫不是作念的你汤哥闹？(侯兴诈倒科，作魂云)我是汤哥来了也。","(正末云)你来做甚么？(侯兴云)老爹，我不幸死了，我嘱咐你的言语，你记者。","我有三件事遗留的话，不要违我的。","(正末云)孩儿，可是那三件事？(侯兴云)头一件事家缘过活，分与侯兴一半。","(正末云)这是谁说来？(侯兴云)是我汤哥说来。","(正末云)依的。","(侯兴云)第二件，侯兴伏侍多年了，与他一纸从良的文书。","(正末云)谁说来？(侯兴云)是我汤哥说来。","(正末云)依的！依的！(侯兴云)第三件，把定奴与侯兴做老婆。","(正末云)是谁说来？(侯兴云)我说来。","(做醒科，云)老爹，我恰才怎生来？(正末云)恰才汤哥附着你来。","(侯兴悲科，云)我那有灵圣的哥哥，不知说甚么来？(正末云)你哥哥吩咐三件事。","(侯兴云)可是那三件事？(正末唱)。"]},{"t":"罗李郎大闹相国寺・隔尾","f":"曲","c":["要从良便写约无差错，(侯兴云)我不要。","(正末云)我道你是家生孩儿，一定不要。","(唱)他要家私停分有下梢。","(侯兴云)我也不要。","(正末云)哦，你也不要？(侯兴云)老爹，这是两件，第三件怎么说哩？(旦儿云)老爹，你是必休说？(正末唱)定奴儿与你为妻，你可是要也不要？(侯兴云)这件我若不要，害疔疮。","(正末唱)窨约，想度，把我半世儿清名误赚了。"]},{"t":"罗李郎大闹相国寺・牧羊关","f":"曲","c":["我脑袋似石头坠，身躯似绳索缚，但行着不觉低高。","这的是些闷都在心头，气刺着肋梢。","你唤医人忙裹药，请大夫把病来调。","我涩的难行立，轰的则待倒。"]},{"t":"罗李郎大闹相国寺・尾煞","f":"曲","c":["问甚么家家门外长安道，买卖归来汗未消，打听的汤哥有些音耗。","那埚里遇着，那搭里撞着，我把那背义的奴胎不道的素放了。","(下)。"]},{"t":"罗李郎大闹相国寺・离调/金菊香","f":"曲","c":["往常时秦楼谢馆饮金卮，柳陌花街占表子，爷娘道有风过耳。","烟花担沉的来无似，则被你压杀我也那土筐儿。"]},{"t":"罗李郎大闹相国寺・商调/集贤宾","f":"曲","c":["出陈州五里巴堠子，无明夜到京师。","指东画西去了义子，走南料北不见孩儿。","也不索唤师婆擂鼓邀神，请山人占卦揲蓍。","则我这眉尖闷锁无钥匙，空教我抹泪揉眵。","只被他明明的抢了媳妇，停停的要了家私。"]},{"t":"罗李郎大闹相国寺・逍遥乐","f":"曲","c":["闪的我单身独自，又不敢对人声扬，只自己感叹嗟咨。","泼性命似风里游丝，(带云)你若死呵。","(唱)落得一碗凉浆一陌纸。","街坊论说，邻里计较，弟兄笑耻。"]},{"t":"罗李郎大闹相国寺・后莲花","f":"曲","c":["人都道你是教师，人都道你是浪子。","上长街百十样风流事，到家中一千场五代史。","自寻思，全不肯改志。","引兴儿共保儿，穿茶坊入酒肆，把家财胡乱使。","占猱儿养弟子，我良言须逆耳。"]},{"t":"罗李郎大闹相国寺・双雁儿","f":"曲","c":["白头翁先哭少年儿，想天公，也有私，教老拙遭逢着这场事。","远远的不避辞，特特的来到此。"]},{"t":"罗李郎大闹相国寺・金菊香","f":"曲","c":["恰离了招商打火店门儿，早来到物穰人稠土市子。","好门面好铺席好库司，门画鸡儿，行行买卖忒如斯。"]},{"t":"罗李郎大闹相国寺・幺篇","f":"曲","c":["彩画的红近着白青间着紫，无褒弹无破绽没瑕疵。","托赖着一人有庆兆民赖之，是当今敕赐，保护着玉叶共金枝。"]},{"t":"罗李郎大闹相国寺・幺篇","f":"曲","c":["见这遭囚夫役两行儿，我买下恰下甑的馒头三扇子。","一人两个休怨咨，但愿圣主宽慈，须有恩赦到来时。"]},{"t":"罗李郎大闹相国寺・醋葫芦","f":"曲","c":["不知是那个小厮，一声声唤这老子。","和那熬煎我的须索辨个雄雌，(净云)是我叫你来。","(正末唱)我这里孜孜的端详了多半时。","好和我那亡过的汤哥相似，是神是鬼远些儿。"]},{"t":"罗李郎大闹相国寺・幺篇","f":"曲","c":["那厮却有一二，咱家无三思。","将那谎局段则向俺跟前使，那厮正是咬人狗儿不露齿。","其余都不是，那匣子里却是谁的骨殖儿？。"]},{"t":"罗李郎大闹相国寺・浪里来煞","f":"曲","c":["我舍着金钟撞破盆，好鞋踏臭屎，但得个轴头儿也有抹着时。","我拚的撅皇城，挝怨鼓，插状子。","怕甚么金瓜武士，我和那泼奴胎情愿打官司。","(众下)。"]},{"t":"罗李郎大闹相国寺・双调/新水令","f":"曲","c":["为汤哥哭的我眼睛昏，教我在他乡有家难奔。","花发时起怪风，月圆后长浮云。","但有个儿孙，谁待受这愁困？。"]},{"t":"罗李郎大闹相国寺・步步娇","f":"曲","c":["想着我前世里原无儿孙分，遭逢着寡宿孤辰运。","我全然不受贫，想着那舆车后拖麻的是谁家胤？我死后谁与我上新坟？这烦恼何时尽？。"]},{"t":"罗李郎大闹相国寺・沉醉东风","f":"曲","c":["我与你送茶饭厨中有人，他把我厮禁持眼里无珍。","我心慈，他心狠，全无些父子情分。","则愿得铁锁沉枷早离身，我落一觉安眠睡稳。"]},{"t":"罗李郎大闹相国寺・胡十八","f":"曲","c":["恰过了六市，来到三门，揉开我这汪泪眼，打拍我这老精神，想着他行行不住叫声频。","莫不是他错认？到今日忘魂，不由我嗔忿忿，不由我怒氲氲。"]},{"t":"罗李郎大闹相国寺・川拨棹","f":"曲","c":["谁家的小魔军，两三番迤逗人？我这里扭项回身，吃我会抢问。","你畅是不知个高低远近，向前向审问的真。"]},{"t":"罗李郎大闹相国寺・收江南","f":"曲","c":["哥也，更怕我不因亲者强来亲，单饶了他两个与些金银。","(张千云)我不敢要银子，你自家告相公去。","(正末唱)哥哥是心直口快射粮军，哥哥是好人，我这里低腰曲脊进衙门。"]},{"t":"罗李郎大闹相国寺・干荷叶","f":"曲","c":["老汉是愚民，特地来诉词因，(苏文顺云)那老的，那里人氏？(正末云)我听这官人声气，也是我陈州人。","(唱)我可便家住在陈州郡。","总饶你满园春，万花新，争如得见当乡人，(正末做认科)(苏文顺云)你敢认的我么？(正末唱)你畅好是安乐也苏文顺。"]},{"t":"罗李郎大闹相国寺・沽美酒","f":"曲","c":["拜了呵再不着榆木枷压项筋。","粗铁锁束腰身，稳情取白马红缨彩色新。","将你那破衣服重加整顿，施礼数叙寒温。"]},{"t":"罗李郎大闹相国寺・太平令","f":"曲","c":["拜的你不须审问，(苏文顺云)哥哥，他是谁？(正末唱)他便是定奴的女婿郎君。","您去了二十载不通音信，十八上才成秦晋。","(苏文顺云)哥哥，你怎生匹配他两个来？(正末云)我也曾勘婚，过门，便就亲，结果了他夫妻和顺。"]},{"t":"罗李郎大闹相国寺・川拨棹","f":"曲","c":["那的是痛欢欣，去时节竹议沦，你两个苦志修文，温故知新。","这的是显耀男儿气分，只愿你早成名天下闻。"]},{"t":"罗李郎大闹相国寺・乱柳叶","f":"曲","c":["这孩儿是你的亲孙，这官人是你的家尊，哎！你个定奴儿快疾将你爷来认。","早是我希彪胡都喜。","则管耻迷丢答都问。","我须是匹配你的大媒人。","(净云)今日俺亲爷见亲儿，亲儿见亲爷，怎不欢喜？老爹你过来。","干你甚事？(推正末科)(旦儿云)今日亲爷见亲女，亲女见亲爷，怎不欢喜？老爹你过来。","干你甚事？(推正末，做悲科，唱)。"]},{"t":"罗李郎大闹相国寺・水仙子","f":"曲","c":["我好生的和劝到半时辰，亲的原来则是亲。","亲儿亲女把亲爷认，中间里干闪下老业人，我死后做了个无主孤魂。","他虽是生身父，我也有养育恩，二十年枉受辛勤。"]},{"t":"罗李郎大闹相国寺・收尾","f":"曲","c":["到长安受尽多劳顿。","业则为故人义分。","你两个养儿女的都到了家，可惜我赶候兴的干折了本。"]},{"t":"刘玄德醉走黄鹤楼・仙吕/点绛唇","f":"曲","c":["卖弄你马壮人强，驱兵领将，东吴往。","咱可便同共商量，商量的都停当。","(刘末云)周瑜请我饮酒，他岂有歹意？(刘封云)哎，老赵，想俺父亲在襄阳会上，也不同小可也。","(正末唱)。"]},{"t":"刘玄德醉走黄鹤楼・混江龙","f":"曲","c":["不比那襄阳会卜，他则待兴心儿图谋汉家邦。","(刘封云)想周瑜破了百万曹兵，他正是擎天玉柱，架海金梁，他有甚歹意？父亲你赴宴走一遭去，有甚么事！(正末唱)你道他是擎天的玉柱，架海金梁，才杀退霸道奸雄曹盂德，那周瑜不弱如兴刘火楚的这汉张良。","索仔细，莫荒脚，涉大水，渡长江。","看了这黄鹤楼胜似他那宴鸿门，觑了他这碧莲会更狠如临潼上。","(刘封云)他见俺父亲，不得不敬，务要走一遭去。","(正末唱)他遣来使相请，咱可便不上落的这何妨？。"]},{"t":"刘玄德醉走黄鹤楼・天下乐","f":"曲","c":["无拈指黄鹤楼敢番做战场，我想，那周瑜有智量，晃晃列着刀共枪。","鱼不可离了水，虎不可离了冈，他可敢安排着恶战场。"]},{"t":"刘玄德醉走黄鹤楼・后庭花","f":"曲","c":["拿着这虚飘飘的纸一张，上写着黑真真字儿行。","他则是仗剑施威计，埋伏打凤凰。","这件事不寻常，那里有风波干丈，我言语不是谎。","(刘末云)凭着俺三兄弟张飞英勇，可量他到的那里也？(正末唱)。"]},{"t":"刘玄德醉走黄鹤楼・金盏儿","f":"曲","c":["你道是张翼德气昂昂，性儿刚，(刘封云)俺三叔叔张飞，十八骑人马，在那当阳桥上，喝了一声，桥塌三横水逆流，唬的曹兵倒退三十里远。","(正末唱)在那当阳桥喝退了曹丞相，据着他一冲一撞卖弄高强。","(刘封云)凭着俺三叔叔坐下乌骓马，手中丈八矛，万夫不当之勇。","(正末唱)倚仗着当三军不刺剌乌骓骑，敌万夫光灿灿丈八点钢枪。","(刘封云)俺三叔安喜县鞭督邮，又在石亭驿中，将袁祥提起腿，掼的花红脑子出来。","不妨事，父亲走一遭去。","(正末唱)你休卖弄安喜县鞭督邮，石亭驿摔袁祥。"]},{"t":"刘玄德醉走黄鹤楼・尾声","f":"曲","c":["他那里明明的捧着瑶觞，暗暗的藏着军将，用计铺谋怎防？着主公坐在那难走难逃筵会上，你心下自索参详，自度量，不比寻常，他则待赚虎离窝入地网。","(刘封云)哎，赵叔，你不知道，那黄鹤楼近在水边。","若水长呵，我安排战船，搭起浮桥，接应我父亲。","他便跌下水去，落的他睡一觉。","(正末唱)那黄鹤楼接大水长，翻波滚浪，正末云)若主公不听赵云谏当呵。","(唱)知他是甚风儿吹过汉阳江？(下)(刘封云)老赵，你去，我父亲他也不听你说。","父亲走一遭，则管嚼食去。","(刘末云)刘封，你与赵云紧守着城池。","则着三五骑人马，跟我过江，直至黄鹤楼上赴宴，走一遭去。","子龙心下莫踌躇，今朝止马践程途。","过江亲赴碧莲会，直至那黄鹤楼上见周瑜。","(下)(刘封云)父亲去了也。","为甚么我赍发的俺父亲过江去？那周瑜是个是智多谋的人，俺父亲若有些好歹，他这个位，就是我承袭。","凭着我这般好心肠，天也与我半碗饭吃。","(下)。"]},{"t":"刘玄德醉走黄鹤楼・豆叶黄","f":"曲","c":["那里，那里酸枣的林儿西里，您娘教你早来家，早来家，恐怕那狼虫咬你。","来摘枣儿，摘枣儿，你道不曾摘枣儿，口里核儿那些来？张罗，张罗，见个狼呵，跳过墙呵，唬杀你娘呵。","(云)我做庄家不须夸，厌着城里富豪家。","吃的饭饱无处去，水坑里面捉虾蟆。","(唱)。"]},{"t":"刘玄德醉走黄鹤楼・正宫/端正好","f":"曲","c":["则听的二姑把三哥来叫，(禾旦云)俺看田苗去来。","(正末唱)东庄里看取些田苗。","落荒休把这山庄绕，咱可便寻一条家抄直道。","(禾旦云)俺这江南，青的是山，绿的是水。","你看那渔舟唱晚，响穷彭蠡之滨；雁阵惊寒，声断衡阳之浦。","家家采下茶苗，杜鹃春啼晓；夏蝉高噪绿杨枝，秋蝉晚噪。","俺庄家好快活也。","(正末唱)。"]},{"t":"刘玄德醉走黄鹤楼・滚绣球","f":"曲","c":["俺这里对青山堪画描，端的是景物好。","你觑那红叶儿秋蝉晚噪，俺这里家家采下茶苗。","(禾旦云)俺江南好暖和也。","(正末唱)则这江南地暖风寒少，俺这里春夏秋冬草不调，绿水千条。","(禾旦云)你看那黄菊近东篱，村老忙将马骞驴骑。","牛金牛表扶策走，只吃的东歪西倒醉如泥，受用有谁知？紫袍金带虽然贵，其实不如俺淡饭黄齑粗布衣。","伴哥儿，我打东庄里过来，看了几般儿社火，吹的吹，舞的舞，擂的擂。","不是我聪明，我一般般都记将来了也。","(正末云)伴姑儿，道我恰才打那东庄头过来，看了几般儿社火，我也都学他的来了也。","(禾旦云)伴哥儿，我不曾见，你试学一遍咱。","(正末云)试听我说一遍咱。","(唱)。"]},{"t":"刘玄德醉走黄鹤楼・叨叨令","f":"曲","c":["那秃二姑在井口上将辘轳儿乞留曲律的搅，(禾旦云)瞎伴姐在麦场上，将碓儿捣也捣的。","(正末唱)瞎伴姐在麦场上将那碓臼儿急并各邦的捣。","(禾旦云)那小厮们手拿着鞭子，哨也哨的。","(正末唱)小厮儿他手拿着鞭杆子他厮厮飕飕的哨，(禾旦云)牧童儿倒骑着水牛，叫也叫的。","(正末唱)那牧童儿便倒骑着个水牛呀呀的叫。","(禾旦云)俺庄家好快活也。","(正末唱)一弄儿快活也么哥，一弄儿快活也么哥，(禾旦云)俺庄家五谷收成了，甚是安乐。","(正末唱)正遇着风调雨顺民安乐。"]},{"t":"刘玄德醉走黄鹤楼・倘秀才","f":"曲","c":["那匹马紧不紧疾不疾荡红尘一道，风吹起脖项上绛毛缨一似火燎他斜拽起团花那一领锦战袍。","端的是人英勇，马咆哮，(关平云)兀那庄家你住者，我和你有说的话。","(正末唱)他那里高声儿叫住着。"]},{"t":"刘玄德醉走黄鹤楼・货郎儿","f":"曲","c":["你过的这乞留曲律蚰蜒小道，听说罢官人你记着。","你过的一横涧搭一横桥，更有那倒塌了的山神庙。","(关平云)再有甚么记号？(正末唱)破墙匡草团瓢，转山坡过岭桥，河取鱼儿水不着，春夏秋冬草不凋。","贪看云中鹘打雁，你可休离俺这山庄，可便错去了。"]},{"t":"刘玄德醉走黄鹤楼・尾声","f":"曲","c":["俺这里风调雨顺民安乐，百姓每鼓腹讴歌贺圣朝。","则这一带青山堪画描，四野田畴景物好。","倒大来无是无非，(关平云)多生受你，慢慢的去。","(唱)可兀的快活到老。","(下)。"]},{"t":"刘玄德醉走黄鹤楼・楚天遥","f":"曲","c":["重重叠替山，曲曲湾湾水。","山水两相连，送伊十万里。","送你几时回，两行凄惶泪。","庄家每快活，忱着甜瓜睡。"]},{"t":"刘玄德醉走黄鹤楼・双调/新水令","f":"曲","c":["我将这锦鳞鱼斜穿孔绿杨枝，舞两风晚凉恰至。","残荷凋翡翠，红叶染胭脂。","景物宽时，(云)我缆住船者。","(唱)我这里上江岸步行至。","(云)我来至这黄鹤楼也。","我打听的周瑜差他那心腹人？唤做俊俏眼，把着楼胡梯。","我怎生推一个乍熟儿，他说我姓张。","我便姓张，他说我姓李。","我便姓李。","我则得上的这楼去呵，我自有个主意。","先见他去者。","(俊俏眼做盹睡科)(正末云)这厮睡着也，我着这厮吃一个巴掌道。","(做打净科)(俊俏眼做惊科，云)是谁打我来？(正末云)道你认的我么？(俊俏眼云)我认的你，有些面熟，你敢是鱼儿张么？(正末云)谁道是虾儿李来？(俊俏眼云)你那里去来？(正末云)我听的元帅在这黄鹤楼上筵宴，我将着这一对金色鲤鱼。","元帅跟前献口味来。","(俊俏眼云)是一对好金色鲤鱼也。","你前日许了鲜鱼儿、鲜虾儿，你计下我，你怎生不送来与我？(正末云)你怎生举荐我一举荐，我把这鱼元帅跟前献了，到明日你来我那船上来，我着你虾儿、鱼儿挑一担来，可不好？(俊俏眼云)休说谎，我如今便替你说去。","你明日好鲜虾儿、鲜鱼儿，可与我挑一担来。","你则在这里，我替你说去。","(俊俏眼做上楼见科)(周瑜云)这厮做甚么？(俊俏眼云)楼下有一个打鱼的，见元帅这里饮酒，献一对金色鲤鱼，与元帅跟前献好新来。","(周瑜云)打鱼的献口味，你认的他么？(俊俏眼云)小的每认得，他每日在这江边打鱼，他唤做鱼儿张。","(周瑜云)既然你认的，着他过来。","(俊俏眼做下楼见正末科，云)我替你说过了也，着你过去哩。","休忘了我的鲜鱼儿、鲜虾儿，明日送来。","(正末云)我这蓑衣斗笠，放在这里。","(俊俏眼云)你放下，我替你看着。","(正末上楼科)(周瑜云)兀那厮，你甚么人？(正末云)小人是这打鱼儿的小张儿。","(周瑜云)你来做甚么来？(正末云)听知的元帅在此筵宴，小的每无甚么孝顺，将着这一对金色鲤鱼，元帅跟前献口味来。","(周瑜云)玄德公，他知道俺在此饮酒，将这一对鱼来献新。","(刘末云)也是他孝顺的心肠。","(周瑜背云)我如今指着这鱼，双关二意，乱道数句，我讥讽这大耳汉，看他知道么？(周瑜对刘末云)玄德公，俺今日在此楼上饮酒，感的这野人来献新，不才周瑜乱道数句，玄德公跟前呈丑咱。","(刘末云)刘备洗耳愿闻。","(周瑜云)这鱼他在那碧波中游戏，不堤防撒网垂钩，则为他失计吞食，今日落在俺渔翁之手。","鱼也，你也难回渊浪，自损你那残生。","你若是做小伏低，我着你活拨拨的远趁江湖；你若是弄巧呈乖，我着你须臾间除鳞切尾。","你可也难逢子产，今日个正遇着杨胥。","鱼也，你若是肯随顺呵，我着你享峥嵘独步过龙。"]},{"t":"刘玄德醉走黄鹤楼・殿前欢","f":"曲","c":["这鱼儿他自寻思，可是他为吞香饵可便中钩儿。","(周瑜云)这鱼可在那里来？(正末唱)他在那水晶宫卫相传示，(周瑜云)兀那渔翁，你将这鱼除鳞切尾，逗盐加酱，当面制造，急忙下手。","某带酒也。","(睡科)(正末唱)准承望命在参差。","任渔公自三思，空有翻波志，他可便眼见的在钢刀下死。","这龟儿比并着，玄德你与我仔细寻思。"]},{"t":"刘玄德醉走黄鹤楼・水仙子","f":"曲","c":["你休恋那玉箫银管饮金卮，你将这碧莲会筵席且告辞。","(刘末云)军师说甚么来？(正末唱)俺军师把元帅多传示，(刘末云)关、张二弟，曾说甚么来？(正末唱)这其间在江边敢没乱死。","(刘末云)军师再说甚么来？(正末唱)俺军师细说言词，(刘末云)俺军师可怎生不着人接应我那？(正末唱)这其间安排着军校，(刘末云)可在那里接应？(正末唱)在堤圈杨柳枝，(刘末云)我怎生得过这江去？(正末唱)先安排下个渔船儿。"]},{"t":"刘玄德醉走黄鹤楼・尾声","f":"曲","c":["小人怎敢泥中刺？(周瑜云)若不看玄德公的面皮，杀了这厮多时了。","(正末唱)休、休、休，可不道大官不觑帘下事。","(正末云)我下的这楼来。","(俊俏眼云)你献了那口味也？(正末云)我献了口味也。","我那蓑衣斗笠呢？(俊俏眼云)兀的不是？明日替我送将虾儿、鱼儿来！(正末唱)恰便似火上浇油，命掩参差。","畅道万语千言，三回两次。","若不是玄德公言词，险些儿三尺龙泉剑下死。","(下)。"]},{"t":"刘玄德醉走黄鹤楼・南吕/一枝花","f":"曲","c":["拨回獬豸身，滴溜扑跳下乌骓骑。","舒开狻猊爪，(正末见刘封走科，云)刘封那里去？(唱)我这里扌昝住锦征衣。","嘴缝上拳捶，手指定奸谗嘴，我拷你个忤逆贼。","(刘封云)三叔息怒。","(正末云)你父亲那里去了？(刘封云)周瑜请的过江饮宴去了也。","(正末唱)你怎生赍发的我哥哥。","去他那四十里长江那壁。"]},{"t":"刘玄德醉走黄鹤楼・梁州","f":"曲","c":["则为那周公瑾两三杯酒食，更压着那一千个他这党太尉的筵席。","我跟前莫得夸强会。","若还他无灾无难，无足无非；若有些个争竞，半米儿疏失，米、来、来，我和你做一个头敌。","则我这村性子不许收拾！割舍了，喝曹操唬了他那三魂，鞭督邮拷折你这脊背。","休恼番，石亭驿摔袁祥撞塌头皮。","若还，得回，俺哥哥无事宋家内，使心量有奸细。","船到江心数十里，则怕他背后跟追。"]},{"t":"刘玄德醉走黄鹤楼・隔尾","f":"曲","c":["休得要临崖勒马收缰急，直等的船到江心那其间补漏迟。","点手儿旁边唤公吏，你与我麻绳子绑者柳树上，高高的吊起，直等的俺哥哥无事来家，恁时索放了你。"]},{"t":"刘玄德醉走黄鹤楼・隔尾","f":"曲","c":["俺哥哥到黑龙江流的是潺潺水，(净云)爹爹救我咱。","(正末唱)红蓼堤边吖吖的叫唤谁？(刘末云)兀那吊的是谁？(正末唱)是你那孝子曾参可人意。","(刘末云)三兄弟，为甚么吊起他来？(正末唱)见哥哥无些个信息，怕有些个疏失，因此上将他在柳树梢头，着他便吊望着你。"]},{"t":"刘玄德醉走黄鹤楼・絮虾蟆","f":"曲","c":["军将便似鱼鳞砌，枪刀便似雁翅般齐，我又索与你迎敌。","自从桃源结义，又在徐州失配。","不曾相持对垒，不曾翻天倒地，我无处发付气力。","付能逢着今日，红锦征袍喜披，黄锦腰带坚系，再把乌骓扣革皮，又把包巾整理。","我听的冬冬鼓擂，忽的摇旗，出的相持。","美也，兀的不欢喜煞爱厮杀的张飞，迎敌。","马蹄儿踏碎了东吴国，你是那周公瑾，我是这张翼德，眼儿里见了，耳朵儿听者。"]},{"t":"狄青复夺衣袄车・仙吕/点绛辱","f":"曲","c":["则我这剑戟藏收，臂无锦鞲，衣袍旧。","马善人熟，想往日威风赳。"]},{"t":"狄青复夺衣袄车・混江龙","f":"曲","c":["玉门关后，老将军无比阵云收。","若题着安邦定国。","受赏封侯。","擐甲披袍骑战马，到不如去拽耙扶犁使耕牛，寻几个渔樵作伴将柴门扣。","心忙意急，壮志难酬。"]},{"t":"狄青复夺衣袄车・油葫芦","f":"曲","c":["遥指南山景物幽，我自趁逐，闲来游玩兴悠悠。","我则见碧滔滔水面上波纹皱，更那堪翠巍巍山色晴岚秀。","相交的野外人，作伴的村下叟。","喜的是扶梨拽耙深耕耨，止不过春种与秋收。"]},{"t":"狄青复夺衣袄车・天下乐","f":"曲","c":["时遇半年五谷收，百姓每歌讴，心意投，俺若是做庄农快活何处有？","若有那二顷田，和他这一耙牛，倒大来千自在百自由。"]},{"t":"狄青复夺衣袄车・寄生草","f":"曲","c":["咱两个才相见，心意投。","英雄只说英雄手，他贤良只说贤良口，则俺这英雄志气冲牛斗。","他若是相持厮杀统戈矛，端的是强中更有强中手。","(云)狄青，你来，我赊与你这付披挂，你以后得志呵，那其间还我钱钞，也未是迟哩。","(狄青云)多谢了老将军。","我若久以后得志呵，此恩必当重报也！(唱)。"]},{"t":"狄青复夺衣袄车・尾声","f":"曲","c":["这红抹额似火霞飘，金面具威风赳。","大杆刀轻轮在手，平定了乾坤四百州。","施展你那武艺滑熟．统戈矛。","有一日建节封侯，恁时节方显男儿得志秋。","则我这气冲着牛斗，胸怀锦绣，我则待播清风万古把杯留。","(下)。"]},{"t":"狄青复夺衣袄车・南吕/一枝花","f":"曲","c":["我与你拽扎了我红纳袄，牢拴住白毡帽。","(带云)好大雪也呵。","(唱)恰便似颠狂飞柳絮，我则见纷纷的剪鹅毛。","头直上瑞雪飘飘，如万对蝴蝶闹，正彤云罩紫霄。","又遇着酷冷天寒，将令差违拗了谁敢承招。"]},{"t":"狄青复夺衣袄车・梁州","f":"曲","c":["恰过了五七层山坡隘角。","早来到十数处野水横桥。","我与你汤风冒雪登长道。","寒风飒枫，冷雾潇潇。","将令严整，暮景良宵。","往来是半月十朝，谁敢道怠慢分毫。","(带云)这一遭。","(唱)我、我、我，虽不足北狄南蛮；来、来、来，又不足天涯海角；呀、呀、呀，过了些无爷娘的水远山遥。","不由我自猜，自焦。","火误了阃外将军号，我急行动军健脚。","不见了扛车何处抓，可怎生无一个消耗？。"]},{"t":"狄青复夺衣袄车・牧羊关","f":"曲","c":["我从来无虚谬，你心中自恁约，违了限半月期高。","俺元帅杀斩权谋，你这件事非同一个草草。","你赶的上夺了呵不见罪，你赶不上呵将来怎耽饶。","我便有那浑身是口也难分晓，则你那好前程可惜断送了。"]},{"t":"狄青复夺衣袄车・乌夜啼","f":"曲","c":["箭离弦似一点流星落，我则见滴溜扑坠落在鞍鞒。","(狄青云)我箭射了昝雄，俺寻那衣袄扛车去来。","(正末唱)也是他今门灾星照，他枉劬劳，咱不索心焦。","(狄青云)赶上史牙恰，一刀劈下马来。","(正末唱)若遇着史牙恰刀并见个低高，夺了那衣袄车便是把冤仇报。","(狄青云)我不用排兵布阵，就要了衣袄车来。","(正末唱)也不用排军校，你端的逢山开道，遇水叠桥。"]},{"t":"狄青复夺衣袄车・牧羊关","f":"曲","c":["史牙恰排军校，狄将军武艺高。","红抹额火焰风飘。","鞍上将如北海的蛟龙，坐下马似南山兽绕。","狄将军施英勇，史牙恰显粗豪。","史牙恰束手才争斗，狄将军去他顶门上，磕叉的则一刀。","(狄青云)某箭射了昝雄，刀劈了史牙恰。","刘庆，你先回去。","复夺了衣袄扛车，赶退番军，我便回大人的话去也。","(正末跪科，云)阿哥，我家中还有八十岁的老母，无人奉养。","你怎生可怜见，将这昝雄的金牌，史牙恰的三叉紫金冠，与我卖些钱钞，侍养老母，可不好也。","(狄青云)这牌与冠都与你。","你就将着这两颗首级，先往大人府里献功去。","我押这衣袄车，我随后便来也。","(正末唱)。"]},{"t":"狄青复夺衣袄车・尾声","f":"曲","c":["鹤随鸾凤飞还远，人伴贤良志转高。","那将军施躁暴，这将军是勇跃，夺了车扛，取了衣袄。","昝先锋着箭凿，史牙恰则一刀。","这狄青恰似活神道，他轻轮着那三尖两刃刚刀，把些个败残军落荒他可都赶去了。","(下)。"]},{"t":"狄青复夺衣袄车・赏花时","f":"曲","c":["推我在深涧里登时一命亏，我若到帅府争知他饶过你。","狄将军英雄有谁及，若我不分一个曲直，必索要别办个是和非。"]},{"t":"狄青复夺衣袄车・幺篇","f":"曲","c":["常言道湛湛青天不可欺，若顺了人心失了正理。","天纲是恢恢，若论着狄肯的这武艺，我则待对倒了他这个赖功的贼！(下)。"]},{"t":"狄青复夺衣袄车・商调/集贤宾","f":"曲","c":["贪慌忙棘针科抓住战衣，杀败了一个小河西。","行不动山岩下歇息，立不住东倒西欹。","眼张狂手似捞凌，行不动一丝无力。","那将军相持厮杀对垒，有军来谁敢迎敌！喧天般发喊声，就地凯征鼙。","名传于世，委实无敌，(正末见科，云)报、报、报！喏(唱)寰中第一。"]},{"t":"狄青复夺衣袄车・后庭花","f":"曲","c":["杀的那血成河如聚水，死尸骸山岸般堆。","疏林外枪刀响，山坡前战马厮，莫迎敌。","谁曾见崎岖的山势，高阜处遥望者见一将来的疾。","雄赳赳将铠甲披，威凛凛战马嘶，红抹额似火焰飞，皂罗袍似雾黑，乌油甲甚整齐，凤翎箭端的直，鹊桦弓偃月起。","那将军面皮，三尖刀两刃齐。","人和马走似飞，喝一声如霹雳，唬的人魂魄飞。"]},{"t":"狄青复夺衣袄车・双雁儿","f":"曲","c":["俺这壁急慌忙扑倒了这云月皂雕旗，把枪刀不撇了，等甚的！","咱顾命逃生早回避，他来的雄势威，惜不的甲马催。"]},{"t":"狄青复夺衣袄车・醋葫芦","f":"曲","c":["昝雄那里饮战马，狄青背后随。","昝雄他英名赳赳竖神威，狄将军怒将金镫踢。","不离子今日，界河的这两岸要相持。"]},{"t":"狄青复夺衣袄车・醋葫芦","f":"曲","c":["狄青将右手兜，左手推。","斟量着远近觑个高低，则他那猿猱臂膊使着气力。","撼山般威势，转回头斜望着昝雄射。"]},{"t":"狄青复夺衣袄车・醋葫芦","f":"曲","c":["箭着处支楞楞撇了画戟，扑簌簌掉了豹尾。","脑桩的落马马空回，弯着弓插着箭忙整理。","将一顶紫金冠撞碎，三思台吞满画桃皮。"]},{"t":"狄青复夺衣袄车・醋葫芦","f":"曲","c":["一个在河道东，一个在临路西。","都不曾答话便相持，却便似黑杀神撞着个霹雳鬼。","枪强刀会，棋逢对手好相持。"]},{"t":"狄青复夺衣袄车・醋葫芦","f":"曲","c":["史牙恰枪去的疾，狄将军刀去劈。","刀迎枪举足律律火光飞，见枪来躲过，着刀去劈。","我则见连肩带臂，恰便似锦毛彪扑倒一个玉狻猊。","(李滚云)箭射死昝雄，刀劈了史牙恰。","天朝威风浩大，猛将英雄，再不敢调遣番兵，俺则索投降纳贡。","便好道饶你深山共深处，到头都属帝王家。","探子，你且回本营中去。","(正末唱)。"]},{"t":"狄青复夺衣袄车・中吕/粉蝶儿","f":"曲","c":["我这里步步刚捱，病身躯恰才安泰，行不动东倒西歪。","脚刚移，身强整，魂灵儿不知个所在。","也是我运拙时乖，谁承望这一场颇余。"]},{"t":"狄青复夺衣袄车・醉春风","f":"曲","c":["这怨恨重如山，咱冤仇深似海。","不走了你个奸浊侥幸赖功贼，黄轸也你畅好是歹、歹！我与你折证的明白，狄青他一心忠孝，搭救他这场灾害。"]},{"t":"狄青复夺衣袄车・红绣鞋","f":"曲","c":["当日个琼填满东郊南陌，粉妆成殿阁楼台，见一簇番兵拥将来。","狄青在火坑中逃了性命，今日向云阳内受非灾，我救这一个苦相持梁栋材。","(范仲淹云)谁射死咎雄来？(正末云)是狄青一箭射死昝雄来。","(唱)。"]},{"t":"狄青复夺衣袄车・上小楼","f":"曲","c":["一来是时间免灾，二来与将军除害。","狄青那里怪眼圆睁，剔竖神眉，怒目张开。","狄青那里显手策，使气概，英雄慷慨，则他那昝先锋那一场灾害。"]},{"t":"狄青复夺衣袄车・十二月","f":"曲","c":["那将军其实壮哉，那一会气夯破胸怀。","史牙恰提枪出阵，狄将军纵马前来。","狄将军刀起处他如何挣挫，那将军威凛凛英勇身材。"]},{"t":"狄青复夺衣袄车・尾声","f":"曲","c":["我见来，我见来，杀的那史牙恰无百刂划。","想狄将军盖世功劳大，保护着一统山河万万载。","(范仲淹云)老夫尽知也。","原来是黄轸混赖狄青的功劳，将黄轸推转杀坏了者！狄青，你听者，为你复夺了衣袄扛车，箭射昝雄，刀劈史牙恰，有此功劳，加你为征西都招讨金吾上将军。","狄青，你望阙跪者，听圣人的命。","则因你敢勇相争，凭谋略收捕贼兵。","真梁栋世之虎将，据英雄天下驰名。","黄面具千般杀气，乌油甲万道威风。","野水岭刀斩牙恰，杏子河箭射昝雄。","施勇烈扬威耀武，秉忠心永镇边庭。","加你为总都大帅，定家邦天下元戎。","朝金阙躬身叩首，立乾坤帝业兴隆。","今日个加官赐赏，保皇图万载升平。"]},{"t":"萨真人夜断碧桃花・仙吕/赏花时","f":"曲","c":["我擎着个笑脸儿将他厮问候，(张道南云)小生陪侍小姐同看花咱。","(正旦唱)他陪着个小意儿和咱相趁逐。","(徐端同夫人上，云)恰才赏牡丹花回绣房中，怎不见大女孩儿？敢是同梅香在后园中看花去了？夫人俺两个看女孩儿去来。","(正旦唱)却被这莺声唤猛叫头，(徐端云)叫梅香。","(张道南，兴儿惊，云)兀的是有人来也。","我与你快走。","(同下)(正旦唱)呀，不提防双亲在背后，我可也怎遮得这场羞。"]},{"t":"萨真人夜断碧桃花・幺篇","f":"曲","c":["他那里恼乱春风卒未休，(梅香云)姐姐，这场事怎生结果也？(正旦唱)则着我独立花前黯自愁，泪不住点儿流。","(做背科，唱)他须是我天缘配偶，常言道女大不中留。","(同梅香下)。"]},{"t":"萨真人夜断碧桃花・仙吕/点绛唇","f":"曲","c":["则我这杏脸藏春，柳眉标恨，萦方寸。","无奈东君。","花落春将尽。"]},{"t":"萨真人夜断碧桃花・混江龙","f":"曲","c":["消不的一天愁闷，清明时节雨纷纷。","慵施粉黛，倦点朱唇。","恰便似薄命照君青冢恨，少年倩女绿窗魂。","这其间可正是我愁时分，则见那巢空翡翠，冢卧麒麟。"]},{"t":"萨真人夜断碧桃花・油葫芦","f":"曲","c":["为甚么我一上青山便化身？端的愁杀人，常只是安排肠断又黄昏，害了个恹渐渐的鬼病儿，积趱下重重叠叠恨。","做了个虚飘飘的恶梦儿，捱不出凄凄凉凉运。","一会家急急煎煎腹内焦，一会家寻寻思思心内忍。","闪的我悲悲切切孤儿寡儿无投奔，因此上凄凄惨惨，无语暗消魂。"]},{"t":"萨真人夜断碧桃花・天下乐","f":"曲","c":["可怜见梦里形容病里身，则今春，憔悴损，比着这花枝更添瘦几分。","也无心对镜鸾。","也无心整鬓云，我只怕韶光也妒人。"]},{"t":"萨真人夜断碧桃花・鹊踏枝","f":"曲","c":["俺只待看是何人？他那里呀的开门。","(张道南做见科，云)花阴下好一个女子也！看他那云鬟雾鬓，杏脸桃腮，柳眉星眼，不由咱不动心也。","俺试问他咱：那壁小娘子，谁氏人家？夤夜到此何故？(正旦唱)哎，你个题诗的相如，休问我听琴的文君，(张道南云)小生只为春色困人，闲观月色，不期遇着小娘子。","(正旦唱)元来是恼春色孤眠不稳，早难道为贱妾断梦劳魂。"]},{"t":"萨真人夜断碧桃花・寄生草","f":"曲","c":["他把那寒温叙，礼数勤。","(张道南云)此一会小官三生有圭也。","(正旦唱)则见他曲躬躬笑把言词问，好着我羞答答忙把身躯褪。","我只索悄冥冥俞把容颜认。","(云)敢问相公高姓？(张道南云)小生姓张，双名道南。","(正旦唱)可正是月明千里故人来，惭愧你东风一夜传芳讯。"]},{"t":"萨真人夜断碧桃花・醉中天","f":"曲","c":["妾身抱天地无穷恨，蒙雨露有深思。","(张道南云)住处有甚邻舍？(正旦唱)常则和野草闲花作比邻。","(张道南云)小娘子家有多远？(正旦唱)俺住处路接天台近。","(张道南云)你那里还有何人？(正旦唱)俺那里有的是秦人晋人，你可也休将咱盘问，则管里絮叨叨拔树寻根。"]},{"t":"萨真人夜断碧桃花・金盏儿","f":"曲","c":["他将我厮温存，我将他索殷勤。","口儿未说早心儿顺，俺两个正是那不因亲者强来亲。","(张道南云)趁此月色，共饮几杯，、岂不美乎？(正旦唱)你待要花前同酌酒，灯细论文。","(张道南云)如此好天良夜，只合早成就了洞房花烛，有甚心情还论文哩？(正旦唱)你则待风清明月夜，成就了花烛洞房春。","(云)相公，贱妾千金之体，一旦委之足下，只愿你他日休负了人者。","(张道南云)小娘子放心，我若负了心呵，天不盖，地不载，日月不照临。","我着你稳取五花官诰，驷马香车，永为秦晋之匹也。","(正旦云)妾身与相公成此亲事，或诗或词，求一首珠玉，以为后会张本。","(张道南云)只是小官学问短浅，焉敢在小娘子跟前卖弄手作！(正旦云)愿求珠玉。","(张道南做写科)(词云)缟衣仙子来何处？咫尺近桃源路。","说是武陵溪畔住，玉纤微露，金莲稳步，只恐莺花妒。","邂逅刘郎垂一顾，何事匆匆便归去。","临别叮咛嘱咐。","柳亭花馆，月窗云户，休把春辜负。","右调寄青玉案。","张道南作。","(正旦云)相公是好高才也。","(张道南云)芜词拙笔，徒污仙眼耳。","(正旦唱)。"]},{"t":"萨真人夜断碧桃花・后庭花","f":"曲","c":["写的来银钩般字字真，珠玑般句句新。","端的是笔落惊风雨，诗成泣鬼神。","不是我意相亲，听了这一篇谈沦。","他能书如王右军，能文似扬子云。","现如今拥双凫做宰臣，许下我五花诰为县君。","(正旦云)相公，妾身收下这词，永为家宝。","(张道南云)量小生之词，有何才能，蒙小娘子如此珍重？(正旦唱)。"]},{"t":"萨真人夜断碧桃花・柳叶儿","f":"曲","c":["则要的言而有信，不索你唬鬼瞒神。","端的个十分才更有十分俊，休使我心儿困。","常将这脚儿勤，咱两个拚则在梦儿中暮雨朝云。"]},{"t":"萨真人夜断碧桃花・赚煞尾","f":"曲","c":["从今后将红叶不题济，准备着青鸟先传信。","(张道南云)小官焉敢负小娘子，但有负心，神明鉴察。","(正旦唱)则要你说下言词有准，休着我为你个薄幸王魁告海神。","(张道南云)小官见小娘子千娇百媚，早把俺那片魂灵儿勾引去了。","(正旦唱)则你这俏心儿引惹了三魂，今日托终身，和你待燕尔新婚。","(张道南云)此一宵欢爱，如锦鸳成对，似彩凤成双，岂不是一夜夫妻百夜恩？(正旦唱)休忘了一夜夫妻百夜恩，(张道南云)只愿小娘子早谐连理，共效于飞，以足生平之愿，(正旦唱)则要你日亲日近，俺可便相随相趁，(张道南云)小官感蒙小娘子厚情，我只愿学那张敞，断然不敢做王魁也。","(正旦唱)哎，你个画眉人可休做了那负心人。","(下)。"]},{"t":"萨真人夜断碧桃花・中吕/粉蝶儿","f":"曲","c":["则他这暮景相催，叹桑榆半竿红日，恨无情兔走乌飞。","被莺花。","闲魔障，他可都笑人憔翠。","到如今翠减双眉，羞见这鬓边霜将镜鸾懒对。"]},{"t":"萨真人夜断碧桃花・醉春风","f":"曲","c":["我这里叹世事若浮云，想光阴如逝水。","常则在大人家服侍了许多年，端的是喜，喜。","赤紧的小姐谦和，相公宽厚。","更遇着大人贤慧。","(嬷嬷云)可早来到也。","兴儿，你报复去，说徐亲家差嬷嬷问安哩。","(兴儿报科，云)相公，有徐家嬷嬷，在于门首。","(张道南云)快请进，(见科)(嬷嬷云)相公，老身奉老相公言语，本待自来问候，恐怕相公病体，迎接不便，径着老身来探近日病体如何？(张道南云)我害的病，不阴不阳，发寒发热，不知是甚么症侯？(嬷嬷唱)。"]},{"t":"萨真人夜断碧桃花・普天乐","f":"曲","c":["你莫不是断王事费精神？(张道南云)不是。","(嬷嬷唱)莫不是因茶饭伤脾胃？(张道南云)也不是。","(嬷嬷唱)莫不是风寒感冒，因病成疾？(张道南云)也不是。","(嬷嬷唱)莫不是文章上若用心？(张道南云)也不是。","(嬷嬷唱)莫不是鞍马上多劳力？(张道南云)这都不是。","(做叹气科)(嬷嬷唱)哎，他那里无语无言只是长吁气，多敢怕等闲问泄漏了天机。","他又不肯明明的说破，则这般恹恹的瘦损，好教我暗暗的猜疑。"]},{"t":"萨真人夜断碧桃花・石榴花","f":"曲","c":["他口夸大语说是赛卢医，卖弄那声价有谁及，医方脉诀幼曾习。","(净做看脉科)(嬷嬷唱)这病呵是风寒暑湿，巩饱劳役？(云)太医你下甚么苎？(太医云)我下服建中汤，减了附子，加上官桂，就着他疾病痊可也。","(嬷嬷唱)你用着建中汤去附子，加官桂必然见功效神奇。","(太医云)这寸关尺三指脉微沉细，常是寒热往来，则怕这病候有些差迟，休说我医生不会看脉。","(嬷嬷唱)怎又道寸关尺三部脉都沉细，还只怕这病候有差迟。"]},{"t":"萨真人夜断碧桃花・斗鹌鹑","f":"曲","c":["元来是风月上留情，全不是寒热间害疾。","你则待送雨行云，那些儿于家为国？常言道心病从来无药医，这等干相思不似你，空则想梦里佳人，做了个色中饿鬼。"]},{"t":"萨真人夜断碧桃花・上小楼","f":"曲","c":["那小姐十分整齐，千般娇媚。","他生的纤纤玉笋，小小银钩，淡淡蛾眉。","(张道南云)他有见识么？(嬷嬷唱)他可便有见识。","(张道南云)他有福气么？(嬷嬷唱)他可便有福气，堪为匹配，(张道南云)他来我家，便是夫人也。","(嬷嬷唱)也不辱没了五花诰县君名位。"]},{"t":"萨真人夜断碧桃花・幺篇","f":"曲","c":["怎么的问着呵越不应？道着呵越不理？(带云)我如今猜着了也。","(张道南云)你猜着甚么？(嬷嬷唱)你恋着雨爱云欢，海誓山盟，月约星期。","他那里恼一会，叹一会，不知何意？我便是女杨修难猜哑谜。"]},{"t":"萨真人夜断碧桃花・满庭芳","f":"曲","c":["待招你个先生做女婿，他早是一言既出，你可休心下疑惑。","(张道南云)他也识字么？(嬷嬷唱)那小姐诗书上索是攻习，(张道南云)可伶俐么？(嬷嬷唱)那小姐忒温柔俊雅忒伶俐，(张道南云)他伶俐杀也比不的孟光么？(嬷嬷唱)他比孟德耀还多艳质，则你这张京兆怎画蛾眉？真个是天缘对，你可便将息贵体，管教你运至遇良医。"]},{"t":"萨真人夜断碧桃花・煞尾","f":"曲","c":["向你个相公行且告别。","(张道南云)嬷嬷。","你这般惯做媒那？(嬷嬷唱)休道是我惯做媒，我说的这事和谐费了多少元阳气，则索先报与夫人相公喜。","(下)。"]},{"t":"萨真人夜断碧桃花・正宫/端正好","f":"曲","c":["帅父将法力施，火将把神通显。","这些时急急煎煎。","向后园中到处搜寻遍，险闹了那一座森罗殿。"]},{"t":"萨真人夜断碧桃花・滚绣球","f":"曲","c":["这一个戗金铠身上穿。","那一个蘸钢鞭腕上悬，一个个气昂昴性儿不善，他每都叫吼吼捋袖拉拳，走的我腿又酸脚又软，不由我不心惊胆战，索陪着笑脸儿褪后趋前。","你觑那昏昏怨雾迷千里，更和那惨惨浮云散几天，端的是苦海无边。"]},{"t":"萨真人夜断碧桃花・呆骨朵","f":"曲","c":["告师父那雷连怒息听分辨，待妾身细泌根源。","(真人云)你敢是思凡的神女么？(正旦唱)我也不足神女思凡，(真人云)敢是天魔地仙么？(正旺唱)也不是天魔地仙。","(真人云)你是甚么鬼怪？从头实实的说来！(正旦云)妾身是潮阳徐知县之女，小字碧桃。","俺父亲将我许与张道南为妻。","当日我父亲不在家，我与梅香往后花园中散心去。","不想张道南走了白鹦鹉，越墙而过，寻此鹦鹉，偶与妾身相见。","说话中间，俺父亲来到，张道南害羞而走。","俺父亲将妾身百般嗔怒，我回绣房中，一气而死，今经三年光景也。","俺父亲就将俺葬在后花园中，墓顶上长一颗碧桃花树。","因妾身有二十年阳寿未尽，以此一灵真性不散。","谁想张道南应举及第，在潮阳为理，妾身念此旧盟，与他重谐匹配。","张道南曾做〔青玉案〕词留证。","只此本情，伏望上仙尊鉴不错。","(真人云)你既然身死，却怎生阴府下不收你那三魂七魄？(正旦唱)我有那二十载阳间寿，(真人云)你既还有阳寿，天曹地府不管，你却这等兴妖作怪？(正旦唱)更有那一万种心头怨。","(真人云)你怨呵，可怨甚的。","(正旦唱)辜负我梦行云十二峰，断送的闭荒坟三四年。"]},{"t":"萨真人夜断碧桃花・倘秀才","f":"曲","c":["直到那判生死阎王殿前，(真人云)你还到那里？(正旦唱)更到那掌善恶曹司案边，他道我这枉死情由实可怜。","姻缘注五百载，阳寿有二十年，因此上把刚魂放免。"]},{"t":"萨真人夜断碧桃花・倘秀才","f":"曲","c":["他可便拂金星砚将龙香墨研，染紫霜毫把笺纸展，(真人云)哦，他写甚么来？(正旦唱)他将那(青玉案)新词写一篇。","(真人云)那秀才只恁的恋酒贪花也。","(正旦唱)他可便酒肠宽似海，端的是色胆大如天，(真人云)你为甚么便随顺他？(正旦唱)不由我不将他来顾恋。"]},{"t":"萨真人夜断碧桃花・滚绣球","f":"曲","c":["他将山盟海誓言，向罗帏锦帐眠，(真人云)他这般病了，如何不怕死？(正旦唱)他可便惜花心死而无怨，(真人云)你是甚么时侯，向他跟前去？(正旦唱)止不过赴佳期月下星前。","(真人云)你不去呵，也由得你。","(正旦唱)他将我死命的留。","我将他死命的缠，俺两个得成双称心满愿。","(真人云)他后来告归养病，你不得和他同去，你可敢还思想着他么？(正旦唱)到如今愁和闷有万万千千。","(真人云)你愁甚么？(正旦唱)我愁的是北邙衰草藏狐兔，恨的是西岭斜阳泣杜鹃，题起来雨泪涟涟。"]},{"t":"萨真人夜断碧桃花・倘秀才","f":"曲","c":["这一个掌姻缘簿的标写着无缘有缘，那一个掌生死案门先注定十年五年，可正是书案傍边一句言。","(真人云)兀那碧桃，我着你还魂去，夫妻重配，父母团圆，你心下可是如何？(正旦唱)但能勾夫妻敢匹配。","父母再团圆，我则索谢天！。"]},{"t":"萨真人夜断碧桃花・随煞尾","f":"曲","c":["谢师父承正法常看诸处行方便，开阐教广与众生解倒悬。","成就夫妻是夙缘，匹配鸾凰趁心愿。","喜的是前度张郎正少年，早晚灾除病体痊，我也不爱他诗礼儒风祖代传，也不爱他簪笏荣名圣主宣，单则爱那惜玉怜香性儿软。","(下)。"]},{"t":"萨真人夜断碧桃花・双调/新水令","f":"曲","c":["则我这俏身躯三载土中埋，今日个得还魂似升天界。","寒灰重发焰，枯树再花开。","也是我苦尽甘来，常言道否极早生泰。"]},{"t":"萨真人夜断碧桃花・步步娇","f":"曲","c":["我与你款款前来深深拜，(徐端云)孩儿，你拜甚么？(正旦唱)可怜我白头父母都年迈，间别来可便三二载，(徐端云)可怎么有二三载？(正旦云)你孩儿自离了父母去呵。","(唱)我正是几度南柯梦中来。","(徐端云)这是怎么说？(正旦云)你孩儿是碧桃也！(唱)将小名儿道的明白，(徐端云)你道是碧桃，他已死过三年了，你一向在那里？(正旦唱)你孩儿半开中落在那荒郊外。"]},{"t":"萨真人夜断碧桃花・折桂令","f":"曲","c":["原来是有朋自远方来，你道是济济衣冠，楚楚人才。","俺也只为情重如山，恩深似海，险害的你骨瘦如柴。","再不索闹攘攘大惊小怪，这一场悄促促似鬼使神差。","(张道南云)我几曾与你相见？你是这等说？(正旦唱)想着俺缱绻情怀，鱼水和谐。","我为你曾下巫山，你为我误入天台。"]},{"t":"萨真人夜断碧桃花・沽美酒","f":"曲","c":["当日个花园中成眷爱，美欢娱在书斋，则他那海誓山盟是谁道来？","哎，你这读书的秀才，俺两个谋成合不谋败。"]},{"t":"萨真人夜断碧桃花・太平令","f":"曲","c":["请你个假古忄敝的官人休怪，我这里把新词袖里忙抬。","(出词科，唱)一字字堪怜堪爱，一句句难学难赛。","我对着众客展开，表白，这(青玉案)是那个的亲笔儿留在？。"]},{"t":"萨真人夜断碧桃花・豆叶黄","f":"曲","c":["叮怜我滞魄游魂，流落在海角天涯，长伴着野草闲花，残烟断霭。","我只道晓色何曾到夜台，谁承望万里归来，喜喜欢欢，再拜我爹爹奶奶。","(夫人云)儿也，你便还魂了，只可惜我玉兰孩儿，兀的不苦痛杀我也。","(正旦唱)。"]},{"t":"萨真人夜断碧桃花・七兄弟","f":"曲","c":["这也是你的运衰，他的命该，留不得两裙钗。","若不是萨真人显出神通大，则我这墓顶上签钉远乡牌，可不的一灵儿永欠下鸳鸯债。","(张道南云)你既是碧桃小姐，当初相见之时，何不就明对我说？却教我做出这一场病症来，争些儿害杀我也。","(正旦唱)。"]},{"t":"萨真人夜断碧桃花・梅花酒","f":"曲","c":["非是我假虚脾爱使乖，也只怕粉脸香腮，引动你蜜意幽怀，倒做了黄祸之灾。","因此上把鬼名儿潜换改，真姓也暗藏埋，况阳寿尚未该，婚姻簿又明载，天对付俏身材？云和雨好安排。","连理树稳情栽，合欢花纵心摘。"]},{"t":"萨真人夜断碧桃花・收江南","f":"曲","c":["呀，今日个月明千里故人来，镜鸾重整向妆台，这的是换人肌骨夺人胎。","休得要乱猜，你不见桃花依旧待春开。"]},{"t":"关云长千里独行・正宫/端正好","f":"曲","c":["我则怕他用心机，敢可兀的铺谋定计。","我想这曹操是那智足奸雄，信着俺小叔莽戆多英勇。","(带云)主公，哎！(唱)你则合操士马教三军明堤备破曹兵，则怕他排队伍暗伏兵，则要你得胜也把他这干戈来定。"]},{"t":"关云长千里独行・仙吕/点绛唇","f":"曲","c":["俺可便奔走东西，气冲两肋，心生计。","恨不的插翅如飞，飞不出剑洞枪林内。","(小旦云)姐姐，玄德公信着三叔叔的计策，全不是了也。","(正旦唱)。"]},{"t":"关云长千里独行・混江龙","f":"曲","c":["谁想这徐州失利，送的俺弟兄姊妹两分离。","闪杀我也仁慈的玄德，送了我也莽撞张飞。","本来也无战争平白的起战争，你正是得便宜翻做了落便宜。","(小旦云)姐姐，你见么，兀的城头上不是二叔叔云长也。","(正旦唱)我这里猛抬头见二叔叔在城头上立，曹丞相倚强压弱，俺如今受困遭危。"]},{"t":"关云长千里独行・油葫芦","f":"曲","c":["则俺这兄弟张飞谁近的，他端的有见识，使一条点钢枪敢与万人敌，他便安排着打凤捞龙计，谁着他便搜寻出劫寨偷营智。","(小旦云)姐姐，玄德定计，曹操他怎生便知道来？(正旦唱)曹丞相暗地里，他可早先准备。","打了个拷栳圈围在垓心内，人和马怎生走不能飞。"]},{"t":"关云长千里独行・天下乐","f":"曲","c":["可正是船到江心补漏迟，(关末云)嫂嫂，如今曹丞相要招安我，我不降他来，则怕曹丞相伤害着你性命也。","(正旦云)叔叔，俺可打甚么不紧也。","(正旦唱)则这曹也波贼，恐害着你。","(关末云)我想哥哥兄弟之情，我怎生归降他？(正旦唱)你若是不归降他怒从心上起。","一壁厢统着士卒，一壁厢探着阵势，(云)叔叔，你若不肯投降，曹丞相将俺这三房头家小，叫声杀坏了。","(唱)你那其间敢眼睁睁怎近得。","(关末云)嫂嫂，我待投降来，想俺兄弟三人，对天盟誓，一在三在，一亡三亡；我若不降来，这三房家小，见在曹营，倘若有些好歹呵，如之奈何？(张辽云)二将军你见么？你这三房头家小，都在俺曹营。","你若不降呵，这三房头家小，怎生了也？(关末云)张文远，你说与你那曹丞相，他若依我三桩事，我便投降。","(张辽云)二将军，你但言的事，俺丞相都依着。","(关末云)我头一桩，我虽然投降，我可不降你丞相，我是降汉不降曹；第二桩。","我和俺哥哥兄弟家属，一宅分两院；第三桩，我若打听的俺哥哥兄弟信息，我便寻去，可不许您拦当。","你说去。","(张辽云)我知道。","丞相，云长投降，叫丞相依他三桩事，他便降。","(曹末云)那三桩事？(张辽云)头一桩，他降汉不降曹；第二桩，他和他嫂嫂家小一宅分两院；第三桩，他但是打听的他哥哥兄弟信息，他便去寻去。","(曹末云)这其间知道他那哥哥兄弟有也无，都依的他。","开了门，我和他厮见，咱。","(张辽云)二将军，俺丞相都依了也。","你开门和俺丞相厮见咱。","(关末云)小校，开了城门。","(曹末云)俺入的这城来。","张文远，教他那三房头老小，与他厮见咱。","(张辽云)理会的。","请两个夫人与二将军厮见咱。","(正、小旦做见关末打悲科)(关末云)嫂嫂，谁想今日有这场也！当初张飞依着我不去呵，无此事也。","看了曹兵那般势大，兄弟是难逃也。","(正旦云)想三叔他是一勇性也(唱)。"]},{"t":"关云长千里独行・金盏儿","f":"曲","c":["刀剑-时催，弓弩似电光飞。","伏兵四面一齐起，饶你有通天武艺，怎施威。","骤征马宛寻家计，插翅走如飞。","他可甚鞭敲金镫响，人和凯歌回。","(曹末与关末相见科)(曹末云)云长，一别许久也。","则今日咱便往京师，见了圣人，将你重重赐赏加官。","一壁厢准备车乘，老小每上车。","(关末云)嫂嫂，您上车儿先行。","(正旦云)多谢叔叔。","(关末云)嫂嫂，关羽不敢。","(小旦云)姐姐，若不是二叔叔，俺岂有今日也。","(正旦唱)。"]},{"t":"关云长千里独行・尾声","f":"曲","c":["今日个救出我这乱军中，不枉了结义在桃园内。","救了俺这姊妹残生顷刻，俺便似太山般一家儿倚靠着你。","从今后照顾您这亲戚，则今后信音稀，要见他容易，则除是一枕南柯梦儿里。","谁想我与玄德公厮离，俺可也是关着前世，玄德公也正是要便宜翻做落便宜。","(同下)。"]},{"t":"关云长千里独行・南吕/一枝花","f":"曲","c":["今日个难除我腹内忧，怎解我眉间皱。","我可也心怀家国恨，则我这眉锁他这个庙堂愁。","我可便有信难投，眼睁睁无人救，今日个这凄凉何日休。","(小旦云>当日都是三叔叔张飞的不是了也。","(正旦唱)你当日逞英雄与曹操做敌头，则被他倒空营俺着他机彀。"]},{"t":"关云长千里独行・梁州","f":"曲","c":["则俺这姊妹淹留在许昌，则被那兄弟每失散在徐州。","(小旦云)姐姐，俺想玄德公何日相见也？(正旦唱)我想这英雄玄德仁慈厚，他端的忠直慷慨，壮志难酬，豁达大度，纳谏如流。","我这里扑簌簌泪满星眸，俺可便看他何日乐矣忘忧。","我、我、我折倒的骨捱捱身似柴蓬，是、是、是俺可也病恹恹黄干黑瘦，呀、呀、呀俺可便每口家绿惨红愁。","怎生做个解忧？半生勤苦干生受。","俺叔叔花也成蜜也就，可便地久天长怎了救？(小旦云)姐姐省烦恼。","俺好歹有一日见玄德公也。","(正旦唱)好教我无了无休。","(正旦云)妹子，俺这里闲攀着话，看有甚么人来。","(关末上，云)欢来不似今朝，喜来那逢今日。","关羽也，我恰才本无酒，我听的那厮说我哥哥兄弟在古城，我故意推醉。","来到这宅中，有俺嫂嫂逐日烦恼，他则说俺哥哥兄弟不见，每日思念。","谁想哥哥兄弟，如今见在古城。","我如今到于嫂嫂宅中，我且不说哥哥兄弟还有哩，我则推醉，看他说甚么。","报复去，道有关羽在于门首。","(报复科)(正旦云)呀，既然二叔叔来了也，叔叔请坐。","(关末推醉科，云)嫂嫂，关羽不必坐。","好酒也，我醉了也。","(正旦云)妹子，你看俺二叔叔好快活也。","(关末云)我怎么不快活？我如今封官为寿亭侯，每日筵宴管待，正好受用也。","(正旦云)叔叔你的是也。","(唱)。"]},{"t":"关云长千里独行・红芍药","f":"曲","c":["你道是新来加你做寿亭侯，(关末云)我上马一提金，下马一提银。","(正旦唱)枉受了些肥马轻裘。","这的是你桃园结义下场头，枉了宰白马杀乌牛。","(关末云)我三日一小宴，五日一大宴。","(正旦唱)你每日吃堂食饮御酒，你全不记往日的冤仇。","想着您同行同坐数年秋，到如今一笔哎都勾！(关末云)我如今官封为寿亭侯哩。","(正旦唱)。"]},{"t":"关云长千里独行・菩萨梁州","f":"曲","c":["今日个你建节来封侯，登时间忘旧。","知书的小叔，你可便枉看了些《左传》《春秋》。","我这里听言说罢泪交流，弟兄今日难相守，甚日个得完就。","准想你结义宾朋不到头，则他这岁月淹留。","(关末云)我将这条凳椅桌都打碎了，幔帐纱橱都扯掉了。","(正旦云)叔叔烦恼了也。","妹子，咱与叔叔陪话去来。","(唱)。"]},{"t":"关云长千里独行・骂玉郎","f":"曲","c":["则我这心中负屈应难受，不由我便扑簌簌泪交的流，我见他扑登忿怒难收救。","他那里踢翻椅桌，攫了幔幕，紧揎起那征袍袖。"]},{"t":"关云长千里独行・采茶歌","f":"曲","c":["叔叔你早则么皱着眉头，休记冤仇，叔叔你与我停嗔息怒。","寿亭侯，则你那失散了的哥哥不知道无共有，方信道知心的这相识可也到头休。","(云)妹妹，俺跪着。","二叔叔，可怜见俺姊妹二人。","(正旦、小旦都跪科)(关末云)嫂嫂请起。","你休烦恼，你欢喜咱。","(二旦云)我有甚么欢喜？(关末云)嫂嫂，你不知俺哥哥兄弟，见在古城有哩。","(正旦云)叔权，谁那般道？(关末云)嫂嫂，今日曹丞相请我赴宴。","有一个张虎来说，我哥哥兄弟杀退了他，哥哥兄弟如今见在古城。","我故意推醉，我特来报与嫂嫂知道。","(二旦云)是真个？(关末云)是真个。","我将曹丞相赐与我的金银和这寿亭侯牌印，我都锁在宜阳宅。","不分星夜，便出许都。","(正旦云)是真个？惭愧也。","叔叔，则今日收拾行李，便索长行。","(唱)。"]},{"t":"关云长千里独行・尾声","f":"曲","c":["则你那忠直勇烈依了你口，谁想这刘备、张飞见在有。","打听的兄弟哥哥有时候，忙离了许州，盼不到地头，俺遥望着千里的这红尘路儿上走。","(下)。"]},{"t":"关云长千里独行・中吕/粉蝶儿","f":"曲","c":["则你那途路迢遥，趁西风斜阳古道，催几鞭行色劬劳。","践红尘，登紫陌，领着些关西小校。","不索辞曹，恨不的一时间古城行到。"]},{"t":"关云长千里独行・醉春风","f":"曲","c":["你今日弃印觅亲兄，你则待封金谒故交。","独行千里探哥哥，似叔叔的少、少、少。","他把你官上加官，禄上赠禄，曹丞相傲也那不傲。","(关末云)兀的后面有军马至了。","(曹末同张辽、许褚上，云)兀的前面不是云长？(做唤关末科，云)寿亭侯兄弟也，且住者。","(关末云>真个是丞相领兵赶来。","(正旦云)叔叔，曹丞相领兵赶将来，你小心在意者。","(关末云)不妨事。","(正旦唱)。"]},{"t":"关云长千里独行・红绣鞋","f":"曲","c":["曹孟德能施谋略，则要你个关云长牢把鞍桥，咱可便嘴尾相衔紧随着，暗暗的便埋着军将，明明的列着枪刀，可休似徐州城失散了。","(云)叔叔，小心在意者。","(关末云)嫂嫂放心，我自知道。","(曹末上见住)(做下马科，云)寿亭侯兄弟也，怎生不辞而去？(关末云)丞相勿罪，我不下马来也。","(许褚云)呀，可早一条计也。","(曹末云)将酒来。","(许褚做斟酒科)(曹末递酒科，云)云长，既然你要去也，你下马来满饮一杯。","(正旦云)叔叔，你休下马去。","(关末云)嫂嫂，他与咱送路，他有甚么歹意？(正旦唱)。"]},{"t":"关云长千里独行・快活三","f":"曲","c":["则他那饯行的意虽好，铺谋的智难逃。","不妨马上接了香醪，我与你附耳低低道。"]},{"t":"关云长千里独行・朝天子","f":"曲","c":["我这里望着，定睛的觑了，曹丞相百万军都来到。","据着他兴心主意不相饶，折算你谁知道。","我见他厚礼卑辞，亲捧香醪，这里面安排下斩人刀。","叔叔你喑约，则依着你嫂嫂，则怕他酒里面藏有机妙。"]},{"t":"关云长千里独行・上小楼","f":"曲","c":["他待使些雕心鹰爪，安排下龙韬虎略。","他一个个执锐披坚，勒马横枪，举斧轮刀。","他将一领锦征袍，盘内托，我可便观了容貌，他那里曲躬躬一身伏着。"]},{"t":"关云长千里独行・幺篇","f":"曲","c":["又不向盘内取，则向刀刃上挑。","险些儿惊杀许褚，荒杀曹公，唬杀张辽。","他每都，紧赶着，奸雄曹操。","我问你那锦征袍要也那不要？。"]},{"t":"关云长千里独行・尾声","f":"曲","c":["袭车胄武艺能，刺颜良名分高。","用尽自己心，惹的旁人笑。","哎，你个奸雄曹操，到陪了西川十样锦征袍。","(下)。"]},{"t":"关云长千里独行・双调/新水令","f":"曲","c":["你保护的俺一家儿妯娌得安康，则他弟和兄这其间别来无恙。","叔叔你是那檠天白玉柱，架海的紫金梁。","义勇忠良，俺今日团圆日不承望。"]},{"t":"关云长千里独行・殿前欢","f":"曲","c":["若不是这汉云长，则为俺这家属不得已可便诈投降。","(刘末云)他受他封官来。","(正旦唱)寿亭侯官职无心望，甚的他快乐的这心肠。","(云)那一日与曹操饮酒，听的说主公与小叔叔在此，收拾便行。","(咀)他封金印出许都，(带云)曹操赶至灞陵桥，三计要拿云长，二叔叔致怒。","(唱)险唬杀那曹丞相，锦征袍便斜挑在他刀尖上。","(带云)若不是二叔叔，俺三房头家小，都落在曹营。","(唱)怎能勾那弟兄每完聚，也不能勾今日得这还乡。"]},{"t":"关云长千里独行・川拨棹","f":"曲","c":["你那里自参详，张将军不料量。","他那里说短论长，数黑论黄。","断不了村沙莽撞，你心中自忖量。"]},{"t":"关云长千里独行・七弟兄","f":"曲","c":["他可便这厢那厢，他两个逞能强，怒忿忿豪气三千丈。","他丈八矛轮动怎生当，这青龙刀举起无遮当，好着我泪两行。","便有些不停当，你心下自参详，你心下自参详。"]},{"t":"关云长千里独行・喜江南","f":"曲","c":["呀，则你那哥哥兄弟好商量，不比你一勇性石亭驿里摔袁祥。","救了俺全家老小得安康，你自便料量，息怒波兴刘灭楚汉张良。"]},{"t":"关云长千里独行・挂玉钩","f":"曲","c":["他恰才万马千军摆下战场，则见他忙把门旗放，显出那弃印封金有智量。","他怎肯扶立起曹丞相，斩了蔡阳，在杀场上。","才听的挝鼓三通，可又早得胜还乡。"]},{"t":"小张屠焚儿救母・仙吕/端正好","f":"曲","c":["我则待积阴功，他则待贪财物。","咱两个利名心水火不同炉，全不肯施财周济贫民苦，无半点儿慈悲处。"]},{"t":"小张屠焚儿救母・幺篇","f":"曲","c":["便是有那金银垛至北斗待何如？当日鲁子敬谒周瑜，郭原真访亚大。","将一领新棉袄，你道是旧衣服。","你二升米，看承做两斛珠。","不由我心劳攘，意踌躇，好教我心忙怎语。"]},{"t":"小张屠焚儿救母・仙吕/点绛唇","f":"曲","c":["母亲病在膏盲，你孩儿仰天悲怆，添惆怅。","母亲受半世孤孀，却怎生越划地无承望。"]},{"t":"小张屠焚儿救母・混江龙","f":"曲","c":["别无甚倚仗，受孤孀耽疾病受凄凉。","心劳意攘，腹热肠慌。","忍冻饿谁怜儿命蹇，守孤贫争敢母亲忘。","常则是半抄儿活计，一合儿糇粮。","看看至死，不久身亡。","遇不收时月，饥俭年光。","母亲眼中泪不离了枕席边，你孩儿腹中愁常潜在眉尖上。","都不到一时半刻，寻思到百计千方。"]},{"t":"小张屠焚儿救母・油葫芦","f":"曲","c":["(云)大嫂，你学几个古人，(唱)孟氏贤达有义方，夫姓梁，常则是荆钗布袄守寒窗。","为夫的，文章冠世诗书广，为妻的孝廉仁义名真响。","母亲行时时亲拜复，勤勤的厮问当。","便有志诚心，无半点儿虚诳。","常则是朝侍奉，暮煎汤。"]},{"t":"小张屠焚儿救母・天下乐","f":"曲","c":["谁不待举案齐眉学孟光，怕不待开张，那里取升合粮？","与人家打勤劳做生活有甚妨？","怕不待时时的杀个猪，勤勤的宰个羊，觅几文邓通钱将我娘侍养。"]},{"t":"小张屠焚儿救母・那吒令","f":"曲","c":["住孤村小庄，无亲族当房。","若母亲命亡，天那！谁人觑当。","大嫂，你学取些贤孝心，我有宽宏量，休学那忤逆婆娘。"]},{"t":"小张屠焚儿救母・鹊踏枝","f":"曲","c":["带头面插金装，穿绫罗好衣裳，出来的毁遍尊亲，骂遍街坊。","你学那哭长城送寒衣孟姜，休学那无廉耻盗果京娘。"]},{"t":"小张屠焚儿救母・寄生草","f":"曲","c":["我虽不读《论》《孟》篇，多闻孝义章。","舜子孝母天将养，郭巨埋子天恩降，孟宗哭竹天垂象。","王祥卧鱼标写在史书中，丁兰刻木图画在丹青上。"]},{"t":"小张屠焚儿救母・醉扶归","f":"曲","c":["卖弄他指下明看读广，止不过《宣明论》、《瑞竹堂》。","通圣散、青龙丸、白虎汤，怎莫这般药直银七两？量这个张屠户朝无夜粮。","他可怒从心上一起，可见老母亲病着床。"]},{"t":"小张屠焚儿救母・金盏儿","f":"曲","c":["朱砂面有容光，这物色淡微黄。","他那里咒连天誓说道无虚诳，恨不得手拈疾病便离床。","愿母亲三焦和肺腹，五脏润肝畅。","可怜见俺忤逆子，则怕妨杀俺七十娘。"]},{"t":"小张屠焚儿救母・后庭花","f":"曲","c":["我这里望东岳圣帝方，祝神明心内想。","则为我生身母三熊病，许下喜孙儿做一炷香。","我这里过茶汤，愿母亲通身舒畅。","汗溶溶如水一江，参似冰凉。","面溶溶有喜光，笑孜孜亲问当。"]},{"t":"小张屠焚儿救母・青哥儿","f":"曲","c":["病可却便是平生、平生模样，往日、往日形像。","常言道孝顺心是人间海上方。","每日家告遍街坊，谁肯惭惶？仰告穹苍，许下明香，儿做神羊。","谁想道舍死回生便离床，兀的是天将傍。"]},{"t":"小张屠焚儿救母・越调/斗鹌鹑","f":"曲","c":["青云天宫千重，占有峰峦万朵。","明晃晃金碧琉璃，高耸耸楼台殿阁。","王孙每宝马金鞍，士女每香车绮罗。","正遇着春昼暄，丽日和。","袅春风绿柳如烟，含夜雨桃红似火。"]},{"t":"小张屠焚儿救母・紫花儿序","f":"曲","c":["闹清明莺声婉啭，荡花枝蝶翅蹁跹，舞东风剪尾娑婆。","你看那车尘马足，作戏敲锣，聒耳笙歌，不似今年上庙的多。","普天下名山一座，壮观着万里乾坤，永镇着百二山河。"]},{"t":"小张屠焚儿救母・金蕉叶","f":"曲","c":["你去山门前潜躲，你去东廊下休来伴我。","你向松阴中权且歇波，我入三门沉吟了几合。"]},{"t":"小张屠焚儿救母・调笑令","f":"曲","c":["别无甚献贺，为救俺母亲活，上圣！教张屠无奈何。","报娘恩三年乳哺恩临大，怀耽十月娘情多。","弃儿救母绝嗣，我为亲娘暴虎冯河。"]},{"t":"小张屠焚儿救母・金蕉叶","f":"曲","c":["恩养上谁人似我，孝名儿天地包罗。","将亲娘煨干就湿都正过，四十年受苦奔波。"]}]};